INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('HexAI-inc/v0-futuristic-website-design/browser-extension', 'browser-extension', 'HexAI-inc', 'v0-futuristic-website-design', 'community', 'browser-extension HexAI-inc v0-futuristic-website-design community The browser-extension skill empowers developers to create ephemeral, restricted, yet powerful extensions, ensuring security and persistence. Ideal for developers seeking to enhance browser functionality. 浏览器扩展开发需要考虑设计约束和安全性要求，确保扩展的高效和安全 ブラウザーエクステンション開発では、設計とセキュリティに関する考慮が必要です 브라우저 확장 개발은 설계 제약과 보안 요구사항을 고려해야 합니다 Las extensiones de navegador son efímeras, restringidas, pero potentes. Aprende a crearlas con agentes de IA, siguiendo las mejores prácticas de seguridad y diseño Les extensions de navigateur sont éphémères, restreintes, mais puissantes. Découvrez comment les créer avec des outils d''IA, en suivant les meilleures pratiques de sécurité et de design Browser-Erweiterungen sind ephemere, eingeschränkte, aber leistungsstarke Werkzeuge. Erfahren Sie, wie Sie sie mit KI-Tools erstellen, indem Sie die besten Praktiken für Sicherheit und Design befolgen Desenvolva extensões de navegador com persistência e segurança em mente, utilizando as melhores práticas para UI/UX e layout Разработайте расширения браузера с учетом персистенции и безопасности, используя лучшие практики для UI/UX и макета قم بإنشاء امتدادات متصفح مع أخذ العوامل الأمنية والاستمرارية في الاعتبار، مستخدمًا أفضل الممارسات لتفاعل المستخدم وتصميم الواجهة how to use browser-extension browser-extension setup guide what is browser-extension browser-extension alternative browser-extension vs chrome extension browser-extension install browser-extension security best practices browser-extension development tutorial browser-extension manifest v3 browser-extension ai integration 浏览器扩展开发 Manifest V3 服务工作者 设计约束 安全性要求 持久化存储 背景脚本 内容脚本 Adheres to frontend-design skill for UI/UX, aesthetics, and layout Avoids global variables and in-memory state in background scripts Complies with Manifest V3 service worker constraints Ensures security as a mandate in browser extension development Navigates the persistence paradox for reliable extension behavior References the frontend-design skill for design constraints browser-extension is a skill that enables developers to build restricted, yet powerful browser add-ons, focusing on persistence and security');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('nyaomaru/is-kit/prettier-format', 'community', 'nyaomaru', 'is-kit', 'nyaomaru/is-kit', 'prettier-format', 0, 0, 29, '2026-03-08T01:57:15.371Z', '2026-03-08T02:04:28.690Z', 'ba1303dc5ada8c9e822ada5dd44e00d7f833b6367d6f62b9cf2c38d0d51a7338', '{"id":"nyaomaru/is-kit/prettier-format","name":"prettier-format","description":{"en":"The prettier-format skill formats or checks code using a Prettier configuration and ignore rules. It is designed for developers working with TypeScript, providing runtime-safe and composable type guards.","zh":"Prettier 格式化工具是一种用于自动格式化 TypeScript 代码的工具，支持运行时安全、组合性和 ergonomics","ja":"Prettier Format は、TypeScript コードの自動整形を実現するツールで、ランタイムセーフ、組み合わせ可能、エргノミクスをサポートしています","ko":"Prettier 포맷팅 도구는 TypeScript 코드의 자동 포맷팅을 thực現하는 도구로, 런타임 안전성, 조합성 및 ergonomics를 지원합니다","es":"Prettier Format es una herramienta ligera para formatear código según la configuración de Prettier. Es seguro en tiempo de ejecución y muy personalizable","fr":"Prettier Format est un outil léger pour formater du code selon la configuration Prettier. Il est sécurisé en temps d''exécution et très personnalisable","de":"Prettier Format ist ein leichtes Tool zum Formatieren von Code gemäß der Prettier-Konfiguration. Es ist laufzeit-sicher und sehr anpassbar","pt":"O Prettier Format é uma ferramenta leve para formatar e verificar código, compatível com TypeScript e outras tecnologias","ru":"Prettier Format - это легкая утилита для форматирования и проверки кода, совместимая с TypeScript и другими технологиями","ar":"أداة التنسيق Prettier Format هي أداة خفيفة لتنسيق وتصحيح الكود، متوافقة مع TypeScript وتقنيات أخرى"},"seo":{"title":{"en":"prettier-format: TypeScript Code Formatting Setup Guide |...","zh":"Prettier 格式化工具：TypeScript 代码格式化最佳实践","ja":"Prettier Format のセットアップガイド：TypeScript コードの自動整形","ko":"Prettier 포맷팅 도구: TypeScript 코드 자동 포맷팅 설정 가이드","es":"Guía de configuración de Prettier Format para desarrollad...","fr":"Configurer Prettier Format : Le guide ultime pour les dév...","de":"Prettier Format Einrichtung: Anleitung für Entwickler","pt":"Guia de Configuração do Prettier Format para Desenvolvedores","ru":"ИИ Агенты: Настройка Prettier Format для Разработчиков","ar":"إعداد أداة التنسيق Prettier Format للاستخدام مع أدوات الـAI"},"description":{"en":"Unlock efficient code formatting with prettier-format. Learn how to use this zero-dependency toolkit for building type guards in TypeScript and improve your ...","zh":"使用 Prettier 格式化工具自动格式化您的 TypeScript 代码，确保代码风格一致，提高开发效率","ja":"Prettier Format を使用して、TypeScript コードの自動整形を実現し、コードスタイルを統一して開発効率を向上させる","ko":"Prettier 포맷팅 도구를 사용하여 TypeScript 코드의 자동 포맷팅을实现하고 코드 스타일을 통일하여 개발 효율을 향상시키세요","es":"Aprende a configurar Prettier Format para mejorar la calidad de tu código con esta guía paso a paso para desarrolladores","fr":"Découvrez comment configurer Prettier Format pour améliorer la qualité de votre code avec ce guide étape par étape pour les développeurs","de":"Erfahren Sie, wie Sie Prettier Format konfigurieren, um die Qualität Ihres Codes zu verbessern, mit diesem Schritt-für-Schritt-Leitfaden für Entwickler","pt":"Aprenda a configurar o Prettier Format para melhorar a produtividade do seu código com essa ferramenta leve e flexível","ru":"Откройте для себя, как настроить Prettier Format для повышения производительности вашего кода с помощью этого легкого и гибкого инструмента","ar":"تعرف على كيفية إعداد أداة التنسيق Prettier Format لتحسين إنتاجية كودك باستخدام هذه الأداة الخفيفة والمميزة"},"definition":{"en":"prettier-format is a lightweight, zero-dependency toolkit for building isFoo style type guards in TypeScript, ensuring runtime safety and composability.","zh":"Prettier 格式化工具是一种用于自动格式化代码的工具，特别适用于 TypeScript 项目","ja":"Prettier Format は、コードの自動整形を実現するツールの一種で、特に TypeScript プロジェクト向けに設計されています","ko":"Prettier 포맷팅 도구는 코드의 자동 포맷팅을實現하는 도구の一種で, 특히 TypeScript 프로젝트용으로 설계되었습니다","es":"Prettier Format es una herramienta de formato de código que utiliza la configuración de Prettier para asegurar la calidad del código","fr":"Prettier Format est un outil de formatage de code qui utilise la configuration Prettier pour assurer la qualité du code","de":"Prettier Format ist ein Code-Formatierungstool, das die Prettier-Konfiguration verwendet, um die Code-Qualität zu gewährleisten","pt":"Prettier Format é uma ferramenta de código aberto para formatar e verificar código","ru":"Prettier Format - это открытая утилита для форматирования и проверки кода","ar":"أداة التنسيق Prettier Format هي أداة مفتوحة المصدر لتنسيق وتصحيح الكود"},"features":{"en":["Formats code using Prettier configuration and ignore rules","Supports --check for verify formatting requests","Supports --write for format or fix requests","Prefer local binaries and the project''s package manager","Compatible with npm package manager"],"zh":["支持运行时安全","组合性和 ergonomics","自动格式化 TypeScript 代码","支持 Prettier 配置和忽略规则","使用本地二进制文件和项目包管理器"],"ja":["ランタイムセーフをサポート","組み合わせ可能とエrgonomics","TypeScript コードの自動整形","Prettier 構成と無視規則をサポート","ローカルバイナリとプロジェクトパッケージマネージャーを使用"],"ko":["런타임 안전성 지원","조합성 및 ergonomics","TypeScript 코드의 자동 포맷팅","Prettier 구성 및 무시 규칙 지원","로컬 바이너리 및 프로젝트 패키지 매니저 사용"],"es":["Formato de código personalizable con Prettier","Seguridad en tiempo de ejecución","Compatibilidad con comandos --check y --write","Soporte para formato de código en proyectos locales","Integración con el administrador de paquetes del proyecto"],"fr":["Formatage de code personnalisable avec Prettier","Sécurité en temps d''exécution","Compatibilité avec les commandes --check et --write","Prise en charge du formatage de code dans les projets locaux","Intégration avec le gestionnaire de paquets du projet"],"de":["Code-Formatierung anpassbar mit Prettier","Laufzeit-Sicherheit","Unterstützung für die Befehle --check und --write","Formatierung von Code in lokalen Projekten","Integration mit dem Paket-Manager des Projekts"],"pt":["Formatar código com configuração personalizada","Verificar código com regras de formatação","Compatível com TypeScript e outras tecnologias","Ferramenta leve e flexível","Suporte a comandos de linha de comando"],"ru":["Форматирование кода с настраиваемой конфигурацией","Проверка кода с правилами форматирования","Совместимость с TypeScript и другими технологиями","Легкая и гибкая утилита","Поддержка командной строки"],"ar":["تنسيق الكود باستخدام إعدادات مخصصة","فحص الكود باستخدام قواعد التنسيق","متوافق مع TypeScript وتقنيات أخرى","أداة خفيفةและมميزة","دعم أوامر سطر الأوامر"]},"keywords":{"en":["how to use prettier-format","prettier-format setup guide","prettier-format alternative","prettier-format vs eslint","prettier-format install","typescript code formatting","zero-dependency toolkit","isFoo style type guards"],"zh":["Prettier 格式化工具","TypeScript 代码格式化","自动格式化","运行时安全","组合性","ergonomics","Prettier 配置","忽略规则"],"ja":["Prettier Format","TypeScript コード整形","自動整形","ランタイムセーフ","組み合わせ可能","エrgonomics","Prettier 構成","無視規則"],"ko":["Prettier 포맷팅 도구","TypeScript 코드 포맷팅","자동 포맷팅","런타임 안전성","조합성","ergonomics","Prettier 구성","무시 규칙"],"es":["Prettier Format","herramientas de formato de código","configuración de Prettier","seguridad en tiempo de ejecución","desarrollo de software","formato de código personalizable","administrador de paquetes","proyectos locales","Herramientas de desarrollo"],"fr":["Prettier Format","outils de formatage de code","configuration Prettier","sécurité en temps d''exécution","développement de logiciels","formatage de code personnalisable","gestionnaire de paquets","projets locaux","Outils de développement"],"de":["Prettier Format","Code-Formatierungstools","Prettier-Konfiguration","Laufzeit-Sicherheit","Software-Entwicklung","Code-Formatierung anpassbar","Paket-Manager","lokale Projekte","Entwicklertools"],"pt":["Prettier Format","formatar código","verificar código","TypeScript","desenvolvimento de software","ferramentas de desenvolvimento","código aberto","configuração personalizada"],"ru":["Prettier Format","форматирование кода","проверка кода","TypeScript","разработка программного обеспечения","инструменты разработки","открытый исходный код","настраиваемая конфигурация"],"ar":["أداة التنسيق Prettier Format","تنسيق الكود","فحص الكود","TypeScript","تطوير البرمجيات","أدوات التطوير","مفتوح المصدر","إعدادات مخصصة"]}},"owner":"nyaomaru","repo":"is-kit","repoPath":"nyaomaru/is-kit","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.371Z","topics":[],"category":"community","skillMd":{"name":"prettier-format","description":"Run Prettier for the is-kit repository. Use when asked to format or check formatting in this project. Always consult AGENTS.md in the repo root before executing commands.","bodyPreview":"# Prettier Format (is-kit)\n\n## Overview\n\nFormat or check code using this repo''s Prettier configuration and ignore rules. Prefer local binaries and the project''s package manager.\n\n## Workflow\n\n1. Read repository instructions.\n\n- Open `AGENTS.md` in the repo root and follow all constraints (commands, formatting, tests, etc.).\n- If `AGENTS.md` is missing, ask how to proceed.\n\n2. Determine intent and scope.\n\n- Use `--check` for \"verify formatting\" requests.\n- Use `--write` for \"format\" or \"fix\" requ","body":"# Prettier Format (is-kit)\n\n## Overview\n\nFormat or check code using this repo''s Prettier configuration and ignore rules. Prefer local binaries and the project''s package manager.\n\n## Workflow\n\n1. Read repository instructions.\n\n- Open `AGENTS.md` in the repo root and follow all constraints (commands, formatting, tests, etc.).\n- If `AGENTS.md` is missing, ask how to proceed.\n\n2. Determine intent and scope.\n\n- Use `--check` for \"verify formatting\" requests.\n- Use `--write` for \"format\" or \"fix\" requests.\n- Ask for target paths when not specified; do not assume whole repo unless requested.\n\n3. Run Prettier with local tooling.\n\n- Prefer `./node_modules/.bin/prettier`.\n- Alternative: `pnpm prettier` (repo uses pnpm).\n- Avoid `npx` unless the user explicitly approves network downloads.\n\n4. Report results.\n\n- Summarize changed files or confirm a clean check.\n- If a command fails, include the error and propose the next step.\n\n## Quick Commands\n\n- Format repo: `./node_modules/.bin/prettier --write .`\n- Check formatting: `./node_modules/.bin/prettier --check .`\n- Format paths: `./node_modules/.bin/prettier --write src tests`\n- Check paths: `pnpm prettier --check src tests`\n\n## Resources\n\n### scripts/\n\n- `run_prettier.sh`: Run Prettier with `--write` or `--check` and auto-pick a runner.\n"},"lastSynced":"2026-03-08T02:04:28.690Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Analysis Agents needing automated formatting and code verification using Prettier configuration and TypeScript","zh":"适合需要使用Prettier配置和TypeScript进行自动化格式化和代码验证的代码分析代理","ja":"Prettierの設定とTypeScriptを使用して自動化されたフォーマットとコードの検証が必要なコード分析エージェントに適しています","ko":"Prettier 구성 및 TypeScript를 사용하여 자동화된 형식 지정 및 코드 확인이 필요한 코드 분석 에이전트에 적합합니다","es":"Perfecto para agentes de análisis de código que necesitan formato automático y verificación de código utilizando configuración de Prettier y TypeScript","fr":"Parfait pour les agents d''analyse de code nécessitant un formatage automatique et une vérification de code à l''aide de la configuration Prettier et de TypeScript","de":"Perfekt für Code-Analyse-Agents, die automatisiertes Formatieren und Code-Verifizierung unter Verwendung von Prettier-Konfiguration und TypeScript benötigen","pt":"Perfeito para Agentes de Análise de Código que necessitam de formatação automatizada e verificação de código usando configuração Prettier e TypeScript","ru":"Идеально подходит для агентов анализа кода, которым необходима автоматизированная форматирование и проверка кода с использованием конфигурации Prettier и TypeScript","ar":"مثالي لعمليات تحليل الشفرة التي تحتاج إلى تنسيق وتحقق تلقائي باستخدام تكوين Prettier وTypeScript"},"recommendation":{"en":"Empowers agents to format or check code using Prettier configuration and ignore rules, providing runtime-safe and composable type guards for TypeScript, and utilizing local binaries and project package managers for seamless integration","zh":"赋予代理使用Prettier配置和忽略规则格式化或检查代码的能力，提供运行时安全和可组合的类型保护 дляTypeScript，并利用本地二进制文件和项目包管理器实现无缝集成","ja":"Prettierの設定と無視ルールを使用してコードをフォーマットまたはチェックする機能をエージェントに与え、TypeScriptのランタイムセーフで合成可能なタイプガードを提供し、ローカルバイナリとプロジェクトパッケージマネージャーを使用してシームレスな統合を実現する","ko":"Prettier 구성 및 무시 규칙을 사용하여 코드를 형식화 또는 확인하는 기능을 에이전트에게 부여하며, TypeScript의 런타임 안전 및 구성 가능한 유형 보호를 제공하고, 로컬 바이너리 및 프로젝트 패키지 관리자를 사용하여 무결점 통합을 구현합니다","es":"Habilita a los agentes a dar formato o verificar código utilizando configuración de Prettier y reglas de ignorar, proporcionando guardias de tipo seguras en tiempo de ejecución y componibles para TypeScript, y utilizando binarios locales y administradores de paquetes de proyecto para una integración perfecta","fr":"Permet aux agents de formater ou de vérifier le code à l''aide de la configuration Prettier et des règles d''ignoration, en fournissant des gardes de type sécurisées et composites pour TypeScript, et en utilisant des binaires locaux et des gestionnaires de paquets de projet pour une intégration transparente","de":"Ermächtigt die Agenten, Code zu formatieren oder zu überprüfen, indem sie die Prettier-Konfiguration und Ignorierregeln verwenden, wodurch Laufzeit-sichere und komponierbare Typwächter für TypeScript bereitgestellt werden und lokale Binaries und Projekt-Paketmanager für eine nahtlose Integration genutzt werden","pt":"Habilita os agentes a formatar ou verificar o código usando configuração Prettier e regras de ignorar, fornecendo guardas de tipo seguros em tempo de execução e compostos para TypeScript, e utilizando binários locais e gerenciadores de pacotes de projeto para integração sem problemas","ru":"Наделяет агентов возможностью форматировать или проверять код с использованием конфигурации Prettier и правил игнорирования, обеспечивая безопасные и составные проверки типов для TypeScript, и использует локальные бинарные файлы и менеджеры пакетов проекта для бесшовной интеграции","ar":"تمكين الوكلاء من تنسيق أو التحقق من الشفرة باستخدام تكوين Prettier وقواعد الإهمال ، وتهيئة حماية أنواع زمنية تشغيل آمنة وقابلة للتأليف لTypeScript ، واستخدام الثنائيات المحلية والإدارة الحزم لمشروع التكامل السلس"},"useCases":{"en":["Automating code formatting for TypeScript projects","Verifying code consistency using Prettier configuration and ignore rules","Debugging formatting issues with --check and --write options"],"zh":["为TypeScript项目自动化代码格式化","使用Prettier配置和忽略规则验证代码一致性","使用--check和--write选项调试格式问题"],"ja":["TypeScriptプロジェクトのコードフォーマットを自動化する","Prettierの設定と無視ルールを使用してコードの一貫性を検証する","--checkおよび--writeオプションを使用してフォーマットの問題をデバッグする"],"ko":["TypeScript 프로젝트의 코드 형식화를 자동화하는 것","Prettier 구성 및 무시 규칙을 사용하여 코드 일관성을 확인하는 것","--check 및 --write 옵션을 사용하여 형식 지정 문제를 디버깅하는 것"],"es":["Automatizar el formato de código para proyectos de TypeScript","Verificar la coherencia del código utilizando configuración de Prettier y reglas de ignorar","Depurar problemas de formato con las opciones --check y --write"],"fr":["Automatiser le formatage de code pour les projets TypeScript","Vérifier la cohérence du code à l''aide de la configuration Prettier et des règles d''ignoration","Déboguer les problèmes de formatage avec les options --check et --write"],"de":["Automatisieren des Code-Formatierens für TypeScript-Projekte","Überprüfen der Code-Konsistenz unter Verwendung von Prettier-Konfiguration und Ignorierregeln","Debuggen von Formatierungsproblemen mit den Optionen --check und --write"],"pt":["Automatizar a formatação de código para projetos TypeScript","Verificar a consistência do código usando configuração Prettier e regras de ignorar","Depurar problemas de formatação com opções --check e --write"],"ru":["Автоматизировать форматирование кода для проектов TypeScript","Проверять согласованность кода с использованием конфигурации Prettier и правил игнорирования","Отладить проблемы форматирования с помощью опций --check и --write"],"ar":["توفير تنسيق تلقائي للشفرة لمشاريع TypeScript","التحقق من الاتساقية للشفرة باستخدام تكوين Prettier وقواعد الإهمال ","تصحيح مشاكل التنسيق باستخدام الخيارات --check و --write"]},"limitations":{"en":["Requires Prettier configuration and ignore rules setup","Designed specifically for TypeScript and compatible package managers","Needs access to repository instructions and AGENTS.md file"],"zh":["需要Prettier配置和忽略规则的设置","专门为TypeScript和兼容包管理器设计","需要访问存储库说明和AGENTS.md文件"],"ja":["Prettierの設定と無視ルールの設定が必要","TypeScriptと互換性のあるパッケージマネージャー専用に設計","リポジトリの説明とAGENTS.mdファイルへのアクセスが必要"],"ko":["Prettier 구성 및 무시 규칙 설정이 필요합니다","TypeScript 및 호환 패키지 관리자専用로 설계되었습니다","저장소 지침 및 AGENTS.md 파일에 대한 액세스가 필요합니다"],"es":["Requiere configuración de Prettier y reglas de ignorar","Diseñado específicamente para TypeScript y administradores de paquetes compatibles","Necesita acceso a instrucciones de repositorio y archivo AGENTS.md"],"fr":["Nécessite une configuration Prettier et des règles d''ignoration","Conçu spécifiquement pour TypeScript et les gestionnaires de paquets compatibles","Nécessite un accès aux instructions du référentiel et au fichier AGENTS.md"],"de":["Benötigt Prettier-Konfiguration und Ignorierregeln","Speziell für TypeScript und kompatible Paketmanager konzipiert","Benötigt Zugriff auf Repository-Anweisungen und die Datei AGENTS.md"],"pt":["Requer configuração Prettier e regras de ignorar","Projetado especificamente para TypeScript e gerenciadores de pacotes compatíveis","Necessita acesso às instruções do repositório e arquivo AGENTS.md"],"ru":["Требует настройки Prettier и правил игнорирования","Разработан специально для TypeScript и совместимых менеджеров пакетов","Требует доступа к инструкциям репозитория и файлу AGENTS.md"],"ar":["يتطلب تكوين Prettier وقواعد الإهمال ","صمم خصيصا لTypeScript والإدارة الحزم المتوافقة ","يحتاج إلى الوصول إلى تعليمات المستو