INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('nyaomaru/is-kit/prettier-format', 'prettier-format', 'nyaomaru', 'is-kit', 'community', 'prettier-format nyaomaru is-kit community The prettier-format skill formats or checks code using a Prettier configuration and ignore rules. It is designed for developers working with TypeScript, providing runtime-safe and composable type guards. Prettier 格式化工具是一种用于自动格式化 TypeScript 代码的工具，支持运行时安全、组合性和 ergonomics Prettier Format は、TypeScript コードの自動整形を実現するツールで、ランタイムセーフ、組み合わせ可能、エргノミクスをサポートしています Prettier 포맷팅 도구는 TypeScript 코드의 자동 포맷팅을 thực現하는 도구로, 런타임 안전성, 조합성 및 ergonomics를 지원합니다 Prettier Format es una herramienta ligera para formatear código según la configuración de Prettier. Es seguro en tiempo de ejecución y muy personalizable Prettier Format est un outil léger pour formater du code selon la configuration Prettier. Il est sécurisé en temps d''exécution et très personnalisable Prettier Format ist ein leichtes Tool zum Formatieren von Code gemäß der Prettier-Konfiguration. Es ist laufzeit-sicher und sehr anpassbar O Prettier Format é uma ferramenta leve para formatar e verificar código, compatível com TypeScript e outras tecnologias Prettier Format - это легкая утилита для форматирования и проверки кода, совместимая с TypeScript и другими технологиями أداة التنسيق Prettier Format هي أداة خفيفة لتنسيق وتصحيح الكود، متوافقة مع TypeScript وتقنيات أخرى how to use prettier-format prettier-format setup guide prettier-format alternative prettier-format vs eslint prettier-format install typescript code formatting zero-dependency toolkit isFoo style type guards Prettier 格式化工具 TypeScript 代码格式化 自动格式化 运行时安全 组合性 ergonomics Prettier 配置 忽略规则 Formats code using Prettier configuration and ignore rules Supports --check for verify formatting requests Supports --write for format or fix requests Prefer local binaries and the project''s package manager Compatible with npm package manager prettier-format is a lightweight, zero-dependency toolkit for building isFoo style type guards in TypeScript, ensuring runtime safety and composability.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mdrideout/junjo-ai-studio/prepare', 'community', 'mdrideout', 'junjo-ai-studio', 'mdrideout/junjo-ai-studio', 'prepare', 0, 0, 29, '2026-03-08T01:57:15.378Z', '2026-03-08T02:05:25.946Z', 'ee9fbabf70790ea3f7eeee824c1b4d7121ecea530cc4ac40a1181bf55101a89d', '{"id":"mdrideout/junjo-ai-studio/prepare","name":"prepare","description":{"en":"Prepare is an AI agent skill that enables developers to review core documents, setup Docker, and master ingestion ADR docs for a Junjo AI Studio task. It benefits developers working with AI agents.","zh":"准备 Junjo AI Studio 任务需要审查核心文档和配置，包括 README.md、AGENTS.md 和 Docker-compose 文件","ja":"Junjo AI Studio タスクの準備には、README.md、AGENTS.md、Docker-compose ファイルなどのコアドキュメントと設定の確認が必要です","ko":"준조 AI 스튜디오 작업을 준비하려면 README.md, AGENTS.md 및 Docker-compose 파일과 같은 핵심 문서 및 설정을 확인해야 합니다","es":"La preparación es un paso crucial para el éxito de tus proyectos de AI. Revisa los documentos clave y configura Docker para asegurarte de que estás listo para empezar.","fr":"La préparation est une étape cruciale pour le succès de vos projets d''IA. Révisez les documents clés et configurez Docker pour vous assurer que vous êtes prêt à commencer.","de":"Die Vorbereitung ist ein entscheidender Schritt für den Erfolg Ihrer KI-Projekte. Überprüfen Sie die wichtigsten Dokumente und konfigurieren Sie Docker, um sicherzustellen, dass Sie bereit sind, loszulegen.","pt":"Prepare o ambiente de desenvolvimento para AI Agents, revisando documentos como README.md e AGENTS.md, e configurando serviços com docker-compose.yml","ru":"Подготовьте среду разработки для ИИ Агентов, просмотрев документы, такие как README.md и AGENTS.md, и настроив сервисы с docker-compose.yml","ar":"أعد بيئة التطوير لعميل الذكاء الاصطناعي، من خلال مراجعة الوثائق مثل README.md و AGENTS.md، وتكوين الخدمات مع docker-compose.yml"},"seo":{"title":{"en":"