INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ProverCoderAI/effect-template/effect-ts-guide', 'effect-ts-guide', 'ProverCoderAI', 'effect-template', 'community', 'effect-ts-guide ProverCoderAI effect-template community The effect-ts-guide skill teaches Effect-TS fundamentals and best practices, applying them to user code and architecture questions, benefiting developers working with Node, Bun, or browser runtimes. Effect TS 是一个用于教学 Effect-TS 基础和最佳实践的技能，涵盖了 runtime、goal 和 constraints 的clarify Effect TS は、Effect-TS の基礎とベストプラクティスを教えるスキルで、runtime、goal、constraints のclarify を含む Effect TS는 Effect-TS의 기본과 베스트 프랙티스를 가르치는 스킬로, runtime, goal, constraints의 clarify를 포함 Effect TS es una habilidad para enseñar fundamentos y mejores prácticas de Effect TS. Aprende a aplicarlos a código y arquitectura de usuario Effect TS est une compétence pour enseigner les fondamentaux et les meilleures pratiques d''Effect TS. Apprenez à les appliquer au code et à l''architecture de l''utilisateur Effect TS ist eine Fähigkeit, um Grundlagen und Best Practices von Effect TS zu lehren. Erfahren Sie, wie Sie sie auf Benutzercode und -architektur anwenden O Effect TS Guide é uma ferramenta para ensinar fundamentos e melhores práticas de Effect TS, aplicando-os a perguntas de código e arquitetura. Руководство по Effect TS - это инструмент для обучения основам и лучшим практикам Effect TS, применяемым к вопросам кода и архитектуры. دليل Effect TS هو أداة لتعليم أساسيات وأفضل الممارسات ل Effect TS، وتطبيقها على أسئلة الشفرة والهيكل how to use effect-ts-guide effect-ts-guide setup guide effect-ts-guide vs typescript what is effect-ts-guide effect-ts-guide install effect-ts-guide alternative effect-ts-guide best practices effect-ts-guide for node developers effect-ts-guide for browser runtime Effect TS 教学 Effect-TS 基础 AIエージェント 用户代码优化 架构问题解决 runtime 的 clarify pure domain logic effects tagged error types Context.Tag 服务接口 Clarifies context for runtime environments like Node, Bun, or browser Separates core vs shell logic, identifying pure domain logic and effects Models errors and dependencies using tagged error types and Context.Tag service interfaces Composes with Effect using pipe/Effect.gen for efficient code architecture Applies Effect-TS fundamentals to user code and architecture questions effect-ts-guide is a skill that provides guidance on Effect-TS fundamentals, best practices, and application to real-world code and architecture questions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('blahami2/event-manager/bug-fixer', 'community', 'blahami2', 'event-manager', 'blahami2/event-manager', 'bug-fixer', 0, 0, 29, '2026-03-08T01:57:15.382Z', '2026-03-08T02:05:41.424Z', 'cd47b19d0a3b7652d9498518fb8b3fe8e76f480aad0ee5cb919aa4f500b32014', '{"id":"blahami2/event-manager/bug-fixer","name":"bug-fixer","description":{"en":"The bug-fixer skill diagnoses and fixes code bugs using automated regression tests, benefiting expert debuggers and developers. It precisely identifies root causes and proposes minimal fixes.","zh":"bug-fixer 是一个自动化代码调试和回归测试的工具，帮助开发者快速定位和修复代码中的 bug","ja":"bug-fixer はコードデバッグと回帰テストを自動化するツールで、開発者がコード内のバグを迅速に特定して修正できるようにします","ko":"bug-fixer는 코드 디버깅과 회귀 테스트를 자동화하는 도구로, 개발자가 코드 내의 버그를 빠르게 식별하고 수정할 수 있도록 합니다","es":"bug-fixer es una herramienta que ayuda a diagnosticar y solucionar errores en el código con pruebas de regresión automatizadas. Mejora la eficiencia de depuración","fr":"bug-fixer est un outil qui aide à diagnostiquer et résoudre les erreurs de code avec des tests de régression automatisés. Améliorez l''efficacité de débogage","de":"bug-fixer ist ein Tool, das bei der Fehlerdiagnose und -behebung im Code mit automatisierten Regressionstests hilft. Verbessern Sie die Effizienz der Fehlersuche","pt":"O Bug-Fixer é uma ferramenta de diagnóstico e correção de erros em código que utiliza testes de regressão automatizados","ru":"ИИ Агент Bug-Fixer - это инструмент для диагностики и исправления ошибок в коде с помощью автоматизированных тестов","ar":"Bug-Fixer هو أداة لتشخيص وأصلاح الأخطاء في الكود باستخدام الاختبارات الارتجاعية الآلية"},"seo":{"title":{"en":"bug-fixer: Automated Regression Testing Setup Guide | AI ...","zh":"bug-fixer 工具：自动化回归测试和代码调试指南","ja":"bug-fixer ツール：自動化された回帰テストとコードデバッグのベストプラクティス","ko":"bug-fixer 도구: 자동화된 회귀 테스트와 코드 디버깅 설정 가이드","es":"Guía de configuración de b