INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('blahami2/event-manager/bug-fixer', 'bug-fixer', 'blahami2', 'event-manager', 'community', 'bug-fixer blahami2 event-manager community The bug-fixer skill diagnoses and fixes code bugs using automated regression tests, benefiting expert debuggers and developers. It precisely identifies root causes and proposes minimal fixes. bug-fixer 是一个自动化代码调试和回归测试的工具，帮助开发者快速定位和修复代码中的 bug bug-fixer はコードデバッグと回帰テストを自動化するツールで、開発者がコード内のバグを迅速に特定して修正できるようにします bug-fixer는 코드 디버깅과 회귀 테스트를 자동화하는 도구로, 개발자가 코드 내의 버그를 빠르게 식별하고 수정할 수 있도록 합니다 bug-fixer es una herramienta que ayuda a diagnosticar y solucionar errores en el código con pruebas de regresión automatizadas. Mejora la eficiencia de depuración bug-fixer est un outil qui aide à diagnostiquer et résoudre les erreurs de code avec des tests de régression automatisés. Améliorez l''efficacité de débogage bug-fixer ist ein Tool, das bei der Fehlerdiagnose und -behebung im Code mit automatisierten Regressionstests hilft. Verbessern Sie die Effizienz der Fehlersuche O Bug-Fixer é uma ferramenta de diagnóstico e correção de erros em código que utiliza testes de regressão automatizados ИИ Агент Bug-Fixer - это инструмент для диагностики и исправления ошибок в коде с помощью автоматизированных тестов Bug-Fixer هو أداة لتشخيص وأصلاح الأخطاء في الكود باستخدام الاختبارات الارتجاعية الآلية how to use bug-fixer bug-fixer setup guide automated regression testing tools bug-fixer vs manual debugging what is bug-fixer bug-fixer install bug-fixer alternative debugging with automated tests bug-fixer tutorial bug-fixer 代码调试 回归测试 AI 工具 自动化测试 代码优化 开发效率 bug 修复 Diagnoses bugs with automated regression tests Proposes minimal and correct fixes Follows precise and accurate response rules Breaks complex tasks into smaller, manageable steps Verifies fixes with automated tests bug-fixer is an AI agent skill that diagnoses and fixes bugs in code with automated regression tests, following precise and accurate rules.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('MrLesk/Backlog.md/context-hunter', 'community', 'MrLesk', 'Backlog.md', 'MrLesk/Backlog.md', 'context-hunter', 0, 0, 29, '2026-03-08T01:57:15.384Z', '2026-03-08T02:05:43.870Z', '8f634b3adef2d8f691d96827da4ade9e4ba7d332bd9a4d892560fe56893da8b0', '{"id":"MrLesk/Backlog.md/context-hunter","name":"context-hunter","description":{"en":"context-hunter is a tool for managing project collaboration between humans and AI Agents in a git ecosystem, enabling efficient workflow by classifying task complexity and running focused discovery loops.","zh":"Context Hunter 是一个用于管理项目协作的工具，帮助开发者优化代码管理和协作流程","ja":"Context Hunter は、プロジェクトの共同作業を管理するためのツールで、開発者がコード管理と共同作業のプロセスを最適化するのに役立ちます","ko":"Context Hunter는 프로젝트 협업을 관리하는 도구로 개발자가 코드 관리와 협업 프로세스를 최적화하는 데 도움이 됩니다","es":"Context Hunter es una herramienta de colaboración para proyectos de git que ayuda a los desarrolladores a gestionar tareas y clasificar la complejidad de las mismas","fr":"Context Hunter est un outil de collaboration pour les projets git qui aide les développeurs à gérer les tâches et à classer la complexité de celles-ci","de":"Context Hunter ist ein Kollaborationstool für Git-Projekte, das Entwicklern hilft, Aufgaben zu verwalten und die Komplexität zu klassifizieren","pt":"O Context Hunter é uma ferramenta de colaboração para desenvolvedores que trabalham com AI Agents em ecossistemas Git, permitindo uma descoberta focada e eficiente","ru":"ИИ Агент Context Hunter - это инструмент для сотрудничества разработчиков, работающих с ИИ Агентами в экосистеме Git, позволяющий сосредоточить поиск и повысить эффективность","ar":"وكلاء الذكاء الاصطناعي Context Hunter هو أداة للتعاون بين المطورين الذين يعملون مع وكلاء الذكاء الاصطناعي في بيئات Git، مما يسمح بالاكتشاف المُركز والفعال"},"seo":{"title":{"en":"context-hunter: Focused Discovery Loop for AI Agents | AI...","zh":"Context Hunter 设置指南：优化项目协作","ja":"Context Hunter 導入ガイド：AIエージェントと人間の共同作業を最適化","ko":"Context Hunter 사용자 가이드: 프로젝트 협업 최적화","es":"Guía de configuración de Context Hunter para agentes de IA","fr":"Guide de mise en place de Context Hunter pour les outils ...","de":"Einrichtungsleitfaden für Context Hunter in der KI-Entwic...","pt":"Guia de Configuração do Context Hunter: Ferramenta de Col...","ru":"Настройка ИИ Агента Context Hunter: Инструмент для Сотруд...","ar":"دليل إعداد Context Hunter: أداة للتعاون بين المطورين"},"description":{"en":"Streamline project collaboration with context-hunter. Learn how to run a focused discovery loop and classify task complexity for efficient workflow","zh":"了解 Context Hunter 如何帮助您优化项目协作，提高开发效率，并简化代码管理","ja":"Context Hunter を使用してプロジェクトの共同作業を最適化し、開発効率を向上させ、コード管理を簡素化する方法について学びます","ko":"Context Hunter로 프로젝트 협업을 최적화하고 개발 효율성을 높이고 코드 관리를 간소화하는 방법에 대해 알아보세요","es":"Optimice su flujo de trabajo con Context Hunter, un herramienta de colaboración para proyectos de git y agentes de IA","fr":"Améliorez votre flux de travail avec Context Hunter, un outil de collaboration pour les projets git et les outils d''IA","de":"Optimieren Sie Ihren Arbeitsablauf mit Context Hunter, einem Kollaborationstool für Git-Projekte und KI-Entwicklung","pt":"Aprenda a configurar o Context Hunter, uma ferramenta de colaboração para desenvolvedores que trabalham com AI Agents em ecossistemas Git","ru":"Узнайте, как настроить ИИ Агента Context Hunter, инструмент для сотрудничества разработчиков, работающих с ИИ Агентами в экосистеме Git","ar":"تعرف على كيفية إعداد Context Hunter، أداة للتعاون بين المطورين الذين يعملون مع وكلاء الذكاء الاصطناعي في بيئات Git"},"definition":{"en":"context-hunter is a tool that facilitates project collaboration by running a focused discovery loop, classifying task complexity into L0, L1, and L2 levels","zh":"Context Hunter 是一个用于优化项目协作和代码管理的工具","ja":"Context Hunter は、プロジェクトの共同作業とコード管理を最適化するためのツールです","ko":"Context Hunter는 프로젝트 협업과 코드 관리를 최적화하는 도구입니다","es":"Context Hunter es un agente de IA que ayuda a los desarrolladores a encontrar los archivos adecuados y a clasificar la complejidad de las tareas","fr":"Context Hunter est un outil d''IA qui aide les développeurs à trouver les fichiers appropriés et à classer la complexité des tâches","de":"Context Hunter ist ein KI-Tool, das Entwicklern hilft, die richtigen Dateien zu finden und die Komplexität von Aufgaben zu klassifizieren","pt":"O Context Hunter é uma ferramenta de colaboração que ajuda os desenvolvedores a encontrar os arquivos certos e realizar tarefas de forma eficiente","ru":"ИИ Агент Context Hunter - это инструмент для сотрудничества, который помогает разработчикам найти нужные файлы и выполнить задачи эффективно","ar":"وكلاء الذكاء الاصطناعي Context Hunter هو أداة للتعاون التي تساعد المطورين على العثور على الملفات الصحيحة وتنفيذ المهام بفعالية"},"features":{"en":["Classifies task complexity into L0 (trivial), L1 (moderate), and L2 (high-risk) levels","Runs a focused discovery loop to find the right files","Supports output by level, including no context brief for L0 tasks","Enables efficient workflow by proceeding directly for L0 tasks","Facilitates project collaboration between humans and AI Agents in a git ecosystem","Utilizes a git ecosystem for streamlined project management"],"zh":["支持分类任务复杂度（L0、L1、L2）","优化代码管理和协作流程","支持 Git 生态系统","提供有针对性的发现循环","简化代码编辑和修复过程","支持多级别输出（L0、L1、L2）"],"ja":["タスクの複雑さを分類する（L0、L1、L2）","コード管理と共同作業のプロセスを最適化する","Git エコシステムをサポートする","フォーカスしたディスカバリーループを提供する","コード編集と修復プロセスを簡素化する","マルチレベル出力をサポートする（L0、L1、L2）"],"ko":["작업 복잡도 분류 지원（L0, L1, L2）","코드 관리 및 협업 프로세스 최적화","Git 생태계 지원","목표 지향적 검색 루프 제공","코드 편집 및 수정 프로세스 간소화","다단계 출력 지원（L0, L1, L2）"],"es":["Clasificación de la complejidad de las tareas en tres niveles: L0, L1 y L2","Búsqueda enfocada de archivos relevantes en el ecosistema de git","Integración con la herramienta Backlog.md para la gestión de proyectos","Compatibilidad con la colaboración entre humanos y agentes de IA","Soporte para la detección de cambios de comportamiento en el código","Análisis de la complejidad de las tareas para una mejor planificación"],"fr":["Classification de la complexité des tâches en trois niveaux : L0, L1 et L2","Recherche ciblée de fichiers pertinents dans l''écosystème git","Intégration avec l''outil Backlog.md pour la gestion de projets","Compatibilité avec la collaboration entre les humains et les outils d''IA","Support pour la détection des changements de comportement dans le code","Analyse de la complexité des tâches pour une meilleure planification"],"de":["Klassifizierung der Komplexität von Aufgaben in drei Ebenen: L0, L1 und L2","Fokussierte Suche nach relevanten Dateien im Git-Ökosystem","Integration mit der Backlog.md-Tool für die Projektverwaltung","Kompatibilität mit der Zusammenarbeit zwischen Menschen und KI-Tools","Unterstützung für die Erkennung von Verhaltensänderungen im Code","Analyse der Komplexität von Aufgaben für eine bessere Planung"],"pt":["Classificação de complexidade de tarefas em L0, L1 e L2","Descoberta focada de arquivos relevantes","Integração com ecossistemas Git","Suporte a colaboração entre humanos e AI Agents","Otimização de processos de desenvolvimento"],"ru":["Классификация сложности задач на L0, L1 и L2","Сосредоточенный поиск релевантных файлов","Интеграция с экосистемой Git","Поддержка сотрудничества между людьми и ИИ Агентами","Оптимизация процессов разработки"],"ar":["تصنيف التعقيدات في المهام إلى L0، L1 و L2","اكتشاف مُركز للملفات ذات الصلة","التكامل مع بيئات Git","دعم التعاون بين البشر ووكلاء الذكاء الاصطناعي","تحسين عمليات التطوير"]},"keywords":{"en":["how to use context-hunter","what is context-hunter","context-hunter alternative","context-hunter vs git","context-hunter install","context-hunter setup guide","context-hunter for AI Agents","git ecosystem project management","focused discovery loop","task complexity classification"],"zh":["Context Hunter","项目协作","代码管理","Git","AI工具","代码编辑","任务管理","协作流程","开发效率"],"ja":["Context Hunter","プロジェクトの共同作業","コード管理","Git","AIエージェント","コード編集","タスク管理","共同作業のプロセス","開発効率"],"ko":["Context Hunter","프로젝트 협업","코드 관리","Git","AI 도구","코드 편집","작업 관리","협업 프로세스","개발 효율성"],"es":["agentes de IA","herramientas de colaboración","gestión de proyectos","git","clasificación de la complejidad","búsqueda de archivos","Backlog.md","desarrollo de software","colaboración entre humanos y agentes de IA"],"fr":["outils d''IA","outils de collaboration","gestion de projets","git","classification de la complexité","recherche de fichiers","Backlog.md","développement de logiciels","collaboration entre les humains et les outils d''IA"],"de":["KI-Tools","Kollaborationstools","Projektverwaltung","Git","Klassifizierung der Komplexität","Dateisuche","Backlog.md","Softwareentwicklung","Zusammenarbeit zwischen Menschen und KI-Tools"],"pt":["Context Hunter","ferramenta de colaboração","desenvolvedores","AI Agents","ecossistemas Git","classificação de complexidade","descoberta focada","integração com Git"],"ru":["ИИ Агент Context Hunter","инструмент для сотрудничества","разработчики","ИИ Агенты","экосистема Git","классификация сложности","сосредоточенный поиск","интеграция с Git"],"ar":["وكلاء الذكاء الاصطناعي Context Hunter","أداة للتعاون","المطورين","وكلاء الذكاء الاصطناعي","بيئات Git","تصنيف التعقيدات","اكتشاف مُركز","التكامل مع Git"]}},"owner":"MrLesk","repo":"Backlog.md","repoPath":"MrLesk/Backlog.md","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.384Z","topics":[],"category":"community","skillMd":{"name":"context-hunter","description":"MUST run before any code implementation task. Classifies complexity, discovers local conventions, finds reusable patterns, and prevents blind coding. Invoke this skill before writing or modifying code.","bodyPreview":"# Context Hunter\n\nBefore writing code, run a focused discovery loop.\nDo not load everything. Find the right files.\n\n## Complexity Gate\n\nClassify task complexity first:\n\n- `L0 (trivial)`: typos, renames, copy-only edits, obvious single-line fixes with no behavior change.\n- `L1 (moderate)`: behavior changes in one bounded area.\n- `L2 (high-risk)`: cross-module changes, data semantics, refactors, architecture-impacting work.\n\nOutput by level:\n- `L0`: no context brief, proceed directly.\n- `L1`: writ","body":"# Context Hunter\n\nBefore writing code, run a focused discovery loop.\nDo not load everything. Find the right files.\n\n## Complexity Gate\n\nClassify task complexity first:\n\n- `L0 (trivial)`: typos, renames, copy-only edits, obvious single-line fixes with no behavior change.\n- `L1 (moderate)`: behavior changes in one bounded area.\n- `L2 (high-risk)`: cross-module changes, data semantics, refactors, architecture-impacting work.\n\nOutput by level:\n- `L0`: no context brief, proceed directly.\n- `L1`: write a micro-brief.\n- `L2`: write a full context brief.\n\nRe-evaluate level during discovery and implementation.\nIf new evidence shows higher complexity than initially classified, upgrade the level and apply the stricter workflow.\n\n## Core Behavior\n\nAct like a senior engineer who asks the next useful question:\n1. **Assess completeness**: Check whether the request omits expected concerns seen in analogous code.\n2. **Discover selectively**: Read the minimum set of relevant files.\n3. **Validate assumptions**: Confirm with tests/config/history.\n4. **Synthesize**: Capture findings before coding for `L1/L2`.\n\n## Discovery Workflow (Before Coding)\n\n### 1) Assess Request Completeness\n\nAsk: \"What is likely missing?\"\n\nExamples:\n- Similar endpoints include auth/validation. Is that expected here?\n- This area uses soft-delete semantics. Should this operation follow that?\n- Similar flows emit telemetry/error states. Should this change do the same?\n- Existing module boundaries suggest a different placement. Is current request still correct?\n\n### 2) Run Targeted Discovery\n\nPrioritize these in order:\n1. Find analogous implementations and copy their structure.\n2. Trace data flow for similar features end-to-end.\n3. Identify reusable utilities before creating new helpers.\n4. Inspect nearby tests to infer team priorities and edge cases.\n5. Read recent commits in the same area for current direction.\n\nPortable discovery actions:\n- Search for feature/domain terms in relevant directories.\n- Enumerate nearby files in the affected area.\n- Inspect recent change history for touched paths.\n- Run targeted validation first, then broader project checks as needed.\n\n### 3) Probe for Silent Knowledge\n\nLook for implicit rules encoded in code:\n- Soft-delete, audit, or historical retention patterns (for data-touching changes).\n- Naming conventions (`userId` vs `user_id`) and file placement norms.\n- Existing design system choices (for this repo: Nuxt + Vue + Tailwind 4.1 patterns).\n- “Dead but dangerous” APIs/functions that exist but are no longer preferred.\n\n### 4) Confidence-Based Stop Rule\n\nStop discovery when confidence is high enough to predict likely review feedback.\nIf you cannot anticipate reviewer concerns yet, keep looking.\n\n### 5) Produce Scaled Discovery Output\n\nFor `L1`, write a micro-brief:\n- Closest analog and chosen pattern.\n- Main risk or ambiguity.\n\nFor `L2`, write a full context brief:\n- Analogous files reviewed (with paths).\n- Patterns to follow (state/data/error handling/naming).\n- Reusable utilities/components/composables identified.\n- Risks and unknowns.\n\nFor `L1/L2`, keep an internal discovery log:\n- Files checked.\n- Patterns inferred.\n- Decisions made from evidence.\n- Naming evidence for new identifiers (`new name -> analog paths -> extracted pattern`).\n\n## Clarification Policy\n\n- Prefer fewer questions.\n- Ask only when the answer would change implementation approach.\n- If convention is clear, proceed silently.\n- Escalate only genuine ambiguity/conflict or product-level tradeoffs.\n\n## During Implementation\n\nChanges should look native to the codebase:\n- Reuse existing abstractions first.\n- Match existing module boundaries and naming.\n- Follow established error-handling and testing style.\n- Prefer consistency over novelty.\n\nNaming derivation rule:\n- Do not invent names from general priors.\n- For each new identifier family (file/function/variable/class/route), derive naming from closest local analogs.\n- Use at least 2 analogous examples when available before finalizing a new naming pattern.\n- If no analog exists, introduce the new term explicitly and record it as a no-analog exception.\n\nIf requirements conflict with discovered conventions:\n- Flag the conflict explicitly.\n- Propose 1-2 alternatives aligned with existing patterns.\n- Ask for decision when tradeoffs are product/architecture-level.\n\n## Verification\n\nAfter coding:\n- Run targeted validation for changed area first.\n- Run broader checks appropriate for risk (`typecheck`, lint/check, tests as needed).\n- Confirm no new pattern drift was introduced.\n\n## Checklist\n\n`L0`:\n- [ ] Confirmed change is truly trivial and safe to execute without full discovery.\n\n`L1/L2`:\n- [ ] Classified complexity (`L0/L1/L2`) before discovery\n- [ ] Studied analogous features in the codebase\n- [ ] Checked for reusable utilities\n- [ ] Reviewed test patterns for similar functionality\n- [ ] Assessed request completeness before implementation\n- [ ] Identified at least one silent convention/risk\n- [ ] Produced the required artifact for the chosen level\n- [ ] Kept an internal discovery log for `L1/L2`\n- [ ] All new names were derived from codebase analogs, or marked as intentional no-analog exceptions\n- [ ] Verified final approach matches existing patterns\n"},"lastSynced":"2026-03-08T02:05:43.870Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing efficient project collaboration and task complexity management in git ecosystems.","zh":"适合需要在git生态系统中进行高效项目协作和任务复杂性管理的AI代理。","ja":"gitエコシステムで効率的なプロジェクトの共同作業とタスクの複雑さ管理が必要なAIエージェントに適しています。","ko":"git 생태계에서 효율적인 프로젝트 협업 및 작업 복잡성 관리가 필요한 AI 에이전트에 적합합니다.","es":"Perfecto para agentes de IA que necesitan una colaboración de proyecto eficiente y una gestión de la complejidad de las tareas en ecosistemas git.","fr":"Parfait pour les agents IA nécessitant une collaboration de projet efficace et une gestion de la complexité des tâches dans les écosystèmes git.","de":"Perfekt für KI-Agents, die eine effiziente Projektzusammenarbeit und eine Komplexitätsverwaltung von Aufgaben in git-Ökosystemen benötigen.","pt":"Perfeito para Agentes de IA que necessitam de colaboração de projeto eficiente e gestão de complexidade de tarefas em ecossistemas git.","ru":"Идеально для ИИ-агентов, которым необходима эффективная сотрудничество в проектах и управление сложностью задач в экосистемах git.","ar":"مثالي لعمليات الوكيل الذكي التي تحتاج إلى تعاون مشروع فعال وإدارة تعقيد المهام في بيئات جيت."},"recommendation":{"en":"Empowers agents to classify task complexity using levels such as L0, L1, and L2, and run focused discovery loops, streamlining workflow and enhancing collaboration with humans through git ecosystems and complexity gates.","zh":"赋予代理人使用L0、L1和L2等级别对任务复杂性进行分类的能力，并运行有针对性的发现循环，从而简化工作流程并通过git生态系统和复杂性门提高与人类的协作。","ja":"L0、L1、L2などのレベルを使用してタスクの複雑さを分類し、集中した発見ループを実行する機能をエージェントに与え、ワークフローを合理化し、gitエコシステムと複雑さゲートを介して人間との共同作業を強化します。","ko":"L0, L1 및 L2와 같은 수준을 사용하여 작업 복잡성을 분류하고 집중적인 발견 루프를 실행하여 워크플ロー를 간소화하고 git 생태계 및 복잡성 게이트를 통해 인간과의 협력을 강화하는 에이전트의 능력을 부여합니다.","es":"Habilita a los agentes a clasificar la complejidad de las tareas utilizando niveles como L0, L1 y L2, y ejecutar bucles de descubrimiento enfocados, simplificando el flujo de trabajo y mejorando la colaboración con humanos a través de ecosistemas git y puertas de complejidad.","fr":"Permet aux agents de classer la complexité des tâches en utilisant des niveaux tels que L0, L1 et L2, et d''exécuter des boucles de découverte ciblées, simplifiant le flux de travail et améliorant la collaboration avec les humains à travers les écosystèmes git et les portes de complexité.","de":"Ermächtigt Agents, die Komplexität von Aufgaben mit Hilfe von Ebenen wie L0, L1 und L2 zu klassifizieren und fokussierte Erkundungsschleifen auszuführen, wodurch der Arbeitsablauf gestrafft und die Zusammenarbeit mit Menschen über git-Ökosysteme und Komplexitätstore verbessert wird.","pt":"Habilita os agentes a classificar a complexidade das tarefas usando níveis como L0, L1 e L2, e executar loops de descoberta focados, simplificando o fluxo de trabalho e melhorando a colaboração com humanos por meio de ecossistemas git e portões de complexidade.","ru":"Наделяет агентов возможностью классифицировать сложность задач с использованием уровней, таких как L0, L1 и L2, и запускать сосредоточенные циклы открытия, упрощая рабочий процесс и улучшая сотрудничество с людьми через экосистемы git и ворота сложности.","ar":"تمكّن الوكلاء من تصنيف تعقيد المهام باستخدام مستويات مثل L0 و L1 و L2، وتشغيل دوائر اكتشاف محددة، مبسطًا تدفق العمل وتحسين التعاون مع البشر من خلال بيئات جيت وبوابات التعقيد."},"useCases":{"en":["Classifying task complexity for efficient workflow management","Running focused discovery loops for targeted file analysis","Streamlining collaboration between humans and AI agents in git ecosystems"],"zh":["为高效的工作流管理分类任务复杂性","运行有针对性的发现循环以进行针对性的文件分析","简化git生态系统中人类和AI代理之间的协作"],"ja":["効率的なワークフロー管理のためのタスクの複雑さを分類する","対象ファイルの分析のための集中した発見ループを実行する","gitエコシステムでの人間とAIエージェントの共同作業を合理化する"],"ko":["효율적인 워크플ロー 관리를 위한 작업 복잡성 분류","대상 파일 분석을 위한 집중적인 발견 루프 실행","git 생태계에서 인간과 AI 에이전트 간의 협력을 간소화하는"],"es":["Clasificar la complejidad de las tareas para una gestión eficiente del flujo de trabajo","Ejecutar bucles de descubrimiento enfocados para un análisis de archivos dirigido","Simplificar la colaboración entre humanos y agentes de IA en ecosistemas git"],"fr":["Classer la complexité des tâches pour une gestion efficace du flux de travail","Exécuter des boucles de découverte ciblées pour une analyse de fichiers ciblée","Simplifier la collaboration entre les humains et les agents IA dans les écosystèmes git"],"de":["Die Komplexität von Aufgaben für eine effiziente Arbeitsablaufverwaltung klassifizieren","Fokussierte Erkundungsschleifen für eine gezielte Dateianalyse ausführen","Die Zusammenarbeit zwischen Menschen und KI-Agents in git-Ökosystemen optimieren"],"pt":["Classificar a complexidade das tarefas para gestão de fluxo de trabalho eficiente","Executar loops de descoberta focados para análise de arquivos direcionada","Simplificar a colaboração entre humanos e agentes de IA em ecossistemas git"],"ru":["Классифицировать сложность задач для эффективного управления рабочим процессом","Запускать сосредоточенные циклы открытия для целевой анализе файлов","Упрощать сотрудничество между людьми и ИИ-агентами в экосистемах git"],"ar":["تصنيف تعقيد المهام لإدارة تدفق العمل الفعال","تشغيل دوائر اكتشاف محددة لتحليل الملفات المستهدفة","تبسيط التعاون بين البشر ووكلاء الذكاء الاصطناعي في بيئات جيت"]},"limitations":{"en":["Requires git ecosystem integration","Limited to task complexity classification and discovery loops"],"zh":["需要git生态系统集成","仅限于任务复杂性分类和发现循环"],"ja":["gitエコシステムの統合が必要","タスクの複雑さの分類と発見ループに限定される"],"ko":["git 생태계 통합 필요","작업 복잡성 분류 및 발견 루프에만 제한됨"],"es":["Requiere integración con el ecosistema git","Limitado a la clasificación de la complejidad de las tareas y los bucles de descubrimiento"],"fr":["Nécessite une intégration avec l''écosystème git","Limité à la classification de la complexité des tâches et aux boucles de découverte"],"de":["Benötigt eine Integration in das git-Ökosystem","Begrenzt auf die Klassifizierung der Komplexität von Aufgaben und Erkundungsschleifen"],"pt":["Requer integração com ecossistemas git","Limitado à classificação de complexidade de tarefas e loops de descoberta"],"ru":["Требует интеграции с экосистемами git","Ограничен классификацией сложности задач и циклами открытия"],"ar":["يتطلب التكامل مع بيئات جيت","محدود بتصنيف تعقيد المهام ودوارات الاكتشاف"]},"version":4},"contentHash":"8f634b3adef2d8f691d96827da4ade9e4ba7d332bd9a4d892560fe56893da8b0","qualityScore":29}');
