INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('MrLesk/Backlog.md/context-hunter', 'context-hunter', 'MrLesk', 'Backlog.md', 'community', 'context-hunter MrLesk Backlog.md community context-hunter is a tool for managing project collaboration between humans and AI Agents in a git ecosystem, enabling efficient workflow by classifying task complexity and running focused discovery loops. Context Hunter 是一个用于管理项目协作的工具，帮助开发者优化代码管理和协作流程 Context Hunter は、プロジェクトの共同作業を管理するためのツールで、開発者がコード管理と共同作業のプロセスを最適化するのに役立ちます Context Hunter는 프로젝트 협업을 관리하는 도구로 개발자가 코드 관리와 협업 프로세스를 최적화하는 데 도움이 됩니다 Context Hunter es una herramienta de colaboración para proyectos de git que ayuda a los desarrolladores a gestionar tareas y clasificar la complejidad de las mismas Context Hunter est un outil de collaboration pour les projets git qui aide les développeurs à gérer les tâches et à classer la complexité de celles-ci Context Hunter ist ein Kollaborationstool für Git-Projekte, das Entwicklern hilft, Aufgaben zu verwalten und die Komplexität zu klassifizieren O Context Hunter é uma ferramenta de colaboração para desenvolvedores que trabalham com AI Agents em ecossistemas Git, permitindo uma descoberta focada e eficiente ИИ Агент Context Hunter - это инструмент для сотрудничества разработчиков, работающих с ИИ Агентами в экосистеме Git, позволяющий сосредоточить поиск и повысить эффективность وكلاء الذكاء الاصطناعي Context Hunter هو أداة للتعاون بين المطورين الذين يعملون مع وكلاء الذكاء الاصطناعي في بيئات Git، مما يسمح بالاكتشاف المُركز والفعال how to use context-hunter what is context-hunter context-hunter alternative context-hunter vs git context-hunter install context-hunter setup guide context-hunter for AI Agents git ecosystem project management focused discovery loop task complexity classification Context Hunter 项目协作 代码管理 Git AI工具 代码编辑 任务管理 协作流程 开发效率 Classifies task complexity into L0 (trivial), L1 (moderate), and L2 (high-risk) levels Runs a focused discovery loop to find the right files Supports output by level, including no context brief for L0 tasks Enables efficient workflow by proceeding directly for L0 tasks Facilitates project collaboration between humans and AI Agents in a git ecosystem Utilizes a git ecosystem for streamlined project management context-hunter is a tool that facilitates project collaboration by running a focused discovery loop, classifying task complexity into L0, L1, and L2 levels');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ZafTec/zaf_tech_landing/astro-tailwind-expert', 'community', 'ZafTec', 'zaf_tech_landing', 'ZafTec/zaf_tech_landing', 'astro-tailwind-expert', 0, 0, 29, '2026-03-08T01:57:15.389Z', '2026-03-08T02:06:01.159Z', 'cffdb3f5842fd605493e958275dc5db6185307ab6e86e58898917030d226efa6', '{"id":"ZafTec/zaf_tech_landing/astro-tailwind-expert","name":"astro-tailwind-expert","description":{"en":"The astro-tailwind-expert skill enables developers to efficiently build and manage Astro projects with Tailwind styling. It streamlines routing and layout management.","zh":"Astro Tailwind Expert 是一个强大的开发工具，支持 Astro 和 Tailwind CSS，提供高效的路由和布局管理","ja":"Astro + Tailwind Expert は、Astro と Tailwind CSS をサポートする強力な開発ツールで、効率的なルーティングとレイアウト管理を提供します","ko":"Astro Tailwind Expert는 Astro와 Tailwind CSS를 지원하는 강력한 개발 도구로, 효율적인 라우팅과 레이아웃 관리를 제공합니다","es":"El experto en Astro con Tailwind CSS ayuda a crear sitios web personalizados con routing y estilos globales","fr":"L''expert en Astro avec Tailwind CSS aide à créer des sites web personnalisés avec routage et styles globaux","de":"Der Experte für Astro mit Tailwind CSS hilft bei der Erstellung von benutzerdefinierten Websites mit Routing und globalen Stilen","pt":"O Astro + Tailwind Expert é uma combinação poderosa para desenvolvimento web. Aprenda a configurar e usar essas tecnologias em seu próximo projeto","ru":"ИИ Агент Astro + Tailwind Expert представляет собой мощную комбинацию для веб-разработки. Узнайте, как настроить и использовать эти технологии в своем следующем проекте","ar":"ال AI Astro + Tailwind Expert هو مزيج قوي لتطوير الويب. تعلم كيفية إعداد واستخدام هذه التكنولوجيا في مشروعك التالي"},"seo":{"title":{"en":"astro-tailwind-expert: Astro and Tailwind Setup Guide | A...","zh":"Astro Tailwind Expert 设置指南 - AIエージェント","ja":"Astro + Tailwind Expert セットアップガイド - AIエージェント","ko":"Astro Tailwind Expert 설정 가이드 - AI 에이전트","es":"Guía de configuración de Astro con Tailwind CSS","fr":"Guide de mise en place d''Astro avec Tailwind CSS","de":"Einrichtungsleitfaden für Astro mit Tailwind CSS","pt":"Guia de Configuração Astro + Tailwind Expert","ru":"ИИ Агент Astro + Tailwind Expert: Настройка и Лучшие Прак...","ar":"دليل إعداد Astro + Tailwind Expert لل.AI"},"description":{"en":"Unlock efficient development with astro-tailwind-expert. Learn how to leverage Astro and Tailwind for seamless routing and styling. Get started now!","zh":"了解 Astro Tailwind Expert 的技术细节，包括路由、布局和全局样式，提升开发效率","ja":"Astro + Tailwind Expert の技術的な詳細を学び、ルーティング、レイアウト、グローバルスタイルを理解して開発効率を向上させる","ko":"Astro Tailwind Expert의 기술적인 세부 사항을 살펴보고, 라우팅, 레이아웃, 글로벌 스타일을 이해하여 개발 효율성을 높여보세요","es":"Aprende a configurar Astro con Tailwind CSS para crear sitios web personalizados con routing y estilos globales","fr":"Découvrez comment configurer Astro avec Tailwind CSS pour créer des sites web personnalisés avec routage et styles globaux","de":"Erfahren Sie, wie Sie Astro mit Tailwind CSS konfigurieren, um benutzerdefinierte Websites mit Routing und globalen Stilen zu erstellen","pt":"Aprenda a configurar o Astro + Tailwind Expert com nosso guia passo a passo e melhore suas habilidades de desenvolvimento web","ru":"Узнайте, как настроить Astro + Tailwind Expert с помощью нашего пошагового руководства и улучшите свои навыки веб-разработки с ИИ Агентами","ar":"تعلم كيفية إعداد Astro + Tailwind Expert باستخدام دليلنا خطوة بخطوة وتحسين مهاراتك في تطوير الويب مع أدوات AI"},"definition":{"en":"astro-tailwind-expert is a skill that integrates Astro and Tailwind for optimized web development, utilizing technologies like Vite and TypeScript.","zh":"Astro Tailwind Expert 是一个集成 Astro 和 Tailwind CSS 的开发工具，用于构建高性能 Web 应用","ja":"Astro + Tailwind Expert は、Astro と Tailwind CSS を統合した開発ツールで、高性能な Web アプリケーションを構築するために使用されます","ko":"Astro Tailwind Expert는 Astro와 Tailwind CSS를 통합한 개발 도구로, 고성능 웹 애플리케이션을 구축하는 데 사용됩니다","es":"Un experto en Astro con Tailwind CSS es una herramienta de AI que ayuda a configurar y personalizar sitios web con tecnologías de vanguardia","fr":"Un expert en Astro avec Tailwind CSS est un outil d''IA qui aide à configurer et personnaliser des sites web avec des technologies de pointe","de":"Ein Experte für Astro mit Tailwind CSS ist ein AI-Tool, das hilft, Websites mit modernen Technologien zu konfigurieren und anzupassen","pt":"O Astro + Tailwind Expert é uma combinação de tecnologias para desenvolvimento web que inclui Astro, Tailwind e Vite","ru":"ИИ Агент Astro + Tailwind Expert - это комбинация технологий для веб-разработки, включающая Astro, Tailwind и Vite","ar":"AI Astro + Tailwind Expert هو مزيج من التكنولوجيا لتطوير الويب يتضمن Astro و Tailwind و Vite"},"features":{"en":["Utilizes Astro for routing, treating src/pages/ as the routing surface","Leverages Tailwind v4 via @tailwindcss/vite for styling","Manages shared structure in src/layouts/ with a default layout in src/layouts/Layout.astro","Loads global styles from src/styles/global.css","Supports aliasing with @/* for src/*, configured in tsconfig.json","Streamlines build output in the dist directory"],"zh":["支持 Astro 路由","提供 Tailwind CSS 布局管理","全局样式加载","使用 @tailwindcss/vite 集成","支持 src/pages/ 路由表面","默认布局在 src/layouts/Layout.astro 中"],"ja":["Astro ルーティングのサポート","Tailwind CSS レイアウト管理の提供","グローバルスタイルの読み込み","@tailwindcss/vite での統合","src/pages/ ルーティング表面のサポート","デフォルトレイアウトは src/layouts/Layout.astro にあります"],"ko":["Astro 라우팅 지원","Tailwind CSS 레이아웃 관리 제공","글로벌 스타일 로딩","@tailwindcss/vite 통합","src/pages/ 라우팅 표면 지원","기본 레이아웃은 src/layouts/Layout.astro에 있습니다"],"es":["Routing basado en archivos `.astro` y `.md`","Estructuras compartidas en `src/layouts/`","Estilos globales en `src/styles/global.css`","Integración con Tailwind v4 a través de `@tailwindcss/vite`","Alias `@/*` para `src/*` configurado en `tsconfig.json`"],"fr":["Routage basé sur les fichiers `.astro` et `.md`","Structures partagées dans `src/layouts/`","Styles globaux dans `src/styles/global.css`","Intégration avec Tailwind v4 via `@tailwindcss/vite`","Alias `@/*` pour `src/*` configuré dans `tsconfig.json`"],"de":["Routing basierend auf Dateien `.astro` und `.md`","Gemeinsame Strukturen in `src/layouts/`","Globale Styles in `src/styles/global.css`","Integration mit Tailwind v4 über `@tailwindcss/vite`","Alias `@/*` für `src/*` konfiguriert in `tsconfig.json`"],"pt":["Suporte a Astro para routing e gerenciamento de rotas","Integração com Tailwind v4 via @tailwindcss/vite","Uso de layouts compartilhados em src/layouts/","Carregamento de estilos globais em src/styles/global.css","Alias @/* para src/* configurado em tsconfig.json"],"ru":["Поддержка Astro для маршрутизации и управления маршрутами","Интеграция с Tailwind v4 через @tailwindcss/vite","Использование общих макетов в src/layouts/","Загрузка глобальных стилей в src/styles/global.css","Псевдоним @/* для src/*, настроенный в tsconfig.json"],"ar":["دعم Astro لتحديد المسار وإدارة المسارات","التكامل مع Tailwind v4 عبر @tailwindcss/vite","استخدام تخطيطات مشتركة في src/layouts/","تحميل أنماط عالمية في src/styles/global.css","الاسم المستعار @/* ل src/* ، يتم تحديده في tsconfig.json"]},"keywords":{"en":["how to use astro-tailwind-expert","astro-tailwind-expert setup guide","what is astro-tailwind-expert","astro-tailwind-expert vs other frameworks","astro-tailwind-expert install","astro and tailwind integration","tailwind v4 tutorial","astro routing tutorial","vite and typescript setup"],"zh":["Astro Tailwind Expert","AIエージェント","开发工具","路由管理","布局管理","全局样式","Tailwind CSS","Astro","高性能 Web 应用"],"ja":["Astro + Tailwind Expert","AIエージェント","開発ツール","ルーティング管理","レイアウト管理","グローバルスタイル","Tailwind CSS","Astro","高性能 Web アプリケーション"],"ko":["Astro Tailwind Expert","AI 에이전트","개발 도구","라우팅 관리","레이아웃 관리","글로벌 스타일","Tailwind CSS","Astro","고성능 웹 애플리케이션"],"es":["astro tailwind css","configuración de astro","tailwind css para astro","routing en astro","estilos globales en astro","desarrollo web con astro","herramientas de ai para desarrollo web"],"fr":["astro tailwind css","configuration d''astro","tailwind css pour astro","routage dans astro","styles globaux dans astro","développement web avec astro","outils d''ia pour le développement web"],"de":["astro tailwind css","konfiguration von astro","tailwind css für astro","routing in astro","globale styles in astro","webentwicklung mit astro","ai-tools für webentwicklung"],"pt":["astro tailwind expert","desenvolvimento web com astro","tailwind css tutorial","vite js exemplo","astro routing exemplo","tailwind v4 configuração"],"ru":["ИИ Агент astro tailwind expert","веб-разработка с astro","tailwind css урок","vite js пример","astro маршрутизация пример","tailwind v4 настройка"],"ar":["AI Astro + Tailwind Expert","تطوير الويب مع Astro","دورة Tailwind CSS","مثال Vite JS","مثال Astro routing","إعداد Tailwind v4"]}},"owner":"ZafTec","repo":"zaf_tech_landing","repoPath":"ZafTec/zaf_tech_landing","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.389Z","topics":[],"category":"community","skillMd":{"name":"astro-tailwind-expert","description":"Expert workflows for developing Astro sites in this repository with Tailwind CSS v4 (via @tailwindcss/vite). Use when creating or modifying Astro pages, layouts, components, routes, Markdown pages, or Tailwind styling/configuration for this project.","bodyPreview":"# Astro + Tailwind Expert (Repo Skill)\n\n## Use these project facts\n- Treat `src/pages/` as the routing surface. Each `.astro` or `.md` file becomes a route.\n- Keep shared structure in `src/layouts/`. The default layout is `src/layouts/Layout.astro`.\n- Load global styles from `src/styles/global.css` (already imported in `Layout.astro`).\n- Rely on Tailwind v4 via `@tailwindcss/vite` in `astro.config.mjs`.\n- Use the `@/*` alias for `src/*` (configured in `tsconfig.json`).\n- Leave build output in `d","body":"# Astro + Tailwind Expert (Repo Skill)\n\n## Use these project facts\n- Treat `src/pages/` as the routing surface. Each `.astro` or `.md` file becomes a route.\n- Keep shared structure in `src/layouts/`. The default layout is `src/layouts/Layout.astro`.\n- Load global styles from `src/styles/global.css` (already imported in `Layout.astro`).\n- Rely on Tailwind v4 via `@tailwindcss/vite` in `astro.config.mjs`.\n- Use the `@/*` alias for `src/*` (configured in `tsconfig.json`).\n- Leave build output in `dist/` and dependencies in `node_modules/` untouched.\n- Refer to Astro docs: https://docs.astro.build/llms-full.txt and Tailwind docs: https://tailwindcss.com/docs for guidance. Use Context7 and/or Astro Docs MCP for up-to-date info.\n- Use Bun for all package operations (`bun add`, `bun remove`, `bun update`) instead of npm.\n\n## Workflow: create or update a page\n1) Create or edit a file in `src/pages/`.\n2) Import the layout with `import Layout from ''@/layouts/Layout.astro'';`.\n3) Wrap page content in `<Layout>...</Layout>`.\n4) Use Tailwind utility classes for styling.\n5) If the page needs a sub-route, create a folder in `src/pages/` and add `index.astro`.\n\n## Workflow: add a new layout or shared wrapper\n1) Create a new layout in `src/layouts/`.\n2) Import `@/styles/global.css` once in the layout frontmatter.\n3) Provide a `<slot />` for page content.\n4) Use this layout by importing it in pages that need it.\n\n## Workflow: add a reusable component\n1) Create `src/components/` if it does not exist.\n2) Add `.astro` components there.\n3) Keep components focused and stateless unless state is required.\n4) Use component props with `Astro.props` in frontmatter.\n5) Import components with `@/components/...`.\n\n## Workflow: use client islands\n- Keep pages mostly static; hydrate only what needs interactivity.\n- Use `client:load`, `client:visible`, or `client:idle` on React/TSX islands.\n- Avoid global client JS when an island will do.\n- Prefer `is:inline` scripts for small interactions scoped to a section.\n\n## Workflow: use images\n- Use `import { Image } from ''astro:assets''` for optimized images.\n- Store optimized images under `src/assets/` and import them.\n- Keep unoptimized/static files (favicons, robots.txt, manifest) under `public/`.\n- Provide explicit `width`, `height`, and `sizes` for `Image`.\n\n## Workflow: environment variables\n- For build-time config, use `import.meta.env`.\n- For runtime server config (SSR/API routes on Node), prefer `process.env`.\n- Never expose secrets to the client; only use public vars in client code.\n\n## Workflow: style with Tailwind\n- Prefer utility classes over custom CSS for one-off styles.\n- Place shared or base styles in `src/styles/global.css`.\n- If you need design tokens or theme extension, add a Tailwind config and include Astro file globs in `content`.\n- Keep class names readable and scoped to the element they affect.\n\n## Workflow: author Markdown routes\n- Add `.md` files under `src/pages/` for simple content routes.\n- Use frontmatter for titles, metadata, or layout selection.\n- Keep Markdown lightweight; move advanced layouts to `.astro`.\n\n## Astro patterns to use\n- Use frontmatter for imports and server-side logic.\n- Use `class:list` only when conditional classes are necessary.\n- Keep layout structure in `Layout` folder; keep page-specific markup in pages.\n- Make use of @/ alias for cleaner imports. Implement it if not configured.\n- Prefer `export const prerender = false` for API routes that must run at request time.\n- Refer to latest docs online for new features or best practices.\n\n## Quality checks\n- Run `bun dev` for local development.\n- Run `bun build` before shipping changes.\n- Use `bun preview` to verify the built output.\n\n## Change discipline\n- Make minimal, focused edits.\n- Avoid editing generated output in `dist/`.\n- Avoid editing dependency artifacts in `node_modules/` or lockfiles unless asked.\n"},"lastSynced":"2026-03-08T02:06:01.159Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing efficient Astro project management with Tailwind styling.","zh":"非常适合需要高效Astro项目管理和Tailwind样式的前端代理。","ja":"Astroプロジェクトの効率的な管理とTailwindスタイリングが必要なフロントエンドエージェントに最適です。","ko":"효율적인 Astro 프로젝트 관리와 Tailwind 스탈링이 필요한 프론트엔드 에이전트에게 적합합니다.","es":"Perfecto para Agentes Frontend que necesitan una gestión de proyectos Astro eficiente con estilos Tailwind.","fr":"Parfait pour les agents Frontend qui ont besoin d''une gestion de projet Astro efficace avec des styles Tailwind.","de":"Perfekt für Frontend-Agents, die eine effiziente Astro-Projektverwaltung mit Tailwind-Styling benötigen.","pt":"Perfeito para Agentes Frontend que precisam de gerenciamento eficiente de projetos Astro com estilização Tailwind.","ru":"Идеально подходит для агентов Frontend, которым требуется эффективное управление проектами Astro с помощью стилизации Tailwind.","ar":"مثالي للوكلاء الأماميين الذين يحتاجون إلى إدارة مشاريع Astro فعالة مع التنسيق Tailwind."},"recommendation":{"en":"Empowers agents to streamline routing and layout management using Astro and Tailwind v4 via @tailwindcss/vite, while leveraging global styles from src/styles/global.css and shared structures in src/layouts/","zh":"赋予代理人使用Astro和Tailwind v4通过@tailwindcss/vite来简化路由和布局管理的能力，同时利用src/styles/global.css中的全局样式和src/layouts/中的共享结构。","ja":"AstroとTailwind v4を使用してルーティングとレイアウト管理を簡素化する能力をエージェントに与え、@tailwindcss/viteを介してsrc/styles/global.cssからのグローバルスタイルとsrc/layouts/からの共有構造を活用します。","ko":"Astro와 Tailwind v4를 사용하여 라우팅과 레이아웃 관리를 간소화하는 능력을 에이전트에게 부여하며, @tailwindcss/vite를 통해 src/styles/global.css의 글로벌 스타일과 src/layouts/의 공유 구조를 활용합니다.","es":"Permite a los agentes optimizar la gestión de rutas y diseños utilizando Astro y Tailwind v4 a través de @tailwindcss/vite, aprovechando los estilos globales de src/styles/global.css y las estructuras compartidas en src/layouts/","fr":"Permet aux agents de rationaliser la gestion des routes et des mises en page en utilisant Astro et Tailwind v4 via @tailwindcss/vite, tout en exploitant les styles globaux de src/styles/global.css et les structures partagées dans src/layouts/","de":"Ermächtigt Agenten, die Routen- und Layoutverwaltung mithilfe von Astro und Tailwind v4 über @tailwindcss/vite zu optimieren, während globale Styles aus src/styles/global.css und gemeinsame Strukturen in src/layouts/ genutzt werden","pt":"Habilita os agentes a simplificar o roteamento e o gerenciamento de layout usando Astro e Tailwind v4 via @tailwindcss/vite, aproveitando estilos globais de src/styles/global.css e estruturas compartilhadas em src/layouts/","ru":"Позволяет агентам упростить маршрутизацию и управление макетом, используя Astro и Tailwind v4 через @tailwindcss/vite, а также использовать глобальные стили из src/styles/global.css и общие структуры в src/layouts/","ar":"تمكّن الوكلاء من تبسيط التوجيه وإدارة التصميم باستخدام Astro و Tailwind v4 عبر @tailwindcss/vite، مع الاستفادة من الأشكال العالمية من src/styles/global.css والهياكل المشتركة في src/layouts/"},"useCases":{"en":["Streamlining Astro project routing using src/pages/","Managing layouts with src/layouts/Layout.astro","Applying global styles from src/styles/global.css","Utilizing Tailwind v4 for styling via @tailwindcss/vite"],"zh":["使用src/pages/简化Astro项目路由","使用src/layouts/Layout.astro管理布局","应用src/styles/global.css中的全局样式","利用Tailwind v4通过@tailwindcss/vite进行样式设置"],"ja":["src/pages/を使用してAstroプロジェクトのルーティングを簡素化する","src/layouts/Layout.astroを使用してレイアウトを管理する","src/styles/global.cssからのグローバルスタイルを適用する","Tailwind v4を使用して@tailwindcss/viteを介してスタイリングする"],"ko":["src/pages/를 사용하여 Astro 프로젝트의 라우팅을 간소화하는 것","src/layouts/Layout.astro를 사용하여 레이아웃을 관리하는 것","src/styles/global.css의 글로벌 스타일을 적용하는 것","Tailwind v4를 사용하여 @tailwindcss/vite를 통해 스타일을 설정하는 것"],"es":["Optimizar la gestión de rutas de proyectos Astro utilizando src/pages/","Gestionar diseños con src/layouts/Layout.astro","Aplicar estilos globales desde src/styles/global.css","Utilizar Tailwind v4 para el estilo a través de @tailwindcss/vite"],"fr":["Rationaliser la gestion des routes de projet Astro en utilisant src/pages/","Gérer les mises en page avec src/layouts/Layout.astro","Appliquer les styles globaux à partir de src/styles/global.css","Utiliser Tailwind v4 pour le style via @tailwindcss/vite"],"de":["Optimieren der Routenverwaltung von Astro-Projekten mithilfe von src/pages/","Verwalten von Layouts mit src/layouts/Layout.astro","Anwenden globaler Styles aus src/styles/global.css","Nutzen von Tailwind v4 für das Styling über @tailwindcss/vite"],"pt":["Otimização do roteamento do projeto Astro usando src/pages/","Gerenciamento de layouts com src/layouts/Layout.astro","Aplicação de estilos globais de src/styles/global.css","Utilização do Tailwind v4 para estilização via @tailwindcss/vite"],"ru":["Оптимизация маршрутизации проекта Astro с помощью src/pages/","Управление макетами с помощью src/layouts/Layout.astro","Применение глобальных стилей из src/styles/global.css","Использование Tailwind v4 для стилизации через @tailwindcss/vite"],"ar":["تبسيط توجيه مشروع Astro باستخدام src/pages/","إدارة التصميمات باستخدام src/layouts/Layout.astro","تطبيق الأشكال العالمية من src/styles/global.css","استخدام Tailwind v4 للتنسيق عبر @tailwindcss/vite"]},"limitations":{"en":["Requires Astro project setup","Dependent on Tailwind v4 via @tailwindcss/vite","Limited to projects using src/pages/ as routing surface"],"zh":["需要Astro项目设置","依赖于Tailwind v4通过@tailwindcss/vite","仅限于使用src/pages/作为路由表面"],"ja":["Astroプロジェクトの設定が必要","Tailwind v4を@tailwindcss/viteを介して使用すること","src/pages/をルーティング表面として使用するプロジェクトのみ"],"ko":["Astro 프로젝트 설정이 필요함","Tailwind v4를 @tailwindcss/vite를 통해 사용하는 것","src/pages/를 라우팅 표면으로 사용하는 프로젝트에만 한정"],"es":["Requiere la configuración del proyecto Astro","Dependiente de Tailwind v4 a través de @tailwindcss/vite","Limitado a proyectos que utilizan src/pages/ como superficie de enrutamiento"],"fr":["Nécessite la configuration du projet Astro","Dépendant de Tailwind v4 via @tailwindcss/vite","Limité aux projets utilisant src/pages/ comme surface de routage"],"de":["Benötigt die Einrichtung des Astro-Projekts","Abhängig von Tailwind v4 über @tailwindcss/vite","Begrenzt auf Projekte, die src/pages/ als Routenoberfläche verwenden"],"pt":["Requer configuração do projeto Astro","Dependente do Tailwind v4 via @tailwindcss/vite","Limitado a projetos que usam src/pages/ como superfície de roteamento"],"ru":["Требуется настройка проекта Astro","Зависит от Tailwind v4 через @tailwindcss/vite","Ограничен проектами, использующими src/pages/ в качестве поверхности маршрутизации"],"ar":["يتطلب إعداد مشروع Astro","يعتمد على Tailwind v4 عبر @tailwindcss/vite","محدود بمشاريع تستخدم src/pages/ كمساحة توجيه"]},"version":4},"contentHash":"cffdb3f5842fd605493e958275dc5db6185307ab6e86e58898917030d226efa6","qualityScore":29}');
