INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ZafTec/zaf_tech_landing/astro-tailwind-expert', 'astro-tailwind-expert', 'ZafTec', 'zaf_tech_landing', 'community', 'astro-tailwind-expert ZafTec zaf_tech_landing community The astro-tailwind-expert skill enables developers to efficiently build and manage Astro projects with Tailwind styling. It streamlines routing and layout management. Astro Tailwind Expert 是一个强大的开发工具，支持 Astro 和 Tailwind CSS，提供高效的路由和布局管理 Astro + Tailwind Expert は、Astro と Tailwind CSS をサポートする強力な開発ツールで、効率的なルーティングとレイアウト管理を提供します Astro Tailwind Expert는 Astro와 Tailwind CSS를 지원하는 강력한 개발 도구로, 효율적인 라우팅과 레이아웃 관리를 제공합니다 El experto en Astro con Tailwind CSS ayuda a crear sitios web personalizados con routing y estilos globales L''expert en Astro avec Tailwind CSS aide à créer des sites web personnalisés avec routage et styles globaux Der Experte für Astro mit Tailwind CSS hilft bei der Erstellung von benutzerdefinierten Websites mit Routing und globalen Stilen O Astro + Tailwind Expert é uma combinação poderosa para desenvolvimento web. Aprenda a configurar e usar essas tecnologias em seu próximo projeto ИИ Агент Astro + Tailwind Expert представляет собой мощную комбинацию для веб-разработки. Узнайте, как настроить и использовать эти технологии в своем следующем проекте ال AI Astro + Tailwind Expert هو مزيج قوي لتطوير الويب. تعلم كيفية إعداد واستخدام هذه التكنولوجيا في مشروعك التالي how to use astro-tailwind-expert astro-tailwind-expert setup guide what is astro-tailwind-expert astro-tailwind-expert vs other frameworks astro-tailwind-expert install astro and tailwind integration tailwind v4 tutorial astro routing tutorial vite and typescript setup Astro Tailwind Expert AIエージェント 开发工具 路由管理 布局管理 全局样式 Tailwind CSS Astro 高性能 Web 应用 Utilizes Astro for routing, treating src/pages/ as the routing surface Leverages Tailwind v4 via @tailwindcss/vite for styling Manages shared structure in src/layouts/ with a default layout in src/layouts/Layout.astro Loads global styles from src/styles/global.css Supports aliasing with @/* for src/*, configured in tsconfig.json Streamlines build output in the dist directory astro-tailwind-expert is a skill that integrates Astro and Tailwind for optimized web development, utilizing technologies like Vite and TypeScript.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('hundong2/Crawl-all-you-need/readme-i18n-sync', 'community', 'hundong2', 'Crawl-all-you-need', 'hundong2/Crawl-all-you-need', 'readme-i18n-sync', 0, 0, 29, '2026-03-08T01:57:15.397Z', '2026-03-08T02:06:24.228Z', '24ac72ba46b97759b53794659751934beee54d92c3267e3a95a8696d70e27000', '{"id":"hundong2/Crawl-all-you-need/readme-i18n-sync","name":"readme-i18n-sync","description":{"en":"The readme-i18n-sync skill automates the translation of README files into multiple languages, preserving Markdown structure and links. It benefits developers who need to maintain multilingual project documentation.","zh":"README 多语言同步工具是一种自动化工具，用于同步 README 文件的多语言版本，支持韩语、日语、中文和法语","ja":"README 多言語同期ツールは、README ファイルの多言語バージョンを同期する自動化ツールです","ko":"README 다국어 동기화 도구는 README 파일의 다국어 버전을 동기화하는 자동화 도구입니다","es":"readme-i18n-sync es una herramienta que sincroniza archivos README en varios idiomas, preservando la estructura de Markdown y los enlaces","fr":"readme-i18n-sync est un outil qui synchronise les fichiers README dans plusieurs langues, en préservant la structure Markdown et les liens, grâce aux Agents IA","de":"readme-i18n-sync ist ein Werkzeug, das README-Dateien in mehreren Sprachen synchronisiert und die Markdown-Struktur sowie die Links beibehält","pt":"O readme-i18n-sync é uma ferramenta de tradução automática para arquivos README, suportando vários idiomas e preservando a estrutura Markdown","ru":"ИИ Агент readme-i18n-sync - это инструмент для автоматического перевода файлов README, поддерживающий несколько языков и сохраняющий структуру Markdown","ar":"readme-i18n-sync هو أداة لترجمة آليّة لملفات README، تدعم عدة لغات وتحافظ على هيكل Markdown"},"seo":{"title":{"en":"readme-i18n-sync: Automated README Translation Setup Guid...","zh":"README 多语言同步工具 - Setup Guide","ja":"README 多言語同期ツール - ベストプラクティス","ko":"README 다국어 동기화 도구 - 사용법","es":"Configuración de readme-i18n-sync: Guía de sincronización...","fr":"Mise en place de readme-i18n-sync: Outil d''Agents IA pour...","de":"Einrichtung von readme-i18n-sync: Werkzeug für die Synchr...","pt":"Guia de Configuração do readme-i18n-sync para Tradução Au...","ru":"Настройка ИИ Агента readme-i18n-sync для Многоязычной Под...","ar":"دليل إعداد readme-i18n-sync لترجمة آليّة متعددة اللغات"},"description":{"en":"Discover how to sync your README files across languages with readme-i18n-sync. Learn to automate translations and preserve Markdown structure - get started now!","zh":"使用 README 多语言同步工具，轻松实现 README 文件的多语言支持，包括韩语、日语、中文和法语","ja":"README 多言語同期ツールを使用して、README ファイルの多言語サポートを簡単に実現します","ko":"README 다국어 동기화 도구를 사용하여 README 파일의 다국어 지원을 쉽게 구현하세요","es":"Aprende a configurar readme-i18n-sync para sincronizar tus archivos README en varios idiomas, incluyendo coreano, japonés, chino y francés","fr":"Découvrez comment mettre en place readme-i18n-sync pour synchroniser vos fichiers README en plusieurs langues, notamment en coréen, japonais, chinois et fran...","de":"Erfahren Sie, wie Sie readme-i18n-sync einrichten, um Ihre README-Dateien in mehreren Sprachen, einschließlich Koreanisch, Japanisch, Chinesisch und Französi...","pt":"Aprenda a configurar o readme-i18n-sync para traduzir arquivos README em vários idiomas, preservando a estrutura Markdown e links","ru":"Узнайте, как настроить ИИ Агент readme-i18n-sync для перевода файлов README на несколько языков, сохраняя структуру Markdown и ссылки","ar":"تعرف على كيفية إعداد readme-i18n-sync لترجمة ملفات README إلى عدة لغات، مع الحفاظ على هيكل Markdown والروابط"},"definition":{"en":"readme-i18n-sync is a skill that automates the translation of README files into Korean, Japanese, Chinese, and French, while preserving Markdown structure and links.","zh":"README 多语言同步工具是一种用于同步 README 文件的多语言版本的自动化工具","ja":"README 多言語同期ツールは、README ファイルの多言語バージョンを同期するツールです","ko":"README 다국어 동기화 도구는 README 파일의 다국어 버전을 동기화하는 도구입니다","es":"readme-i18n-sync es una herramienta de sincronización de archivos README que admite varios idiomas","fr":"readme-i18n-sync est un outil de synchronisation de fichiers README qui prend en charge plusieurs langues, notamment avec l''aide des Agents IA","de":"readme-i18n-sync ist ein Werkzeug zur Synchronisierung von README-Dateien, das mehrere Sprachen unterstützt","pt":"O readme-i18n-sync é uma ferramenta de tradução automática para arquivos README, que preserva a estrutura Markdown e links","ru":"ИИ Агент readme-i18n-sync - это инструмент для автоматического перевода файлов README, сохраняющий структуру Markdown и ссылки","ar":"readme-i18n-sync هو أداة لترجمة آليّة لملفات README، تحافظ على هيكل Markdown والروابط"},"features":{"en":["Translates README files into Korean, Japanese, Chinese, and French","Preserves Markdown structure, links, code blocks, tables, badges, and file paths","Writes translated outputs to separate README files (e.g., README.kr.md, README.jp.md)","Ensures consistent navigation row across all README files","Supports automated workflow execution"],"zh":["支持韩语、日语、中文和法语的多语言同步","保留 Markdown 结构、链接、代码块、表格、徽章和文件路径","输出多语言 README 文件，包括 README.kr.md、README.jp.md、README.zh.md 和 README.fr.md","确保每个 README 文件以导航行开头","支持 AIエージェント 和 自动化工具"],"ja":["韓国語、日語、中国語、フランス語の多言語同期をサポート","Markdown 構造、リンク、コードブロック、テーブル、バッジ、ファイルパスを保持","多言語 README ファイルを出力、README.kr.md、README.jp.md、README.zh.md、README.fr.md を含む","各 README ファイルがナビゲーション行で始まることを保証","AIエージェント と 自動化ツールをサポート"],"ko":["한국어、일본어、중국어、프랑스어의 다국어 동기화를 지원","Markdown 구조、링크、코드 블록、테이블、배지、파일 경로를 유지","다국어 README 파일을 출력、README.kr.md、README.jp.md、README.zh.md、README.fr.md를 포함","각 README 파일이 네비게이션 행으로 시작하는 것을 보장","AI 에이전트 와 자동화 도구를 지원"],"es":["Sincronización de archivos README en varios idiomas","Preservación de la estructura de Markdown","Mantenimiento de los enlaces y rutas de archivos","Compatibilidad con coreano, japonés, chino y francés","Generación de archivos README con navegación integrada"],"fr":["Synchronisation de fichiers README dans plusieurs langues","Préservation de la structure Markdown","Maintenance des liens et des chemins de fichiers","Compatibilité avec le coréen, le japonais, le chinois et le français","Génération de fichiers README avec navigation intégrée, avec l''aide des Agents IA"],"de":["Synchronisierung von README-Dateien in mehreren Sprachen","Beibehaltung der Markdown-Struktur","Beibehaltung der Links und Dateipfade","Unterstützung für Koreanisch, Japanisch, Chinesisch und Französisch","Erzeugung von README-Dateien mit integrierter Navigation"],"pt":["Tradução automática de arquivos README para vários idiomas","Preservação da estrutura Markdown e links","Suporte a vários idiomas, incluindo Inglês, Coreano, Japonês, Chinês e Francês","Criação de arquivos README traduzidos com navegação para idiomas","Execução de fluxo de trabalho para tradução e criação de arquivos README"],"ru":["Автоматический перевод файлов README на несколько языков","Сохранение структуры Markdown и ссылок","Поддержка нескольких языков, включая Английский, Корейский, Японский, Китайский и Французский","Создание переведенных файлов README с навигацией по языкам","Выполнение рабочего процесса для перевода и создания файлов README"],"ar":["ترجمة آليّة لملفات README إلى عدة لغات","الحفاظ على هيكل Markdown والروابط","دعم عدة لغات، بما في ذلك الإنجليزي والكوري والياباني والصيني والفرنسي","إنشاء ملفات README المترجمة مع التنقل بين اللغات","تنفيذ سير عمل لترجمة وإنشاء ملفات README"]},"keywords":{"en":["how to use readme-i18n-sync","readme-i18n-sync setup guide","automated README translation","Markdown structure preservation","readme-i18n-sync alternative","readme-i18n-sync vs translation tools","readme-i18n-sync install","multilingual project documentation","README file synchronization"],"zh":["README 多语言同步","自动化工具","多语言支持","README 文件","AIエージェント","自动化","多语言","README 同步","代码块","文件路径"],"ja":["README 多言語同期","自動化ツール","多言語サポート","README ファイル","AIエージェント","自動化","多言語","README 同期","コードブロック","ファイルパス"],"ko":["README 다국어 동기화","자동화 도구","다국어 지원","README 파일","AI 에이전트","자동화","다국어","README 동기화","코드 블록","파일 경로"],"es":["readme-i18n-sync","sincronización de README"," Agents IA","traducción de Markdown","sincronización de archivos","compatibilidad con varios idiomas"," Agents de inteligencia artificial"],"fr":["readme-i18n-sync","synchronisation de fichiers README","Agents IA","traduction de Markdown","synchronisation de fichiers","compatibilité avec plusieurs langues","outils d''intelligence artificielle"],"de":["readme-i18n-sync","Synchronisierung von README-Dateien","Werkzeuge für die Synchronisierung","Übersetzung von Markdown","Synchronisierung von Dateien","Unterstützung für mehrere Sprachen","Tools für künstliche Intelligenz"],"pt":["readme-i18n-sync","tradução automática","arquivos README","estrutura Markdown","links","idiomas","Coreano","Japonês","Chinês","Francês"],"ru":["ИИ Агент readme-i18n-sync","автоматический перевод","файлы README","структура Markdown","ссылки","языки","Корейский","Японский","Китайский","Французский"],"ar":["readme-i18n-sync","ترجمة آليّة","ملفات README","هيكل Markdown","روابط","لغات","الكوري","الياباني","الصيني","الفرنسي"]}},"owner":"hundong2","repo":"Crawl-all-you-need","repoPath":"hundong2/Crawl-all-you-need","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.397Z","topics":[],"category":"community","skillMd":{"name":"readme-i18n-sync","description":"Automatically sync README.md translations into README.kr.md, README.jp.md, README.zh.md, and README.fr.md while preserving Markdown structure and language navigation links. Use when a user asks to translate README updates across Korean, Japanese, Chinese, and French or keep localized README files aligned with the English source.","bodyPreview":"# README I18N Sync\n\n## Execute Workflow\n\n1. Read `README.md` as the source of truth.\n2. Translate into Korean, Japanese, Chinese, and French.\n3. Preserve Markdown structure, links, code blocks, tables, badges, and file paths.\n4. Write outputs to:\n- `README.kr.md`\n- `README.jp.md`\n- `README.zh.md`\n- `README.fr.md`\n5. Ensure every README file starts with this navigation row:\n`[English](./README.md) | [한국어](./README.kr.md) | [日本語](./README.jp.md) | [中文](./README.zh.md) | [Français](./README.fr.md)`","body":"# README I18N Sync\n\n## Execute Workflow\n\n1. Read `README.md` as the source of truth.\n2. Translate into Korean, Japanese, Chinese, and French.\n3. Preserve Markdown structure, links, code blocks, tables, badges, and file paths.\n4. Write outputs to:\n- `README.kr.md`\n- `README.jp.md`\n- `README.zh.md`\n- `README.fr.md`\n5. Ensure every README file starts with this navigation row:\n`[English](./README.md) | [한국어](./README.kr.md) | [日本語](./README.jp.md) | [中文](./README.zh.md) | [Français](./README.fr.md)`\n6. Verify section ordering remains identical across all language files.\n\n## Apply Translation Rules\n\n- Translate prose only.\n- Keep commands, code snippets, URLs, and file paths unchanged.\n- Keep heading levels and list/table layout unchanged.\n- Keep tool and product names unchanged unless explicitly requested.\n- Do not add or remove sections.\n\n## Use Automation\n\n- Run `scripts/readme_i18n_sync.sh --engine <codex|claude|copilot|gemini>`.\n- Configure one environment variable for the selected engine:\n- `README_I18N_CODEX_CMD`\n- `README_I18N_CLAUDE_CMD`\n- `README_I18N_COPILOT_CMD`\n- `README_I18N_GEMINI_CMD`\n\n## Read Reference\n\n- Prompt contract: `references/prompt-template.md`\n"},"lastSynced":"2026-03-08T02:06:24.228Z","agentAnalysis":{"suitability":{"en":"Perfect for Multilingual Documentation Agents needing automated Markdown translation capabilities.","zh":"非常适合需要自动化 Markdown 翻译功能的多语言文档代理。","ja":"マルチリンガル ドキュメント エージェントが自動化された Markdown 翻訳機能を必要とする場合に最適です。","ko":"자동화된 Markdown 번역 기능이 필요한 다국어 문서 에이전트에게 적합합니다.","es":"Perfecto para agentes de documentación multilingüe que necesitan capacidades de traducción de Markdown automatizadas.","fr":"Parfait pour les agents de documentation multilingue ayant besoin de capacités de traduction de Markdown automatisées.","de":"Perfekt für mehrsprachige Dokumentationsagenten, die automatisierte Markdown-Übersetzungs-Funktionen benötigen.","pt":"Perfeito para Agentes de Documentação Multilíngue que precisam de capacidades de tradução automatizada do Markdown.","ru":"Идеально для Многоязычных Агентов Документации, которым необходимы автоматические возможности перевода Markdown.","ar":"مثالي للوكلاء الوثائقية متعددة اللغات الذين يحتاجون إلى قدرات الترجمة الآلية للماركداون."},"recommendation":{"en":"Empowers agents to translate README files into multiple languages, preserving Markdown structure and links, using protocols like file paths and code blocks, and supporting languages such as Korean, Japanese, Chinese, and French.","zh":"赋予代理翻译 README 文件到多种语言的能力，保留 Markdown 结构和链接，使用诸如文件路径和代码块的协议，并支持诸如韩语、日语、中文和法语等语言。","ja":"エージェントに README ファイルを複数の言語に翻訳する能力を与え、Markdown 構造とリンクを保持し、ファイル パスやコード ブロックなどのプロトコルを使用し、韓国語、日語、中国語、フランス語などの言語をサポートします。","ko":"에이전트가 README 파일을 여러 언어로 번역할 수 있는 기능을 제공하며, Markdown 구조와 링크를 유지하고, 파일 경로 및 코드 블록과 같은 프로토콜을 사용하며, 한국어, 일본어, 중국어, 프랑스어 등 언어를 지원합니다.","es":"Habilita a los agentes a traducir archivos README a varios idiomas, preservando la estructura y los enlaces de Markdown, utilizando protocolos como rutas de archivo y bloques de código, y admitiendo idiomas como coreano, japonés, chino y francés.","fr":"Permet aux agents de traduire des fichiers README dans plusieurs langues, en préservant la structure et les liens Markdown, en utilisant des protocoles tels que les chemins de fichiers et les blocs de code, et en prenant en charge des langues telles que le coréen, le japonais, le chinois et le français.","de":"Ermöglicht es den Agents, README-Dateien in mehrere Sprachen zu übersetzen, wobei die Markdown-Struktur und -Links erhalten bleiben, und Protokolle wie Dateipfade und Codeblöcke verwendet werden, und Sprachen wie Koreanisch, Japanisch, Chinesisch und Französisch unterstützt werden.","pt":"Habilita os agentes a traduzir arquivos README em vários idiomas, preservando a estrutura e os links do Markdown, utilizando protocolos como caminhos de arquivo e blocos de código, e suportando idiomas como coreano, japonês, chinês e francês.","ru":"Наделяет агентов возможностью переводить файлы README на несколько языков, сохраняя структуру и ссылки Markdown, используя протоколы, такие как пути к файлам и блоки кода, и поддерживая языки, такие как корейский, японский, китайский и французский.","ar":"يمنح الوكلاء القدرة على ترجمة ملفات README إلى عدة لغات، مع الحفاظ على هيكل وروابط الماركداون، واستخدام بروتوكولات مثل مسارات الملفات وكتلة الشفرة، ودعم اللغات مثل الكورية واليابانية والصينية والفرنسية."},"useCases":{"en":["Automating README translations for open-source projects","Generating multilingual documentation for global software releases","Preserving Markdown links and code blocks during translation"],"zh":["自动化开源项目的 README 翻译","为全球软件发布生成多语言文档","在翻译过程中保留 Markdown 链接和代码块"],"ja":["オープンソース プロジェクトの README 翻訳を自動化する","グローバル ソフトウェア リリース用のマルチリンガル ドキュメントを生成する","翻訳中に Markdown リンクとコード ブロックを保持する"],"ko":["오픈소스 프로젝트의 README 번역을 자동화하는 것","글로벌 소프트웨어 릴리스를 위한 다국어 문서를 생성하는 것","번역 과정에서 Markdown 링크와 코드 블록을 유지하는 것"],"es":["Automatizar traducciones de README para proyectos de código abierto","Generar documentación multilingüe para lanzamientos de software globales","Preservar enlaces y bloques de código de Markdown durante la traducción"],"fr":["Automatiser les traductions de fichiers README pour les projets open-source","Générer de la documentation multilingue pour les sorties de logiciels mondiales","Préserver les liens et les blocs de code Markdown pendant la traduction"],"de":["Automatisieren von README-Übersetzungen für Open-Source-Projekte","Erstellen von mehrsprachiger Dokumentation für globale Software-Veröffentlichungen","Erhalten von Markdown-Links und -Codeblöcken während der Übersetzung"],"pt":["Automatizar traduções de README para projetos de código aberto","Gerar documentação multilíngue para lançamentos de software globais","Preservar links e blocos de código do Markdown durante a tradução"],"ru":["Автоматизировать переводы файлов README для проектов с открытым исходным кодом","Генерировать многоязычную документацию для глобальных релизов программного обеспечения","Сохранять ссылки и блоки кода Markdown во время перевода"],"ar":["تحويل ترجمات README تلقائيًا لمشاريع البرمجيات مفتوحة المصدر","توليد وثائق متعددة اللغات لإصدارات البرامج العالمية","الحفاظ على الروابط وكتلة الشفرة للماركداون أثناء الترجمة"]},"limitations":{"en":["Limited to translating README files in Markdown format","Requires specific language support, currently Korean, Japanese, Chinese, and French","Needs filesystem access to read and write README files"],"zh":["仅限翻译 Markdown 格式的 README 文件","需要特定的语言支持，目前支持韩语、日语、中文和法语","需要文件系统访问权限来读取和写入 README 文件"],"ja":["Markdown 形式の README ファイルのみを翻訳する","特定の言語サポートが必要であり、現在韓国語、日語、中国語、フランス語がサポートされている","README ファイルを読み書きするためにファイル システム アクセスが必要"],"ko":["Markdown 형식의 README 파일만 번역할 수 있음","특정 언어 지원이 필요하며, 현재 한국어, 일본어, 중국어, 프랑스어가 지원됨","README 파일을 읽고 쓰기 위해 파일 시스템 접근 권한이 필요함"],"es":["Limitado a la traducción de archivos README en formato Markdown","Requiere soporte de idioma específico, actualmente coreano, japonés, chino y francés","Necesita acceso al sistema de archivos para leer y escribir archivos README"],"fr":["Limité à la traduction de fichiers README au format Markdown","Nécessite une prise en charge linguistique spécifique, actuellement le coréen, le japonais, le chinois et le français","Nécessite un accès au système de fichiers pour lire et écrire des fichiers README"],"de":["Begrenzt auf die Übersetzung von README-Dateien im Markdown-Format","Benötigt spezifische Sprachunterstützung, derzeit Koreanisch, Japanisch, Chinesisch und Französisch","Benötigt Dateisystemzugriff, um README-Dateien zu lesen und zu schreiben"],"pt":["Limitado à tradução de arquivos README no formato Markdown","Exige suporte a idiomas específicos, atualmente coreano, japonês, chinês e francês","Necessita de acesso ao sistema de arquivos para ler e gravar arquivos README"],"ru":["Ограничен переводом файлов README в формате Markdown","Требует поддержки конкретных языков, в настоящее время корейского, японского, китайского и французского","Требует доступа к файловой системе для чтения и записи файлов README"],"ar":["محدود بترجمة ملفات README بتنسيق الماركداون","يتطلب دعمًا للغات محددة، حاليًا الكورية واليابانية والصينية والفرنسية","يحتاج إلى الوصول إلى نظام الملفات لقراءة وكتابة ملفات README"]},"version":4},"contentHash":"24ac72ba46b97759b53794659751934beee54d92c3267e3a95a8696d70e27000","qualityScore":29}');
