INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('hundong2/Crawl-all-you-need/readme-i18n-sync', 'readme-i18n-sync', 'hundong2', 'Crawl-all-you-need', 'community', 'readme-i18n-sync hundong2 Crawl-all-you-need community The readme-i18n-sync skill automates the translation of README files into multiple languages, preserving Markdown structure and links. It benefits developers who need to maintain multilingual project documentation. README 多语言同步工具是一种自动化工具，用于同步 README 文件的多语言版本，支持韩语、日语、中文和法语 README 多言語同期ツールは、README ファイルの多言語バージョンを同期する自動化ツールです README 다국어 동기화 도구는 README 파일의 다국어 버전을 동기화하는 자동화 도구입니다 readme-i18n-sync es una herramienta que sincroniza archivos README en varios idiomas, preservando la estructura de Markdown y los enlaces readme-i18n-sync est un outil qui synchronise les fichiers README dans plusieurs langues, en préservant la structure Markdown et les liens, grâce aux Agents IA readme-i18n-sync ist ein Werkzeug, das README-Dateien in mehreren Sprachen synchronisiert und die Markdown-Struktur sowie die Links beibehält O readme-i18n-sync é uma ferramenta de tradução automática para arquivos README, suportando vários idiomas e preservando a estrutura Markdown ИИ Агент readme-i18n-sync - это инструмент для автоматического перевода файлов README, поддерживающий несколько языков и сохраняющий структуру Markdown readme-i18n-sync هو أداة لترجمة آليّة لملفات README، تدعم عدة لغات وتحافظ على هيكل Markdown how to use readme-i18n-sync readme-i18n-sync setup guide automated README translation Markdown structure preservation readme-i18n-sync alternative readme-i18n-sync vs translation tools readme-i18n-sync install multilingual project documentation README file synchronization README 多语言同步 自动化工具 多语言支持 README 文件 AIエージェント 自动化 多语言 README 同步 代码块 文件路径 Translates README files into Korean, Japanese, Chinese, and French Preserves Markdown structure, links, code blocks, tables, badges, and file paths Writes translated outputs to separate README files (e.g., README.kr.md, README.jp.md) Ensures consistent navigation row across all README files Supports automated workflow execution readme-i18n-sync is a skill that automates the translation of README files into Korean, Japanese, Chinese, and French, while preserving Markdown structure and links.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jdubray/puffin/coding-standard-javascript', 'community', 'jdubray', 'puffin', 'jdubray/puffin', 'coding-standard-javascript', 0, 0, 29, '2026-03-08T01:57:15.412Z', '2026-03-08T02:07:05.154Z', 'f2f313ffa77dcf96a497d772a29bc4108e1d04bb2904c038ec7a4f1aa45ca051', '{"id":"jdubray/puffin/coding-standard-javascript","name":"coding-standard-javascript","description":{"en":"The coding-standard-javascript skill provides guidelines for writing clean and maintainable JavaScript/TypeScript code, benefiting developers and AI agents alike.","zh":"JavaScript 编码标准是编写高质量代码的基础，本文介绍了文件命名、变量命名等关键规则","ja":"JavaScript コーディングスタンダードは、高品質なコードを書くための基本です。この記事では、ファイル命名、変数命名などの重要な規則を紹介します","ko":"JavaScript 코딩 표준은 최고의 코드를 작성하는 데必要합니다. 파일命名, 변수命名 등을 포함한 주요 규칙을 살펴보세요","es":"Establezca los estándares de codificación de JavaScript para mejorar la calidad y legibilidad de su código. Aprenda sobre los nombres de archivos y variables","fr":"Définissez les normes de codage JavaScript pour améliorer la qualité et la lisibilité de votre code. Découvrez les noms de fichiers et de variables","de":"Legen Sie die Codierungsstandards für JavaScript fest, um die Qualität und Lesbarkeit Ihres Codes zu verbessern. Erfahren Sie mehr über Dateinamen und Variablen","pt":"Padrões de codificação JavaScript para melhorar a qualidade do código. Use kebab-case para nomes de arquivos e camelCase para variáveis","ru":"Падагоны кодирования JavaScript для улучшения качества кода. Используйте kebab-case для имен файлов и camelCase для переменных","ar":"معايير الترميز الجافاسكربت لتحسين جودة التعليمات البرمجية. استخدم kebab-case للأسماء الملفات و camelCase للمتغيرات"},"seo":{"title":{"en":"coding-standard-javascript: Best Practices for AI Agents ...","zh":"JavaScript 编码标准设置指南","ja":"JavaScript コーディングスタンダードのベストプラクティス","ko":"JavaScript 코딩 표준 가이드","es":"Guía de Configura