INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jdubray/puffin/coding-standard-javascript', 'coding-standard-javascript', 'jdubray', 'puffin', 'community', 'coding-standard-javascript jdubray puffin community The coding-standard-javascript skill provides guidelines for writing clean and maintainable JavaScript/TypeScript code, benefiting developers and AI agents alike. JavaScript 编码标准是编写高质量代码的基础，本文介绍了文件命名、变量命名等关键规则 JavaScript コーディングスタンダードは、高品質なコードを書くための基本です。この記事では、ファイル命名、変数命名などの重要な規則を紹介します JavaScript 코딩 표준은 최고의 코드를 작성하는 데必要합니다. 파일命名, 변수命名 등을 포함한 주요 규칙을 살펴보세요 Establezca los estándares de codificación de JavaScript para mejorar la calidad y legibilidad de su código. Aprenda sobre los nombres de archivos y variables Définissez les normes de codage JavaScript pour améliorer la qualité et la lisibilité de votre code. Découvrez les noms de fichiers et de variables Legen Sie die Codierungsstandards für JavaScript fest, um die Qualität und Lesbarkeit Ihres Codes zu verbessern. Erfahren Sie mehr über Dateinamen und Variablen Padrões de codificação JavaScript para melhorar a qualidade do código. Use kebab-case para nomes de arquivos e camelCase para variáveis Падагоны кодирования JavaScript для улучшения качества кода. Используйте kebab-case для имен файлов и camelCase для переменных معايير الترميز الجافاسكربت لتحسين جودة التعليمات البرمجية. استخدم kebab-case للأسماء الملفات و camelCase للمتغيرات how to use coding-standard-javascript javascript coding standards typescript coding best practices coding-standard-javascript setup guide coding-standard-javascript alternative javascript file naming conventions typescript variable naming rules JavaScript 编码标准 JavaScript 代码规范 文件命名规则 变量命名规则 类型定义文件 JavaScript 开发最佳实践 AIエージェント JavaScript 代码质量 Enforces kebab-case naming for source and component files Supports camelCase naming for variables Uses .test.js or .spec.js suffix for test files Generates type definition files with .d.ts suffix Applies to both JavaScript and TypeScript code coding-standard-javascript is a set of rules for JavaScript/TypeScript coding, covering file naming conventions, variable naming, and test file suffixes.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('LegacyCodeHQ/clarity/verify-language-support', 'community', 'LegacyCodeHQ', 'clarity', 'LegacyCodeHQ/clarity', 'verify-language-support', 0, 0, 29, '2026-03-08T01:57:15.430Z', '2026-03-08T02:07:31.703Z', '8235a0124ad4176fdd8826a42f197ae49ab32af2010420f1cd8ce97cc0988156', '{"id":"LegacyCodeHQ/clarity/verify-language-support","name":"verify-language-support","description":{"en":"The verify-language-support skill validates language support end-to-end in Clarity, benefiting AI-native developers and coding agents. It ensures parser/resolver behavior and maturity level changes are properly tested.","zh":"verify-language-support 是 Clarity 中的一个工作流，用于验证语言支持。它包括目标语言模块、命令输出和解析器/解析行为的验证","ja":"verify-language-support は Clarity の言語サポートを検証するワークフローです。対象言語モジュール、コマンド出力、パーサー/リゾルバ動作の検証を含みます","ko":"verify-language-support는 Clarity에서 언어 지원을 검증하는 워크플로우입니다. 대상 언어 모듈, 명령 출력 및 파서/리졸버 동작의 검증을 포함합니다","es":"Verify-language-support es una herramienta para validar el soporte de idiomas en Clarity. Utiliza pruebas dirigidas y regresión para garantizar la precisión.","fr":"Verify-language-support est un outil pour valider la prise en charge des langues dans Clarity. Il utilise des tests ciblés et de régression pour assurer la précision.","de":"Verify-language-support ist ein Tool zur Überprüfung der Sprachunterstützung in Clarity. Es verwendet gezielte Tests und Regressionstests, um die Genauigkeit zu gewährleisten.","pt":"O verify-language-support é uma ferramenta de design de software para desenvolvedores de IA que valida o suporte de idiomas de forma eficiente.","ru":"Verify-language-support - это инструмент для разработчиков ИИ, который проверяет поддержку языков в программном обеспечении.","ar":"verify-language-support هي أداة تصميم برمجيات للمانحين الذكاء الاصطناعي التي تدعم التحقق من دعم اللغة"},"seo":{"title":{"en":"Verify-Language-Support: End-to-End Validation Setup Guid...","zh":"AI工具_verify-language-support 设置指南","ja":"AIエージェント_verify-language-support のベストプラクティス","ko":"AI 에이전트_verify-language-support 구축 가이드","es":"Guía de configuración para verify-language-support en her...","fr":"Configurer le support linguistique avec verify-language-s...","de":"Einrichtungsleitfaden für verify-language-support in KI-T...","pt":"Guia de Configuração do verify-language-support para Ferr...","ru":"Настройка verify-language-support для ИИ Агентов: Лучшие ...","ar":"دليل إعداد verify-language-support لأدوات الذكاء الاصطناعي"},"description":{"en":"Validate language support in Clarity with targeted tests and regression tests. Learn how to setup verify-language-support for AI-native developers and coding...","zh":"了解如何使用 verify-language-support 工作流来验证 Clarity 中的语言支持","ja":"Clarity の言語サポートを検証するために verify-language-support ワークフローを使用する方法について学びます","ko":"Clarity에서 언어 지원을 검증하는 verify-language-support 워크플로우 사용 방법을 알아보세요","es":"Aprende a validar el soporte de idiomas en Clarity con verify-language-support y mejora la precisión de tus herramientas de AI","fr":"Découvrez comment valider la prise en charge des langues dans Clarity avec verify-language-support pour améliorer la précision de vos outils d''IA","de":"Erfahren Sie, wie Sie die Sprachunterstützung in Clarity mit verify-language-support überprüfen und die Genauigkeit Ihrer KI-Tools verbessern","pt":"Aprenda a validar o suporte de idiomas com o verify-language-support e melhore a eficiência do seu workflow de desenvolvimento de IA","ru":"Узнайте, как проверить поддержку языков с помощью verify-language-support и повысьте эффективность вашего рабочего процесса разработки ИИ","ar":"تعرف على كيفية التحقق من دعم اللغة باستخدام verify-language-support وเพิ่م كفاءة سير عمل تطوير الذكاء الاصطناعي"},"definition":{"en":"verify-language-support is a workflow that validates language support in Clarity, confirming parser/resolver behavior and testing affected command output.","zh":"verify-language-support 是一种验证 Clarity 中语言支持的工作流","ja":"verify-language-support は Clarity の言語サポートを検証するためのワークフローです","ko":"verify-language-support는 Clarity에서 언어 지원을 검증하는 워크플로우입니다","es":"Verify-language-support es una función que valida el soporte de idiomas en Clarity","fr":"Verify-language-support est une fonction qui valide la prise en charge des langues dans Clarity","de":"Verify-language-support ist eine Funktion, die die Sprachunterstützung in Clarity überprüft","pt":"O verify-language-support é uma ferramenta de validação de suporte de idiomas para desenvolvedores de IA","ru":"Verify-language-support - это инструмент для проверки поддержки языков для разработчиков ИИ","ar":"verify-language-support هي أداة للتحقق من دعم اللغة لمطوري الذكاء الاصطناعي"},"features":{"en":["Runs targeted tests using `go test ./depgraph/<language>`","Updates regression tests near changed logic in `d`","Confirms current local changes with `git status --short`","Validates parser/resolver behavior for target language modules under `depgraph/<language>/`","Tests affected command output in `cmd/languages/` when maturity level changes"],"zh":["目标语言模块验证","命令输出验证","解析器/解析行为验证","Go 测试框架集成","回归测试支持"],"ja":["対象言語モジュールの検証","コマンド出力の検証","パーサー/リゾルバ動作の検証","Go テストフレームワークの統合","リグレッションテストのサポート"],"ko":["대상 언어 모듈 검증","명령 출력 검증","파서/리졸버 동작 검증","Go 테스트 프레임워크 통합","회귀 테스트 지원"],"es":["Pruebas dirigidas para validar el soporte de idiomas","Regresión para garantizar la precisión","Integración con depgraph y cmd/languages","Soporte para múltiples idiomas","Utiliza go test para ejecutar pruebas"],"fr":["Tests ciblés pour valider la prise en charge des langues","Régression pour assurer la précision","Intégration avec depgraph et cmd/languages","Prise en charge de plusieurs langues","Utilise go test pour exécuter les tests"],"de":["Gezielte Tests zur Überprüfung der Sprachunterstützung","Regressionstests zur Gewährleistung der Genauigkeit","Integration mit depgraph und cmd/languages","Unterstützung für mehrere Sprachen","Verwenden von go test zur Ausführung von Tests"],"pt":["Validação de suporte de idiomas com depgraph","Testes direcionados com go test","Atualização de testes de regressão","Integração com cmd/languages/","Suporte a múltiplos idiomas","Uso de git status para confirmação de alterações"],"ru":["Проверка поддержки языков с помощью depgraph","Целевые тесты с go test","Обновление тестов регрессии","Интеграция с cmd/languages/","Поддержка нескольких языков","Использование git status для подтверждения изменений"],"ar":["التحقق من دعم اللغة باستخدام depgraph","اختبارات موجهة مع go test","تحديث اختبارات الانحدار","التكامل مع cmd/languages/","دعم اللغات المتعددة","استخدام git status للتأكيد على التغييرات"]},"keywords":{"en":["how to use verify-language-support","verify-language-support setup guide","Clarity language support validation","end-to-end testing for AI agents","verify-language-support alternative","verify-language-support vs Clarity","install verify-language-support","what is verify-language-support","verify-language-support for AI-native developers"],"zh":["AI 工具","Clarity","语言支持","verify-language-support","Go 测试","解析器/解析行为","目标语言模块","命令输出"],"ja":["AI エージェント","Clarity","言語サポート","verify-language-support","Go テスト","パーサー/リゾルバ動作","対象言語モジュール","コマンド出力"],"ko":["AI 에이전트","Clarity","언어 지원","verify-language-support","Go 테스트","파서/리졸버 동작","대상 언어 모듈","명령 출력"],"es":["verify-language-support","herramientas de AI","validar soporte de idiomas","Clarity","pruebas dirigidas","regresión","depgraph","cmd/languages"],"fr":["verify-language-support","outils d''IA","valider la prise en charge des langues","Clarity","tests ciblés","régression","depgraph","cmd/languages"],"de":["verify-language-support","KI-Tools","überprüfen der Sprachunterstützung","Clarity","gezielte Tests","Regressionstests","depgraph","cmd/languages"],"pt":["verify-language-support","desenvolvimento de IA","ferramentas de IA","validação de suporte de idiomas","depgraph","go test","testes de regressão","cmd/languages/","git status"],"ru":["verify-language-support","разработка ИИ","инструменты ИИ","проверка поддержки языков","depgraph","go test","тесты регрессии","cmd/languages/","git status"],"ar":["verify-language-support","تطوير الذكاء الاصطناعي","أدوات الذكاء الاصطناعي","التحقق من دعم اللغة","depgraph","go test","اختبارات الانحدار","cmd/languages/","git status"]}},"owner":"LegacyCodeHQ","repo":"clarity","repoPath":"LegacyCodeHQ/clarity","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.430Z","topics":[],"category":"community","skillMd":{"name":"verify-language-support","description":"End-to-end workflow for validating language support changes in the clarity dependency graph analyzer","bodyPreview":"Use this workflow to validate language support end-to-end in `clarity`.\n\n## Prepare\n\n1. Identify the target language module under `depgraph/<language>/`.\n2. Identify affected command output in `cmd/languages/` when maturity level changes.\n3. Confirm current local changes with `git status --short`.\n\n## Verify Parser/Resolver Behavior\n\n1. Run targeted tests first:\n   - `go test ./depgraph/<language>`\n2. If behavior changed, add or update regression tests near changed logic:\n   - Parser tests in `d","body":"Use this workflow to validate language support end-to-end in `clarity`.\n\n## Prepare\n\n1. Identify the target language module under `depgraph/<language>/`.\n2. Identify affected command output in `cmd/languages/` when maturity level changes.\n3. Confirm current local changes with `git status --short`.\n\n## Verify Parser/Resolver Behavior\n\n1. Run targeted tests first:\n   - `go test ./depgraph/<language>`\n2. If behavior changed, add or update regression tests near changed logic:\n   - Parser tests in `depgraph/<language>/parser_*_test.go`\n   - Resolver tests in `depgraph/<language>/*resolver*_test.go` (or add one)\n3. Prefer symbol-usage-based assertions over package-level assumptions.\n\n## Validate on a Real Repository (Always Interactive)\n\n1. Pick a representative repo for the language.\n2. Clone into `/tmp`.\n3. Build a review queue before rendering graphs:\n   - Use non-merge commits only.\n   - Use commits with `5-30` changed files.\n   - Prioritize commits that are mostly about the target language (based on file extensions/paths).\n   - Each selected commit should include at least a few files in the target language (minimum 3 unless unavailable).\n   - Default queue size is 10 commits unless the user requests a different count.\n4. Show the queue to the user before starting graph renders.\n5. Render exactly one commit at a time in the IDE:\n   - Show commit context immediately before the diagram:\n     - `git -C /tmp/<repo> show -s --format=''%h %s'' <sha>`\n   - In chat, print the commit message line before the Mermaid block so the user knows what change they are reviewing.\n   - `go run . graph --repo /tmp/<repo> -c <sha> -f mermaid`\n   - Always include the rendered diagram directly in chat (Mermaid fenced block). If Mermaid is not visible, provide DOT/text fallback in chat.\n   - If diagrams still are not visible to the user, generate and open the graph URL in the browser (for example `clarity graph -u` or equivalent URL output).\n6. Pause after each commit and wait for explicit user confirmation (for example, `next`) before continuing.\n7. Continue this request/response loop until the queue is complete or the user stops.\n8. After completing the default 10-commit queue, ask:\n   - \"Do you want me to proceed with updating maturity level and committing the changes?\"\n   - If the user says yes, do it immediately without extra confirmation:\n     - Update module maturity as justified by validation results.\n     - Update `cmd/languages` golden output if changed.\n     - Run quality gates (`make lint`, `make test`).\n     - Commit the changes with a focused `type: subject` message.\n9. Keep validation focused on edge quality for each commit:\n   - Production file incorrectly depends on test file\n   - Fan-out caused by same-name declarations across source sets/targets\n   - Missing edges where symbols are clearly referenced\n10. If the user asks a side question during review (for example what `.in` means), answer briefly and then resume the queue when prompted.\n\n## Fixing Issues\n\n1. Update parser extraction to collect real referenced symbols.\n2. Update resolver logic to map imports/references to concrete declarations.\n3. Avoid package-wide linking for imports.\n4. For ambiguous symbol definitions (multiple files define same symbol), skip linking unless disambiguation is available.\n5. Add regression tests covering the exact failing pattern from real commits.\n\n## Quality Gates\n\n1. Run lint and full tests:\n   - `make lint`\n   - `make test`\n2. If `cmd/languages` output changes (for example, maturity icon changed), update golden:\n   - `go test ./cmd/languages -run TestLanguagesCommand_PrintsSupportedLanguagesAndExtensions -update`\n   - Re-run `make test`\n\n## Review Graph of Local Changes\n\n1. If 3 or more files changed, run:\n   - `./clarity graph -f mermaid`\n2. Ensure test-to-code directionality and dependency density look plausible.\n\n## Handoff Checklist\n\n1. Summarize what changed and why.\n2. Include exact files touched.\n3. Include command results for `make lint` and `make test`.\n4. If commit is requested, use one focused commit message in `type: subject` format.\n"},"lastSynced":"2026-03-08T02:07:31.703Z","agentAnalysis":{"suitability":{"en":"Perfect for Coding Agents needing comprehensive language support validation in Clarity","zh":"非常适合需要在 Clarity 中进行全面语言支持验证的编码代理","ja":"Clarity で包括的な言語サポートの検証が必要なコーディング エージェントに最適","ko":"Clarity에서 종합적인 언어 지원 검증이 필요한 코딩 에이전트에게 완벽함","es":"Ideal para agentes de codificación que necesitan una validación de soporte de lenguaje integral en Clarity","fr":"Parfait pour les agents de codage nécessitant une validation de support de langage complet dans Clarity","de":"Perfekt für Codierungsagenten, die eine umfassende Sprachunterstützungsvalidierung in Clarity benötigen","pt":"Perfeito para Agentes de Codificação que necessitam de validação de suporte de linguagem abrangente no Clarity","ru":"Идеально подходит для агентов кодирования, которым требуется комплексная проверка поддержки языка в Clarity","ar":"مثالي لعميل الترميز الذي يحتاج إلى التحقق الشامل للدعم اللغوي في Clarity"},"recommendation":{"en":"Empowers agents to validate language support end-to-end, ensuring proper parser and resolver behavior, and maturity level changes are thoroughly tested using Go test and regression tests in depgraph and cmd/languages directories","zh":"使代理能够从端到端验证语言支持，确保正确的解析器和解析器行为，并且成熟度级别的变化得到了使用 Go 测试和在 depgraph 和 cmd/languages 目录中的回归测试的充分测试","ja":"エージェントが言語サポートをエンドツーエンドで検証できるようにし、適切なパーサーおよび解決済み動作を保証し、成熟度レベルの変更が Go テストおよび depgraph および cmd/languages ディレクトリ内の回帰テストを使用して十分にテストされるようにする","ko":"에이전트가 언어 지원을 종단 간으로 검증할 수 있도록하여 올바른 파서 및 해결기 동작을 보장하고 성숙도 수준의 변경이 Go 테스트 및 depgraph 및 cmd/languages 디렉토리 내의 회귀 테스트를 사용하여 충분히 테스트되도록 함","es":"Habilita a los agentes a validar el soporte de lenguaje de extremo a extremo, asegurando un comportamiento adecuado del analizador y del resolutor, y que los cambios en el nivel de madurez se prueben exhaustivamente usando Go test y pruebas de regresión en los directorios depgraph y cmd/languages","fr":"Permet aux agents de valider le support de langage de bout en bout, en garantissant un comportement correct du parseur et du résolveur, et que les changements de niveau de maturité soient soigneusement testés à l''aide de Go test et de tests de régression dans les répertoires depgraph et cmd/languages","de":"Ermächtigt Agenten, Sprachunterstützung von Ende zu Ende zu validieren, indem ein ordnungsgemäßes Verhalten von Parser und Resolver sichergestellt wird und Änderungen des Reifegrads gründlich mit Go-Test und RegressionsTests in den Verzeichnissen depgraph und cmd/languages getestet werden","pt":"Habilita os agentes a validar o suporte de linguagem de ponta a ponta, garantindo o comportamento adequado do analisador e do resolvedor, e que as alterações no nível de maturidade sejam rigorosamente testadas usando Go test e testes de regressão nos diretórios depgraph e cmd/languages","ru":"Наделяет агентов возможностью проверить поддержку языка от начала до конца, обеспечивая правильное поведение парсера и решателя, и изменения уровня зрелости проходят тщательное тестирование с помощью Go test и регрессионных тестов в директориях depgraph и cmd/languages","ar":"يمنح الوكيل القدرة على التحقق من دعم اللغة من النهاية إلى النهاية، وضمان سلوك المُحلل والمُحلل الصحيح، وتجربة تغييرات مستوى النضج بشكل شامل باستخدام Go test واختبارات الانحدار في الدلائل depgraph و cmd/languages"},"useCases":{"en":["Validating parser and resolver behavior for new languages","Testing maturity level changes in language modules","Debugging language support issues in Clarity"],"zh":["验证新语言的解析器和解析器行为","测试语言模块中的成熟度级别更改","在 Clarity 中调试语言支持问题"],"ja":["新しい言語のパーサーおよび解決済み動作の検証","言語モジュール内の成熟度レベルの変更のテスト","Clarity での言語サポートの問題のデバッグ"],"ko":["新的 언어의 파서 및 해결기 동작을 검증","언어 모듈 내의 성숙도 수준 변경을 테스트","Clarity에서의 언어 지원 문제를 디버깅"],"es":["Validar el comportamiento del analizador y del resolutor para nuevos lenguajes","Probar cambios en el nivel de madurez en módulos de lenguaje","Depurar problemas de soporte de lenguaje en Clarity"],"fr":["Valider le comportement du parseur et du résolveur pour de nouvelles langues","Tester les changements de niveau de maturité dans les modules de langage","Déboguer les problèmes de support de langage dans Clarity"],"de":["Überprüfen des Verhaltens von Parser und Resolver für neue Sprachen","Testen von Änderungen des Reifegrads in Sprachmodulen","Fehlerbehebung bei Sprachunterstützungsproblemen in Clarity"],"pt":["Validar o comportamento do analisador e do resolvedor para novos idiomas","Testar alterações no nível de maturidade nos módulos de linguagem","Depurar problemas de suporte de linguagem no Clarity"],"ru":["Проверка поведения парсера и решателя для новых языков","Тестирование изменений уровня зрелости в модулях языка","Отладка проблем поддержки языка в Clarity"],"ar":["التحقق من سلوك المُحلل والمُحلل للغات الجديدة","اختبار التغييرات في مستوى النضج في وحدات اللغة","تصحيح مشاكل دعم اللغة في Clarity"]},"limitations":{"en":["Requires Go testing environment","Limited to Clarity language modules","Needs access to depgraph and cmd/languages directories"],"zh":["需要 Go 测试环境","仅限 Clarity 语言模块","需要访问 depgraph 和 cmd/languages 目录"],"ja":["Go テスト環境が必要","Clarity 言語モジュールに限定される","depgraph および cmd/languages ディレクトリへのアクセスが必要"],"ko":["Go 테스트 환경이 필요","Clarity 언어 모듈로 제한","depgraph 및 cmd/languages 디렉토리에 대한 액세스가 필요"],"es":["Requiere un entorno de pruebas Go","Limitado a módulos de lenguaje Clarity","Necesita acceso a los directorios depgraph y cmd/languages"],"fr":["Nécessite un environnement de test Go","Limité aux modules de langage Clarity","Nécessite l''accès aux répertoires depgraph et cmd/languages"],"de":["Benötigt eine Go-Testumgebung","Begrenzt auf Clarity-Sprachmodule","Benötigt Zugriff auf die Verzeichnisse depgraph und cmd/languages"],"pt":["Exige ambiente de teste Go","Limitado a módulos de linguagem Clarity","Necessita acesso aos diretórios depgraph e cmd/languages"],"ru":["Требуется среда тестирования Go","Ограничен модулями языка Clarity","Требуется доступ к директориям depgraph и cmd/languages"],"ar":["يتطلب بيئة اختبار Go","محدود بوحدات اللغة Clarity","يحتاج إلى الوصول إلى الدلائل depgraph و cmd/languages"]},"version":4},"contentHash":"8235a0124ad4176fdd8826a42f197ae49ab32af2010420f1cd8ce97cc0988156","qualityScore":29}');
