INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('LegacyCodeHQ/clarity/verify-language-support', 'verify-language-support', 'LegacyCodeHQ', 'clarity', 'community', 'verify-language-support LegacyCodeHQ clarity community The verify-language-support skill validates language support end-to-end in Clarity, benefiting AI-native developers and coding agents. It ensures parser/resolver behavior and maturity level changes are properly tested. verify-language-support 是 Clarity 中的一个工作流，用于验证语言支持。它包括目标语言模块、命令输出和解析器/解析行为的验证 verify-language-support は Clarity の言語サポートを検証するワークフローです。対象言語モジュール、コマンド出力、パーサー/リゾルバ動作の検証を含みます verify-language-support는 Clarity에서 언어 지원을 검증하는 워크플로우입니다. 대상 언어 모듈, 명령 출력 및 파서/리졸버 동작의 검증을 포함합니다 Verify-language-support es una herramienta para validar el soporte de idiomas en Clarity. Utiliza pruebas dirigidas y regresión para garantizar la precisión. Verify-language-support est un outil pour valider la prise en charge des langues dans Clarity. Il utilise des tests ciblés et de régression pour assurer la précision. Verify-language-support ist ein Tool zur Überprüfung der Sprachunterstützung in Clarity. Es verwendet gezielte Tests und Regressionstests, um die Genauigkeit zu gewährleisten. O verify-language-support é uma ferramenta de design de software para desenvolvedores de IA que valida o suporte de idiomas de forma eficiente. Verify-language-support - это инструмент для разработчиков ИИ, который проверяет поддержку языков в программном обеспечении. verify-language-support هي أداة تصميم برمجيات للمانحين الذكاء الاصطناعي التي تدعم التحقق من دعم اللغة how to use verify-language-support verify-language-support setup guide Clarity language support validation end-to-end testing for AI agents verify-language-support alternative verify-language-support vs Clarity install verify-language-support what is verify-language-support verify-language-support for AI-native developers AI 工具 Clarity 语言支持 verify-language-support Go 测试 解析器/解析行为 目标语言模块 命令输出 Runs targeted tests using `go test ./depgraph/<language>` Updates regression tests near changed logic in `d` Confirms current local changes with `git status --short` Validates parser/resolver behavior for target language modules under `depgraph/<language>/` Tests affected command output in `cmd/languages/` when maturity level changes verify-language-support is a workflow that validates language support in Clarity, confirming parser/resolver behavior and testing affected command output.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('macho715/hvdc-codex-ops/etl-duckdb', 'community', 'macho715', 'hvdc-codex-ops', 'macho715/hvdc-codex-ops', 'etl-duckdb', 0, 0, 29, '2026-03-08T01:57:15.432Z', '2026-03-08T02:07:34.950Z', 'f301f4d713e256f6e4064dce0b2e583f81ec6bc6cf76f61bca504c8f30f089ed', '{"id":"macho715/hvdc-codex-ops/etl-duckdb","name":"etl-duckdb","description":{"en":"The etl-duckdb skill executes a PowerShell script to perform ETL operations, outputting a DuckDB database file and a comprehensive Markdown report. It is designed for developers and data engineers who need to automate and validate data transformation pipelines.","zh":"etl-duckdb 是一个用于数据转换和报告生成的技能。它使用 PowerShell 脚本运行和输出数据","ja":"etl-duckdb はデータ変換とレポート生成に使用されるスキルです。PowerShell スクリプトを実行してデータを出力します","ko":"etl-duckdb는 데이터 변환 및 보고서 생성을 위한 스킬입니다. PowerShell 스크립트를 실행하여 데이터를 출력합니다","es":"etl-duckdb es una herramienta para cargar y transformar datos utilizando PowerShell y DuckDB. Permite generar informes y producir datos transformados","fr":"etl-duckdb est un outil pour charger et transformer des données en utilisant PowerShell et DuckDB. Il permet de générer des rapports et de produire des données transformées","de":"etl-duckdb ist ein Tool zum Laden und Transformieren von Daten mithilfe von PowerShell und DuckDB. Es ermöglicht die Generierung von Berichten und die Produktion von transformierten Daten","pt":"O ETL-DuckDB é uma ferramenta de extração, transformação e carga de dados que utiliza o DuckDB. Ela é projetada para desenvolvedores que necessitam de uma solução eficiente para gerenciar dados.","ru":"ETL-DuckDB — это инструмент для извлечения, преобразования и загрузки данных, использующий DuckDB. Он предназначен для разработчиков, которым нужен эффективный способ управления данными.","ar":"ETL-DuckDB هو أداة لاستخراج وتحويل وتحميل البيانات التي تستخدم DuckDB. وهي مصممة للبرمجين الذين يحتاجون إلى حل فعال لادارة البيانات."},"seo":{"title":{"en":"etl-duckdb: Automated ETL Pipeline Setup Guide | AI Agent...","zh":"etl-duckdb Setup Guide: PowerShell 执行和数据转换","ja":"etl-duckdb の設定方法: PowerShell 実行とデータ変換","ko":"etl-duckdb 설정 가이드: PowerShell 실행 및 데이터 변환","es":"Guía de Configuración de etl-duckdb para Desarrolladores","fr":"Guide d''Installation de etl-duckdb pour les Développeurs","de":"Einrichtungsleitfaden für etl-duckdb-Entwickler","pt":"Guia de Configuração do ETL-DuckDB: Ferramentas de IAs pa...","ru":"Настройка ETL-DuckDB: Лучшие практики для ИИ Агентов","ar":"دليل إعداد ETL-DuckDB: أدوات ذكاء اصطناعي للبرمجة"},"description":{"en":"Automate your ETL workflows with the etl-duckdb AI Agent skill. This PowerShell-driven tool processes data, outputs DuckDB files & generates detailed Markdow...","zh":"使用 etl-duckdb 进行数据转换和报告生成。了解如何运行 PowerShell 脚本和输出数据","ja":"etl-duckdb を使用してデータ変換とレポート生成を行う。PowerShell スクリプトの実行方法と出力データについて学ぶ","ko":"etl-duckdb를 사용하여 데이터 변환 및 보고서 생성을 수행합니다. PowerShell 스크립트 실행 및 출력 데이터에 대해 알아보기","es":"Aprende a configurar etl-duckdb para cargar y transformar datos con PowerShell y DuckDB","fr":"Découvrez comment installer et utiliser etl-duckdb pour charger et transformer des données avec PowerShell et DuckDB","de":"Erfahren Sie, wie Sie etl-duckdb einrichten, um Daten mit PowerShell und DuckDB zu laden und zu transformieren","pt":"Aprenda a configurar o ETL-DuckDB para desenvolvedores, com foco em ferramentas de IAs e tecnologias de programação","ru":"Узнайте, как настроить ETL-DuckDB для ИИ Агентов, с учетом технологий программирования и инструментов","ar":"تعلم كيفية إعداد ETL-DuckDB للبرمجة، مع التركيز على أدوات ذكاء اصطناعي وتقنيات البرمجة"},"definition":{"en":"etl-duckdb is an AI Agent skill that automates Extract, Transform, Load (ETL) workflows using a PowerShell script. It processes data inputs to generate a DuckDB database file and a detailed Markdown report containing metrics like input rows and null cells.","zh":"etl-duckdb 是一个 AI 工具，用于执行数据转换和报告生成","ja":"etl-duckdb は AI エージェントであり、データ変換とレポート生成を実行します","ko":"etl-duckdb는 데이터 변환 및 보고서 생성을 위한 AI 에이전트입니다","es":"etl-duckdb es una herramienta de extracción, transformación y carga de datos que utiliza DuckDB y PowerShell","fr":"etl-duckdb est un outil d''extraction, de transformation et de chargement de données qui utilise DuckDB et PowerShell","de":"etl-duckdb ist ein Tool für die Extraktion, Transformation und Ladung von Daten, das DuckDB und PowerShell verwendet","pt":"O que é ETL-DuckDB? É uma ferramenta de IAs para extração, transformação e carga de dados que utiliza o DuckDB.","ru":"Что такое ETL-DuckDB? Это инструмент ИИ Агентов для извлечения, преобразования и загрузки данных, использующий DuckDB.","ar":"ما هو ETL-DuckDB؟ هو أداة ذكاء اصطناعي لاستخراج وتحويل وتحميل البيانات التي تستخدم DuckDB."},"features":{"en":["Executes ETL processes via PowerShell script using the -ExecutionPolicy Bypass flag","Outputs a finalized DuckDB database file to data/_artifacts/ops.duckdb","Generates a comprehensive ETL report in Markdown format at reports/etl_report.md","Implements a fail-safe that creates a ''以묐떒'' table if inputs are missing","Collects and reports key evidence metrics: input_rows, null_cells, duplicated_rows, and duckdb_written"],"zh":["使用 PowerShell 脚本运行","输出数据到 data/_artifacts/ops.duckdb","生成报告到 reports/etl_report.md","支持 fail-safe 模式","输出 input_rows, null_cells, duplicated_rows, duckdb_written 数据"],"ja":["PowerShell スクリプトを使用して実行","データを data/_artifacts/ops.duckdb に出力","レポートを reports/etl_report.md に生成","fail-safe モードをサポート","input_rows, null_cells, duplicated_rows, duckdb_written データを出力"],"ko":["PowerShell 스크립트를 사용하여 실행","데이터를 data/_artifacts/ops.duckdb에 출력","보고서를 reports/etl_report.md에 생성","fail-safe 모드를 지원","input_rows, null_cells, duplicated_rows, duckdb_written 데이터를 출력"],"es":["Carga y transformación de datos con PowerShell","Integración con DuckDB para almacenar y consultar datos","Generación de informes en formato Markdown","Detección de filas duplicadas y celdas nulas","Escritura de datos en formato DuckDB"],"fr":["Chargement et transformation de données avec PowerShell","Intégration avec DuckDB pour stocker et interroger des données","Génération de rapports au format Markdown","Détection de lignes en double et de cellules vides","Écriture de données au format DuckDB"],"de":["Datenladen und -transformieren mit PowerShell","Integration mit DuckDB zum Speichern und Abfragen von Daten","Berichtsgenerierung im Markdown-Format","Erkennung von doppelten Zeilen und leeren Zellen","Daten schreiben im DuckDB-Format"],"pt":["Suporte ao DuckDB para armazenamento de dados","Capacidade de executar scripts em PowerShell","Geração de relatórios em formato Markdown","Opção de fail-safe para produzir relatórios parciais","Suporte à extração, transformação e carga de dados"],"ru":["Поддержка DuckDB для хранения данных","Возможность выполнять скрипты в PowerShell","Генерация отчетов в формате Markdown","Опция fail-safe для создания частичных отчетов","Поддержка извлечения, преобразования и загрузки данных"],"ar":["دعم DuckDB لتخزين البيانات","قدرة على تشغيل البرامج النصية في PowerShell","إنتاج تقارير بالتنسيق Markdown","خيار fail-safe لإنشاء تقارير جزئية","دعم استخراج وتحويل وتحميل البيانات"]},"keywords":{"en":["how to use etl-duckdb","what is etl-duckdb","etl-duckdb setup guide","etl-duckdb install","etl-duckdb vs custom script","etl-duckdb DuckDB output","etl-duckdb PowerShell ETL","etl-duckdb fail-safe mechanism","etl-duckdb report metrics"],"zh":["etl-duckdb","PowerShell 脚本","数据转换","报告生成","AI 工具","数据处理","duckdb","数据输出"],"ja":["etl-duckdb","PowerShell スクリプト","データ変換","レポート生成","AI エージェント","データ処理","duckdb","データ出力"],"ko":["etl-duckdb","PowerShell 스크립트","데이터 변환","보고서 생성","AI 에이전트","데이터 처리","duckdb","데이터 출력"],"es":["etl-duckdb","carga de datos","transformación de datos","PowerShell","DuckDB","informes de datos","extracción de datos","herramientas de datos"],"fr":["etl-duckdb","chargement de données","transformation de données","PowerShell","DuckDB","rapports de données","extraction de données","outils de données"],"de":["etl-duckdb","Datenladen","Datentransformierung","PowerShell","DuckDB","Datenberichte","Datenextraktion","Datenwerkzeuge"],"pt":["ETL-DuckDB","Ferramentas de IAs","DuckDB","Extração de dados","Transformação de dados","Carga de dados","PowerShell","Relatórios em Markdown"],"ru":["ETL-DuckDB","ИИ Агенты","DuckDB","Извлечение данных","Преобразование данных","Загрузка данных","PowerShell","Отчеты в формате Markdown"],"ar":["ETL-DuckDB","أدوات ذكاء اصطناعي","DuckDB","استخراج البيانات","تحويل البيانات","تحميل البيانات","PowerShell","التقارير بالتنسيق Markdown"]}},"owner":"macho715","repo":"hvdc-codex-ops","repoPath":"macho715/hvdc-codex-ops","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.432Z","topics":[],"category":"community","skillMd":{"name":"etl-duckdb","description":"Load CSV/XLSX into DuckDB with validation and an ETL markdown report","bodyPreview":"Instructions:\n- Run: powershell -ExecutionPolicy Bypass -File .codex/skills/etl-duckdb/scripts/run.ps1\n- Output:\n  - data/_artifacts/ops.duckdb\n  - reports/etl_report.md\nFail-safe:\n- If inputs missing, produce only the ''以묐떒'' table in reports/etl_report.md and exit.\nEvidence Required:\n- input_rows, null_cells, duplicated_rows, duckdb_written","body":"Instructions:\n- Run: powershell -ExecutionPolicy Bypass -File .codex/skills/etl-duckdb/scripts/run.ps1\n- Output:\n  - data/_artifacts/ops.duckdb\n  - reports/etl_report.md\nFail-safe:\n- If inputs missing, produce only the ''以묐떒'' table in reports/etl_report.md and exit.\nEvidence Required:\n- input_rows, null_cells, duplicated_rows, duckdb_written\n"},"lastSynced":"2026-03-08T02:07:34.950Z","agentAnalysis":{"suitability":{"en":"Ideal for Data Engineering Agents requiring automated ETL pipeline validation and DuckDB database generation.","zh":"适用于需要自动化ETL管道验证和DuckDB数据库生成的数据工程代理。","ja":"データエンジニアリングエージェントが自動化されたETLパイプラインの検証とDuckDBデータベースの生成を必要とする場合に最適です。","ko":"자동화된 ETL 파이프라인 유효성 검사와 DuckDB 데이터베이스 생성이 필요한 데이터 엔지니어링 에이전트에 적합합니다.","es":"Ideal para Agentes de Ingeniería de Datos que requieren una validación automatizada de canalizaciones ETL y generación de bases de datos DuckDB.","fr":"Idéal pour les Agents d''Ingénierie de Données nécessitant une validation automatique de canalisation ETL et une génération de base de données DuckDB.","de":"Ideal für Data-Engineering-Agents, die eine automatisierte Validierung von ETL-Pipelines und eine Generierung von DuckDB-Datenbanken erfordern.","pt":"Ideal para Agentes de Engenharia de Dados que exigem validação de pipeline ETL automatizada e geração de banco de dados DuckDB.","ru":"Идеально для агентов инженерии данных, требующих автоматизированную проверку конвейера ETL и генерацию базы данных DuckDB.","ar":"مثالي لعميل هندسة البيانات الذي يتطلب التحقق التلقائي من трубة ETL وتوليد قاعدة بيانات DuckDB."},"recommendation":{"en":"Empowers agents to execute PowerShell scripts for ETL operations, producing comprehensive Markdown reports and DuckDB database files, leveraging input validation and data transformation pipelines with metrics like input_rows, null_cells, and duplicated_rows.","zh":"赋予代理执行PowerShell脚本以进行ETL操作，生成全面Markdown报告和DuckDB数据库文件，利用输入验证和数据转换管道，具有input_rows、null_cells和duplicated_rows等指标。","ja":"エージェントがPowerShellスクリプトを実行してETL操作を実行し、包括的なMarkdownレポートとDuckDBデータベースファイルを生成します。入力検証とデータ変換パイプラインを利用し、input_rows、null_cells、duplicated_rowsなどの指標を使用します。","ko":"에이전트가 PowerShell 스크립트를 실행하여 ETL 작업을 수행하고, 포괄적인 Markdown 보고서와 DuckDB 데이터베이스 파일을 생성하여, 입력 유효성 검사 및 데이터 변환 파이프라인을 활용하며, input_rows, null_cells, duplicated_rows와 같은 지표를 사용합니다.","es":"Permite a los agentes ejecutar scripts de PowerShell para operaciones ETL, produciendo informes Markdown completos y archivos de base de datos DuckDB, aprovechando la validación de entrada y las canalizaciones de transformación de datos con métricas como input_rows, null_cells y duplicated_rows.","fr":"Permet aux agents d''exécuter des scripts PowerShell pour les opérations ETL, produisant des rapports Markdown complets et des fichiers de base de données DuckDB, en exploitant la validation des entrées et les pipelines de transformation de données avec des métriques comme input_rows, null_cells et duplicated_rows.","de":"Ermächtigt die Agenten, PowerShell-Skripte für ETL-Operationen auszuführen, um umfassende Markdown-Berichte und DuckDB-Datenbankdateien zu erstellen, die Eingabvalidierung und Daten-Transformationspipelines mit Metriken wie input_rows, null_cells und duplicated_rows nutzen.","pt":"Habilita os agentes a executar scripts PowerShell para operações ETL, produzindo relatórios Markdown abrangentes e arquivos de banco de dados DuckDB, aproveitando a validação de entrada e pipelines de transformação de dados com métricas como input_rows, null_cells e duplicated_rows.","ru":"Позволяет агентам выполнять скрипты PowerShell для операций ETL, производя всесторонние отчеты Markdown и файлы базы данных DuckDB, используя проверку ввода и конвейеры преобразования данных с метриками, такими как input_rows, null_cells и duplicated_rows.","ar":"يمكن للوكلاء تشغيل نصوص PowerShell لعمليات ETL ، مما ينتج تقارير Markdown شاملة وأماكن قاعدة بيانات DuckDB ، مستفيداً من التحقق من إدخال وممرات تحويل البيانات مع مقاييس مثل input_rows و null_cells و duplicated_rows."},"useCases":{"en":["Automating data transformation pipelines","Generating comprehensive ETL reports in Markdown format","Validating data quality with DuckDB output"],"zh":["自动化数据转换管道","生成Markdown格式的全面ETL报告","使用DuckDB输出验证数据质量"],"ja":["データ変換パイプラインの自動化","Markdown形式の包括的なETLレポートの生成","DuckDB出力を使用したデータ品質の検証"],"ko":["데이터 변환 파이프라인 자동화","Markdown 형식의 포괄적인 ETL 보고서 생성","DuckDB 출력을 사용한 데이터 품질 검증"],"es":["Automatización de canalizaciones de transformación de datos","Generación de informes ETL completos en formato Markdown","Validación de la calidad de los datos con salida de DuckDB"],"fr":["Automatisation des pipelines de transformation de données","Génération de rapports ETL complets au format Markdown","Validation de la qualité des données avec une sortie DuckDB"],"de":["Automatisierung von Daten-Transformationspipelines","Generierung umfassender ETL-Berichte im Markdown-Format","Validierung der Datenqualität mit DuckDB-Ausgabe"],"pt":["Automatizar pipelines de transformação de dados","Gerar relatórios ETL abrangentes no formato Markdown","Validar a qualidade dos dados com saída DuckDB"],"ru":["Автоматизировать конвейеры преобразования данных","Генерировать всесторонние отчеты ETL в формате Markdown","Проверять качество данных с выводом DuckDB"],"ar":["تأتمتة أنابيب تحويل البيانات","توليد تقارير ETL شاملة بالتنسيق Markdown","التحقق من جودة البيانات باستخدام إخراج DuckDB"]},"limitations":{"en":["Requires PowerShell execution environment","Dependent on input data availability for full functionality","Produces limited ''以묐떒'' table report if inputs are missing"],"zh":["需要PowerShell执行环境","需要输入数据以实现全部功能","如果输入缺失，仅生成有限的表格报告"],"ja":["PowerShell実行環境が必要","完全な機能を実現するために入力データが必要","入力が不足している場合、限定的な表形式のレポートのみを生成する"],"ko":["PowerShell 실행 환경이 필요함","전체 기능을 구현하기 위해 입력 데이터가 필요함","입력이 누락된 경우 제한된 표 형식의 보고서만 생성함"],"es":["Requiere un entorno de ejecución de PowerShell","Dependiente de la disponibilidad de datos de entrada para la funcionalidad completa","Produce un informe de tabla limitado ''以묐떒'' si los datos de entrada están ausentes"],"fr":["Nécessite un environnement d''exécution PowerShell","Dépend de la disponibilité des données d''entrée pour la fonctionnalité complète","Produit un rapport de table limité ''以묐떒'' si les données d''entrée sont manquantes"],"de":["Benötigt eine PowerShell-Ausführungsumgebung","Abhängig von der Verfügbarkeit der Eingabedaten für die vollständige Funktionalität","Erzeugt einen begrenzten ''以묐떒''-Tabellenbericht, wenn die Eingabedaten fehlen"],"pt":["Exige ambiente de execução PowerShell","Dependente da disponibilidade de dados de entrada para funcionalidade completa","Produz relatório de tabela limitado se as entradas estiverem faltando"],"ru":["Требует среды выполнения PowerShell","Зависит от наличия входных данных для полной функциональности","Производит ограниченный отчет таблицы, если входные данные отсутствуют"],"ar":["يتطلب بيئة تشغيل PowerShell","يعتمد على توافر بيانات الإدخال للوظائف الكاملة","ينتج تقرير جدول محدود إذا كانت الإدخالات ناقصة"]},"version":4},"contentHash":"f301f4d713e256f6e4064dce0b2e583f81ec6bc6cf76f61bca504c8f30f089ed","qualityScore":29}');
