INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('macho715/hvdc-codex-ops/etl-duckdb', 'etl-duckdb', 'macho715', 'hvdc-codex-ops', 'community', 'etl-duckdb macho715 hvdc-codex-ops community The etl-duckdb skill executes a PowerShell script to perform ETL operations, outputting a DuckDB database file and a comprehensive Markdown report. It is designed for developers and data engineers who need to automate and validate data transformation pipelines. etl-duckdb 是一个用于数据转换和报告生成的技能。它使用 PowerShell 脚本运行和输出数据 etl-duckdb はデータ変換とレポート生成に使用されるスキルです。PowerShell スクリプトを実行してデータを出力します etl-duckdb는 데이터 변환 및 보고서 생성을 위한 스킬입니다. PowerShell 스크립트를 실행하여 데이터를 출력합니다 etl-duckdb es una herramienta para cargar y transformar datos utilizando PowerShell y DuckDB. Permite generar informes y producir datos transformados etl-duckdb est un outil pour charger et transformer des données en utilisant PowerShell et DuckDB. Il permet de générer des rapports et de produire des données transformées etl-duckdb ist ein Tool zum Laden und Transformieren von Daten mithilfe von PowerShell und DuckDB. Es ermöglicht die Generierung von Berichten und die Produktion von transformierten Daten O ETL-DuckDB é uma ferramenta de extração, transformação e carga de dados que utiliza o DuckDB. Ela é projetada para desenvolvedores que necessitam de uma solução eficiente para gerenciar dados. ETL-DuckDB — это инструмент для извлечения, преобразования и загрузки данных, использующий DuckDB. Он предназначен для разработчиков, которым нужен эффективный способ управления данными. ETL-DuckDB هو أداة لاستخراج وتحويل وتحميل البيانات التي تستخدم DuckDB. وهي مصممة للبرمجين الذين يحتاجون إلى حل فعال لادارة البيانات. how to use etl-duckdb what is etl-duckdb etl-duckdb setup guide etl-duckdb install etl-duckdb vs custom script etl-duckdb DuckDB output etl-duckdb PowerShell ETL etl-duckdb fail-safe mechanism etl-duckdb report metrics etl-duckdb PowerShell 脚本 数据转换 报告生成 AI 工具 数据处理 duckdb 数据输出 Executes ETL processes via PowerShell script using the -ExecutionPolicy Bypass flag Outputs a finalized DuckDB database file to data/_artifacts/ops.duckdb Generates a comprehensive ETL report in Markdown format at reports/etl_report.md Implements a fail-safe that creates a ''以묐떒'' table if inputs are missing Collects and reports key evidence metrics: input_rows, null_cells, duplicated_rows, and duckdb_written etl-duckdb is an AI Agent skill that automates Extract, Transform, Load (ETL) workflows using a PowerShell script. It processes data inputs to generate a DuckDB database file and a detailed Markdown report containing metrics like input rows and null cells.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('hack-dance/hack/hack-cli', 'community', 'hack-dance', 'hack', 'hack-dance/hack', 'hack-cli', 0, 0, 29, '2026-03-08T01:57:15.438Z', '2026-03-08T02:08:50.641Z', '14aa38fb0747528de111e45fd1d094729ec60bcf46a445aebca3597e17a6e8b0', '{"id":"hack-dance/hack/hack-cli","name":"hack-cli","description":{"en":"hack-cli is a tool for opinionated local-dev orchestration, helping developers run multiple projects simultaneously without port conflicts. It benefits developers working on complex projects.","zh":"hack-cli 是一个本地开发工具，用于解决多个项目同时运行时的端口冲突问题。它提供了一种简单的方式来管理和编排本地开发环境。","ja":"hack-cli は、複数のプロジェクトを同時に実行する際のポートの競合問題を解決するためのローカル開発ツールです。シンプルな方法でローカル開発環境を管理およびオーケストレーションします。","ko":"hack-cli는 여러 프로젝트를 동시에 실행할 때 발생하는 포트 충돌 문제를 해결하는 로컬 개발 도구입니다. 로컬 개발 환경을 관리하고 오케스트레이션하는 간단한 방법을 제공합니다.","es":"hack-cli es una herramienta de orquestación local para proyectos de desarrollo que evita conflictos de puertos. Utiliza hack como interfaz principal para el desarrollo local.","fr":"hack-cli est un outil d''orchestration local pour les projets de développement qui évite les conflits de ports. Utilisez hack comme interface principale pour le développement local.","de":"hack-cli ist ein Tool für die lokale Orchestrierung von Entwicklungsprojekten, das Portkonflikte vermeidet. Verwenden Sie hack als primäre Schnittstelle für die lokale Entwicklung.","pt":"O hack-cli é uma ferramenta de orquestração de desenvolvimento local que permite executar múltiplos projetos simultaneamente sem conflitos de portas.","ru":"Hack-cli - это инструмент локальной разработки, который позволяет запускать несколько проектов одновременно без конфликтов портов с помощью ИИ Агентов.","ar":"hack-cli هو أداة تنسيق تطوير محلية تتيح تشغيل مشاريع متعددة في وقت واحد بدون صراعات منافذ"},"seo":{"title":{"en":"hack-cli: Local Dev Orchestration Setup Guide | AI Agent ...","zh":"hack-cli 本地开发设置指南","ja":"hack-cli ローカル開発ベストプラクティス","ko":"hack-cli 로컬 개발 환경 설정 가이드","es":"Guía de configuración de hack-cli para desarrollos locales","fr":"Guide de démarrage de hack-cli pour les environnements de...","de":"Einrichtungsleitfaden für hack-cli in lokalen Entwicklung...","pt":"Guia de Configuração do hack-cli: Orquestração de Projeto...","ru":"Настройка hack-cli: локальная разработка без конфликтов п...","ar":"دليل إعداد hack-cli: تنسيق التطوير المحلي بدون صراعات منافذ"},"description":{"en":"Streamline local development with hack-cli. Learn how to avoid port conflicts and manage multiple projects seamlessly. Get started now!","zh":"使用 hack-cli 进行本地开发，解决端口冲突问题，提高开发效率。了解 hack-cli 的操作规则和配置方案。","ja":"hack-cli を使用してローカル開発を実施し、ポートの競合問題を解決します。hack-cli の操作ルールと構成スキーマについて学習します。","ko":"hack-cli를 사용하여 로컬 개발을 진행하고 포트 충돌 문제를 해결하여 개발 효율을 높입니다. hack-cli의 운영 규칙과 구성 스키마에 대해 알아보세요.","es":"Aprende a utilizar hack-cli para gestionar múltiples proyectos sin conflictos de puertos y sigue las mejores prácticas para su uso","fr":"Découvrez comment utiliser hack-cli pour gérer plusieurs projets sans conflits de ports et suivez les meilleures pratiques pour son utilisation","de":"Erfahren Sie, wie Sie hack-cli verwenden können, um mehrere Projekte ohne Portkonflikte zu verwalten und folgen Sie den besten Praktiken für dessen Einsatz","pt":"Aprenda a usar o hack-cli para gerenciar múltiplos projetos locais sem conflitos de portas. Descubra como configurar e otimizar seu fluxo de trabalho de dese...","ru":"Узнайте, как использовать hack-cli для управления несколькими локальными проектами без конфликтов портов. Откройте для себя, как настроить и оптимизировать с...","ar":"تعرف على كيفية استخدام hack-cli لإدارة مشاريع متعددة محلية بدون صراعات منافذ. اكتشف كيفية تنفيذ وتحسين تدفق عملك التطويري"},"definition":{"en":"hack-cli is an opinionated local-dev orchestration tool for running multiple projects at the same time without port conflicts.","zh":"hack-cli 是一个命令行工具，用于本地开发环境的管理和编排。","ja":"hack-cli は、ローカル開発環境を管理およびオーケストレーションするためのコマンドラインツールです。","ko":"hack-cli는 로컬 개발 환경을 관리하고 오케스트레이션하는 커맨드 라인 도구입니다.","es":"hack-cli es una herramienta de línea de comandos (CLI) para la orquestación de proyectos de desarrollo local","fr":"hack-cli est un outil en ligne de commande (CLI) pour l''orchestration de projets de développement local","de":"hack-cli ist ein Kommandozeilen-Tool (CLI) für die Orchestrierung von lokalen Entwicklungsumgebungen","pt":"O que é hack-cli? É uma ferramenta de orquestração de desenvolvimento local que gerencia projetos sem conflitos de portas.","ru":"Что такое hack-cli? Это инструмент локальной разработки, который управляет проектами без конфликтов портов с ИИ Агентами.","ar":"ما هو hack-cli? هو أداة تنسيق تطوير محلية لإدارة المشاريع بدون صراعات منافذ"},"features":{"en":["Uses `hack` as the primary interface for local development","Runs `hack doctor` for manual runtime and network repair","Manages project services using `docker` and `docker compose`","Utilizes `.hack/.internal` and `.hack/.branch` as managed artifacts","Prevents port conflicts when running multiple projects simultaneously","Supports MCP for shell access when unavailable"],"zh":["使用 Docker 和 Docker Compose 进行本地开发","自动管理端口冲突问题","提供 hack doctor 命令来诊断和修复问题","支持 MCP 和 shell 访问","生成和管理 hack 内部文件"],"ja":["Docker と Docker Compose を使用したローカル開発","ポートの競合問題を自動的に管理","hack doctor コマンドを使用して問題を診断および修復","MCP とシェルアクセスをサポート","hack 内部ファイルを生成および管理"],"ko":["Docker와 Docker Compose를 사용한 로컬 개발","포트 충돌 문제를 자동으로 관리","hack doctor 명령을 사용하여 문제를 진단 및 修復","MCP와 쉘 접근을 지원","hack 내부 파일을 생성 및 관리"],"es":["Orquestación de proyectos de desarrollo local","Evita conflictos de puertos","Utiliza Docker y docker-compose de manera eficiente","Incluye comandos como ''hack doctor'' para diagnosticar y reparar problemas","Genera archivos de configuración automáticamente","Permite el uso de MCP cuando no se tiene acceso a la shell"],"fr":["Orchestration de projets de développement local","Évite les conflits de ports","Utilise Docker et docker-compose de manière efficace","Inclut des commandes comme ''hack doctor'' pour diagnostiquer et réparer les problèmes","Génère des fichiers de configuration automatiquement","Permet l''utilisation de MCP lorsque l''accès à la shell n''est pas disponible"],"de":["Orchestrierung von lokalen Entwicklungsumgebungen","Vermeidet Portkonflikte","Nutzt Docker und docker-compose effizient","Enthält Befehle wie ''hack doctor'' zur Diagnose und Reparatur von Problemen","Generiert Konfigurationsdateien automatisch","Ermöglicht die Verwendung von MCP, wenn der Shell-Zugriff nicht verfügbar ist"],"pt":["Gerenciamento de múltiplos projetos locais","Evita conflitos de portas","Interface primária para desenvolvimento local com `hack`","Suporte a `docker` e `docker compose`","Comandos `hack doctor` e `hack doctor --fix` para reparo de runtime e rede"],"ru":["Управление несколькими локальными проектами","Избежание конфликтов портов","Основной интерфейс для локальной разработки с `hack` и ИИ Агентами","Поддержка `docker` и `docker compose`","Команды `hack doctor` и `hack doctor --fix` для ремонта runtime и сети"],"ar":["إدارة مشاريع متعددة محلية","تجنب صراعات منافذ","واجهة رئيسية لالتطوير المحلي مع `hack`","دعم `docker` و `docker compose`","أوامر `hack doctor` و `hack doctor --fix` لصيانة وقت التشغيل و الشبكة"]},"keywords":{"en":["how to use hack-cli","hack-cli setup guide","hack-cli vs docker","hack-cli alternative","what is hack-cli","hack-cli install","hack-cli local development","avoiding port conflicts with hack-cli","hack-cli docker compose","hack-cli tutorial"],"zh":["hack-cli","本地开发工具","端口冲突解决","Docker","Docker Compose","MCP","shell 访问","hack doctor","AI工具","AIエージェント"],"ja":["hack-cli","ローカル開発ツール","ポートの競合問題","Docker","Docker Compose","MCP","シェルアクセス","hack doctor","AIエージェント","コマンドラインツール"],"ko":["hack-cli","로컬 개발 도구","포트 충돌 해결","Docker","Docker Compose","MCP","쉘 접근","hack doctor","AI 도구","로컬 개발 환경"],"es":["hack-cli","desarrollo local","orquestación de proyectos","evitar conflictos de puertos","docker","docker-compose","herramientas de desarrollo","CLI","desarrollo de software"],"fr":["hack-cli","développement local","orchestration de projets","éviter les conflits de ports","docker","docker-compose","outils de développement","CLI","développement de logiciels"],"de":["hack-cli","lokale Entwicklung","Orchestrierung von Projekten","Vermeidung von Portkonflikten","docker","docker-compose","Entwicklungstools","CLI","Software-Entwicklung"],"pt":["hack-cli","orquestração de desenvolvimento local","gerenciamento de projetos locais","conflitos de portas","docker","docker compose","desenvolvimento de software"],"ru":["hack-cli","локальная разработка","управление проектами","конфликты портов","docker","docker compose","разработка программного обеспечения","ИИ Агенты"],"ar":["hack-cli","تنسيق التطوير المحلي","إدارة مشاريع محلية","صراعات منافذ","docker","docker compose","تطوير البرمجيات"]}},"owner":"hack-dance","repo":"hack","repoPath":"hack-dance/hack","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.438Z","topics":[],"category":"community","skillMd":{"name":"hack-cli","description":">","bodyPreview":"# hack CLI\n\nUse `hack` as the primary interface for local development.\n\n## Operating Rules\n\n- Prefer `hack` over raw `docker` / `docker compose`.\n- Do not start/stop project services from Docker Desktop UI for `hack`-managed repos.\n- Treat `.hack/.internal` and `.hack/.branch` as hack-managed artifacts; avoid hand-editing generated files.\n- Use MCP only when shell access is unavailable.\n- Run `hack doctor` (and `hack doctor --fix`) before manual runtime/network repair.\n\n## Config + Schema\n\n- Pro","body":"# hack CLI\n\nUse `hack` as the primary interface for local development.\n\n## Operating Rules\n\n- Prefer `hack` over raw `docker` / `docker compose`.\n- Do not start/stop project services from Docker Desktop UI for `hack`-managed repos.\n- Treat `.hack/.internal` and `.hack/.branch` as hack-managed artifacts; avoid hand-editing generated files.\n- Use MCP only when shell access is unavailable.\n- Run `hack doctor` (and `hack doctor --fix`) before manual runtime/network repair.\n\n## Config + Schema\n\n- Project config: `.hack/hack.config.json`\n- Global config: `~/.hack/hack.config.json`\n- Schema URL: `https://schemas.hack/hack.config.schema.json`\n- Prefer CLI config edits via `hack config get/set`.\n\n## Hostname Routing\n\n- Primary host is `dev_host` (default: `<project>.hack`).\n- Subdomains use `<sub>.<dev_host>` (for example: `api.myapp.hack`).\n- OAuth alias can add `<dev_host>.<tld>` and `<sub>.<dev_host>.<tld>` (default: `gy`).\n- Only HTTP services with Caddy labels and `hack-dev` network attachment are routable.\n- Required labels: `caddy`, `caddy.reverse_proxy`, `caddy.tls=internal`.\n- Quick checks: `hack open`, `hack open <sub>`, `hack open --json`.\n\n## TLS + OAuth Host Rules\n\n- Caddy internal PKI provides HTTPS for routed hosts; trust CA with `hack global trust`.\n- `.hack` is local-first and not a public suffix.\n- Use alias hosts like `*.hack.gy` when provider callback validation rejects non-public-suffix hosts.\n- Alias hosts are local routes unless you explicitly add remote ingress/tunnel plumbing.\n\n## Managed Files\n\n- Source-of-truth files: `.hack/docker-compose.yml`, `.hack/hack.config.json`, `.hack/hack.env.json`.\n- Local-only files: `.hack/.env` and `.hack/.internal/` (gitignored; machine-specific state).\n- Generated by hack: `.hack/.internal/compose.override.yml`, `.hack/.internal/compose.env.override.yml`, `.hack/.branch/compose.<branch>.override.yml`.\n- Managed via CLI: `.hack/.internal/extra-hosts.json` using `hack internal extra-hosts ...` commands.\n- Lifecycle runtime files: `.hack/.internal/lifecycle/state.json`, `.hack/.internal/lifecycle/*.log`.\n\n## Advanced Networking\n\n- Static host mappings: set `internal.extra_hosts` in `.hack/hack.config.json`.\n- Dynamic mappings for local proxies/tunnels: `hack internal extra-hosts set <hostname> <target>`.\n- List/remove mappings: `hack internal extra-hosts list` / `hack internal extra-hosts unset <hostname>`.\n- Prefer `host-gateway` for host-local proxy targets when possible.\n- Apply changes with `hack restart`; verify with `hack doctor`.\n\n## Quick Start\n\n- Bootstrap project config: `hack init`\n- Start services: `hack up --detach`\n- Alternate shorthand: `hack up -d`\n- Restart services: `hack restart`\n- Open app: `hack open --json`\n- Tail logs (compose): `hack logs --pretty`\n- Per-service logs: `hack logs <service>`\n- Snapshot logs: `hack logs --json --no-follow`\n- Loki history/query: `hack logs --loki --since 2h --pretty`\n- Run commands: `hack run <service> <cmd...>`\n- Stop services: `hack down`\n\n## Global Infra\n\n- Install once: `hack global install`\n- Start/stop/status: `hack global up`, `hack global down`, `hack global status`\n- Global logs: `hack global logs <service> --no-follow --tail 200`\n\n## Remote Nodes + Dispatch\n\n- Pair/register a node: `hack node pair ...`, then verify via `hack node list` and `hack node status --watch`.\n- Repair SSH access for remote Git/mutagen: `hack node ssh setup --node <id>`.\n- Inspect node workspace map on the node host: `ssh <user@host> ''hack node workspace list --json''`.\n- Inspect/repair controller route bridge: `hack node routes status`, `hack node routes repair`.\n- Dispatch command to remote workspace: `hack dispatch run --project <name|id> --node default --branch <branch> --runner generic -- \"pwd\"`.\n\n## Lifecycle + Startup\n\n- Put host setup in `.hack/hack.config.json` under `startup` / `lifecycle`.\n- Use lifecycle processes for long-running host tasks, not ad-hoc terminals.\n- Inspect via `hack projects --details` and `hack logs <service-or-process>`.\n\n## Branch Instances\n\nUse branch instances to run parallel environments:\n\n- `hack up --branch <name> --detach`\n- `hack open --branch <name>`\n- `hack logs --branch <name>`\n- `hack down --branch <name>`\n\n## Sessions\n\n- Picker: `hack session`\n- Start/attach: `hack session start <project>`\n- Isolated agent session: `hack session start <project> --new --name agent-1`\n- Exec: `hack session exec <session> \"<command>\"`\n- Stop: `hack session stop <session>`\n\n## Tickets\n\n- Create: `hack tickets create --title \"...\" --body-stdin`\n- List/show: `hack tickets list`, `hack tickets show T-00001`\n- Status/sync: `hack tickets status T-00001 in_progress`, `hack tickets sync`\n\n## Project Targeting\n\n- Run from repo root when possible.\n- Otherwise use `--project <name>` or `--path <repo-root>`.\n- List projects: `hack projects --json`.\n\n## Agent Maintenance\n\n- Project-level hack commands auto-check integration drift and attempt auto-sync.\n- Set `HACK_SETUP_SYNC_MODE=warn` to warn-only, or `HACK_SETUP_SYNC_MODE=off` to disable.\n- Refresh project + global integrations: `hack setup sync --all-scopes`\n- Check generated integrations: `hack setup sync --all-scopes --check`\n- Remove generated integrations: `hack setup sync --all-scopes --remove`\n- After self-update: `hack update` then `hack setup sync --all-scopes`\n\n## Agent Setup\n\n- Cursor rules: `hack setup cursor`\n- Claude hooks: `hack setup claude`\n- Codex skill: `hack setup codex`\n- Tickets skill: `hack setup tickets`\n- Init prompt: `hack agent init` (use --client cursor|claude|codex to open)\n- Init patterns: `hack agent patterns`\n- MCP (no shell only): `hack setup mcp`\n- MCP install (explicit): `hack mcp install --all --scope project`\n"},"lastSynced":"2026-03-08T02:08:50.641Z","agentAnalysis":{"suitability":{"en":"Ideal for Local Development Agents requiring seamless project orchestration and port conflict resolution.","zh":"适用于需要无缝项目编排和端口冲突解决的本地开发代理。","ja":"ローカル開発エージェントがプロジェクトのオーケストレーションとポートのコンフリクト解決をスムーズに実行する必要がある場合に最適です。","ko":"프로젝트 오케스트레이션과 포트 충돌 해결을 무중단으로 수행해야 하는 로컬 개발 에이전트에 적합합니다.","es":"Ideal para agentes de desarrollo local que requieren una orquestación de proyecto sin problemas y resolución de conflictos de puerto.","fr":"Idéal pour les agents de développement local nécessitant une orchestration de projet sans problème et une résolution de conflits de port.","de":"Ideal für lokale Entwicklungsschritte, die eine reibungslose Projektorchestrierung und Portkonfliktlösung erfordern.","pt":"Ideal para Agentes de Desenvolvimento Local que exigem orquestração de projeto sem problemas e resolução de conflitos de porta.","ru":"Идеально для Локальных Разработчиков, требующих бесшовной оркестрации проектов и разрешения конфликтов портов.","ar":"مثالي لعميل التطوير المحلي الذي يتطلب تنسيق مشروع متكامل وحل النزاعات البورتية."},"recommendation":{"en":"Empowers agents to manage multiple projects simultaneously using `docker` and `docker compose` under the `hack` interface, preventing port conflicts and ensuring efficient local development with features like `hack doctor` for runtime and network repair.","zh":"赋予代理同时管理多个项目的能力，使用 `docker` 和 `docker compose` 在 `hack` 接口下，防止端口冲突，确保本地开发的高效，并具有如 `hack doctor` 的运行时和网络修复功能。","ja":"エージェントが `docker` と `docker compose` を使用して `hack` インターフェイスの下で複数のプロジェクトを同時に管理できるようにし、ポートのコンフリクトを防ぎ、ローカル開発を効率化します。さらに、`hack doctor` などの実行時とネットワークの修復機能を備えています。","ko":"에이전트가 `docker`와 `docker compose`를 사용하여 `hack` 인터페이스 아래에서 여러 프로젝트를 동시에 관리할 수 있도록 하여 포트 충돌을 방지하고 로컬 개발을 효율적으로 수행하며, `hack doctor`와 같은 런타임 및 네트워크 복구 기능을 제공합니다.","es":"Habilita a los agentes a gestionar múltiples proyectos simultáneamente utilizando `docker` y `docker compose` bajo la interfaz `hack`, evitando conflictos de puerto y garantizando un desarrollo local eficiente con funciones como `hack doctor` para la reparación de tiempo de ejecución y red.","fr":"Permet aux agents de gérer plusieurs projets simultanément en utilisant `docker` et `docker compose` sous l''interface `hack`, en évitant les conflits de port et en garantissant un développement local efficace avec des fonctionnalités comme `hack doctor` pour la réparation du runtime et du réseau.","de":"Ermöglicht es Agenten, mehrere Projekte gleichzeitig mit `docker` und `docker compose` unter der `hack`-Schnittstelle zu verwalten, Portkonflikte zu vermeiden und einen effizienten lokalen Entwicklungsprozess mit Funktionen wie `hack doctor` für Laufzeit- und Netzwerkreparaturen sicherzustellen.","pt":"Habilita os agentes a gerenciar vários projetos simultaneamente usando `docker` e `docker compose` sob a interface `hack`, prevenindo conflitos de porta e garantindo desenvolvimento local eficiente com recursos como `hack doctor` para reparo em tempo de execução e rede.","ru":"Наделяет агентов возможностью управлять несколькими проектами одновременно, используя `docker` и `docker compose` под интерфейсом `hack`, предотвращая конфликты портов и гарантируя эффективную локальную разработку с такими функциями, как `hack doctor` для ремонтных и сетевых работ.","ar":"يمنح الوكلاء القدرة على إدارة مشاريع متعددة في نفس الوقت باستخدام `docker` و `docker compose` تحت واجهة `hack` ، وتجنب النزاعات البورتية وضمان التطوير المحلي الفعال باستخدام ميزات مثل `hack doctor` لإصلاح وقت التشغيل والشبكة."},"useCases":{"en":["Orchestrating local development for complex projects","Resolving port conflicts between multiple project services","Automating runtime and network repairs with `hack doctor`"],"zh":["编排复杂项目的本地开发","解决多个项目服务之间的端口冲突","使用 `hack doctor` 自动执行运行时和网络修复"],"ja":["複雑なプロジェクトのローカル開発のオーケストレーション","複数のプロジェクトサービス間のポートコンフリクトの解決","`hack doctor` を使用した実行時とネットワークの自動修復"],"ko":["복잡한 프로젝트의 로컬 개발 오케스트레이션","여러 프로젝트 서비스 간의 포트 충돌 해결","`hack doctor`를 사용한 런타임 및 네트워크 자동 복구"],"es":["Orquestar el desarrollo local para proyectos complejos","Resolver conflictos de puerto entre múltiples servicios de proyecto","Automatizar reparaciones de tiempo de ejecución y red con `hack doctor`"],"fr":["Orchestrer le développement local pour les projets complexes","Résoudre les conflits de port entre les services de projet multiples","Automatiser les réparations du runtime et du réseau avec `hack doctor`"],"de":["Orchestrieren der lokalen Entwicklung für komplexe Projekte","Auflösen von Portkonflikten zwischen mehreren Projektservices","Automatisieren von Laufzeit- und Netzwerkreparaturen mit `hack doctor`"],"pt":["Orquestração do desenvolvimento local para projetos complexos","Resolução de conflitos de porta entre vários serviços de projeto","Automação de reparos de tempo de execução e rede com `hack doctor`"],"ru":["Оркестрация локального развития для сложных проектов","Разрешение конфликтов портов между несколькими сервисами проекта","Автоматизация ремонтных и сетевых работ с помощью `hack doctor`"],"ar":["تنسيق التطوير المحلي لمشاريع معقدة","حل النزاعات البورتية بين خدمات المشروع المتعددة","أتمتة إصلاحات وقت التشغيل والشبكة باستخدام `hack doctor`"]},"limitations":{"en":["Requires adherence to operating rules for `hack`-managed repositories","Avoids hand-editing generated files in `.hack/.internal` and `.hack/.branch`","Limited to local development environments"],"zh":["需要遵守 `hack` 管理存储库的操作规则","避免手动编辑 `.hack/.internal` 和 `.hack/.branch` 生成的文件","仅限本地开发环境"],"ja":["`hack` 管理リポジトリの操作ルールを遵守する必要がある","`.hack/.internal` と `.hack/.branch` 生成されたファイルを手動で編集しない","ローカル開発環境のみに限定"],"ko":["`hack` 관리 저장소의 운영 규칙을 준수해야 함",".hack/.internal` 및 `.hack/.branch` 생성된 파일의 수동 편집을 피함","로컬 개발 환경에만 제한"],"es":["Requiere la adherencia a las reglas de funcionamiento para los repositorios administrados por `hack`","Evita la edición manual de los archivos generados en `.hack/.internal` y `.hack/.branch`","Limitado a entornos de desarrollo local"],"fr":["Nécessite l''adhésion aux règles de fonctionnement pour les référentiels gérés par `hack`","Évite l''édition manuelle des fichiers générés dans `.hack/.internal` et `.hack/.branch`","Limité aux environnements de développement local"],"de":["Erfordert die Einhaltung der Betriebsregeln für von `hack` verwaltete Repositorys","Vermeidet die manuelle Bearbeitung von in `.hack/.internal` und `.hack/.branch` generierten Dateien","Begrenzt auf lokale Entwicklungsumgebungen"],"pt":["Exige aderência às regras de funcionamento para repositórios gerenciados por `hack`","Evita a edição manual de arquivos gerados em `.hack/.internal` e `.hack/.branch`","Limitado a ambientes de desenvolvimento local"],"ru":["Требует соблюдения правил работы для репозиториев, управляемых `hack`","Избегает ручного редактирования сгенерированных файлов в `.hack/.internal` и `.hack/.branch`","Ограничен локальными средами разработки"],"ar":["يتطلب الالتزام بقواعد التشغيل للمستودعات التي يديرها `hack`","يتجنب تحرير الملفات الم生成 يدويًا في `.hack/.internal` و `.hack/.branch`","محدود بالبيئات التطويرية المحلية"]},"version":4},"contentHash":"14aa38fb0747528de111e45fd1d094729ec60bcf46a445aebca3597e17a6e8b0","qualityScore":29}');
