INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('hack-dance/hack/hack-cli', 'hack-cli', 'hack-dance', 'hack', 'community', 'hack-cli hack-dance hack community hack-cli is a tool for opinionated local-dev orchestration, helping developers run multiple projects simultaneously without port conflicts. It benefits developers working on complex projects. hack-cli 是一个本地开发工具，用于解决多个项目同时运行时的端口冲突问题。它提供了一种简单的方式来管理和编排本地开发环境。 hack-cli は、複数のプロジェクトを同時に実行する際のポートの競合問題を解決するためのローカル開発ツールです。シンプルな方法でローカル開発環境を管理およびオーケストレーションします。 hack-cli는 여러 프로젝트를 동시에 실행할 때 발생하는 포트 충돌 문제를 해결하는 로컬 개발 도구입니다. 로컬 개발 환경을 관리하고 오케스트레이션하는 간단한 방법을 제공합니다. hack-cli es una herramienta de orquestación local para proyectos de desarrollo que evita conflictos de puertos. Utiliza hack como interfaz principal para el desarrollo local. hack-cli est un outil d''orchestration local pour les projets de développement qui évite les conflits de ports. Utilisez hack comme interface principale pour le développement local. hack-cli ist ein Tool für die lokale Orchestrierung von Entwicklungsprojekten, das Portkonflikte vermeidet. Verwenden Sie hack als primäre Schnittstelle für die lokale Entwicklung. O hack-cli é uma ferramenta de orquestração de desenvolvimento local que permite executar múltiplos projetos simultaneamente sem conflitos de portas. Hack-cli - это инструмент локальной разработки, который позволяет запускать несколько проектов одновременно без конфликтов портов с помощью ИИ Агентов. hack-cli هو أداة تنسيق تطوير محلية تتيح تشغيل مشاريع متعددة في وقت واحد بدون صراعات منافذ how to use hack-cli hack-cli setup guide hack-cli vs docker hack-cli alternative what is hack-cli hack-cli install hack-cli local development avoiding port conflicts with hack-cli hack-cli docker compose hack-cli tutorial hack-cli 本地开发工具 端口冲突解决 Docker Docker Compose MCP shell 访问 hack doctor AI工具 AIエージェント Uses `hack` as the primary interface for local development Runs `hack doctor` for manual runtime and network repair Manages project services using `docker` and `docker compose` Utilizes `.hack/.internal` and `.hack/.branch` as managed artifacts Prevents port conflicts when running multiple projects simultaneously Supports MCP for shell access when unavailable hack-cli is an opinionated local-dev orchestration tool for running multiple projects at the same time without port conflicts.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kindfi-org/kindfi/stellar-dev', 'community', 'kindfi-org', 'kindfi', 'kindfi-org/kindfi', 'stellar-dev', 0, 0, 29, '2026-03-08T01:57:15.452Z', '2026-03-08T02:09:00.714Z', 'b8dcd872cda86918f9dd42ff0e482f8a7631c3d9948db2a8b3cba2d6f3156b3f', '{"id":"kindfi-org/kindfi/stellar-dev","name":"stellar-dev","description":{"en":"The stellar-dev skill enables developers to build Web3 crowdfunding platforms on Stellar, featuring milestone-based escrows and gamified engagement. It benefits developers working with Soroban smart contracts and Stellar dApp frontend development.","zh":"Stellar开发技能是用于构建Stellar区块链应用的技能，包括Soroban智能合约开发和Stellar dApp前端工作","ja":"Stellar開発スキルは、Stellarブロックチェーンアプリケーションを構築するために使用されるスキルで、Sorobanスマートコントラクト開発とStellar dAppフロントエンド作業が含まれます","ko":"Stellar 개발 스킬은 Stellar 블록체인 애플리케이션을 구축하기 위해 사용되는 스킬로, Soroban 스마트 컨트랙트 개발과 Stellar dApp 프론트엔드 작업이 포함됩니다","es":"stellar-dev es una habilidad para desarrollar contratos inteligentes en Stellar con Soroban y crear aplicaciones descentralizadas con React y Node.js","fr":"stellar-dev est une compétence pour développer des contrats intelligents sur Stellar avec Soroban et créer des applications décentralisées avec React et Node.js","de":"stellar-dev ist eine Fähigkeit zur Entwicklung von Smart Contracts auf Stellar mit Soroban und zur Erstellung dezentraler Anwendungen mit React und Node.js","pt":"O stellar-dev é uma habilidade de desenvolvimento Web3 que permite criar aplicações com Soroban, React e Node.js. Aprenda a configurá-lo","ru":"ИИ Агент stellar-dev - это навык разработки Web3, который позволяет создавать приложения с помощью Soroban, React и Node.js. Узнайте, как его настроить","ar":"stellar-dev هو مهارة تطور الويب 3 التي تمكن من إنشاء تطبيقات باستخدام Soroban و React و Node.js. تعلم كيفية إعداده"},"seo":{"title":{"en":"stellar-dev: Soroban Smart Contract Development Setup Gui...","zh":"Stellar开发技能：Soroban智能合约开发指南","ja":"Stellar開発スキル：Sorobanスマートコントラクト開発ベストプラクティス","ko":"Stellar 개발 스킬: Soroban 스마트 컨트랙트 개발 가이드","es":"Guía de configuración de stellar-dev para desarrollo de c...","fr":"Guide de mise en place de stellar-dev pour le développeme...","de":"Setup-Anleitung für stellar-dev: Entwicklung von Smart Co...","pt":"Guia de Configuração do stellar-dev para Desenvolvedores","ru":"Настройка ИИ Агента stellar-dev: Руководство для Разработ...","ar":"دليل إعداد stellar-dev للتنمية: أدوات ذكاء اصطناعي"},"description":{"en":"Unlock the power of Stellar development with stellar-dev. Learn how to build milestone-based escrows, gamified engagement, and LLM tools. Get started now!","zh":"了解Stellar开发技能，包括Soroban智能合约开发、Stellar dApp前端工作和钱包连接等","ja":"Stellar開発スキルを学ぶ：Sorobanスマートコントラクト開発、Stellar dAppフロントエンド作業、ウォレット接続など","ko":"Stellar 개발 스킬을 알아보세요: Soroban 스마트 컨트랙트 개발, Stellar dApp 프론트엔드 작업, 지갑 연결 등","es":"Aprenda a utilizar stellar-dev para desarrollar contratos inteligentes en Stellar con Soroban, React y Node.js","fr":"Découvrez comment utiliser stellar-dev pour développer des contrats intelligents sur Stellar avec Soroban, React et Node.js","de":"Erfahren Sie, wie Sie stellar-dev für die Entwicklung von Smart Contracts auf Stellar mit Soroban, React und Node.js verwenden","pt":"Aprenda a configurar o stellar-dev para desenvolver aplicações Web3 com Soroban, React e Node.js","ru":"Узнайте, как настроить ИИ Агент stellar-dev для разработки приложений Web3 с помощью Soroban, React и Node.js","ar":"تعلم كيفية إعداد stellar-dev لتنمية تطبيقات الويب 3 باستخدام Soroban و React و Node.js"},"definition":{"en":"stellar-dev is a skill for Soroban-first Stellar development, enabling the creation of smart contracts, dApp frontends, and wallet connection flows using technologies like Rust, React, and Node.js.","zh":"Stellar开发技能是用于构建Stellar区块链应用的技能，涉及Soroban智能合约开发、Stellar dApp前端工作等","ja":"Stellar開発スキルは、Stellarブロックチェーンアプリケーションを構築するために使用されるスキルで、Sorobanスマートコントラクト開発やStellar dAppフロントエンド作業を含みます","ko":"Stellar 개발 스킬은 Stellar 블록체인 애플리케이션을 구축하기 위해 사용되는 스킬로, Soroban 스마트 컨트랙트 개발이나 Stellar dApp 프론트엔드 작업을 포함합니다","es":"stellar-dev es una habilidad de desarrollo de contratos inteligentes en Stellar","fr":"stellar-dev est une compétence de développement de contrats intelligents sur Stellar","de":"stellar-dev ist eine Fähigkeit zur Entwicklung von Smart Contracts auf Stellar","pt":"O stellar-dev é uma habilidade de desenvolvimento que permite criar aplicações Web3 com Soroban e React","ru":"ИИ Агент stellar-dev - это навык разработки, который позволяет создавать приложения Web3 с помощью Soroban и React","ar":"stellar-dev هو مهارة تطور تمكن من إنشاء تطبيقات الويب 3 باستخدام Soroban و React"},"features":{"en":["Soroban smart contract development using Rust","Stellar dApp frontend work with React, Next.js, and Node.js","Wallet connection and signing flows using Freighter","Transaction building, sending, and confirmation on the Stellar network","Stellar Asset issuance and management using Client SDKs","Zero-knowledge proof verification for enhanced security"],"zh":["Soroban智能合约开发","Stellar dApp前端工作（React / Next.js / Node.js）","钱包连接和签名流程（Freighter等）","交易构建、发送和确认","Stellar资产发行和管理"],"ja":["Sorobanスマートコントラクト開発","Stellar dAppフロントエンド作業（React / Next.js / Node.js）","ウォレット接続と署名フロー（Freighterなど）","トランザクション構築、送信、確認","Stellarアセットの発行と管理"],"ko":["Soroban 스마트 컨트랙트 개발","Stellar dApp 프론트엔드 작업（React / Next.js / Node.js）","지갑 연결과 서명 흐름（Freighter 등）","트랜잭션 구축, 전송, 확인","Stellar 자산 발행 및 관리"],"es":["Desarrollo de contratos inteligentes con Soroban","Creación de aplicaciones descentralizadas con React y Node.js","Conexión de billeteras y flujos de firma con Freighter","Creación y envío de transacciones en Stellar","Emisión y gestión de activos en Stellar","Uso de SDK de cliente en JavaScript, Python, Go y Rust"],"fr":["Développement de contrats intelligents avec Soroban","Création d''applications décentralisées avec React et Node.js","Connexion de portefeuilles et flux de signature avec Freighter","Création et envoi de transactions sur Stellar","Émission et gestion d''actifs sur Stellar","Utilisation de SDK de client en JavaScript, Python, Go et Rust"],"de":["Entwicklung von Smart Contracts mit Soroban","Erstellung dezentraler Anwendungen mit React und Node.js","Verbindung von Wallets und Signierflüssen mit Freighter","Erstellung und Senden von Transaktionen auf Stellar","Ausgabe und Verwaltung von Assets auf Stellar","Verwendung von Client-SDK in JavaScript, Python, Go und Rust"],"pt":["Desenvolvimento de contratos inteligentes com Soroban","Criação de interfaces de usuário com React e Node.js","Conexão de carteiras e fluxos de assinatura","Criação e envio de transações","Emissão e gerenciamento de ativos Stellar","Uso de SDKs de cliente em JavaScript, Python, Go e Rust"],"ru":["Разработка умных контрактов с помощью Soroban","Создание интерфейсов пользователя с помощью React и Node.js","Подключение кошельков и потоков подписи","Создание и отправка транзакций","Выпуск и управление активами Stellar","Использование клиентских SDK на JavaScript, Python, Go и Rust"],"ar":["تطوير العقود الذكية مع Soroban","إنشاء واجهات المستخدم مع React و Node.js","اتصال المحافظ وعمليات التوقيع","إنشاء و发送 المعاملات","إصدار وإدارة الأصول Stellar","استخدام SDK العميل في JavaScript و Python و Go و Rust"]},"keywords":{"en":["how to use stellar-dev","stellar-dev tutorial","stellar-dev vs soroban","stellar-dev install guide","stellar-dev setup for AI agents","what is stellar-dev","stellar-dev alternative","stellar-dev for Web3 development","stellar-dev and Rust programming","stellar-dev for dApp development"],"zh":["Stellar开发","Soroban智能合约","Stellar dApp","区块链开发","智能合约开发","React开发","Node.js开发"],"ja":["Stellar開発","Sorobanスマートコントラクト","Stellar dApp","ブロックチェーン開発","スマートコントラクト開発","React開発","Node.js開発"],"ko":["Stellar 개발","Soroban 스마트 컨트랙트","Stellar dApp","블록체인 개발","스마트 컨트랙트 개발","React 개발","Node.js 개발"],"es":["stellar-dev","desarrollo de contratos inteligentes","Soroban","React","Node.js","Stellar","contratos inteligentes","aplicaciones descentralizadas","billeteras","firma de transacciones"],"fr":["stellar-dev","développement de contrats intelligents","Soroban","React","Node.js","Stellar","contrats intelligents","applications décentralisées","portefeuilles","signature de transactions"],"de":["stellar-dev","Entwicklung von Smart Contracts","Soroban","React","Node.js","Stellar","Smart Contracts","dezentrale Anwendungen","Wallets","Transaktions-Signierung"],"pt":["stellar-dev","desenvolvimento web3","soroban","react","node.js","contratos inteligentes","carteiras digitais","transações","ativos stellar","sdk de cliente"],"ru":["stellar-dev","разработка web3","soroban","react","node.js","умные контракты","цифровые кошельки","транзакции","активы stellar","клиентские sdk"],"ar":["stellar-dev","تطوير الويب 3","soroban","react","node.js","العقود الذكية","المحافظ الرقمية","المعاملات","الأصول stellar","sdk العميل"]}},"owner":"kindfi-org","repo":"kindfi","repoPath":"kindfi-org/kindfi","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.452Z","topics":[],"category":"community","skillMd":{"name":"stellar-dev","description":"End-to-end Stellar development playbook. Covers Soroban smart contracts (Rust SDK), Stellar CLI, JavaScript/Python/Go SDKs for client apps, Stellar RPC (preferred) and Horizon API (legacy), Stellar Assets vs Soroban tokens (SAC bridge), wallet integration (Freighter, Stellar Wallets Kit), smart accounts with passkeys, status-sensitive zero-knowledge proof patterns, testing strategies, security patterns, and common pitfalls. Optimized for payments, asset tokenization, DeFi, privacy-aware applications, and financial applications. Use when building on Stellar, Soroban, or working with XLM, Stellar Assets, trustlines, anchors, SEPs, ZK proofs, or the Stellar RPC/Horizon APIs.","bodyPreview":"# Stellar Development Skill (Soroban-first)\n\n## What this Skill is for\n\nUse this Skill when the user asks for:\n\n- Soroban smart contract development (Rust)\n- Stellar dApp frontend work (React / Next.js / Node.js)\n- Wallet connection + signing flows (Freighter, etc.)\n- Transaction building / sending / confirmation\n- Stellar Asset issuance and management\n- Client SDK usage (JavaScript, Python, Go, Rust)\n- Zero-knowledge proof verification (where supported by target network/protocol)\n- Privacy-pres","body":"# Stellar Development Skill (Soroban-first)\n\n## What this Skill is for\n\nUse this Skill when the user asks for:\n\n- Soroban smart contract development (Rust)\n- Stellar dApp frontend work (React / Next.js / Node.js)\n- Wallet connection + signing flows (Freighter, etc.)\n- Transaction building / sending / confirmation\n- Stellar Asset issuance and management\n- Client SDK usage (JavaScript, Python, Go, Rust)\n- Zero-knowledge proof verification (where supported by target network/protocol)\n- Privacy-preserving applications (privacy pools, confidential tokens)\n- Local testing and deployment\n- Security hardening and audit-style reviews\n\n## What this Skill is NOT for\n\n- Bitcoin, Ethereum, Solana, or other non-Stellar blockchain development\n- Stellar node/validator operation (see [validators docs](https://developers.stellar.org/docs/validators))\n- General Rust programming unrelated to Soroban\n- Stellar protocol governance or CAP authoring\n\n## Default stack decisions (opinionated)\n\n### 1. Smart Contracts: Soroban (Rust)\n\n- Use Soroban SDK (`soroban-sdk` crate) for all smart contract development\n- Contracts compile to WebAssembly (WASM)\n- Use `#![no_std]` - standard library not available\n- 64KB contract size limit - use release optimizations\n- Prefer Stellar Assets over custom token contracts when possible\n\n### 2. Client SDK: stellar-sdk (JavaScript) first\n\n- Use `@stellar/stellar-sdk` for browser and Node.js applications\n- Supports both Stellar RPC and legacy Horizon API\n- Full transaction building, signing, and submission\n- Soroban contract deployment and invocation\n\n### 3. API Access: Stellar RPC first (Horizon legacy-focused)\n\n- **Prefer Stellar RPC** for new projects (JSON-RPC, real-time state)\n- **Horizon API** remains available for legacy compatibility and historical-query workflows\n- RPC: 7-day history for most methods; `getLedgers` queries back to genesis (Infinite Scroll)\n- Use Hubble/Galexie for comprehensive historical data beyond RPC\n\n### 4. Token Strategy: Stellar Assets first\n\n- **Prefer Stellar Assets** (classic issuance + trustlines) for fungible tokens\n- Built-in ecosystem support (wallets, exchanges, anchors)\n- Stellar Asset Contracts (SAC) provide Soroban interoperability\n- Use custom Soroban tokens only for complex logic requirements\n\n### 5. Testing\n\n- **Local**: Use Stellar Quickstart Docker for local network\n- **Testnet**: Use Testnet with Friendbot for funding\n- **Unit tests**: Compile to native for fast iteration\n- **Integration tests**: Deploy to local/testnet\n\n### 6. Wallet Integration\n\n- **Freighter** is the primary browser wallet\n- Use Stellar Wallets Kit for multi-wallet support\n- Wallet Standard for consistent connection patterns\n\n### 7. Freshness policy\n\n- Verify volatile facts (protocol support, RPC endpoints, CAP/SEP status, SDK API changes) against official docs before asserting them as current.\n\n## Operating procedure (how to execute tasks)\n\n### 1. Classify the task layer\n\n- Smart contract layer (Soroban/Rust)\n- Client SDK/scripts layer (JS/Python/Go)\n- Frontend/wallet layer\n- Asset management layer (issuance, trustlines)\n- Testing/CI layer\n- Infrastructure (RPC/Horizon/indexing)\n\n### Quick routing\n\n- Need custom on-chain logic? → [contracts-soroban.md](contracts-soroban.md)\n- Building a frontend/dApp? → [frontend-stellar-sdk.md](frontend-stellar-sdk.md)\n- Issuing or managing tokens? → [stellar-assets.md](stellar-assets.md)\n- Zero-knowledge proofs or privacy? → [zk-proofs.md](zk-proofs.md)\n- Setting up tests/CI? → [testing.md](testing.md)\n- Querying chain data or indexing? → [api-rpc-horizon.md](api-rpc-horizon.md) (also see [Data Docs](https://developers.stellar.org/docs/data))\n- Security review? → [security.md](security.md)\n- Hit an error? → [common-pitfalls.md](common-pitfalls.md)\n- Need upgrade/factory/governance/DeFi architecture patterns? → [advanced-patterns.md](advanced-patterns.md)\n- Need SEP/CAP guidance and standards links? → [standards-reference.md](standards-reference.md)\n\n### 2. Pick the right building blocks\n\n- Contracts: Soroban Rust SDK + Stellar CLI\n- Frontend: stellar-sdk (JS) + Freighter/Wallets Kit\n- Backend: stellar-sdk (JS/Python/Go) + RPC\n- Assets: Classic operations or SAC for Soroban interop\n- Testing: Quickstart (local) or Testnet\n\n### 3. Implement with Stellar-specific correctness\n\nAlways be explicit about:\n\n- Network passphrase (Mainnet vs Testnet vs local)\n- Source account + sequence number\n- Fee + resource limits (for Soroban)\n- Authorization requirements\n- Trustline status for assets\n- Contract storage types (temporary vs persistent vs instance)\n\n### 4. Add tests\n\n- Unit tests: Native compilation with `#[test]`\n- Integration tests: Local Quickstart or Testnet\n- Contract tests: Use `Env` from soroban-sdk\n- Frontend tests: Mock wallet/RPC interactions\n\n### 5. Deliverables expectations\n\nWhen you implement changes, provide:\n\n- Exact files changed + diffs\n- Commands to install/build/test/deploy\n- Network configuration (passphrase, RPC endpoint)\n- Risk notes for signing/fees/storage/authorization\n\n## Progressive disclosure (read when needed)\n\n- Smart contracts: [contracts-soroban.md](contracts-soroban.md)\n- Frontend + wallets: [frontend-stellar-sdk.md](frontend-stellar-sdk.md)\n- Testing strategy: [testing.md](testing.md)\n- Stellar Assets: [stellar-assets.md](stellar-assets.md)\n- Zero-knowledge proofs: [zk-proofs.md](zk-proofs.md)\n- API access (RPC/Horizon): [api-rpc-horizon.md](api-rpc-horizon.md)\n- Security checklist: [security.md](security.md)\n- Common pitfalls: [common-pitfalls.md](common-pitfalls.md)\n- Advanced architecture patterns: [advanced-patterns.md](advanced-patterns.md)\n- SEP/CAP standards map: [standards-reference.md](standards-reference.md)\n- Ecosystem projects: [ecosystem.md](ecosystem.md)\n- Reference links: [resources.md](resources.md)\n\n## Keywords\n\nstellar, soroban, xlm, smart contracts, rust, wasm, webassembly, rpc, horizon,\nfreighter, stellar-sdk, soroban-sdk, stellar-cli, trustline, anchor, sep, passkey,\nsmart wallet, sac, stellar asset contract, defi, token, nft, scaffold stellar, constructor, upgrade, factory, governance, standards,\nzero-knowledge, zk, zk-snark, groth16, bn254, poseidon, pairing, privacy, confidential, noir, risc zero, privacy pool, merkle tree\n"},"lastSynced":"2026-03-08T02:09:00.714Z","agentAnalysis":{"suitability":{"en":"Essential for Web3 Development Agents building decentralized crowdfunding platforms on the Stellar network.","zh":"对于构建Stellar网络上去中心化众筹平台的Web3开发代理至关重要。","ja":"Stellarネットワーク上で分散型クラウドファンディングプラットフォームを構築するWeb3開発エージェントに不可欠です。","ko":"Stellar 네트워크에서 분산 크라우드 펀딩 플랫폼을 구축하는 Web3 개발 에이전트에 필수적입니다.","es":"Esencial para los agentes de desarrollo Web3 que crean plataformas de financiación colectiva descentralizadas en la red Stellar.","fr":"Essentiel pour les agents de développement Web3 qui créent des plateformes de financement participatif décentralisées sur le réseau Stellar.","de":"Wichtig für Web3-Entwicklungsagenten, die dezentralisierte Crowdfunding-Plattformen im Stellar-Netzwerk erstellen.","pt":"Essencial para Agentes de Desenvolvimento Web3 que constroem plataformas de crowdfunding descentralizadas na rede Stellar.","ru":"Необходим для Агентов Разработки Web3, создающих децентрализованные платформы краудфандинга в сети Stellar.","ar":"أساسي لوكلاء تطوير Web3 الذين يقومون ببناء منصات التمويل الجماعي اللامركزية على شبكة Stellar."},"recommendation":{"en":"Enables direct integration with Soroban smart contracts using Rust and provides comprehensive Stellar dApp frontend capabilities with React/Next.js. It handles wallet connection flows via Freighter, transaction building/signing, and supports zero-knowledge proof verification where protocol-supported.","zh":"能够使用Rust直接集成Soroban智能合约，并提供使用React/Next.js的综合Stellar dApp前端功能。它通过Freighter处理钱包连接流程、交易构建/签名，并在协议支持的情况下支持零知识证明验证。","ja":"Rustを使用してSorobanスマートコントラクトと直接統合し、React/Next.jsを使用した包括的なStellar dAppフロントエンド機能を提供します。Freighterを介したウォレット接続フロー、トランザクションの構築/署名を処理し、プロトコルがサポートされている場合、ゼロ知識証明の検証もサポートします。","ko":"Rust를 사용하여 Soroban 스마트 계약과 직접 통합하고 React/Next.js를 사용한 종합 Stellar dApp 프론트엔드 기능을 제공합니다. Freighter를 통해 지갑 연결 흐름, 거래構築/서명 처리하고, 프로토콜 지원 시 제로 지식 증명 검증도 지원합니다.","es":"Permite la integración directa con contratos inteligentes Soroban utilizando Rust y ofrece capacidades de frontend de dApp de Stellar completas con React/Next.js. Maneja flujos de conexión de wallet a través de Freighter, creación/firma de transacciones y admite la verificación de pruebas de conocimiento cero donde el protocolo lo admite.","fr":"Permet l''intégration directe avec les contrats intelligents Soroban en utilisant Rust et fournit des capacités de frontend de dApp Stellar complètes avec React/Next.js. Il gère les flux de connexion de portefeuille via Freighter, la construction/signature de transactions et prend en charge la vérification de preuve à connaissances nulles lorsque le protocole le prend en charge.","de":"Ermöglicht die direkte Integration mit Soroban-Smart-Verträgen unter Verwendung von Rust und bietet umfassende Stellar-dApp-Frontend-Funktionen mit React/Next.js. Es verwaltet Wallet-Verbindungsabläufe über Freighter, Transaktionsaufbau/Unterschrift und unterstützt die Verifizierung von Nullwissenbeweisen, wo das Protokoll unterstützt wird.","pt":"Permite a integração direta com contratos inteligentes Soroban usando Rust e fornece capacidades abrangentes de frontend para dApps Stellar com React/Next.js. Ele gerencia fluxos de conexão de carteira via Freighter, construção/assinatura de transações e suporta verificação de provas de conhecimento zero onde suportado pelo protocolo.","ru":"Обеспечивает прямую интеграцию со смарт-контрактами Soroban с использованием Rust и предоставляет комплексные возможности фронтенда для Stellar dApp с React/Next.js. Он обрабатывает потоки подключения кошелька через Freighter, создание/подписание транзакций и поддерживает проверку доказательств с нулевым разглашением (zero-knowledge), где это поддерживается протоколом.","ar":"يمكن من التكامل المباشر مع عقود Soroban الذكية باستخدام Rust ويوفر قدرات شاملة لواجهة أمامية لتطبيقات Stellar اللامركزية (dApp) مع React/Next.js. وهو يدير عمليات تدفق اتصال المحفظة عبر Freighter، وبناء/توقيع المعاملات، ويدعم التحقق من إثباتات المعرفة الصفرية حيث تكون مدعومة من البروتوكول."},"useCases":{"en":["Developing milestone-based escrow crowdfunding platforms","Implementing wallet authentication with Freighter integration","Building and deploying Soroban smart contracts in Rust","Managing Stellar asset issuance and transactions"],"zh":["开发基于里程碑的托管众筹平台","实现Freighter集成的钱包认证","使用Rust构建和部署Soroban智能合约","管理Stellar资产发行和交易"],"ja":["マイルストーンベースのエスクロークラウドファンディングプラットフォームを開発する","Freighter統合を使用したウォレット認証を実装する","Rustを使用してSorobanスマートコントラクトを構築して展開する","Stellarアセットの発行とトランザクションを管理する"],"ko":["마일스톤 기반 에스クロ우 크라우드 펀딩 플랫폼 개발","Freighter 통합을 사용한 지갑 인증 구현","Rust를 사용하여 Soroban 스마트 계약을 구축하고 배포","Stellar 자산 발행 및 거래 관리"],"es":["Desarrollar plataformas de financiación colectiva basadas en hitos","Implementar la autenticación de wallet con integración de Freighter","Crear y desplegar contratos inteligentes Soroban en Rust","Gestionar la emisión de activos y transacciones de Stellar"],"fr":["Développer des plateformes de financement participatif basées sur des étapes","Mettre en œuvre l''authentification de portefeuille avec l''intégration de Freighter","Créer et déployer des contrats intelligents Soroban en Rust","Gérer l''émission d''actifs et les transactions de Stellar"],"de":["Entwicklung von Meilenstein-basierten Crowdfunding-Plattformen","Implementierung der Wallet-Authentifizierung mit Freighter-Integration","Erstellung und Bereitstellung von Soroban-Smart-Verträgen in Rust","Verwaltung der Ausgabe von Stellar-Assets und -Transaktionen"],"pt":["Desenvolvimento de plataformas de crowdfunding com contrato de garantia baseado em marcos","Implementação de autenticação de carteira com integração Freighter","Construção e implantação de contratos inteligentes Soroban em Rust","Gerenciamento de emissão e transações de ativos Stellar"],"ru":["Разработка платформ краудфандинга с условным депонированием на основе этапов","Реализация аутентификации кошелька с интеграцией Freighter","Создание и развертывание смарт-контрактов Soroban на Rust","Управление выпуском активов Stellar и проведение транзакций"],"ar":["تطوير منصات التمويل الجماعي ذات الحفظ الاستثماري القائمة على المعالم","تنفيذ المصادقة على المحفظة مع تكامل Freighter","بناء ونشر عقود Soroban الذكية باستخدام Rust","إدارة إصدار أصول Stellar والمعاملات"]},"limitations":{"en":["Requires Stellar network/Soroban-specific knowledge","Dependent on external wallet providers (e.g., Freighter)","Zero-knowledge features limited to network protocol support"],"zh":["需要Stellar网络/Soroban特定知识","依赖外部钱包提供商（例如Freighter）","零知识功能仅限于网络协议支持"],"ja":["Stellarネットワーク/Soroban特有の知識が必要","外部ウォレットプロバイダー（例：Freighter）に依存","ゼロ知識機能はネットワークプロトコルのサポートに限定"],"ko":["Stellar 네트워크/Soroban 특정 지식 필요","외부 지갑 제공商(Freighter 등)에 의존","제로 지식 기능은 네트워크 프로토콜 지원으로 제한"],"es":["Requiere conocimiento específico de la red Stellar/Soroban","Depende de proveedores de wallet externos (por ejemplo, Freighter)","Las características de conocimiento cero están limitadas al soporte del protocolo de red"],"fr":["Nécessite des connaissances spécifiques au réseau Stellar/Soroban","Dépend de fournisseurs de portefeuille externes (par exemple, Freighter)","Les fonctionnalités de connaissance nulle sont limitées au support du protocole réseau"],"de":["Benötigt Stellar-Netzwerk/Soroban-spezifisches Wissen","Hängt von externen Wallet-Anbietern ab (z. B. Freighter)","Nullwissenfunktionen sind auf die Netzwerkprotokollunterstützung beschränkt"],"pt":["Requer conhecimento específico da rede Stellar/Soroban","Dependente de provedores externos de carteira (ex.: Freighter)","Recursos de conhecimento zero limitados ao suporte do protocolo de rede"],"ru":["Требует специфических знаний сети Stellar/Soroban","Зависит от внешних поставщиков кошельков (например, Freighter)","Функции нулевого разглашения (zero-knowledge) ограничены поддержкой сетевого протокола"],"ar":["يتطلب معرفة محددة بشبكة Stellar/Soroban","يعتمد على موفري المحافظ الخارجيين (مثل Freighter)","ميزات المعرفة الصفرية محدودة بدعم بروتوكول الشبكة"]},"version":4},"contentHash":"b8dcd872cda86918f9dd42ff0e482f8a7631c3d9948db2a8b3cba2d6f3156b3f","qualityScore":29}');
