INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('kindfi-org/kindfi/stellar-dev', 'stellar-dev', 'kindfi-org', 'kindfi', 'community', 'stellar-dev kindfi-org kindfi community The stellar-dev skill enables developers to build Web3 crowdfunding platforms on Stellar, featuring milestone-based escrows and gamified engagement. It benefits developers working with Soroban smart contracts and Stellar dApp frontend development. Stellar开发技能是用于构建Stellar区块链应用的技能，包括Soroban智能合约开发和Stellar dApp前端工作 Stellar開発スキルは、Stellarブロックチェーンアプリケーションを構築するために使用されるスキルで、Sorobanスマートコントラクト開発とStellar dAppフロントエンド作業が含まれます Stellar 개발 스킬은 Stellar 블록체인 애플리케이션을 구축하기 위해 사용되는 스킬로, Soroban 스마트 컨트랙트 개발과 Stellar dApp 프론트엔드 작업이 포함됩니다 stellar-dev es una habilidad para desarrollar contratos inteligentes en Stellar con Soroban y crear aplicaciones descentralizadas con React y Node.js stellar-dev est une compétence pour développer des contrats intelligents sur Stellar avec Soroban et créer des applications décentralisées avec React et Node.js stellar-dev ist eine Fähigkeit zur Entwicklung von Smart Contracts auf Stellar mit Soroban und zur Erstellung dezentraler Anwendungen mit React und Node.js O stellar-dev é uma habilidade de desenvolvimento Web3 que permite criar aplicações com Soroban, React e Node.js. Aprenda a configurá-lo ИИ Агент stellar-dev - это навык разработки Web3, который позволяет создавать приложения с помощью Soroban, React и Node.js. Узнайте, как его настроить stellar-dev هو مهارة تطور الويب 3 التي تمكن من إنشاء تطبيقات باستخدام Soroban و React و Node.js. تعلم كيفية إعداده how to use stellar-dev stellar-dev tutorial stellar-dev vs soroban stellar-dev install guide stellar-dev setup for AI agents what is stellar-dev stellar-dev alternative stellar-dev for Web3 development stellar-dev and Rust programming stellar-dev for dApp development Stellar开发 Soroban智能合约 Stellar dApp 区块链开发 智能合约开发 React开发 Node.js开发 Soroban smart contract development using Rust Stellar dApp frontend work with React, Next.js, and Node.js Wallet connection and signing flows using Freighter Transaction building, sending, and confirmation on the Stellar network Stellar Asset issuance and management using Client SDKs Zero-knowledge proof verification for enhanced security stellar-dev is a skill for Soroban-first Stellar development, enabling the creation of smart contracts, dApp frontends, and wallet connection flows using technologies like Rust, React, and Node.js.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('AugusDogus/junkyard-index/fixing-metadata', 'community', 'AugusDogus', 'junkyard-index', 'AugusDogus/junkyard-index', 'fixing-metadata', 0, 0, 29, '2026-03-08T01:57:15.454Z', '2026-03-08T02:09:04.004Z', '7cd1cc3cf26337291ef629e6b3fbba36f8becb86768782df5c83a0845e26e22c', '{"id":"AugusDogus/junkyard-index/fixing-metadata","name":"fixing-metadata","description":{"en":"The fixing-metadata skill enables developers to validate metadata across multiple files and locations. It benefits developers by providing a straightforward way to identify and fix metadata issues.","zh":"fixing-metadata工具帮助您设置正确、完整的元数据。通过命令行工具，确保您的元数据符合要求","ja":"fixing-metadataツールは、正しく、完全なメタデータを設定するのに役立ちます。コマンドラインツールを使用して、メタデータを確認します","ko":"fixing-metadata 도구는 올바르고 완전한 메타데이터를 설정하는 데 도움이 됩니다. 명령줄 도구를 사용하여 메타데이터를 확인합니다","es":"El skill fixing-metadata es un agente de IA que analiza archivos para identificar errores en metadatos SEO. Proporciona informes detallados de violaciones, su impacto y sugerencias de código concisas para su corrección, sin imponer frameworks adicionales.","fr":"Le skill fixing-metadata est un agent IA qui analyse les fichiers pour identifier les erreurs de métadonnées SEO. Il fournit des rapports détaillés sur les violations, leur impact et des suggestions de code concises pour les corriger, sans imposer de frameworks supplémentaires.","de":"Der fixing-metadata Skill ist ein KI-Agent, der Dateien analysiert, um SEO-Metadatenfehler zu identifizieren. Er liefert detaillierte Verstoßberichte, deren Auswirkungen und präzise Code-Korrekturvorschläge, ohne zusätzliche Frameworks vorauszusetzen.","pt":"O ''fixing-metadata'' é uma ferramenta para garantir metadados corretos, permitindo a revisão de arquivos e a geração de relatórios de violações","ru":"ИИ Агент ''fixing-metadata'' - это инструмент для обеспечения правильных метаданных, позволяющий проверять файлы и генерировать отчеты о нарушениях","ar":"وكلاء الذكاء الاصطناعي ''fixing-metadata'' هم أداة لضمان البيانات الوصفية الصحيحة، مما يسمح بمراجعة الملفات وتوليد تقارير عن الانتهاكات"},"seo":{"title":{"en":"fixing-metadata: Metadata Validation Setup Guide | AI Age...","zh":"元数据修复工具：正确设置元数据的指南","ja":"メタデータ修正ツール：メタデータを正しく設定するためのガイド","ko":"메타데이터 수정 도구: 올바른 설정 방법","es":"fixing-metadata: Guía de configuración para metadatos SEO","fr":"fixing-metadata: Guide des bonnes pratiques pour les méta...","de":"fixing-metadata: Setup-Anleitung für SEO-Metadaten","pt":"Guia de Configuração do ''fixing-metadata'' para Metadados ...","ru":"Настройка ''fixing-metadata'': Руководство по Исправлению М...","ar":"دليل إعداد ''fixing-metadata'' لتصحيح البيانات الوصفية"},"description":{"en":"Discover how to ensure accurate metadata with the fixing-metadata skill. Learn to review files and report violations with a simple `/fixing-metadata` command.","zh":"使用fixing-metadata工具，确保您的元数据正确且完整。设置指南和最佳实践","ja":"fixing-metadataツールを使用して、メタデータを正しく設定します。設定ガイドとベストプラクティス","ko":"fixing-metadata 도구를 사용하여 메타데이터를 올바르게 설정합니다. 설정 가이드 및 모범 사례","es":"Herramienta AI Agent para auditar y corregir metadatos en archivos. Detecta violaciones, explica su impacto SEO y sugiere correcciones de código minimalistas.","fr":"Outil d''IA Agent pour auditer et corriger les métadonnées dans les fichiers. Détecte les violations, explique l''impact SEO et suggère des corrections de code...","de":"AI Agent Tool zum Auditing und Korrigieren von Metadaten in Dateien. Erkennt Verstöße, erklärt SEO-Auswirkungen und schlägt minimale Code-Korrekturen vor.","pt":"Aprenda a aplicar regras de metadados corretas com o ''fixing-metadata'', incluindo revisão de arquivos e relatórios de violações","ru":"Узнайте, как применять правильные правила метаданных с помощью ''fixing-metadata'', включая проверку файлов и отчеты о нарушениях","ar":"تعرف على كيفية تطبيق قواعد البيانات الوصفية الصحيحة باستخدام ''fixing-metadata''، بما في ذلك مراجعة الملفات وتقارير الانتهاكات"},"definition":{"en":"fixing-metadata is a technical skill that ensures correct and complete metadata by reviewing files against predefined rules and reporting violations.","zh":"fixing-metadata是指确保元数据正确、完整的过程，涉及代码级别的检查和修复","ja":"fixing-metadataは、メタデータを正しく、完全にするためのプロセスであり、コードレベルのチェックと修正を含みます","ko":"fixing-metadata는 메타데이터를 올바르고 완전하게 만드는 과정으로, 코드 수준의 검사와 수정을 포함합니다","es":"fixing-metadata es un skill de IA Agent diseñado para auditar y corregir metadatos en archivos. Identifica violaciones de reglas, explica su relevancia para el SEO y proporciona soluciones de código minimalistas para garantizar metadatos correctos y completos.","fr":"fixing-metadata est un skill d''IA Agent conçu pour auditer et corriger les métadonnées dans les fichiers. Il identifie les violations de règles, explique leur pertinence pour le SEO et fournit des solutions de code minimalistes pour garantir des métadonnées correctes et complètes.","de":"fixing-metadata ist ein KI-Agent Skill, der Metadaten in Dateien überprüft und korrigiert. Er identifiziert Regelverstöße, erklärt deren SEO-Relevanz und bietet minimale Code-Lösungen für korrekte und vollständige Metadaten.","pt":"O ''fixing-metadata'' é uma ferramenta de correção de metadados que ajuda a garantir a precisão e completude dos metadados","ru":"ИИ Агент ''fixing-metadata'' - это инструмент для исправления метаданных, помогающий обеспечить точность и полноту метаданных","ar":"وكلاء الذكاء الاصطناعي ''fixing-metadata'' هم أداة لتصحيح البيانات الوصفية التي تساعد على ضمان الدقة والاكتمال للبيانات الوصفية"},"features":{"en":["Reviews files against all predefined metadata rules","Reports violations with exact line or snippet quotes","Provides concrete code-level fix suggestions","Supports file review with a simple `/fixing-metadata <file>` command","Applies constraints to any metadata work in the conversation with `/fixing-metadata`"],"zh":["支持命令行工具","代码级别的检查和修复","确保元数据正确和完整","支持文件检查和报告","提供具体的修复建议"],"ja":["コマンドラインツールをサポート","コードレベルのチェックと修正","メタデータを正しく、完全にする","ファイルのチェックと報告をサポート","具体的な修正案を提供"],"ko":["명령줄 도구 지원","코드 수준의 검사와 수정","메타데이터를 올바르고 완전하게 만듦","파일 검사 및 보고서 지원","구체적인 수정 제안 제공"],"es":["Análisis de archivos con el comando `/fixing-metadata <file>`","Identificación de violaciones citando el código exacto","Explicación concisa del impacto SEO de cada error","Sugerencias de corrección con diffs de código minimalistas","Evita la introducción de frameworks o librerías SEO no solicitadas","Aplicación de restricciones para todo trabajo con metadatos en la conversación"],"fr":["Analyse de fichiers avec la commande `/fixing-metadata <file>`","Identification des violations en citant le code exact","Explication concise de l''impact SEO de chaque erreur","Suggestions de correction avec des diffs de code minimalistes","Évite l''introduction de frameworks ou bibliothèques SEO non demandés","Application de contraintes pour tout travail sur les métadonnées dans la conversation"],"de":["Dateianalyse mit dem Befehl `/fixing-metadata <file>`","Identifizierung von Verstößen durch Zitieren des genauen Codes","Knappe Erklärung der SEO-Auswirkungen jedes Fehlers","Korrekturvorschläge mit minimalen Code-Diffs","Vermeidet die Einführung nicht angeforderter SEO-Frameworks oder Bibliotheken","Anwendung von Einschränkungen für alle Metadatenarbeiten in der Konversation"],"pt":["Revisão de arquivos contra regras de metadados","Relatórios de violações com citação exata da linha ou trecho","Sugestões de correção concreta em nível de código","Preferência por diferenças mínimas","Não introduz novos frameworks ou bibliotecas de SEO"],"ru":["Проверка файлов против правил метаданных","Отчеты о нарушениях с точной цитатой строки или фрагмента","Конкретные предложения по исправлению на уровне кода","Предпочтение минимальным изменениям","Не вводит новые фреймворки или библиотеки SEO"],"ar":["مراجعة الملفات ضد قواعد البيانات الوصفية","تقارير عن الانتهاكات مع اقتباس دقيق للخط أو الشريحة","مقترحات لتصحيح ملموس على مستوى الكود","الأفضلية للتغييرات المعدلة بشكل мінімي","لا يُدخل إطارات أو مكتبات جديدة لتحسين محركات البحث"]},"keywords":{"en":["how to use fixing-metadata","what is fixing-metadata","fixing-metadata alternative","fixing-metadata vs metadata validation tools","fixing-metadata install","fixing-metadata setup guide","metadata validation best practices","fixing-metadata for AI agents"],"zh":["元数据修复","AIエージェント","命令行工具","代码检查","元数据设置","修复建议","元数据完整性","代码级别修复"],"ja":["メタデータ修正","AIエージェント","コマンドラインツール","コードチェック","メタデータ設定","修正案","メタデータ完全性","コードレベルの修正"],"ko":["메타데이터 수정","AI 도구","명령줄 도구","코드 검사","메타데이터 설정","수정 제안","메타데이터 완전성","코드 수준 수정"],"es":["fixing-metadata AI Agent","corregir metadatos SEO","auditoría metadatos automática","herramienta corrección metadata","comando fixing-metadata","SEO técnico metadatos","minimal code diffs metadata","violaciones reglas metadata"],"fr":["fixing-metadata outil IA","corriger métadonnées SEO","audit automatique métadonnées","outil correction métadonnées","commande fixing-metadata","SEO technique métadonnées","diffs de code minimaux métadonnées","violations règles métadonnées"],"de":["fixing-metadata KI Tool","Metadaten korrigieren SEO","automatisches Metadaten-Auditing","Metadaten Korrektur Tool","Befehl fixing-metadata","technisches SEO Metadaten","minimale Code Diffs Metadaten","Metadaten Regelverstöße"],"pt":["metadados corretos","revisão de arquivos","relatórios de violações","correção de metadados","ferramentas de SEO","otimização de metadados"],"ru":["правильные метаданные","проверка файлов","отчеты о нарушениях","исправление метаданных","инструменты SEO","оптимизация метаданных"],"ar":["بيانات وصفية صحيحة","مراجعة الملفات","تقارير عن الانتهاكات","تصحيح البيانات الوصفية","أدوات تحسين محركات البحث","تحسين البيانات الوصفية"]}},"owner":"AugusDogus","repo":"junkyard-index","repoPath":"AugusDogus/junkyard-index","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.454Z","topics":[],"category":"community","skillMd":{"name":"fixing-metadata","description":"Ship correct, complete metadata.","bodyPreview":"# fixing-metadata\n\nShip correct, complete metadata.\n\n## how to use\n\n- `/fixing-metadata`\n  Apply these constraints to any metadata work in this conversation.\n\n- `/fixing-metadata <file>`\n  Review the file against all rules below and report:\n  - violations (quote the exact line or snippet)\n  - why it matters (one short sentence)\n  - a concrete fix (code-level suggestion)\n\nDo not introduce new frameworks or SEO libraries unless explicitly requested. Prefer minimal diffs.\n\n## when to apply\n\nReferen","body":"# fixing-metadata\n\nShip correct, complete metadata.\n\n## how to use\n\n- `/fixing-metadata`\n  Apply these constraints to any metadata work in this conversation.\n\n- `/fixing-metadata <file>`\n  Review the file against all rules below and report:\n  - violations (quote the exact line or snippet)\n  - why it matters (one short sentence)\n  - a concrete fix (code-level suggestion)\n\nDo not introduce new frameworks or SEO libraries unless explicitly requested. Prefer minimal diffs.\n\n## when to apply\n\nReference these guidelines when:\n\n- adding or changing page titles, descriptions, canonical, robots\n- implementing Open Graph or Twitter card metadata\n- setting favicons, app icons, manifest, theme-color\n- building shared SEO components or layout metadata defaults\n- adding structured data (JSON-LD)\n- changing locale, alternate languages, or canonical routing\n- shipping new pages, marketing pages, or shareable links\n\n## rule categories by priority\n\n| priority | category                    | impact     |\n| -------- | --------------------------- | ---------- |\n| 1        | correctness and duplication | critical   |\n| 2        | title and description       | high       |\n| 3        | canonical and indexing      | high       |\n| 4        | social cards                | high       |\n| 5        | icons and manifest          | medium     |\n| 6        | structured data             | medium     |\n| 7        | locale and alternates       | low-medium |\n| 8        | tool boundaries             | critical   |\n\n## quick reference\n\n### 1. correctness and duplication (critical)\n\n- define metadata in one place per page, avoid competing systems\n- do not emit duplicate title, description, canonical, or robots tags\n- metadata must be deterministic, no random or unstable values\n- escape and sanitize any user-generated or dynamic strings\n- every page must have safe defaults for title and description\n\n### 2. title and description (high)\n\n- every page must have a title\n- use a consistent title format across the site\n- keep titles short and readable, avoid stuffing\n- shareable or searchable pages should have a meta description\n- descriptions must be plain text, no markdown or quote spam\n\n### 3. canonical and indexing (high)\n\n- canonical must point to the preferred URL for the page\n- use noindex only for private, duplicate, or non-public pages\n- robots meta must match actual access intent\n- previews or staging pages should be noindex by default when possible\n- paginated pages must have correct canonical behavior\n\n### 4. social cards (high)\n\n- shareable pages must set Open Graph title, description, and image\n- Open Graph and Twitter images must use absolute URLs\n- prefer correct image dimensions and stable aspect ratios\n- og:url must match the canonical URL\n- use a sensible og:type, usually website or article\n- set twitter:card appropriately, summary_large_image by default\n\n### 5. icons and manifest (medium)\n\n- include at least one favicon that works across browsers\n- include apple-touch-icon when relevant\n- manifest must be valid and referenced when used\n- set theme-color intentionally to avoid mismatched UI chrome\n- icon paths should be stable and cacheable\n\n### 6. structured data (medium)\n\n- do not add JSON-LD unless it clearly maps to real page content\n- JSON-LD must be valid and reflect what is actually rendered\n- do not invent ratings, reviews, prices, or organization details\n- prefer one structured data block per page unless required\n\n### 7. locale and alternates (low-medium)\n\n- set the html lang attribute correctly\n- set og:locale when localization exists\n- add hreflang alternates only when pages truly exist\n- localized pages must canonicalize correctly per locale\n\n### 8. tool boundaries (critical)\n\n- prefer minimal changes, do not refactor unrelated code\n- do not migrate frameworks or SEO libraries unless requested\n- follow the project’s existing metadata pattern (Next.js metadata API, react-helmet, manual head, etc.)\n\n## review guidance\n\n- fix critical issues first (duplicates, canonical, indexing)\n- ensure title, description, canonical, and og:url agree\n- verify social cards on a real URL, not localhost\n- prefer stable, boring metadata over clever or dynamic\n- keep diffs minimal and scoped to metadata only\n"},"lastSynced":"2026-03-08T02:09:04.004Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Review Agents needing precise metadata validation and correction capabilities.","zh":"适用于需要精确元数据验证和纠正能力的代码审查代理。","ja":"コードレビューエージェントが正確なメタデータの検証と修正機能を必要とする場合に最適です。","ko":"정확한 메타데이터 검증 및 수정 기능이 필요한 코드 리뷰 에이전트에 적합합니다.","es":"Ideal para agentes de revisión de código que necesitan capacidades de validación y corrección de metadatos precisas.","fr":"Idéal pour les agents de révision de code nécessitant des capacités de validation et de correction de métadonnées précises.","de":"Ideal für Code-Review-Agenten, die präzise Metadaten-Validierungs- und Korrekturfunktionen benötigen.","pt":"Ideal para Agentes de Revisão de Código que necessitam de capacidades precisas de validação e correção de metadados.","ru":"Идеально подходит для Агентов проверки кода, которым требуются точные возможности проверки и исправления метаданных.","ar":"مثالي لوكلاء مراجعة التعليمات البرمجية الذين يحتاجون إلى قدرات دقيقة للتحقق من البيانات الوصفية وتصحيحها."},"recommendation":{"en":"Empowers agents to ship correct and complete metadata by validating and fixing metadata issues across multiple files and locations, utilizing minimal diffs and avoiding introduction of new frameworks or SEO libraries unless explicitly requested.","zh":"通过验证和修复多个文件和位置的元数据问题，利用最小的差异，并避免引入新的框架或SEO库（除非明确请求），使代理能够发布正确且完整的元数据。","ja":"複数のファイルと場所のメタデータの問題を検証して修正し、最小の差分を利用し、明示的に要求されない限り新しいフレームワークやSEOライブラリの導入を避けることで、エージェントが正確で完全なメタデータをリリースできるようにします。","ko":"여러 파일과 위치의 메타데이터 문제를 검증하고 수정하여 최소한의 차이를 사용하고, 명시적으로 요청하지 않는 한 새로운 프레임워크나 SEO 라이브러리의 도입을 피함으로써 에이전트가 올바르고 완전한 메타데이터를 출판할 수 있도록 합니다.","es":"Habilita a los agentes a enviar metadatos correctos y completos validando y corrigiendo problemas de metadatos en varios archivos y ubicaciones, utilizando diferencias mínimas y evitando la introducción de nuevos frameworks o bibliotecas de SEO a menos que se solicite explícitamente.","fr":"Permet aux agents d''envoyer des métadonnées correctes et complètes en validant et en corrigeant les problèmes de métadonnées dans plusieurs fichiers et emplacements, en utilisant des différences minimales et en évitant l''introduction de nouveaux frameworks ou bibliothèques de SEO à moins que cela ne soit explicitement demandé.","de":"Ermächtigt die Agenten, korrekte und vollständige Metadaten zu liefern, indem sie Metadatenprobleme in mehreren Dateien und Orten validieren und korrigieren, minimale Unterschiede verwenden und die Einführung neuer Frameworks oder SEO-Bibliotheken vermeiden, es sei denn, dies wird explizit angefordert.","pt":"Capacita os agentes a enviar metadados corretos e completos, validando e corrigindo problemas de metadados em vários arquivos e locais, utilizando diffs mínimos e evitando a introdução de novos frameworks ou bibliotecas de SEO, a menos que explicitamente solicitado.","ru":"Позволяет агентам предоставлять корректные и полные метаданные путем проверки и исправления проблем с метаданными в нескольких файлах и местах, используя минимальные изменения (diffs) и избегая внедрения новых фреймворков или SEO-библиотек, если это явно не запрошено.","ar":"يمكن الوكلاء من شحن بيانات وصفية صحيحة وكاملة من خلال التحقق من مشاكل البيانات الوصفية وإصلاحها عبر ملفات ومواقع متعددة، باستخدام الحد الأدنى من الاختلافات (diffs) وتجنب إدخال أطر عمل أو مكتبات SEO جديدة إلا إذا طُلب ذلك صراحةً."},"useCases":{"en":["Validating metadata consistency","Debugging metadata violations","Generating concrete fixes for metadata issues"],"zh":["验证元数据一致性","调试元数据违规","为元数据问题生成具体的修复方案"],"ja":["メタデータの一貫性を検証する","メタデータ違反をデバッグする","メタデータの問題に対する具体的な修正を生成する"],"ko":["메타데이터 일관성을 검증하다","메타데이터 위반을 디버깅하다","메타데이터 문제에 대한 구체적인 수정을 생성하다"],"es":["Validar la consistencia de los metadatos","Depurar violaciones de metadatos","Generar correcciones concretas para problemas de metadatos"],"fr":["Valider la cohérence des métadonnées","Déboguer les violations de métadonnées","Générer des corrections concrètes pour les problèmes de métadonnées"],"de":["Validieren der Konsistenz von Metadaten","Debuggen von Metadaten-Verletzungen","Generieren konkreter Korrekturen für Metadatenprobleme"],"pt":["Validação da consistência de metadados","Depuração de violações de metadados","Geração de correções concretas para problemas de metadados"],"ru":["Проверка согласованности метаданных","Отладка нарушений метаданных","Генерация конкретных исправлений для проблем с метаданными"],"ar":["التحقق من اتساق البيانات الوصفية","تصحيح انتهاكات البيانات الوصفية","إنشاء إصلاحات ملموسة لمشاكل البيانات الوصفية"]},"limitations":{"en":["Requires access to file system or specific files for review","Prefer minimal diffs, avoiding new frameworks or SEO libraries"],"zh":["需要访问文件系统或特定文件以进行审查","更喜欢最小的差异，避免引入新的框架或SEO库"],"ja":["レビューのためにファイルシステムまたは特定のファイルにアクセスする必要がある","最小の差分を好み、新しいフレームワークやSEOライブラリの導入を避ける"],"ko":["검토를 위해 파일 시스템이나 특정 파일에 접근할 필요가 있다","최소한의 차이를 선호하며, 새로운 프레임워크나 SEO 라이브러리의 도입을 피한다"],"es":["Requiere acceso al sistema de archivos o a archivos específicos para revisión","Preferir diferencias mínimas, evitando nuevos frameworks o bibliotecas de SEO"],"fr":["Nécessite un accès au système de fichiers ou à des fichiers spécifiques pour la révision","Préférer des différences minimales, en évitant les nouveaux frameworks ou bibliothèques de SEO"],"de":["Erfordert Zugriff auf Dateisystem oder bestimmte Dateien für die Überprüfung","Bevorzugen minimale Unterschiede, Vermeiden neuer Frameworks oder SEO-Bibliotheken"],"pt":["Requer acesso ao sistema de arquivos ou a arquivos específicos para revisão","Prefere diffs mínimos, evitando novos frameworks ou bibliotecas de SEO"],"ru":["Требуется доступ к файловой системе или определенным файлам для проверки","Предпочтение минимальным изменениям (diffs), избегая новых фреймворков или SEO-библиотек"],"ar":["يتطلب الوصول إلى نظام الملفات أو ملفات محددة للمراجعة","يفضل الحد الأدنى من الاختلافات (diffs)، ويتجنب أطر العمل أو مكتبات SEO الجديدة"]},"version":4},"contentHash":"7cd1cc3cf26337291ef629e6b3fbba36f8becb86768782df5c83a0845e26e22c","qualityScore":29}');
