INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('AugusDogus/junkyard-index/fixing-metadata', 'fixing-metadata', 'AugusDogus', 'junkyard-index', 'community', 'fixing-metadata AugusDogus junkyard-index community The fixing-metadata skill enables developers to validate metadata across multiple files and locations. It benefits developers by providing a straightforward way to identify and fix metadata issues. fixing-metadata工具帮助您设置正确、完整的元数据。通过命令行工具，确保您的元数据符合要求 fixing-metadataツールは、正しく、完全なメタデータを設定するのに役立ちます。コマンドラインツールを使用して、メタデータを確認します fixing-metadata 도구는 올바르고 완전한 메타데이터를 설정하는 데 도움이 됩니다. 명령줄 도구를 사용하여 메타데이터를 확인합니다 El skill fixing-metadata es un agente de IA que analiza archivos para identificar errores en metadatos SEO. Proporciona informes detallados de violaciones, su impacto y sugerencias de código concisas para su corrección, sin imponer frameworks adicionales. Le skill fixing-metadata est un agent IA qui analyse les fichiers pour identifier les erreurs de métadonnées SEO. Il fournit des rapports détaillés sur les violations, leur impact et des suggestions de code concises pour les corriger, sans imposer de frameworks supplémentaires. Der fixing-metadata Skill ist ein KI-Agent, der Dateien analysiert, um SEO-Metadatenfehler zu identifizieren. Er liefert detaillierte Verstoßberichte, deren Auswirkungen und präzise Code-Korrekturvorschläge, ohne zusätzliche Frameworks vorauszusetzen. O ''fixing-metadata'' é uma ferramenta para garantir metadados corretos, permitindo a revisão de arquivos e a geração de relatórios de violações ИИ Агент ''fixing-metadata'' - это инструмент для обеспечения правильных метаданных, позволяющий проверять файлы и генерировать отчеты о нарушениях وكلاء الذكاء الاصطناعي ''fixing-metadata'' هم أداة لضمان البيانات الوصفية الصحيحة، مما يسمح بمراجعة الملفات وتوليد تقارير عن الانتهاكات how to use fixing-metadata what is fixing-metadata fixing-metadata alternative fixing-metadata vs metadata validation tools fixing-metadata install fixing-metadata setup guide metadata validation best practices fixing-metadata for AI agents 元数据修复 AIエージェント 命令行工具 代码检查 元数据设置 修复建议 元数据完整性 代码级别修复 Reviews files against all predefined metadata rules Reports violations with exact line or snippet quotes Provides concrete code-level fix suggestions Supports file review with a simple `/fixing-metadata <file>` command Applies constraints to any metadata work in the conversation with `/fixing-metadata` fixing-metadata is a technical skill that ensures correct and complete metadata by reviewing files against predefined rules and reporting violations.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('MohmmedAshraf/laravel-translations/inertia-react-development', 'community', 'MohmmedAshraf', 'laravel-translations', 'MohmmedAshraf/laravel-translations', 'inertia-react-development', 0, 0, 29, '2026-03-08T01:57:15.461Z', '2026-03-08T02:09:13.602Z', '57d99997545f761d70f79d133db3b708f168e6134e88e8bfb2885950809e280e', '{"id":"MohmmedAshraf/laravel-translations/inertia-react-development","name":"inertia-react-development","description":{"en":"The inertia-react-development skill enables developers to efficiently create and manage React page components and forms using Inertia.js, streamlining client-side navigation and translation management.","zh":"Inertia React 开发技能提供了创建和修改 React 页面组件、使用表单和客户端导航的能力","ja":"Inertia React 開発スキルは、React ページコンポーネントの作成、フォームの使用、クライアント側のナビゲーションを実現します","ko":"Inertia React 개발 스킬은 React 페이지 컴포넌트 생성, 폼 사용, 클라이언트 측 탐색 등을 가능하게 합니다","es":"Inertia React Development es una habilidad para crear y personalizar componentes de página de React con Inertia","fr":"Inertia React Development est une compétence pour créer et personnaliser des composants de page React avec Inertia","de":"Inertia React Development ist eine Fähigkeit zum Erstellen und Anpassen von React-Seitenelementen mit Inertia","pt":"Inertia React Development é uma habilidade que simplifica a criação e modificação de componentes de página React para Inertia","ru":"Inertia React Development - это навык, который упрощает создание и изменение компонентов страниц React для Inertia","ar":"Inertia React Development هو مهارة تبسط إنشاء وتعديل مكونات الصفحة React ل Inertia"},"seo":{"title":{"en":"inertia-react-development: Inertia.js React Setup Guide |...","zh":"Inertia React 开发设置指南","ja":"Inertia React 開発ベストプラクティス - AIエージェント","ko":"Inertia React 개발 가이드 - 클라이언트 측 탐색","es":"Guía de configuración de Inertia React Development","fr":"Guide de mise en route de Inertia React Development","de":"Einrichtungsleitfaden für Inertia React Development","pt":"Guia de Configuração para Inertia React Development","ru":"ИИ Агенты: Руководство по Настройке Inertia React Develop...","ar":"دليل الإعداد للتفاعل مع التطوير بالتفاعل Inertia React"},"description":{"en":"Unlock efficient React development with Inertia.js. Learn how to create, modify, and optimize React page components and forms with our expert guide.","zh":"了解 Inertia React 开发的基本用法，包括创建和修改 React 页面组件、使用表单和客户端导航等","ja":"Inertia React 開発の基本的な使い方を学びましょう。React ページコンポーネントの作成、フォームの使用、クライアント側のナビゲーションなど","ko":"Inertia React 개발의 기본 사용법을 익히세요. React 페이지 컴포넌트 생성, 폼 사용, 클라이언트 측 탐색 등","es":"Aprende a crear y personalizar componentes de página de React con Inertia y a trabajar con formularios y navegación cliente","fr":"Découvrez comment créer et personnaliser des composants de page React avec Inertia et travailler avec des formulaires et une navigation cliente","de":"Erfahren Sie, wie Sie React-Seitenelemente mit Inertia erstellen und anpassen sowie mit Formularen und Client-Navigation arbeiten","pt":"Aprenda a criar e modificar componentes de página React para Inertia com esse guia passo a passo","ru":"Изучите, как создавать и изменять компоненты страниц React для Inertia с помощью этого пошагового руководства","ar":"تعلم كيفية إنشاء وتعديل مكونات الصفحة React ل Inertia باستخدام هذا الدليل بالخطوات"},"definition":{"en":"inertia-react-development is a skill that facilitates building React applications with Inertia.js, focusing on efficient component creation, form handling, and client-side navigation.","zh":"Inertia React 开发是一种用于创建 React 页面组件和管理客户端导航的技能","ja":"Inertia React 開発は、React ページコンポーネントを作成し、クライアント側のナビゲーションを管理するスキルです","ko":"Inertia React 개발은 React 페이지 컴포넌트를 생성하고 클라이언트 측 탐색을 관리하는 스킬입니다","es":"Inertia React Development es una habilidad que permite a los desarrolladores crear y personalizar componentes de página de React con Inertia","fr":"Inertia React Development est une compétence qui permet aux développeurs de créer et de personnaliser des composants de page React avec Inertia","de":"Inertia React Development ist eine Fähigkeit, die es Entwicklern ermöglicht, React-Seitenelemente mit Inertia zu erstellen und anzupassen","pt":"Inertia React Development é uma habilidade que fornece recursos para criar e modificar componentes de página React para Inertia","ru":"Inertia React Development - это навык, который предоставляет ресурсы для создания и изменения компонентов страниц React для Inertia","ar":"Inertia React Development هو مهارة يوفر موارد لإنشاء وتعديل مكونات الصفحة React ل Inertia"},"features":{"en":["Creates and modifies React page components for Inertia","Works with forms in React using `<Form>` or `useForm`","Implements client-side navigation with `<Link>` or `router`","Utilizes Inertia v2 features like deferred props, prefetching, and polling","Builds React-specific features with the Inertia protocol"],"zh":["创建和修改 React 页面组件","使用表单（<Form> 或 useForm）","实现客户端导航（<Link> 或 router）","使用 Inertia v2 功能：延迟属性、预取和轮询","构建 React 特定功能与 Inertia 协议"],"ja":["React ページコンポーネントの作成と修正","フォーム（<Form> または useForm）を使用","クライアント側のナビゲーション（<Link> または router）を実現","Inertia v2 機能：遅延プロパティ、プリフェッチ、ポーリングを使用","React 特有の機能と Inertia プロトコルを構築"],"ko":["React 페이지 컴포넌트 생성 및 수정","폼（<Form> 또는 useForm）사용","클라이언트 측 탐색（<Link> 또는 router）구현","Inertia v2 기능：지연 속성, 프리패치, 폴링 사용","React 특정 기능과 Inertia 프로토콜 구축"],"es":["Creación y personalización de componentes de página de React con Inertia","Trabajo con formularios en React utilizando `<Form>` o `useForm`","Implementación de navegación cliente con `<Link>` o `router`","Uso de características de v2 como propiedades diferidas, precarga y sondeo","Construcción de características específicas de React con el protocolo Inertia"],"fr":["Création et personnalisation de composants de page React avec Inertia","Travail avec des formulaires en React en utilisant `<Form>` ou `useForm`","Mise en œuvre de la navigation cliente avec `<Link>` ou `router`","Utilisation de fonctionnalités de v2 telles que les propriétés différées, la préchargement et le sondage","Construction de fonctionnalités spécifiques à React avec le protocole Inertia"],"de":["Erstellung und Anpassung von React-Seitenelementen mit Inertia","Arbeit mit Formularen in React unter Verwendung von `<Form>` oder `useForm`","Implementierung der Client-Navigation mit `<Link>` oder `router`","Verwendung von v2-Funktionen wie aufgeschobene Eigenschaften, Vorladung und Abfragen","Erstellung von React-spezifischen Funktionen mit dem Inertia-Protokoll"],"pt":["Criação e modificação de componentes de página React para Inertia","Trabalho com formulários em React usando `<Form>` ou `useForm`","Implementação de navegação de cliente com `<Link>` ou `router`","Uso de recursos do v2: propriedades adiadas, pré-carregamento e polling","Construção de recursos específicos do React com o protocolo Inertia"],"ru":["Создание и изменение компонентов страниц React для Inertia","Работа с формами в React с помощью `<Form>` или `useForm`","Реализация клиентской навигации с помощью `<Link>` или `router`","Использование функций v2: отложенные свойства, предзагрузка и опрос","Строительство специфичных для React функций с помощью протокола Inertia"],"ar":["إنشاء وتعديل مكونات الصفحة React ل Inertia","العمل مع النماذج في React باستخدام `<Form>` أو `useForm`","تنفيذ التنقل العميل مع `<Link>` أو `router`","استخدام ميزات v2: الخصائص المؤجلة، التحميل المسبق والاستطلاع","بناء ميزات محددة ل React باستخدام بروتوكول Inertia"]},"keywords":{"en":["how to use inertia-react-development","inertia-react-development setup guide","inertia-react-development vs Next.js","inertia-react-development install","what is inertia-react-development","inertia-react-development alternative","inertia-react-development tutorial","inertia-react-development best practices","inertia-react-development documentation"],"zh":["Inertia React 开发","React 页面组件","客户端导航","Inertia v2","延迟属性","预取","轮询","AI 工具","React 开发最佳实践"],"ja":["Inertia React 開発","React ページコンポーネント","クライアント側のナビゲーション","Inertia v2","遅延プロパティ","プリフェッチ","ポーリング","AI エージェント","React 開発ベストプラクティス"],"ko":["Inertia React 개발","React 페이지 컴포넌트","클라이언트 측 탐색","Inertia v2","지연 속성","프리패치","폴링","AI 툴","React 개발 가이드"],"es":["Inertia React Development","desarrollo de aplicaciones React","creación de componentes de página de React","formularios en React","navegación cliente en React","protocolo Inertia","Herramientas de AI para desarrolladores","Agentes de IA para programación"],"fr":["Inertia React Development","développement d''applications React","création de composants de page React","formulaires en React","navigation cliente en React","protocole Inertia","Outils d''IA pour les développeurs","Agents d''IA pour la programmation"],"de":["Inertia React Development","Entwicklung von React-Anwendungen","Erstellung von React-Seitenelementen","Formulare in React","Client-Navigation in React","Inertia-Protokoll","AI-Tools für Entwickler","KI-Agenten für die Programmierung"],"pt":["Inertia React Development","criação de componentes React","modificação de componentes React","formulários em React","navegação de cliente em React","recursos do v2 do Inertia","protocolo Inertia","desenvolvimento de aplicativos React"],"ru":["Inertia React Development","создание компонентов React","изменение компонентов React","формы в React","клиентская навигация в React","функции v2 Inertia","протокол Inertia","разработка приложений React"],"ar":["Inertia React Development","إنشاء مكونات React","تعديل مكونات React","نماذج في React","تنقل العميل في React","ميزات v2 من Inertia","بروتوكول Inertia","تطوير تطبيقات React"]}},"owner":"MohmmedAshraf","repo":"laravel-translations","repoPath":"MohmmedAshraf/laravel-translations","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.461Z","topics":[],"category":"community","skillMd":{"name":"inertia-react-development","description":">-","bodyPreview":"# Inertia React Development\n\n## When to Apply\n\nActivate this skill when:\n\n- Creating or modifying React page components for Inertia\n- Working with forms in React (using `<Form>` or `useForm`)\n- Implementing client-side navigation with `<Link>` or `router`\n- Using v2 features: deferred props, prefetching, or polling\n- Building React-specific features with the Inertia protocol\n\n## Documentation\n\nUse `search-docs` for detailed Inertia v2 React patterns and documentation.\n\n## Basic Usage\n\n### Page C","body":"# Inertia React Development\n\n## When to Apply\n\nActivate this skill when:\n\n- Creating or modifying React page components for Inertia\n- Working with forms in React (using `<Form>` or `useForm`)\n- Implementing client-side navigation with `<Link>` or `router`\n- Using v2 features: deferred props, prefetching, or polling\n- Building React-specific features with the Inertia protocol\n\n## Documentation\n\nUse `search-docs` for detailed Inertia v2 React patterns and documentation.\n\n## Basic Usage\n\n### Page Components Location\n\nReact page components should be placed in the `resources/js/pages` directory.\n\n### Page Component Structure\n\n<code-snippet name=\"Basic React Page Component\" lang=\"react\">\n\nexport default function UsersIndex({ users }) {\n    return (\n        <div>\n            <h1>Users</h1>\n            <ul>\n                {users.map(user => <li key={user.id}>{user.name}</li>)}\n            </ul>\n        </div>\n    )\n}\n\n</code-snippet>\n\n## Client-Side Navigation\n\n### Basic Link Component\n\nUse `<Link>` for client-side navigation instead of traditional `<a>` tags:\n\n<code-snippet name=\"Inertia React Navigation\" lang=\"react\">\n\nimport { Link, router } from ''@inertiajs/react''\n\n<Link href=\"/\">Home</Link>\n<Link href=\"/users\">Users</Link>\n<Link href={`/users/${user.id}`}>View User</Link>\n\n</code-snippet>\n\n### Link with Method\n\n<code-snippet name=\"Link with POST Method\" lang=\"react\">\n\nimport { Link } from ''@inertiajs/react''\n\n<Link href=\"/logout\" method=\"post\" as=\"button\">\n    Logout\n</Link>\n\n</code-snippet>\n\n### Prefetching\n\nPrefetch pages to improve perceived performance:\n\n<code-snippet name=\"Prefetch on Hover\" lang=\"react\">\n\nimport { Link } from ''@inertiajs/react''\n\n<Link href=\"/users\" prefetch>\n    Users\n</Link>\n\n</code-snippet>\n\n### Programmatic Navigation\n\n<code-snippet name=\"Router Visit\" lang=\"react\">\n\nimport { router } from ''@inertiajs/react''\n\nfunction handleClick() {\n    router.visit(''/users'')\n}\n\n// Or with options\nrouter.visit(''/users'', {\n    method: ''post'',\n    data: { name: ''John'' },\n    onSuccess: () => console.log(''Success!''),\n})\n\n</code-snippet>\n\n## Form Handling\n\n### Form Component (Recommended)\n\nThe recommended way to build forms is with the `<Form>` component:\n\n<code-snippet name=\"Form Component Example\" lang=\"react\">\n\nimport { Form } from ''@inertiajs/react''\n\nexport default function CreateUser() {\n    return (\n        <Form action=\"/users\" method=\"post\">\n            {({ errors, processing, wasSuccessful }) => (\n                <>\n                    <input type=\"text\" name=\"name\" />\n                    {errors.name && <div>{errors.name}</div>}\n\n                    <input type=\"email\" name=\"email\" />\n                    {errors.email && <div>{errors.email}</div>}\n\n                    <button type=\"submit\" disabled={processing}>\n                        {processing ? ''Creating...'' : ''Create User''}\n                    </button>\n\n                    {wasSuccessful && <div>User created!</div>}\n                </>\n            )}\n        </Form>\n    )\n}\n\n</code-snippet>\n\n### Form Component With All Props\n\n<code-snippet name=\"Form Component Full Example\" lang=\"react\">\n\nimport { Form } from ''@inertiajs/react''\n\n<Form action=\"/users\" method=\"post\">\n    {({\n        errors,\n        hasErrors,\n        processing,\n        progress,\n        wasSuccessful,\n        recentlySuccessful,\n        clearErrors,\n        resetAndClearErrors,\n        defaults,\n        isDirty,\n        reset,\n        submit\n    }) => (\n        <>\n            <input type=\"text\" name=\"name\" defaultValue={defaults.name} />\n            {errors.name && <div>{errors.name}</div>}\n\n            <button type=\"submit\" disabled={processing}>\n                {processing ? ''Saving...'' : ''Save''}\n            </button>\n\n            {progress && (\n                <progress value={progress.percentage} max=\"100\">\n                    {progress.percentage}%\n                </progress>\n            )}\n\n            {wasSuccessful && <div>Saved!</div>}\n        </>\n    )}\n</Form>\n\n</code-snippet>\n\n### Form Component Reset Props\n\nThe `<Form>` component supports automatic resetting:\n\n- `resetOnError` - Reset form data when the request fails\n- `resetOnSuccess` - Reset form data when the request succeeds\n- `setDefaultsOnSuccess` - Update default values on success\n\nUse the `search-docs` tool with a query of `form component resetting` for detailed guidance.\n\n<code-snippet name=\"Form with Reset Props\" lang=\"react\">\n\nimport { Form } from ''@inertiajs/react''\n\n<Form\n    action=\"/users\"\n    method=\"post\"\n    resetOnSuccess\n    setDefaultsOnSuccess\n>\n    {({ errors, processing, wasSuccessful }) => (\n        <>\n            <input type=\"text\" name=\"name\" />\n            {errors.name && <div>{errors.name}</div>}\n\n            <button type=\"submit\" disabled={processing}>\n                Submit\n            </button>\n        </>\n    )}\n</Form>\n\n</code-snippet>\n\nForms can also be built using the `useForm` helper for more programmatic control. Use the `search-docs` tool with a query of `useForm helper` for guidance.\n\n### `useForm` Hook\n\nFor more programmatic control or to follow existing conventions, use the `useForm` hook:\n\n<code-snippet name=\"useForm Hook Example\" lang=\"react\">\n\nimport { useForm } from ''@inertiajs/react''\n\nexport default function CreateUser() {\n    const { data, setData, post, processing, errors, reset } = useForm({\n        name: '''',\n        email: '''',\n        password: '''',\n    })\n\n    function submit(e) {\n        e.preventDefault()\n        post(''/users'', {\n            onSuccess: () => reset(''password''),\n        })\n    }\n\n    return (\n        <form onSubmit={submit}>\n            <input\n                type=\"text\"\n                value={data.name}\n                onChange={e => setData(''name'', e.target.value)}\n            />\n            {errors.name && <div>{errors.name}</div>}\n\n            <input\n                type=\"email\"\n                value={data.email}\n                onChange={e => setData(''email'', e.target.value)}\n            />\n            {errors.email && <div>{errors.email}</div>}\n\n            <input\n                type=\"password\"\n                value={data.password}\n                onChange={e => setData(''password'', e.target.value)}\n            />\n            {errors.password && <div>{errors.password}</div>}\n\n            <button type=\"submit\" disabled={processing}>\n                Create User\n            </button>\n        </form>\n    )\n}\n\n</code-snippet>\n\n## Inertia v2 Features\n\n### Deferred Props\n\nUse deferred props to load data after initial page render:\n\n<code-snippet name=\"Deferred Props with Empty State\" lang=\"react\">\n\nexport default function UsersIndex({ users }) {\n    // users will be undefined initially, then populated\n    return (\n        <div>\n            <h1>Users</h1>\n            {!users ? (\n                <div className=\"animate-pulse\">\n                    <div className=\"h-4 bg-gray-200 rounded w-3/4 mb-2\"></div>\n                    <div className=\"h-4 bg-gray-200 rounded w-1/2\"></div>\n                </div>\n            ) : (\n                <ul>\n                    {users.map(user => (\n                        <li key={user.id}>{user.name}</li>\n                    ))}\n                </ul>\n            )}\n        </div>\n    )\n}\n\n</code-snippet>\n\n### Polling\n\nAutomatically refresh data at intervals:\n\n<code-snippet name=\"Polling Example\" lang=\"react\">\n\nimport { router } from ''@inertiajs/react''\nimport { useEffect } from ''react''\n\nexport default function Dashboard({ stats }) {\n    useEffect(() => {\n        const interval = setInterval(() => {\n            router.reload({ only: [''stats''] })\n        }, 5000) // Poll every 5 seconds\n\n        return () => clearInterval(interval)\n    }, [])\n\n    return (\n        <div>\n            <h1>Dashboard</h1>\n            <div>Active Users: {stats.activeUsers}</div>\n        </div>\n    )\n}\n\n</code-snippet>\n\n### WhenVisible (Infinite Scroll)\n\nLoad more data when user scrolls to a specific element:\n\n<code-snippet name=\"Infinite Scroll with WhenVisible\" lang=\"react\">\n\nimport { WhenVisible } from ''@inertiajs/react''\n\nexport default function UsersList({ users }) {\n    return (\n        <div>\n            {users.data.map(user => (\n                <div key={user.id}>{user.name}</div>\n            ))}\n\n            {users.next_page_url && (\n                <WhenVisible\n                    data=\"users\"\n                    params={{ page: users.current_page + 1 }}\n                    fallback={<div>Loading more...</div>}\n                />\n            )}\n        </div>\n    )\n}\n\n</code-snippet>\n\n## Common Pitfalls\n\n- Using traditional `<a>` links instead of Inertia''s `<Link>` component (breaks SPA behavior)\n- Forgetting to add loading states (skeleton screens) when using deferred props\n- Not handling the `undefined` state of deferred props before data loads\n- Using `<form>` without preventing default submission (use `<Form>` component or `e.preventDefault()`)\n- Forgetting to check if `<Form>` component is available in your Inertia version"},"lastSynced":"2026-03-08T02:09:13.602Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing streamlined React page component management and client-side navigation with Inertia.js","zh":"非常适合需要简化React页面组件管理和客户端导航的前端代理，特别是使用Inertia.js","ja":"Reactページコンポーネントの管理とクライアント側ナビゲーションを簡素化する必要があるフロントエンドエージェントに最適。特にInertia.jsを使用する場合","ko":"React 페이지 컴포넌트 관리와 클라이언트 측 내비게이션을 간소화해야 하는 프론트엔드 에이전트에게 이상적입니다. 특히 Inertia.js를 사용하는 경우","es":"Ideal para agentes de frontend que necesitan una gestión optimizada de componentes de página React y navegación del lado del cliente con Inertia.js","fr":"Parfait pour les agents Frontend ayant besoin d''une gestion rationalisée des composants de page React et d''une navigation côté client avec Inertia.js","de":"Perfekt für Frontend-Agents, die eine optimierte Verwaltung von React-Seitenkomponenten und clientseitige Navigation mit Inertia.js benötigen","pt":"Perfeito para Agentes Frontend que precisam de gerenciamento de componentes de página React simplificado e navegação no lado do cliente com Inertia.js","ru":"Идеально для Фронтенд-агентов, которым необходим упрощенное управление компонентами страниц React и клиентской навигацией с помощью Inertia.js","ar":"مثالي للوكلاء الأمامية الذين يحتاجون إلى إدارة مكونات صفحة React المبسطة والتوجيه على جانب العميل مع Inertia.js"},"recommendation":{"en":"Empowers agents to efficiently create and manage React page components and forms using Inertia.js, streamlining client-side navigation and translation management with features like deferred props, prefetching, and polling","zh":"赋予代理高效创建和管理React页面组件和表单的能力，使用Inertia.js简化客户端导航和翻译管理，具有延迟属性、预取和轮询等功能","ja":"エージェントがReactページコンポーネントとフォームを作成および管理するための効率的な方法を提供します。Inertia.jsを使用してクライアント側ナビゲーションと翻訳管理を簡素化します。遅延プロパティ、プレビュー、ポーリングなどの機能が含まれます","ko":"에이전트가 React 페이지 컴포넌트와 폼을 효율적으로 생성 및 관리할 수 있도록 해줍니다. Inertia.js를 사용하여 클라이언트 측 내비게이션과 번역 관리를 간소화하며, 지연 속성, 사전 가져오기 및 폴링 등의 기능을 제공합니다","es":"Permite a los agentes crear y gestionar de manera eficiente componentes de página y formularios React utilizando Inertia.js, optimizando la navegación del lado del cliente y la gestión de traducciones con funciones como props diferidos, prefetching y polling","fr":"Permet aux agents de créer et de gérer efficacement des composants de page et des formulaires React en utilisant Inertia.js, rationalisant la navigation côté client et la gestion des traductions avec des fonctionnalités telles que les props différés, le préchargement et le polling","de":"Ermöglicht Agents die effiziente Erstellung und Verwaltung von React-Seitenkomponenten und Formularen mit Inertia.js, optimiert die clientseitige Navigation und Übersetzungsverwaltung mit Funktionen wie deferred props, Prefetching und Polling","pt":"Habilita os agentes a criar e gerenciar componentes de página React e formulários de forma eficiente usando Inertia.js, simplificando a navegação no lado do cliente e o gerenciamento de traduções com recursos como propriedades adiadas, pré-carregamento e sondagem","ru":"Наделяет агентов возможностью эффективно создавать и управлять компонентами страниц React и формами с помощью Inertia.js, упрощая клиентскую навигацию и управление переводами с помощью функций, таких как отложенные свойства, предварительная загрузка и опрос","ar":"تمكين الوكلاء من إنشاء وإدارة مكونات صفحة React والاستمارات بفعالية باستخدام Inertia.js، وبذلك تسهل التنقل على جانب العميل وإدارة الترجمة باستخدام ميزات مثل الخصائص المتأخرة والتحميل المسبق والاستطلاع"},"useCases":{"en":["Creating or modifying React page components for Inertia","Implementing client-side navigation with Inertia''s Link or router","Building React-specific features with the Inertia protocol","Working with forms in React using Inertia''s Form or useForm","Utilizing Inertia v2 features for optimized performance"],"zh":["为Inertia创建或修改React页面组件","使用Inertia的Link或路由器实现客户端导航","使用Inertia协议构建React特定功能","使用Inertia的Form或useForm在React中处理表单","使用Inertia v2功能实现优化性能"],"ja":["Inertia用のReactページコンポーネントを作成または変更する","InertiaのLinkまたはルーターを使用してクライアント側ナビゲーションを実装する","Inertiaプロトコルを使用してReact固有の機能を構築する","InertiaのFormまたはuseFormを使用してReactでフォームを処理する","Inertia v2の機能を使用してパフォーマンスを最適化する"],"ko":["Inertia를 위한 React 페이지 컴포넌트를 생성하거나 수정","Inertia의 Link 또는 라우터를 사용하여 클라이언트 측 내비게이션을 구현","Inertia 프로토콜을 사용하여 React 특정 기능을 구축","Inertia의 Form 또는 useForm를 사용하여 React에서 폼을 처리","Inertia v2 기능을 사용하여 성능을 최적화"],"es":["Crear o modificar componentes de página React para Inertia","Implementar navegación del lado del cliente con Link o el router de Inertia","Construir funciones específicas de React con el protocolo Inertia","Trabajar con formularios en React utilizando Form o useForm de Inertia","Utilizar funciones de Inertia v2 para un rendimiento optimizado"],"fr":["Créer ou modifier des composants de page React pour Inertia","Mettre en œuvre une navigation côté client avec Link ou le routeur d''Inertia","Construire des fonctionnalités spécifiques à React avec le protocole Inertia","Travailler avec des formulaires en React utilisant Form ou useForm d''Inertia","Utiliser les fonctionnalités d''Inertia v2 pour des performances optimisées"],"de":["Erstellen oder Ändern von React-Seitenkomponenten für Inertia","Implementierung clientseitiger Navigation mit Inertias Link oder Router","Entwicklung von React-spezifischen Funktionen mit dem Inertia-Protokoll","Arbeiten mit Formularen in React unter Verwendung von Inertias Form oder useForm","Nutzung von Inertia v2-Funktionen für optimierte Leistung"],"pt":["Criar ou modificar componentes de página React para Inertia","Implementar navegação no lado do cliente com Link ou roteador do Inertia","Construir recursos específicos do React com o protocolo Inertia","Trabalhar com formulários no React usando Form ou useForm do Inertia","Utilizar recursos do Inertia v2 para desempenho otimizado"],"ru":["Создавать или изменять компоненты страниц React для Inertia","Реализовывать клиентскую навигацию с помощью Link или роутера Inertia","Строить функции, специфичные для React, с помощью протокола Inertia","Работать с формами в React с помощью Form или useForm Inertia","Использовать функции Inertia v2 для оптимизированной производительности"],"ar":["إنشاء أو تعديل مكونات صفحة React ل Inertia","تنفيذ التوجيه على جانب العميل باستخدام Link أو الموجه Inertia","بناء ميزات محددة ل React باستخدام بروتوكول Inertia","العمل مع الاستمارات في React باستخدام Form أو useForm من Inertia","استخدام ميزات Inertia v2 للأداء المُحسّن"]},"limitations":{"en":["Requires Inertia.js and React setup","Limited to React page component and form management","Dependent on Inertia protocol for client-side navigation and translation management"],"zh":["需要Inertia.js和React设置","仅限React页面组件和表单管理","依赖Inertia协议用于客户端导航和翻译管理"],"ja":["Inertia.jsとReactの設定が必要","Reactページコンポーネントとフォームの管理のみ","クライアント側ナビゲーションと翻訳管理にInertiaプロトコルに依存"],"ko":["Inertia.js와 React 설정이 필요","React 페이지 컴포넌트와 폼 관리에만 제한","클라이언트 측 내비게이션과 번역 관리에 Inertia 프로토콜에 의존"],"es":["Requiere la configuración de Inertia.js y React","Limitado a la gestión de componentes de página y formularios React","Dependiente del protocolo Inertia para la navegación del lado del cliente y la gestión de traducciones"],"fr":["Nécessite la configuration d''Inertia.js et React","Limité à la gestion des composants de page et des formulaires React","Dépendant du protocole Inertia pour la navigation côté client et la gestion des traductions"],"de":["Erfordert Inertia.js und React Setup","Beschränkt auf die Verwaltung von React-Seitenkomponenten und Formularen","Abhängig vom Inertia-Protokoll für clientseitige Navigation und Übersetzungsverwaltung"],"pt":["Exige configuração do Inertia.js e React","Limitado ao gerenciamento de componentes de página React e formulários","Dependente do protocolo Inertia para navegação no lado do cliente e gerenciamento de traduções"],"ru":["Требует настройки Inertia.js и React","Ограничен управлением компонентами страниц React и формами","Зависит от протокола Inertia для клиентской навигации и управления переводами"],"ar":["يتطلب إعداد Inertia.js و React","محدود لإدارة مكونات