INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('manas-z/BookingSystem_2.0/react:components', 'react:components', 'manas-z', 'BookingSystem_2.0', 'community', 'react:components manas-z BookingSystem_2.0 community The react:components skill enables frontend engineers to transform designs into clean React code using automated tools. It facilitates namespace discovery, metadata fetch, and high-reliability download for efficient development. 本文介绍如何使用 React 组件和 AI 工具来开发高质量的代码，包括 namespace 发现、元数据获取和高可靠性下载等功能 本文では、React コンポーネントと AI エージェントを使用して、高品質のコードを開発する方法を紹介します。名前空間の発見、メタデータの取得、高可頼性のダウンロードなど 이 문서는 React 컴포넌트와 AI 도구를 사용하여 고품질의 코드를 개발하는 방법을 소개합니다. 네임스페이스 발견, 메타데이터 获取, 고신뢰성 다운로드 등 react:components es una habilidad que permite a los desarrolladores frontend transformar diseños en código React limpio y modular react:components est une compétence qui permet aux développeurs frontend de transformer des conceptions en code React propre et modulaire react:components ist eine Fähigkeit, die es Frontend-Entwicklern ermöglicht, Entwürfe in sauberen und modularen React-Code umzuwandeln O skill react:components permite a você criar componentes React modulares e de alta qualidade com a ajuda de ferramentas de IA Навык react:components позволяет вам создавать модульные и высококачественные компоненты React с помощью ИИ Агентов المهارة react:components تمكنك من إنشاء مكونات رياكت قابلة وذات جودة عالية مع أدوات الإعتراف الاصطناعي how to use react:components react:components setup guide react:components vs other frontend tools react:components install what is react:components react:components alternative react:components tutorial react:components best practices react:components for AI agents React 组件 AI 工具 namespace 发现 元数据获取 高可靠性下载 代码质量保证 React 开发 AI 集成 Namespace discovery using the `list_tools` command Metadata fetch via the `[prefix]:get_screen` call High-reliability download using internal AI fetch tools Modular approach to React component development Automated code quality assurance using tools like Stitch MCP prefix Integration with design JSON for seamless transformation react:components is a skill that allows frontend engineers to transform designs into clean React code using a modular approach and automated tools like Stitch MCP prefix');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('codingshot/tryramadan/tryramadan-accessibility', 'community', 'codingshot', 'tryramadan', 'codingshot/tryramadan', 'tryramadan-accessibility', 0, 0, 29, '2026-03-08T01:57:15.476Z', '2026-03-08T02:09:48.970Z', 'c37fffffa0814d90f9a986bea86f40c017b86cc5336087e92a8328ae02a58e6f', '{"id":"codingshot/tryramadan/tryramadan-accessibility","name":"tryramadan-accessibility","description":{"en":"The tryramadan-accessibility skill helps developers create accessible UI components for keyboard and screen-reader users. It provides guidelines for adding skip links and focus visibility.","zh":"TryRamadan-Accessibility是一个确保应用程序无障碍的技能，提供了全局要求和交互元素的可见焦点环","ja":"TryRamadan-Accessibilityは、アプリケーションをアクセシブルにするためのスキルで、グローバル要件とインタラクティブ要素の可視フォーカスリングを提供します","ko":"TryRamadan-Accessibility는 애플리케이션을 접근성 있게 만드는 스킬로, 글로벌 요구 사항과 상호 작용 요소의 가시적 초점 링을 제공합니다","es":"tryramadan-accessibility es una habilidad que ayuda a garantizar la accesibilidad en las aplicaciones, proporcionando un enlace de salto y un anillo de enfoque visible para elementos interactivos","fr":"tryramadan-accessibility est une compétence qui aide à garantir l''accessibilité dans les applications, en fournissant un lien de saut et un anneau de focus visible pour les éléments interactifs","de":"tryramadan-accessibility ist eine Fähigkeit, die hilft, die Barrierefreiheit in Anwendungen zu gewährleisten, indem sie einen Sprunglink und einen sichtbaren Fokusring für interaktive Elemente bereitstellt","pt":"O tryramadan-accessibility é uma habilidade que ajuda a manter a acessibilidade em aplicações ao adicionar ou alterar UI, garantindo a usabilidade para usuários de teclado e leitores de tela","ru":"ИИ Агент tryramadan-accessibility помогает поддерживать доступность в приложениях при добавлении или изменении UI, обеспечивая использование для пользователей клавиатуры и экранных читателей","ar":"أداة ذكاء اصطناعي tryramadan-accessibility تساعد على الحفاظ على إمكانية الوصول في التطبيقات عند إضافة أو تغيير واجهة المستخدم، وضمان سهولة الاستخدام لمستخدمي لوحة المفاتيح وقارئي الشاشة"},"seo":{"title":{"en":"tryramadan-accessibility: Accessibility Setup Guide | AI ...","zh":"TryRamadan-Accessibility.setup指南 - 无障碍AIエージェント","ja":"TryRamadan-Accessibility設定ガイド - アクセシビリティAIエージェント","ko":"TryRamadan-Accessibility 설정 가이드 - 접근성 AI 에이전트","es":"Guía de configuración de tryramadan-accessibility para ag...","fr":"Guide de mise en place de tryramadan-accessibility pour l...","de":"Einrichtungsleitfaden für tryramadan-accessibility in AI-...","pt":"Guia de Acessibilidade tryramadan-accessibility para Dese...","ru":"Настройка ИИ Агентов tryramadan-accessibility для доступн...","ar":"إعداد أداة ذكاء اصطناعي tryramadan-accessibility لتحسين إ..."},"description":{"en":"Ensure your app is accessible to all users with tryramadan-accessibility. Learn how to implement skip links and focus visibility for keyboard and screen-read...","zh":"学习TryRamadan-Accessibility的最佳实践，确保您的应用程序对键盘和屏幕阅读器用户保持无障碍","ja":"TryRamadan-Accessibilityのベストプラクティスを学び、アプリケーションをキーボードとスクリーンリーダーにアクセシブルに保ちます","ko":"TryRamadan-Accessibility의 베스트 프랙티스를 학습하고, 애플리케이션을 키보드와 스크린 리더에 접근성 있게 유지하세요","es":"Aprende a implementar tryramadan-accessibility en tus aplicaciones para garantizar la accesibilidad para usuarios de teclado y lectores de pantalla","fr":"Découvrez comment mettre en œuvre tryramadan-accessibility dans vos applications pour garantir l''accessibilité aux utilisateurs de clavier et de lecteurs d''é...","de":"Erfahren Sie, wie Sie tryramadan-accessibility in Ihren Anwendungen implementieren, um die Barrierefreiheit für Tastatur- und Screen-Reader-Benutzer zu gewäh...","pt":"Aprenda a implementar a acessibilidade em sua aplicação com o tryramadan-accessibility, garantindo a usabilidade para usuários de teclado e leitores de tela","ru":"Узнайте, как настроить доступность в вашем приложении с помощью tryramadan-accessibility, обеспечивая использование для пользователей клавиатуры и экранных ч...","ar":"تعرف على كيفية تطبيق إمكانية الوصول في تطبيقك باستخدام tryramadan-accessibility، وضمان سهولة الاستخدام لمستخدمي لوحة المفاتيح وقارئي الشاشة"},"definition":{"en":"tryramadan-accessibility is a skill that provides accessibility guidelines for UI development, ensuring apps are usable by keyboard and screen-reader users.","zh":"TryRamadan-Accessibility是一种AIエージェント技能，帮助开发者确保应用程序的无障碍性","ja":"TryRamadan-Accessibilityは、アクセシビリティを確保するためのAIエージェントスキルです","ko":"TryRamadan-Accessibility는 접근성을 보장하는 데 도움이 되는 AI 에이전트 스킬입니다","es":"tryramadan-accessibility es una habilidad de agente de IA que garantiza la accesibilidad en aplicaciones web","fr":"tryramadan-accessibility est une compétence d''outil d''IA qui garantit l''accessibilité dans les applications web","de":"tryramadan-accessibility ist eine Fähigkeit von AI-Tools, die die Barrierefreiheit in Webanwendungen gewährleistet","pt":"O tryramadan-accessibility é uma habilidade de acessibilidade que garante a usabilidade de aplicações para usuários de teclado e leitores de tela","ru":"ИИ Агент tryramadan-accessibility - это habilidade доступности, обеспечивающая использование приложений для пользователей клавиатуры и экранных читателей","ar":"أداة ذكاء اصطناعي tryramadan-accessibility هي أداة إمكانية وصول تؤمن سهولة استخدام التطبيقات لمستخدمي لوحة المفاتيح وقارئي الشاشة"},"features":{"en":["Provides skip link functionality with ''Skip to main content'' at the top","Ensures focus visibility for interactive elements using focus-visible:ring-2 and focus-visible:ring-offset-2","Targets main landmark with id=''main-content''","Supports accessible UI development for keyboard users","Enhances screen-reader compatibility with proper focus management","Avoids removing outline without a replacement for accessibility"],"zh":["Skip to main content链接","交互元素的可见焦点环","支持键盘和屏幕阅读器用户","全局要求和交互元素的可见性","提供无障碍的应用程序开发"],"ja":["Skip to main contentリンク","インタラクティブ要素の可視フォーカスリング","キーボードとスクリーンリーダーに対応","グローバル要件とインタラクティブ要素の可視性","アクセシブルなアプリケーション開発を提供"],"ko":["스킵 투 메인 컨텐츠 링크","상호 작용 요소의 가시적 초점 링","키보드와 스크린 리더에 대한 지원","글로벌 요구 사항과 상호 작용 요소의 가시성","접근성 있는 애플리케이션 개발을 제공"],"es":["Enlace de salto a contenido principal","Anillo de enfoque visible para elementos interactivos","Compatibilidad con usuarios de teclado y lectores de pantalla","Implementación de requisitos de accesibilidad globales","Soporte para elementos personalizados y controles"],"fr":["Lien de saut au contenu principal","Anneau de focus visible pour les éléments interactifs","Compatibilité avec les utilisateurs de clavier et les lecteurs d''écran","Mise en œuvre des exigences d''accessibilité mondiales","Prise en charge des éléments personnalisés et des contrôles"],"de":["Sprunglink zum Hauptinhalt","Sichtbarer Fokusring für interaktive Elemente","Kompatibilität mit Tastatur- und Screen-Reader-Benutzern","Implementierung globaler Barrierefreiheitsanforderungen","Unterstützung für benutzerdefinierte Elemente und Steuerelemente"],"pt":["Skip link para \"Conteúdo principal\" no topo da página","Anel de foco visível para elementos interativos","Compatibilidade com leitores de tela","Acessibilidade para usuários de teclado","Manutenção da acessibilidade ao adicionar ou alterar UI"],"ru":["Ссылка для пропуска до \"Основного контента\" вверху страницы","Видимый фокус для интерактивных элементов","Совместимость с экранными читателями","Доступность для пользователей клавиатуры","Поддержание доступности при добавлении или изменении UI"],"ar":["رابط لتخطي \"المحتوى الرئيسي\" في أعلى الصفحة","حلقات التركيز المرئية للعناصر التفاعلية","التوافق مع قارئي الشاشة","إمكانية الوصول لمستخدمي لوحة المفاتيح","الحفاظ على إمكانية الوصول عند إضافة أو تغيير واجهة المستخدم"]},"keywords":{"en":["how to use tryramadan-accessibility","tryramadan-accessibility setup guide","accessible UI development","tryramadan-accessibility vs other accessibility tools","implementing skip links in tryramadan-accessibility","focus visibility in tryramadan-accessibility","tryramadan-accessibility for screen-reader users","tryramadan-accessibility install","tryramadan-accessibility documentation"],"zh":["TryRamadan-Accessibility","AIエージェント","无障碍开发","键盘支持","屏幕阅读器支持","交互元素","可见焦点环","全局要求"],"ja":["TryRamadan-Accessibility","AIエージェント","アクセシビリティ開発","キーボード対応","スクリーンリーダー対応","インタラクティブ要素","可視フォーカスリング","グローバル要件"],"ko":["TryRamadan-Accessibility","AI 에이전트","접근성 개발","키보드 지원","스크린 리더 지원","상호 작용 요소","가시적 초점 링","글로벌 요구 사항"],"es":["tryramadan-accessibility","accesibilidad web","agentes de IA","desarrollo de aplicaciones","usabilidad","tecnologías de accesibilidad","WCAG","lectores de pantalla"],"fr":["tryramadan-accessibility","accessibilité web","outils d''IA","développement d''applications","utilisabilité","technologies d''accessibilité","WCAG","lecteurs d''écran"],"de":["tryramadan-accessibility","Barrierefreiheit im Web","AI-Tools","Anwendungsentwicklung","Benutzerfreundlichkeit","Barrierefreiheitstechnologien","WCAG","Screen-Reader"],"pt":["acessibilidade web","tryramadan-accessibility","desenvolvimento de aplicações","usuários de teclado","leitores de tela","guias de acessibilidade","boas práticas de acessibilidade"],"ru":["доступность веб-сайтов","ИИ Агенты tryramadan-accessibility","разработка приложений","пользователи клавиатуры","экранные читатели","руководства по доступности","лучшие практики доступности"],"ar":["إمكانية الوصول إلى الويب","أداة ذكاء اصطناعي tryramadan-accessibility","تطوير التطبيقات","مستخدمو لوحة المفاتيح","قارئو الشاشة","دلائل إمكانية الوصول","أفضل الممارسات لإمكانية الوصول"]}},"owner":"codingshot","repo":"tryramadan","repoPath":"codingshot/tryramadan","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.476Z","topics":[],"category":"community","skillMd":{"name":"tryramadan-accessibility","description":"Accessibility (a11y) in TryRamadan. Covers skip link, focus visibility, aria-live for countdowns and dynamic content, RTL for Arabic, and axe-core tests. Use when adding or changing UI components, forms, or dynamic content to keep the app accessible.","bodyPreview":"# Accessibility (TryRamadan)\n\nUse this skill when **adding or changing UI** so the app stays accessible to keyboard and screen-reader users.\n\n---\n\n## 1. Global requirements\n\n- **Skip link:** \"Skip to main content\" at the top (focusable first); target `id=\"main-content\"` on main landmark.\n- **Focus visibility:** Interactive elements (buttons, links, custom controls) must have visible focus ring, e.g. `focus-visible:ring-2 focus-visible:ring-offset-2`. Avoid removing outline without a replacement.","body":"# Accessibility (TryRamadan)\n\nUse this skill when **adding or changing UI** so the app stays accessible to keyboard and screen-reader users.\n\n---\n\n## 1. Global requirements\n\n- **Skip link:** \"Skip to main content\" at the top (focusable first); target `id=\"main-content\"` on main landmark.\n- **Focus visibility:** Interactive elements (buttons, links, custom controls) must have visible focus ring, e.g. `focus-visible:ring-2 focus-visible:ring-offset-2`. Avoid removing outline without a replacement.\n- **Landmarks:** Use semantic HTML (`<main>`, `<nav>`, `<header>`, `<footer>`) and one `<h1>` per page where appropriate.\n\n---\n\n## 2. Dynamic content and countdowns\n\n- **Countdown timers** (e.g. time until Iftar, Suhoor end): Use `aria-live=\"polite\"` and `aria-label` describing the value (e.g. \"X hours Y minutes until Iftar\") so screen readers announce updates.\n- **Next prayer / status:** Wrap in `role=\"status\"` or `aria-live=\"polite\"` so changes are announced.\n- **FastingTimer, Dashboard countdown, DashboardPrayers next-prayer block:** Already use aria-live and aria-label; preserve when editing.\n\n---\n\n## 3. Forms and controls\n\n- **Labels:** Use `<label>` with `htmlFor` or `Label` component; avoid placeholders as sole labels.\n- **Errors:** Associate error text with inputs (e.g. `aria-describedby` or `aria-invalid`).\n- **Buttons:** Prefer `<button type=\"button\">` for actions; use `aria-label` when icon-only (e.g. Settings gear).\n\n---\n\n## 4. Arabic and RTL\n\n- **Arabic text:** Use `dir=\"rtl\"` on containers for Arabic content (e.g. `bodyAr`, glossary Arabic).\n- **Mixed content:** Keep surrounding layout LTR unless the whole section is RTL; use `dir=\"rtl\"` on the Arabic phrase/block (e.g. `<p className=\"font-arabic\" dir=\"rtl\">`).\n- **Transliteration:** Keep consistent (e.g. Suhoor, Iftar, Fajr) as used in the app.\n\n---\n\n## 5. Testing\n\n- **File:** `src/test/accessibility.test.tsx`.\n- **Tool:** vitest-axe (axe-core). Run `expect(...).toHaveNoViolations()` after rendering a page or component.\n- **Coverage:** HeroSection, OnboardingWelcome, ArabicHover/ArabicTerm, and other critical flows. Add new pages or components that introduce new interactive or dynamic content.\n\n---\n\n## 6. Checklist for UI changes\n\n- [ ] New interactive elements have visible focus and sensible tab order.\n- [ ] New countdowns or live-updating text have aria-live and aria-label.\n- [ ] New forms have proper labels and error association.\n- [ ] Arabic content has dir=\"rtl\" where needed.\n- [ ] Add or extend axe test for the changed flow if it’s a critical path.\n"},"lastSynced":"2026-03-08T02:09:48.970Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing to ensure accessibility compliance in UI components for keyboard and screen-reader users.","zh":"适合于需要确保UI组件对键盘和屏幕阅读器用户进行无障碍访问的前端代理。","ja":"キーボードとスクリーンリーダーのユーザーに対するUIコンポーネントのアクセシビリティコンプライアンスを確保する必要があるフロントエンドエージェントに適しています。","ko":"키보드와 화면 리더 사용자를 위한 UI 구성 요소의 접근성 준수를 보장해야 하는 프런트 엔드 에이전트에 적합합니다.","es":"Perfecto para agentes Frontend que necesitan garantizar el cumplimiento de la accesibilidad en componentes de UI para usuarios de teclado y lectores de pantalla.","fr":"Parfait pour les agents Frontend qui ont besoin de garantir la conformité à l''accessibilité dans les composants UI pour les utilisateurs de clavier et de lecteurs d''écran.","de":"Perfekt für Frontend-Agents, die die Einhaltung der Barrierefreiheit in UI-Komponenten für Tastatur- und Bildschirmlesebenutzer sicherstellen müssen.","pt":"Perfeito para Agentes Frontend que precisam garantir a conformidade de acessibilidade em componentes de UI para usuários de teclado e leitor de tela.","ru":"Идеально для фронтенд-агентов, которым необходимо обеспечить соблюдение требований доступности в компонентах пользовательского интерфейса для пользователей клавиатуры и программ чтения с экрана.","ar":"مثالي للوكلاء الأماميين الذين يحتاجون إلى ضمان امتثال مكونات الواجهة لاستخدام لوحة المفاتيح وقارئ الشاشة."},"recommendation":{"en":"Empowers agents to create accessible UI components with skip links and focus visibility, utilizing CSS properties like focus-visible:ring-2 and focus-visible:ring-offset-2 to enhance interactive element accessibility.","zh":"赋予代理创建具有跳过链接和焦点可见性的可访问UI组件的能力，利用CSS属性（如focus-visible:ring-2和focus-visible:ring-offset-2）来增强交互元素的无障碍访问。","ja":"スキップリンクとフォーカス可視性を使用して、アクセシブルなUIコンポーネントを作成するエージェントを可能にします。さらに、CSSプロパティ（例：focus-visible:ring-2とfocus-visible:ring-offset-2）を使用して、インタラクティブ要素のアクセシビリティを高めることができます。","ko":"스킵 링크와 포커스 표시를 사용하여 접근 가능한 UI 구성 요소를 만들 수 있는 에이전트를 가능하게 합니다. 또한 CSS 속성(focus-visible:ring-2 및 focus-visible:ring-offset-2 등)을 사용하여 상호 작용 요소의 접근성을 향상시킬 수 있습니다.","es":"Habilita a los agentes a crear componentes de UI accesibles con enlaces de salto y visibilidad de foco, utilizando propiedades CSS como focus-visible:ring-2 y focus-visible:ring-offset-2 para mejorar la accesibilidad de los elementos interactivos.","fr":"Permet aux agents de créer des composants UI accessibles avec des liens de saut et une visibilité de focus, en utilisant des propriétés CSS comme focus-visible:ring-2 et focus-visible:ring-offset-2 pour améliorer l''accessibilité des éléments interactifs.","de":"Ermächtigt die Agents, zugängliche UI-Komponenten mit Sprunglinks und Fokussierbarkeit zu erstellen, indem sie CSS-Eigenschaften wie focus-visible:ring-2 und focus-visible:ring-offset-2 verwenden, um die Zugänglichkeit interaktiver Elemente zu verbessern.","pt":"Habilita os agentes a criar componentes de UI acessíveis com links de saltar e visibilidade de foco, utilizando propriedades CSS como focus-visible:ring-2 e focus-visible:ring-offset-2 para melhorar a acessibilidade de elementos interativos.","ru":"Наделяет агентов возможностью создавать доступные компоненты пользовательского интерфейса со ссылками для перехода и видимостью фокуса, используя свойства CSS, такие как focus-visible:ring-2 и focus-visible:ring-offset-2, для улучшения доступности интерактивных элементов.","ar":"تمكن الوكلاء من إنشاء مكونات واجهة مستخدم قابلة للوصول مع روابط تخطي ووضوح تركيز، باستخدام خصائص CSS مثل focus-visible:ring-2 و focus-visible:ring-offset-2 لتحسين إمكانية الوصول إلى العناصر التفاعلية."},"useCases":{"en":["Implementing skip links for keyboard navigation","Adding visible focus rings to interactive elements","Ensuring accessibility compliance in custom UI controls"],"zh":["为键盘导航实现跳过链接","将可见焦点环添加到交互元素","确保自定义UI控件的无障碍访问"],"ja":["キーボードナビゲーションのスキップリンクを実装する","インタラクティブ要素に可視フォーカスリングを追加する","カスタムUIコントロールのアクセシビリティを確保する"],"ko":["키보드 탐색을 위한 스킵 링크 구현","상호 작용 요소에 표시 가능한 포커스 링 추가","사용자 지정 UI 컨트롤의 접근성 보장"],"es":["Implementar enlaces de salto para la navegación por teclado","Agregar anillos de enfoque visibles a los elementos interactivos","Garantizar el cumplimiento de la accesibilidad en controles de UI personalizados"],"fr":["Mettre en œuvre des liens de saut pour la navigation au clavier","Ajouter des anneaux de focus visibles aux éléments interactifs","Assurer la conformité à l''accessibilité dans les contrôles UI personnalisés"],"de":["Implementierung von Sprunglinks für die Tastaturnavigation","Hinzufügen sichtbarer Fokusringe zu interaktiven Elementen","Sicherstellung der Barrierefreiheit in benutzerdefinierten UI-Steuerungen"],"pt":["Implementar links de saltar para navegação por teclado","Adicionar anéis de foco visíveis a elementos interativos","Garantir conformidade de acessibilidade em controles de UI personalizados"],"ru":["Реализация ссылок для перехода для навигации с помощью клавиатуры","Добавление видимых колец фокуса к интерактивным элементам","Обеспечение соблюдения требований доступности в пользовательских элементах управления"],"ar":["تنفيذ روابط تخطي للتنقل بواسطة لوحة المفاتيح","إضافة طواقي تركيز مرئية إلى العناصر التفاعلية","ضمان امتثال مكونات الواجهة لاستخدام لوحة المفاتيح وقارئ الشاشة"]},"limitations":{"en":["Requires CSS styling capabilities","Limited to UI component accessibility"],"zh":["需要CSS样式功能","仅限UI组件的无障碍访问"],"ja":["CSSスタイリング機能が必要","UIコンポーネントのアクセシビリティに限定される"],"ko":["CSS 스타일링 기능이 필요","UI 구성 요소의 접근성에만 제한됨"],"es":["Requiere capacidades de estilo CSS","Limitado a la accesibilidad de los componentes de UI"],"fr":["Nécessite des capacités de style CSS","Limité à l''accessibilité des composants UI"],"de":["Benötigt CSS-Formatierungsfähigkeiten","Begrenzt auf die Barrierefreiheit von UI-Komponenten"],"pt":["Requer capacidades de estilização CSS","Limitado à acessibilidade de componentes de UI"],"ru":["Требует возможностей стилизации CSS","Ограничен доступностью компонентов пользовательского интерфейса"],"ar":["يتطلب khảيات تنسيق CSS","محدود بيمكنية الوصول إلى مكونات الواجهة"]},"version":4},"contentHash":"c37fffffa0814d90f9a986bea86f40c017b86cc5336087e92a8328ae02a58e6f","qualityScore":29}');
