INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('codingshot/tryramadan/tryramadan-accessibility', 'tryramadan-accessibility', 'codingshot', 'tryramadan', 'community', 'tryramadan-accessibility codingshot tryramadan community The tryramadan-accessibility skill helps developers create accessible UI components for keyboard and screen-reader users. It provides guidelines for adding skip links and focus visibility. TryRamadan-Accessibility是一个确保应用程序无障碍的技能，提供了全局要求和交互元素的可见焦点环 TryRamadan-Accessibilityは、アプリケーションをアクセシブルにするためのスキルで、グローバル要件とインタラクティブ要素の可視フォーカスリングを提供します TryRamadan-Accessibility는 애플리케이션을 접근성 있게 만드는 스킬로, 글로벌 요구 사항과 상호 작용 요소의 가시적 초점 링을 제공합니다 tryramadan-accessibility es una habilidad que ayuda a garantizar la accesibilidad en las aplicaciones, proporcionando un enlace de salto y un anillo de enfoque visible para elementos interactivos tryramadan-accessibility est une compétence qui aide à garantir l''accessibilité dans les applications, en fournissant un lien de saut et un anneau de focus visible pour les éléments interactifs tryramadan-accessibility ist eine Fähigkeit, die hilft, die Barrierefreiheit in Anwendungen zu gewährleisten, indem sie einen Sprunglink und einen sichtbaren Fokusring für interaktive Elemente bereitstellt O tryramadan-accessibility é uma habilidade que ajuda a manter a acessibilidade em aplicações ao adicionar ou alterar UI, garantindo a usabilidade para usuários de teclado e leitores de tela ИИ Агент tryramadan-accessibility помогает поддерживать доступность в приложениях при добавлении или изменении UI, обеспечивая использование для пользователей клавиатуры и экранных читателей أداة ذكاء اصطناعي tryramadan-accessibility تساعد على الحفاظ على إمكانية الوصول في التطبيقات عند إضافة أو تغيير واجهة المستخدم، وضمان سهولة الاستخدام لمستخدمي لوحة المفاتيح وقارئي الشاشة how to use tryramadan-accessibility tryramadan-accessibility setup guide accessible UI development tryramadan-accessibility vs other accessibility tools implementing skip links in tryramadan-accessibility focus visibility in tryramadan-accessibility tryramadan-accessibility for screen-reader users tryramadan-accessibility install tryramadan-accessibility documentation TryRamadan-Accessibility AIエージェント 无障碍开发 键盘支持 屏幕阅读器支持 交互元素 可见焦点环 全局要求 Provides skip link functionality with ''Skip to main content'' at the top Ensures focus visibility for interactive elements using focus-visible:ring-2 and focus-visible:ring-offset-2 Targets main landmark with id=''main-content'' Supports accessible UI development for keyboard users Enhances screen-reader compatibility with proper focus management Avoids removing outline without a replacement for accessibility tryramadan-accessibility is a skill that provides accessibility guidelines for UI development, ensuring apps are usable by keyboard and screen-reader users.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('The-Tech-Idea/BeepDM/etl', 'community', 'The-Tech-Idea', 'BeepDM', 'The-Tech-Idea/BeepDM', 'etl', 0, 0, 29, '2026-03-08T01:57:15.482Z', '2026-03-08T02:09:56.888Z', '82552d99035e94c424c836e192a715420120d269e6024a4123e2b838bbd5c8da', '{"id":"The-Tech-Idea/BeepDM/etl","name":"etl","description":{"en":"The etl skill is a library for managing connections to different data sources, ideal for developers migrating data between datasources. It offers tools like ETLEditor and DataImportManager for efficient ETL operations.","zh":"ETL库是一个用于管理不同数据源连接的库，提供ETL脚本生成和数据迁移功能","ja":"ETLツールは、異なるデータソースへの接続を管理し、ETLスクリプトを生成し、データを移行するライブラリです","ko":"ETL 라이브러리는 다양한 데이터 소스를 연결 관리하고 ETL 스크립트를 생성하며 데이터를 마이그레이션하는 라이브러리입니다","es":"La biblioteca ETL es una herramienta para gestionar conexiones a diferentes fuentes de datos. Utilice ETLEditor para orquestar copias de esquemas y datos.","fr":"La bibliothèque ETL est un outil pour gérer les connexions à différentes sources de données. Utilisez ETLEditor pour orchestrer des copies de schémas et de données.","de":"Die ETL-Bibliothek ist ein Tool zur Verwaltung von Verbindungen zu verschiedenen Datenquellen. Verwenden Sie ETLEditor, um Schema- und Datenkopien zu orchestrieren.","pt":"A biblioteca ETL é uma ferramenta para gerenciar conexões com diferentes fontes de dados. Aprenda a usá-la para migrar dados e mais","ru":"Библиотека ETL — это инструмент для управления связями с различными источниками данных. Узнайте, как использовать ее для миграции данных и больше","ar":"مكتبة ETL هي أداة لإدارة الاتصالات ببيانات المصادر المختلفة. تعلم كيفية استخدامها لتنقل البيانات وغيرها"},"seo":{"title":{"en":"etl: ETL Operations Setup Guide | AI Agent Skill","zh":"ETL库：数据源连接管理与脚本生成","ja":"ETLツール：データソース接続管理とスクリプト生成","ko":"ETL 라이브러리: 데이터 소스 연결 관리 및 스크립트 생성","es":"Guía de configuración de ETL para gestión de fuentes de d...","fr":"Guide de mise en place de l''ETL pour la gestion des sourc...","de":"ETL-Setup-Leitfaden für die Verwaltung von Datenquellen","pt":"Guia de Configuração ETL para Gerenciamento de Conexões d...","ru":"ИИ Агенты: Руководство по Настройке ETL для Управления Св...","ar":"دليل إعداد ETL لت 管理 الاتصالات ببيانات المصادر"},"description":{"en":"Discover how to migrate data between datasources with etl. Learn to use ETLEditor, DataImportManager, and ETLScriptManager for seamless ETL operations. Get s...","zh":"使用ETL库管理数据源连接，生成ETL脚本，并进行数据迁移","ja":"ETLツールを使用してデータソース接続を管理し、ETLスクリプトを生成し、データを移行します","ko":"ETL 라이브러리를 사용하여 데이터 소스 연결을 관리하고 ETL 스크립트를 생성하며 데이터를 마이그레이션합니다","es":"Aprende a utilizar la biblioteca ETL para migrar datos entre fuentes y gestionar conexiones con diferentes datasources","fr":"Découvrez comment utiliser la bibliothèque ETL pour migrer des données entre sources et gérer les connexions avec différentes sources de données","de":"Erfahren Sie, wie Sie die ETL-Bibliothek verwenden können, um Daten zwischen Quellen zu migrieren und Verbindungen zu verschiedenen Datenquellen zu verwalten","pt":"Aprenda a configurar a biblioteca ETL para gerenciar conexões com diferentes fontes de dados e migrar dados com eficiência","ru":"Узнайте, как настроить библиотеку ETL для управления связями с различными источниками данных и миграции данных","ar":"تعلم كيفية تكوين مكتبة ETL لإدارة الاتصالات ببيانات المصادر المختلفة وتنقل البيانات بكفاءة"},"definition":{"en":"etl is a library for managing connections to different data sources, facilitating ETL operations such as data migration and import governance.","zh":"ETL库是一种用于管理数据源连接和生成ETL脚本的库","ja":"ETLツールは、データソース接続を管理し、ETLスクリプトを生成するためのライブラリです","ko":"ETL 라이브러리는 데이터 소스 연결을 관리하고 ETL 스크립트를 생성하는 라이브러리입니다","es":"ETL es una biblioteca para gestionar conexiones a diferentes fuentes de datos y migrar datos entre ellas","fr":"ETL est une bibliothèque pour gérer les connexions à différentes sources de données et migrer des données entre elles","de":"ETL ist eine Bibliothek zur Verwaltung von Verbindungen zu verschiedenen Datenquellen und zum Migrieren von Daten zwischen ihnen","pt":"ETL é uma biblioteca para gerenciar conexões com diferentes fontes de dados","ru":"ETL — это библиотека для управления связями с различными источниками данных","ar":"ETL هو مكتبة لإدارة الاتصالات ببيانات المصادر المختلفة"},"features":{"en":["Use ETLEditor for schema and data copy orchestration","Utilize DataImportManager for advanced import governance and data quality","Leverage ETLScriptManager for standalone JSON script persistence","Perform mapping-based imports and diagnose ETL runtime behavior","Run direct datasource-to-datasource copy methods","Generate ETL scripts for efficient data migration"],"zh":["支持数据源连接管理","提供ETL脚本生成功能","支持数据迁移","包含ETLEditor、DataImportManager和ETLScriptManager","提供数据质量和运行历史记录功能","支持JSON脚本持久化"],"ja":["データソース接続管理をサポート","ETLスクリプト生成機能を提供","データ移行をサポート","ETLEditor、DataImportManager、ETLScriptManagerを含む","データ品質と実行履歴レコード機能を提供","JSONスクリプトの永続化をサポート"],"ko":["데이터 소스 연결 관리 지원","ETL 스크립트 생성 기능 제공","데이터 마이그레이션 지원","ETLEditor, DataImportManager, ETLScriptManager 포함","데이터 품질 및 실행 기록 레코드 기능 제공","JSON 스크립트 영속화 지원"],"es":["Soporte para migración de datos entre fuentes","Orquestación de copias de esquemas y datos con ETLEditor","Generación de scripts ETL","Gestión de importaciones con DataImportManager","Diagnóstico de comportamiento en tiempo de ejecución de ETL","Soporte para copias directas de fuente a fuente"],"fr":["Prise en charge de la migration de données entre sources","Orchestration de copies de schémas et de données avec ETLEditor","Génération de scripts ETL","Gestion des importations avec DataImportManager","Diagnostic du comportement en temps d''exécution de l''ETL","Prise en charge de copies directes de source à source"],"de":["Unterstützung für die Migration von Daten zwischen Quellen","Orchestrierung von Schema- und Datenkopien mit ETLEditor","Generierung von ETL-Skripten","Verwaltung von Importen mit DataImportManager","Diagnose des Laufzeitverhaltens von ETL","Unterstützung für direkte Kopien von Quelle zu Quelle"],"pt":["Suporte a múltiplas fontes de dados","Orquestração de cópia de esquema e dados","Geração de scripts ETL","Importação baseada em mapeamento","Diagnóstico de comportamento de tempo de execução ETL"],"ru":["Поддержка нескольких источников данных","Оркестровка копирования схемы и данных","Генерация скриптов ETL","Импорт на основе сопоставления","Диагностика поведения времени выполнения ETL"],"ar":["دعم مصادر بيانات متعددة","أوركسترا نسخة مخطط وبيانات","توليد نصوص ETL","استيراد قائم على التطابق","تشخيص سلوك وقت تشغيل ETL"]},"keywords":{"en":["how to use etl","etl alternative","etl setup guide","what is etl","etl vs talend","etl install","etl operations guide","etl data migration","etl import governance"],"zh":["ETL库","数据源连接管理","ETL脚本生成","数据迁移","ETLEditor","DataImportManager","ETLScriptManager","JSON脚本持久化","数据质量","运行历史记录"],"ja":["ETLツール","データソース接続管理","ETLスクリプト生成","データ移行","ETLEditor","DataImportManager","ETLScriptManager","JSONスクリプトの永続化","データ品質","実行履歴レコード"],"ko":["ETL 라이브러리","데이터 소스 연결 관리","ETL 스크립트 생성","데이터 마이그레이션","ETLEditor","DataImportManager","ETLScriptManager","JSON 스크립트 영속화","데이터 품질","실행 기록 레코드"],"es":["ETL","migración de datos","gestión de fuentes de datos","ETLEditor","DataImportManager","script ETL","copias de esquemas y datos","diagnóstico de ETL","herramientas de ETL","bibliotecas de ETL"],"fr":["ETL","migration de données","gestion des sources de données","ETLEditor","DataImportManager","script ETL","copies de schémas et de données","diagnostic ETL","outils ETL","bibliothèques ETL"],"de":["ETL","Datenmigration","Verwaltung von Datenquellen","ETLEditor","DataImportManager","ETL-Skript","Schema- und Datenkopien","ETL-Diagnose","ETL-Tools","ETL-Bibliotheken"],"pt":["etl","gerenciamento de conexões de dados","migração de dados","biblioteca etl","orquestração de cópia de esquema e dados","geração de scripts etl","importação baseada em mapeamento","diagnóstico de comportamento de tempo de execução etl"],"ru":["etl","управление связями с источниками данных","миграция данных","библиотека etl","оркестровка копирования схемы и данных","генерация скриптов etl","импорт на основе сопоставления","диагностика поведения времени выполнения etl"],"ar":["etl","إدارة الاتصالات ببيانات المصادر","نقل البيانات","مكتبة etl","أوركسترا نسخة مخطط وبيانات","توليد نصوص etl","استيراد قائم على التطابق","تشخيص سلوك وقت تشغيل etl"]}},"owner":"The-Tech-Idea","repo":"BeepDM","repoPath":"The-Tech-Idea/BeepDM","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.482Z","topics":[],"category":"community","skillMd":{"name":"etl","description":"Detailed ETL guidance for ETLEditor workflows, script building, validation, import execution, runtime controls, and cross-skill integration in BeepDM.","bodyPreview":"# ETL Operations Guide\n\nUse this skill when migrating data between datasources, generating ETL scripts, running mapping-based imports, or diagnosing ETL runtime behavior.\n\n## Decision Guide\n- Use `ETLEditor` for schema+data copy orchestration, script generation, and direct datasource-to-datasource copy methods.\n- Use `DataImportManager` for advanced import governance (staging, replay, data quality, run history, profiling).\n- Use `ETLScriptManager` only when you need standalone JSON script persis","body":"# ETL Operations Guide\n\nUse this skill when migrating data between datasources, generating ETL scripts, running mapping-based imports, or diagnosing ETL runtime behavior.\n\n## Decision Guide\n- Use `ETLEditor` for schema+data copy orchestration, script generation, and direct datasource-to-datasource copy methods.\n- Use `DataImportManager` for advanced import governance (staging, replay, data quality, run history, profiling).\n- Use `ETLScriptManager` only when you need standalone JSON script persistence/execution outside the normal `ETLEditor` flow.\n\n## Prerequisites\n1. `IDMEEditor` is initialized and services are available.\n2. Source and destination datasource names resolve in `DMEEditor.GetDataSource(...)`.\n3. Required datasources can be opened (`DMEEditor.OpenDataSource(...)`).\n4. Entity metadata is loaded for source and destination.\n5. `IProgress<PassedArgs>` and `CancellationToken` are provided by caller.\n\n## Core Runtime Types\n- `ETLEditor`: main ETL orchestrator implementing `IETL`.\n- `ETLScriptHDR`: script container (`ScriptSource`, `ScriptDetails`, run metadata).\n- `ETLScriptDet`: per-step operation (`CreateEntity`, `CopyData`, mappings, tracking).\n- `ETLValidator`: preflight validator for mappings and source/destination consistency.\n- `ETLDataCopier`: optional async/batched data copy utility.\n- `ETLScriptManager`: script repository-style load/save/validate/execute service.\n\n## Public ETLEditor API Surface\n- Script setup:\n  - `CreateScriptHeader(IDataSource Srcds, IProgress<PassedArgs> progress, CancellationToken token)`\n  - `GetCreateEntityScript(IDataSource ds, List<string> entities, ..., bool copydata = false)`\n  - `GetCreateEntityScript(IDataSource Dest, List<EntityStructure> entities, ..., bool copydata = false)`\n  - `GetCopyDataEntityScript(IDataSource Dest, List<EntityStructure> entities, ...)`\n- Direct copy APIs:\n  - `CopyEntityStructure`, `CopyEntitiesStructure`\n  - `CopyEntityData`, `CopyEntitiesData`, `CopyDatasourceData`\n- Script execution APIs:\n  - `RunCreateScript(..., bool copydata = true, bool useEntityStructure = true)`\n  - `CreateImportScript(EntityDataMap mapping, EntityDataMap_DTL selectedMapping)`\n  - `RunImportScript(..., bool useEntityStructure = true)`\n- Persistence:\n  - `SaveETL(string datasourceName)`\n  - `LoadETL(string datasourceName)`\n\n## Primary Workflows\n### 1) Full migration (create + copy)\n1. `CreateScriptHeader(sourceDs, progress, token)`.\n2. Ensure each `ETLScriptDet.DestinationDataSourceName` points to destination datasource.\n3. Optionally filter/reorder `Script.ScriptDetails` and set `CopyData`.\n4. Run `RunCreateScript(progress, token, copydata: true, useEntityStructure: true)`.\n5. Review `IErrorsInfo`, `LoadDataLogs`, and `ETLScriptDet.Tracking`.\n\n### 2) Structure-only migration\n1. Build create scripts using `GetCreateEntityScript(...)`.\n2. Execute `RunCreateScript(..., copydata: false, ...)`.\n3. Validate destination schema before data load.\n\n### 3) Data-only copy into existing schema\n1. Build copy-only scripts with `GetCopyDataEntityScript(...)`.\n2. Assign `Script.ScriptDetails` to copy list.\n3. Run `RunCreateScript(..., copydata: true, ...)` with existing destination entities.\n\n### 4) Mapping-based import\n1. Build mapping (`EntityDataMap` + selected `EntityDataMap_DTL`).\n2. `CreateImportScript(mapping, selectedMapping)`.\n3. `RunImportScript(progress, token, useEntityStructure: true)`.\n4. Check `LoadDataLogs` and destination inserts.\n\n## Validation and Preflight\n- `RunCreateScript(...)` and `RunImportScript(...)` now run ETL preflight internally.\n- `RunCreateScript(...)` can bridge preflight to `DataImportManager.RunMigrationPreflightAsync(...)` when enabled.\n- For explicit caller-controlled checks, you can still use:\n  - `ETLValidator.ValidateEntityMapping(mapping)`\n  - `ValidateMappedEntity(...)`\n  - `ValidateEntityConsistency(sourceDs, destDs, srcEntity, destEntity)`\n- Enforce `IErrorsInfo.Flag == Errors.Ok` as go/no-go before manual operation chaining.\n\n## Runtime Controls and Diagnostics\n- `StopErrorCount` controls early stop threshold during script execution.\n- Cancellation is honored through `CancellationToken`; always pass a real token.\n- `LoadDataLogs` is human-readable run trace (`InputLine` messages).\n- `ETLScriptDet.Tracking` stores detailed per-script error/record context.\n- `DMEEditor.ErrorObject` is authoritative final status for operation calls.\n- Run-level telemetry is now correlated with a run id and emits summary counters.\n- Evidence artifacts are generated under `Scripts/ETL_Evidence`:\n  - per-run file: `<runId>.md`\n  - rolling summary: `ETL_EVIDENCE_SUMMARY.md`\n  - current week/month views: `ETL_EVIDENCE_CURRENT_WEEK.md`, `ETL_EVIDENCE_CURRENT_MONTH.md`\n\n## Script Persistence and Reuse\n- `SaveETL(datasourceName)` now validates script and persists via `ETLScriptManager` canonical path.\n- `LoadETL(datasourceName)` now loads from manager first, with legacy folder fallback for compatibility.\n- `ETLScriptManager` supports repository-style operations (`LoadScripts`, `SaveScript`, `ValidateScript`, `ExecuteScriptAsync`) when managing scripts independently.\n\n## Operational Pitfalls\n- Do not keep destination names equal to source unless intentionally copying back.\n- If `useEntityStructure` is false, ETL re-reads structures from datasource at runtime.\n- For large entity copies, prefer `ETLDataCopier.CopyEntityDataAsync(...)` with bounded batch/retry/parallel settings.\n- Internal ETL preflight is active in `RunCreateScript`/`RunImportScript`; keep custom validator calls only when you need stricter caller-side gates.\n- Direct helper methods like `InsertEntity(...)` are public implementation details, not part of `IETL`; avoid treating them as stable contract APIs.\n\n## In-Memory Integration Pattern\n- In-memory datasource implementations (for example `InMemoryRDBSource` variants) commonly:\n  1. build scripts via `GetCreateEntityScript` or `GetCopyDataEntityScript`,\n  2. assign `DMEEditor.ETL.Script.ScriptDetails`,\n  3. execute `RunCreateScript` for load/refresh operations.\n- Keep in-memory structure and entity-name synchronization consistent before ETL runs.\n\n## Additional Resources\n- API examples and troubleshooting snippets: [reference.md](reference.md)\n- Related skills:\n  - [beepservice](../beepservice/SKILL.md)\n  - [connection](../connection/SKILL.md)\n  - [environmentservice](../environmentservice/SKILL.md)\n  - [idatasource](../idatasource/SKILL.md)\n  - [inmemorydb](../inmemorydb/SKILL.md)\n  - [importing](../importing/SKILL.md)\n  - [migration](../migration/SKILL.md)\n  - [universal-helper-factory](../universal-helper-factory/SKILL.md)\n  - [universal-rdbms-helper](../universal-rdbms-helper/SKILL.md)\n"},"lastSynced":"2026-03-08T02:09:56.888Z","agentAnalysis":{"suitability":{"en":"Ideal for Data Migration Agents requiring efficient ETL operations and datasource management","zh":"适合需要高效ETL操作和数据源管理的数据迁移代理","ja":"効率的なETL操作とデータソース管理を必要とするデータ移行エージェントに最適","ko":"효율적인 ETL 작업 및 데이터 소스 관리가 필요한 데이터 마이그레이션 에이전트에 적합","es":"Ideal para Agentes de Migración de Datos que requieren operaciones ETL eficientes y gestión de fuentes de datos","fr":"Idéal pour les Agents de Migration de Données nécessitant des opérations ETL efficaces et une gestion de sources de données","de":"Ideal für Data-Migrations-Agents, die effiziente ETL-Operationen und Datenquellenverwaltung benötigen","pt":"Ideal para Agentes de Migração de Dados que requerem operações ETL eficientes e gerenciamento de datasource","ru":"Идеально для агентов миграции данных, требующих эффективных операций ETL и управления источниками данных","ar":"مثالي لعميل نقل البيانات الذي يتطلب عمليات ETL فعالة وإدارة مصدر البيانات"},"recommendation":{"en":"Empowers agents to orchestrate schema and data copies, generate ETL scripts, and manage imports using tools like ETLEditor and DataImportManager, supporting advanced import governance and data quality protocols","zh":"赋予代理编排模式和数据副本、生成ETL脚本和使用ETLEditor和DataImportManager等工具管理导入，支持高级导入治理和数据质量协议","ja":"エージェントにスキーマとデータのコピー、ETLスクリプトの生成、ETLEditorとDataImportManagerなどのツールを使用したインポートの管理を行い、高度なインポートのガバナンスとデータ品質プロトコルをサポートする","ko":"에이전트가 스키마 및 데이터 복사, ETL 스크립트 생성 및 ETLEditor 및 DataImportManager와 같은 도구를 사용하여 가져오기를 관리하고 고급 가져오기 거버넌스 및 데이터 품질 프로토콜을 지원","es":"Habilita a los agentes a orquestar copias de esquemas y datos, generar scripts ETL y gestionar importaciones utilizando herramientas como ETLEditor y DataImportManager, que admiten protocolos de gobernanza de importación avanzada y protocolos de calidad de datos","fr":"Permet aux agents d''orchestrer des copies de schémas et de données, de générer des scripts ETL et de gérer les imports en utilisant des outils comme ETLEditor et DataImportManager, qui prennent en charge des protocoles de gouvernance d''importation avancés et des protocoles de qualité de données","de":"Ermächtigt die Agents, Schemata und Datenkopien zu orchestrieren, ETL-Skripte zu generieren und Importe mithilfe von Tools wie ETLEditor und DataImportManager zu verwalten, die erweiterte Import-Governance- und Datenqualitätsprotokolle unterstützen","pt":"Habilita os agentes a orquestrar cópias de esquema e dados, gerar scripts ETL e gerenciar imports usando ferramentas como ETLEditor e DataImportManager, dando suporte a protocolos avançados de governança de importação e qualidade de dados","ru":"Наделяет агентов возможностью оркестровать копии схемы и данных, генерировать скрипты ETL и управлять импортом с помощью инструментов seperti ETLEditor и DataImportManager, поддерживая продвинутые протоколы управления импортом и качества данных","ar":"يتمكن العملاء من تنسيق نسخ مخطط البيانات والبيانات وإنشاء نصوص برمجة ETL وإدارة الاستيراد باستخدام أدوات مثل ETLEditor و DataImportManager، مع دعم بروتوكولات متقدمة لحوكمة الاستيراد وبروتوكولات جودة البيانات"},"useCases":{"en":["Migrating data between datasources","Generating ETL scripts for custom imports","Diagnosing ETL runtime behavior for optimization"],"zh":["迁移数据源之间的数据","生成自定义导入的ETL脚本","诊断ETL运行时行为以优化"],"ja":["データソース間のデータを移行する","カスタムインポートのETLスクリプトを生成する","ETLのランタイム動作を診断して最適化する"],"ko":["데이터 소스 간의 데이터 마이그레이션","사용자 지정 가져오기용 ETL 스크립트 생성","최적화를 위해 ETL 런타임 동작 진단"],"es":["Migrar datos entre fuentes de datos","Generar scripts ETL para importaciones personalizadas","Diagnosticar el comportamiento de tiempo de ejecución de ETL para la optimización"],"fr":["Migrer des données entre sources de données","Générer des scripts ETL pour des imports personnalisés","Diagnostiquer le comportement de temps d''exécution de ETL pour l''optimisation"],"de":["Daten zwischen Datenquellen migrieren","ETL-Skripte für benutzerdefinierte Importe generieren","ETL-Laufzeitverhalten für die Optimierung diagnostizieren"],"pt":["Migrar dados entre datasources","Gerar scripts ETL para imports personalizados","Diagnosticar comportamento de tempo de execução ETL para otimização"],"ru":["Миграция данных между источниками данных","Генерация скриптов ETL для пользовательских импортов","Диагностика поведения ETL во время выполнения для оптимизации"],"ar":["نقل البيانات بين مصادر البيانات","إنشاء نصوص برمجة ETL للاستيرادات المخصصة","تشخيص سلوك وقت تشغيل ETL لتحسين الأداء"]},"limitations":{"en":["Requires specific datasource connections","Dependent on ETLEditor and DataImportManager tools"],"zh":["需要特定的数据源连接","依赖于ETLEditor和DataImportManager工具"],"ja":["特定のデータソース接続が必要","ETLEditorとDataImportManagerなどのツールに依存"],"ko":["특정 데이터 소스 연결 필요","ETLEditor 및 DataImportManager와 같은 도구에 의존"],"es":["Requiere conexiones de fuentes de datos específicas","Dependiente de las herramientas ETLEditor y DataImportManager"],"fr":["Nécessite des connexions de sources de données spécifiques","Dépend des outils ETLEditor et DataImportManager"],"de":["Benötigt spezifische Datenquellenverbindungen","Abhängig von den Tools ETLEditor und DataImportManager"],"pt":["Requer conexões de datasource específicas","Dependente de ferramentas ETLEditor e DataImportManager"],"ru":["Требует специфических соединений с источниками данных","Зависит от инструментов ETLEditor и DataImportManager"],"ar":["يتطلب اتصالات مصدر بيانات محددة","يعتمد على أدوات ETLEditor و DataImportManager"]},"version":4},"contentHash":"82552d99035e94c424c836e192a715420120d269e6024a4123e2b838bbd5c8da","qualityScore":29}');
