INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('The-Tech-Idea/BeepDM/etl', 'etl', 'The-Tech-Idea', 'BeepDM', 'community', 'etl The-Tech-Idea BeepDM community The etl skill is a library for managing connections to different data sources, ideal for developers migrating data between datasources. It offers tools like ETLEditor and DataImportManager for efficient ETL operations. ETL库是一个用于管理不同数据源连接的库，提供ETL脚本生成和数据迁移功能 ETLツールは、異なるデータソースへの接続を管理し、ETLスクリプトを生成し、データを移行するライブラリです ETL 라이브러리는 다양한 데이터 소스를 연결 관리하고 ETL 스크립트를 생성하며 데이터를 마이그레이션하는 라이브러리입니다 La biblioteca ETL es una herramienta para gestionar conexiones a diferentes fuentes de datos. Utilice ETLEditor para orquestar copias de esquemas y datos. La bibliothèque ETL est un outil pour gérer les connexions à différentes sources de données. Utilisez ETLEditor pour orchestrer des copies de schémas et de données. Die ETL-Bibliothek ist ein Tool zur Verwaltung von Verbindungen zu verschiedenen Datenquellen. Verwenden Sie ETLEditor, um Schema- und Datenkopien zu orchestrieren. A biblioteca ETL é uma ferramenta para gerenciar conexões com diferentes fontes de dados. Aprenda a usá-la para migrar dados e mais Библиотека ETL — это инструмент для управления связями с различными источниками данных. Узнайте, как использовать ее для миграции данных и больше مكتبة ETL هي أداة لإدارة الاتصالات ببيانات المصادر المختلفة. تعلم كيفية استخدامها لتنقل البيانات وغيرها how to use etl etl alternative etl setup guide what is etl etl vs talend etl install etl operations guide etl data migration etl import governance ETL库 数据源连接管理 ETL脚本生成 数据迁移 ETLEditor DataImportManager ETLScriptManager JSON脚本持久化 数据质量 运行历史记录 Use ETLEditor for schema and data copy orchestration Utilize DataImportManager for advanced import governance and data quality Leverage ETLScriptManager for standalone JSON script persistence Perform mapping-based imports and diagnose ETL runtime behavior Run direct datasource-to-datasource copy methods Generate ETL scripts for efficient data migration etl is a library for managing connections to different data sources, facilitating ETL operations such as data migration and import governance.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('felixzhu97/finpulse/project-standards', 'community', 'felixzhu97', 'finpulse', 'felixzhu97/finpulse', 'project-standards', 0, 0, 29, '2026-03-08T01:57:15.494Z', '2026-03-08T02:10:11.284Z', '5514d58da608facc5796018e1a250cb543f5d5c3ac03e523669919736a933946', '{"id":"felixzhu97/finpulse/project-standards","name":"project-standards","description":{"en":"project-standards is a professional-grade platform that facilitates financial data analysis and portfolio management, benefiting developers and financial analysts by ensuring up-to-date documentation and diagrams.","zh":"项目标准是一套专业的代码、API和架构管理规范，确保项目开发过程中的高效性和准确性","ja":"プロジェクト標準は、コード、API、建築の管理規範であり、プロジェクト開発プロセスの効率性と正確性を保証します","ko":"프로젝트 표준은 코드, API, 아키텍처를 관리하는 규范으로 프로젝트 개발 과정의 효율성과 정확성을 보장합니다","es":"Estándares de proyecto para análisis financiero y gestión de carteras. Actualiza la documentación y los diagramas después de cada cambio","fr":"Normes de projet pour l''analyse financière et la gestion de portefeuille. Mettez à jour la documentation et les diagrammes après chaque modification","de":"Projektstandards für die Finanzdatenanalyse und das Portfolio-Management. Aktualisieren Sie die Dokumentation und Diagramme nach jeder Änderung","pt":"O projeto-standards é uma plataforma de análise de dados financeiros e gestão de portfolio que exige atualizações de documentação e diagramas após alterações no código, APIs ou arquitetura","ru":"Стандарты Проектов - это платформа для финансового анализа данных и управления портфелем, требующая обновления документации и диаграмм после изменений в коде, API или архитектуре с помощью ИИ Агентов","ar":"مواصفات المشروع هي منصة للتحليل المالي و إدارة المحفظة التي تتطلب تحديثات للوثائق والرسومات بعد التغييرات في الكود أو واجهات البرمجة أو الهياكل باستخدام أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"project-standards: Update Documentation and Diagrams Prom...","zh":"项目标准设置指南 - AI工具","ja":"プロジェクト標準設定ガイド - AIエージェント","ko":"프로젝트 표준 설정 가이드 - AI 에이전트","es":"Guía de configuración de estándares de proyecto para anál...","fr":"Guide de mise en place des normes de projet pour l''analys...","de":"Einrichtungsleitfaden für Projektstandards in der Finanzd...","pt":"Padronização de Projetos: Guia de Configuração para Análi...","ru":"Стандарты Проектов: Настройка для Финансового Анализа дан...","ar":"مواصفات المشروع: دليل الإعداد للتحليل المالي باستخدام أدو..."},"description":{"en":"Discover how project-standards streamlines financial data analysis and portfolio management by updating README, API docs, and .puml diagrams - get started now!","zh":"了解项目标准的重要性和实施方法，确保您的项目代码、API和架构保持最新和准确","ja":"プロジェクト標準の重要性と実装方法を学び、コード、API、建築を最新かつ正確に保つ","ko":"프로젝트 표준의 중요성과 구현 방법을 알아보고 코드, API, 아키텍처를 최신 상태로 유지하세요","es":"Aprende a implementar estándares de proyecto para análisis financiero y gestión de carteras con nuestra guía paso a paso","fr":"Découvrez comment mettre en place des normes de projet pour l''analyse financière et la gestion de portefeuille avec notre guide étape par étape","de":"Erfahren Sie, wie Sie Projektstandards für die Finanzdatenanalyse und das Portfolio-Management mit unserem Schritt-für-Schritt-Leitfaden umsetzen","pt":"Aprenda a aplicar padrões de projeto para análise de dados financeiros e gestão de portfolio com atualizações de documentação e diagramas","ru":"Изучайте, как применять стандарты проектов для финансового анализа данных и управления портфелем с обновлениями документации и диаграмм с помощью ИИ Агентов","ar":"تعرف على كيفية تطبيق معايير المشروع للتحليل المالي و إدارة المحفظة مع تحديثات الوثائق والرسومات باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"project-standards is a set of guidelines for maintaining accurate and current documentation and diagrams in financial data analysis and portfolio management projects.","zh":"项目标准是指在项目开发过程中，对代码、API和架构的管理和维护规范","ja":"プロジェクト標準とは、プロジェクト開発プロセスにおいて、コード、API、建築の管理とメンテナンスに関する規範","ko":"프로젝트 표준이란 프로젝트 개발 과정에서 코드, API, 아키텍처의 관리와 유지 보수를 위한 규칙","es":"Estándares de proyecto son reglas para mantener la documentación y los diagramas actualizados después de cambios en el código o la arquitectura","fr":"Les normes de projet sont des règles pour maintenir la documentation et les diagrammes à jour après des modifications du code ou de l''architecture","de":"Projektstandards sind Regeln, um die Dokumentation und Diagramme nach Änderungen im Code oder in der Architektur auf dem neuesten Stand zu halten","pt":"Projeto-standards é um conjunto de diretrizes para manter a documentação e diagramas atualizados após alterações no código ou arquitetura","ru":"Стандарты Проектов - это набор руководящих принципов для поддержания актуальности документации и диаграмм после изменений в коде или архитектуре с помощью ИИ Агентов","ar":"مواصفات المشروع هي مجموعة من المبادئ التوجيهية لتحديث الوثائق والرسومات بعد التغييرات في الكود أو الهياكل باستخدام أدوات الذكاء الاصطناعي"},"features":{"en":["Updates README files in root and affected areas","Modifies API documentation to reflect code changes","Edits .puml diagrams to ensure structural accuracy","Applies after changes to code, APIs, or architecture","Supports updating documentation and diagrams upon user request"],"zh":["更新README和文档","修改代码和API时更新相关文档","使用.puml图表进行架构设计","确保代码、API和架构的一致性","实现项目开发过程中的高效性和准确性"],"ja":["READMEとドキュメントを更新","コードとAPIの変更時に関連ドキュメントを更新",".puml図表を使用して建築設計","コード、API、建築の一貫性を保つ","プロジェクト開発プロセスの効率性と正確性を実現"],"ko":["README와 문서를 업데이트","코드와 API를 변경할 때 관련 문서를 업데이트",".puml 다이어그램을 사용하여 아키텍처 설계","코드, API, 아키텍처의 일관성을 유지","프로젝트 개발 과정의 효율성과 정확성을 구현"],"es":["Actualiza el archivo README después de cada cambio","Mantén actualizados los documentos de la API y los diagramas .puml","Aplica estándares de proyecto después de cambios en el código o la arquitectura","Actualiza la documentación cuando se agregan o modifican características","Mantén la documentación y los diagramas actualizados para una mejor colaboración"],"fr":["Mettez à jour le fichier README après chaque modification","Gardez à jour les documents d''API et les diagrammes .puml","Appliquez les normes de projet après des modifications du code ou de l''architecture","Mettez à jour la documentation lorsque des fonctionnalités sont ajoutées ou modifiées","Gardez la documentation et les diagrammes à jour pour une meilleure collaboration"],"de":["Aktualisieren Sie die README-Datei nach jeder Änderung","Halten Sie die API-Dokumente und .puml-Diagramme auf dem neuesten Stand","Wenden Sie Projektstandards an, nachdem der Code oder die Architektur geändert wurde","Aktualisieren Sie die Dokumentation, wenn Funktionen hinzugefügt oder geändert werden","Halten Sie die Dokumentation und Diagramme auf dem neuesten Stand für eine bessere Zusammenarbeit"],"pt":["Atualização de documentação em README","Atualização de diagramas em `.puml`","Gerenciamento de portfolio com análise de dados financeiros","Integração com APIs para atualizações em tempo real","Suporte a múltiplos formatos de documentação"],"ru":["Обновление документации в README","Обновление диаграмм в `.puml`","Управление портфелем с финансовым анализом данных","Интеграция с API для обновлений в реальном времени с помощью ИИ Агентов","Поддержка нескольких форматов документации"],"ar":["تحديث الوثائق في README","تحديث الرسومات في `.puml`","إدارة المحفظة مع التحليل المالي","التكامل مع واجهات البرمجة لتحديثات في الوقت الفعلي باستخدام أدوات الذكاء الاصطناعي","دعم عدة صيغ للوثائق"]},"keywords":{"en":["how to use project-standards","project-standards setup guide","project-standards alternative to manual documentation","project-standards vs financial analysis tools","what is project-standards","project-standards install for financial data analysis"],"zh":["项目标准","代码管理","API管理","架构设计","README更新","项目开发效率","AI工具","项目管理规范"],"ja":["プロジェクト標準","コード管理","API管理","建築設計","README更新","プロジェクト開発効率","AIエージェント","プロジェクト管理規範"],"ko":["프로젝트 표준","코드 관리","API 관리","아키텍처 설계","README 업데이트","프로젝트 개발 효율","AI 에이전트","프로젝트 관리 규칙"],"es":["estándares de proyecto","análisis financiero","gestión de carteras","documentación de API","diagramas .puml","colaboración en proyectos","desarrollo de software","mejores prácticas de codificación"],"fr":["normes de projet","analyse financière","gestion de portefeuille","documentation d''API","diagrammes .puml","collaboration sur les projets","développement de logiciels","meilleures pratiques de codage"],"de":["Projektstandards","Finanzdatenanalyse","Portfolio-Management","API-Dokumentation",".puml-Diagramme","Projektzusammenarbeit","Software-Entwicklung","Best Practices für Codierung"],"pt":["projeto-standards","análise de dados financeiros","gestão de portfolio","atualização de documentação","diagramas `.puml`","APIs de análise de dados","desenvolvimento de software","padronização de projetos"],"ru":["Стандарты Проектов","финансовый анализ данных","управление портфелем","обновление документации","диаграммы `.puml`","API для финансового анализа","разработка программного обеспечения","ИИ Агенты для финансового анализа"],"ar":["مواصفات المشروع","التحليل المالي","إدارة المحفظة","تحديث الوثائق","الرسومات `.puml`","واجهات البرمجة للتحليل المالي","تطوير البرمجيات","أدوات الذكاء الاصطناعي للتحليل المالي"]}},"owner":"felixzhu97","repo":"finpulse","repoPath":"felixzhu97/finpulse","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.494Z","topics":[],"category":"community","skillMd":{"name":"project-standards","description":"Keeps documentation and diagrams in sync with code changes; when API or resources change, add or update seed data using well-known real-world data. Use when editing code, adding features, refactoring, changing APIs, or when the user asks to update docs or diagrams.","bodyPreview":"# Project Standards\n\n## When to Apply\n\n- After changing code, APIs, or architecture\n- When adding or modifying features\n- When the user asks to update docs or diagrams\n\n## Update Documentation and Diagrams Promptly\n\nAfter any change that affects behavior, structure, or contracts:\n\n- **README**: Update the root README and any README in the affected area (e.g. `apps/*/README.md`, `packages/*/README.md`, `docs/**/README.md`).\n- **Code/API changes**: Update relevant API docs and any `.puml` diagrams","body":"# Project Standards\n\n## When to Apply\n\n- After changing code, APIs, or architecture\n- When adding or modifying features\n- When the user asks to update docs or diagrams\n\n## Update Documentation and Diagrams Promptly\n\nAfter any change that affects behavior, structure, or contracts:\n\n- **README**: Update the root README and any README in the affected area (e.g. `apps/*/README.md`, `packages/*/README.md`, `docs/**/README.md`).\n- **Code/API changes**: Update relevant API docs and any `.puml` diagrams under `docs/` that describe the same area.\n- **Diagrams (English and Chinese)**: When updating diagrams, update both `docs/en/` and `docs/zh/` so they stay in sync (e.g. `docs/en/rd/c4/`, `docs/zh/rd/c4/`; `docs/en/product/domain/`, `docs/zh/product/domain/`; `docs/en/rd/togaf/`, `docs/zh/rd/togaf/`; `docs/en/data/er-diagram/`, `docs/zh/data/er-diagram/`).\n- **New modules or layers**: Add or adjust C4/clean-architecture diagrams in both en and zh; keep layout in sync with code (e.g. `clean-architecture-portfolio-api.puml`).\n- **Data/DB changes**: Update `docs/en/data/er-diagram/` and `docs/zh/data/er-diagram/` and any schema or data-architecture docs.\n\nDo not leave docs or diagrams outdated; update them in the same change set when possible.\n\n## Seed Data When API Changes\n\nWhen API or resources change (new or modified endpoints, schemas, or domain entities exposed as API):\n\n1. **Add or update seed data** so local/demo can be restored with one command.\n2. **Use well-known, real-world data** only. No placeholders like `user1`, `test-xxx`, or `foo`.\n\n| Type | Use (examples) | Avoid |\n|------|----------------|-------|\n| People/customers | Warren Buffett, Ray Dalio, Carl Icahn | user1, John Doe, Test User |\n| Symbols/instruments | AAPL, MSFT, GOOGL, AMZN, NVDA, META, TSLA, JPM, SPY, QQQ | STOCK1, TEST, XXX |\n| Company names | Apple Inc., Microsoft Corporation, Alphabet Inc. | Company A, Test Corp |\n| Brokers/counterparties | Charles Schwab, Interactive Brokers, Fidelity, Vanguard | Broker1, Acme Inc |\n| Bonds | US912828VM18 (2Y Treasury), US912828XG18 (10Y) | BOND001 |\n| Options | AAPL250117C00230000 (AAPL Jan 2026 230 Call) | OPTION1 |\n\nNumeric values (prices, quantities, rates) may be fictional; identifiers, names, and codes must follow the above style.\n\n- **Script**: `scripts/seed/generate-seed-data.js`\n- **Method**: Prefer `POST /api/v1/<resource>/batch`; legacy portfolio via `POST /api/v1/seed`.\n- **Run**: From repo root `pnpm run generate-seed-data` (or via `pnpm run start:server`).\n\nFor new resources, add `postBatch(\"/api/v1/<resource>/batch\", [ ... ])` in `seedResources()` and update the final `console.log` resource count.\n\n## Checklist Before Finishing a Task\n\n- [ ] README and other docs that describe the changed area are updated\n- [ ] English and Chinese diagrams that describe the changed area are updated\n- [ ] If API/resources changed: seed data added or updated in `generate-seed-data.js` using well-known data; no placeholder names; `pnpm run generate-seed-data` succeeds (with API running)\n"},"lastSynced":"2026-03-08T02:10:11.284Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing standardized documentation and diagram updates for financial data analysis and portfolio management","zh":"非常适合需要标准化文档和金融数据分析及投资组合管理图表更新的开发代理","ja":"開発エージェントが金融データ分析およびポートフォリオ管理の標準化されたドキュメントと図の更新が必要な場合に最適","ko":"금융 데이터 분석 및 포트폴리오 관리를 위한 표준화된 문서 및 다이어그램 업데이트가 필요한 개발 에이전트에게 적합","es":"Perfecto para Agentes de Desarrollo que necesitan documentación estandarizada y actualizaciones de diagramas para análisis de datos financieros y gestión de carteras","fr":"Parfait pour les Agents de Développement ayant besoin de documentation standardisée et de mises à jour de diagrammes pour l''analyse de données financières et la gestion de portefeuille","de":"Perfekt für Entwicklungssagenten, die standardisierte Dokumentation und Diagramm-Aktualisierungen für Finanzdatenanalyse und Portfoliomanagement benötigen","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de documentação padronizada e atualizações de diagramas para análise de dados financeiros e gestão de carteira","ru":"Идеально для агентов разработки, которым необходима стандартизированная документация и обновления диаграмм для финансового анализа данных и управления портфелем","ar":"مثالي لعميل التطوير الذين يحتاجون إلى توثيق معياري وتحديثات مخططات لتحليل البيانات المالية وإدارة المحفظة"},"recommendation":{"en":"Empowers agents to maintain up-to-date README files and API documentation, ensuring consistency across code, APIs, and architecture, utilizing file formats like .puml for diagrams and markdown for README updates","zh":"赋予代理维护最新的README文件和API文档的能力，确保代码、API和架构的一致性，使用.puml等文件格式更新图表，使用markdown更新README文件","ja":"エージェントが最新のREADMEファイルとAPIドキュメントを保守できるようにし、コード、API、及びアーキテクチャ間の一貫性を確保する。.pumlなどのファイル形式を使用して図を更新し、markdownを使用してREADMEファイルを更新する","ko":"에이전트가 최신의 README 파일과 API 문서를 유지할 수 있도록 하여 코드, API, 아키텍처 간的一致성을 보장하며, .puml 등의 파일 형식을 이용하여 다이어그램을 업데이트하고 markdown를 이용하여 README 파일을 업데이트한다","es":"Habilita a los agentes para mantener archivos README y documentación de API actualizados, garantizando la coherencia en el código, las API y la arquitectura, utilizando formatos de archivo como .puml para diagramas y markdown para actualizaciones de README","fr":"Permet aux agents de maintenir des fichiers README et une documentation API à jour, en garantissant la cohérence entre le code, les API et l''architecture, en utilisant des formats de fichiers tels que .puml pour les diagrammes et markdown pour les mises à jour de README","de":"Ermächtigt Agenten, aktuelle README-Dateien und API-Dokumentationen zu pflegen, die Konsistenz über Code, APIs und Architektur hinweg sicherzustellen, unter Verwendung von Dateiformaten wie .puml für Diagramme und markdown für README-Aktualisierungen","pt":"Habilita os agentes a manter arquivos README e documentação de API atualizados, garantindo a consistência em todo o código, APIs e arquitetura, utilizando formatos de arquivo como .puml para diagramas e markdown para atualizações de README","ru":"Предоставляет агентам возможность поддерживать актуальные файлы README и документацию API, обеспечивая согласованность во всем коде, API и архитектуре, используя форматы файлов, такие как .puml для диаграмм и markdown для обновлений README","ar":"تمكّن العميل من الحفاظ على ملفات README وتوثيق API محدثة، مما يضمن الاتساق عبر جميع الشفرة وواجهات برمجة التطبيقات والهيكل، باستخدام تنسيقات الملفات مثل .puml لرسومات markdown لتحديثات README"},"useCases":{"en":["Updating documentation after code changes","Generating diagrams for modified APIs","Maintaining consistent README files across projects"],"zh":["代码更改后更新文档","为修改的API生成图表","在项目间维护一致的README文件"],"ja":["コードの変更後ドキュメントを更新する","変更されたAPIの図を生成する","プロジェクト間で一貫したREADMEファイルを保守する"],"ko":["코드 변경 후 문서를 업데이트한다","변경된 API에 대한 다이어그램을 생성한다","프로젝트 간에 일관된 README 파일을 유지한다"],"es":["Actualización de la documentación después de los cambios de código","Generación de diagramas para APIs modificadas","Mantenimiento de archivos README coherentes en todos los proyectos"],"fr":["Mise à jour de la documentation après les modifications de code","Génération de diagrammes pour les API modifiées","Maintenance de fichiers README cohérents dans tous les projets"],"de":["Aktualisierung der Dokumentation nach Code-Änderungen","Generierung von Diagrammen für modifizierte APIs","Aufrechterhaltung konsistenter README-Dateien in allen Projekten"],"pt":["Atualizar documentação após alterações de código","Gerar diagramas para APIs modificadas","Manter arquivos README consistentes em todos os projetos"],"ru":["Обновление документации после изменений кода","Генерация диаграмм для измененных API","Поддержание согласованных файлов README во всех проектах"],"ar":["تحديث التوثيق بعد تغييرات الشفرة","генерация مخططات لبرمجة تطبيقات معدلة","الحفاظ على ملفات README متسقة في جميع المشاريع"]},"limitations":{"en":["Requires access to project codebase and documentation","Limited to projects with existing README and .puml files"],"zh":["需要访问项目代码库和文档","仅限于具有现有README文件和.puml文件的项目"],"ja":["プロジェクトのコードベースとドキュメントへのアクセスが必要","既存のREADMEファイルと.pumlファイルを持つプロジェクトのみに限定"],"ko":["프로젝트 코드베이스 및 문서에 접근할 수 있어야 함","既存의 README 파일 및 .puml 파일을 갖춘 프로젝트에만 제한"],"es":["Requiere acceso a la base de código del proyecto y la documentación","Limitado a proyectos con archivos README y .puml existentes"],"fr":["Nécessite l''accès à la base de code du projet et à la documentation","Limité aux projets avec des fichiers README et .puml existants"],"de":["Benötigt Zugriff auf den Code-Stammsatz des Projekts und die Dokumentation","Begrenzt auf Projekte mit vorhandenen README- und .puml-Dateien"],"pt":["Requer acesso à base de código do projeto e documentação","Limitado a projetos com arquivos README e .puml existentes"],"ru":["Требует доступа к базе кода проекта и документации","Ограничен проектами с существующими файлами README и .puml"],"ar":["يتطلب الوصول إلى قاعدة الشفرة للمشروع والتوثيق","محدود بمشاريع ذات ملفات README و.puml موجودة"]},"version":4},"contentHash":"5514d58da608facc5796018e1a250cb543f5d5c3ac03e523669919736a933946","qualityScore":29}');
