INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('JasonRowe/Wahoo-KICKR-Randomizer/bluetooth-trainer-expert', 'bluetooth-trainer-expert', 'JasonRowe', 'Wahoo-KICKR-Randomizer', 'community', 'bluetooth-trainer-expert JasonRowe Wahoo-KICKR-Randomizer community The bluetooth-trainer-expert skill provides a workflow for developing biking fitness applications that interact with Smart Trainers. It benefits developers creating Windows apps for Wahoo KIKR and FTMS devices. 蓝牙训练师专家是一种Windows应用，用于控制Wahoo KICKR的阻力，使工作坊更加有趣。它提供了一种Console First的开发方法 Bluetooth Trainer Expertは、Wahoo KICKRの抵抗を制御してワークアウトをより楽しくするWindowsアプリケーションです。Console Firstアプローチを提供します 블루투스 트레이너 전문가는 워크샵을 더 재미있게 만들기 위해 Wahoo KICKR의 저항을 제어하는 Windows 애플리케이션입니다. Console First 개발 방법을 제공합니다 Bluetooth-trainer-expert es una herramienta para desarrolladores que permite controlar la resistencia en dispositivos Wahoo KIKR para crear aplicaciones de fitness más divertidas Bluetooth-trainer-expert est un outil pour les développeurs qui souhaite rendre leurs applications de fitness plus engageantes en contrôlant la résistance des dispositifs Wahoo KIKR Bluetooth-trainer-expert ist ein Tool für Entwickler, um die Resistenz von Wahoo-KIKR-Geräten zu steuern und eigene Fitnessanwendungen zu erstellen O Bluetooth Trainer Expert é uma aplicação Windows para controlar a resistência no Wahoo KIKR, tornando as sessões de treinamento mais divertidas ИИ Агент Bluetooth Trainer Expert - это приложение Windows для управления сопротивлением на Wahoo KIKR, делая тренировки более интересными Bluetooth Trainer Expert هو تطبيق ويندوز لتحكم في مقاومة جهاز Wahoo KIKR، مما يجعل الجلسات التدريبية أكثر متعة how to use bluetooth-trainer-expert bluetooth-trainer-expert alternative bluetooth-trainer-expert setup guide what is bluetooth-trainer-expert bluetooth-trainer-expert vs Wahoo KICKR bluetooth-trainer-expert install for Windows developing biking fitness apps with bluetooth-trainer-expert bluetooth-trainer-expert for FTMS devices Smart Trainer app development with bluetooth-trainer-expert 蓝牙训练师专家 智能训练应用开发 Wahoo KICKR Console First C# Console Application WPF/MAUI AI工具 智能训练设备 Windows应用开发 Implements a Console First approach for isolating connection and protocol logic Supports development of biking fitness applications for Wahoo KIKR and FTMS devices Utilizes C# Console Application (BikeFitnessConsole) for protocol logic testing Enables physical verification of Smart Trainer interactions Follows a proven workflow for efficient Smart Trainer app development bluetooth-trainer-expert is a Windows app skill that controls resistance on Smart Trainers, such as Wahoo KICKR, using a Console First approach for efficient development.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('yceachan/Neo-Embedded-Linux/script-manager', 'community', 'yceachan', 'Neo-Embedded-Linux', 'yceachan/Neo-Embedded-Linux', 'script-manager', 0, 0, 29, '2026-03-08T01:57:15.597Z', '2026-03-08T02:12:07.056Z', '95f5121193f4a9dace05f5ab22ab0a652f02e994e26ff303483db75f70960ff4', '{"id":"yceachan/Neo-Embedded-Linux/script-manager","name":"script-manager","description":{"en":"The script-manager skill is designed for developers working with Linux Kernel Driver development on NXP i.MX6ULL, providing an AI-assisted playbook for managing scripts in the .gemini/scripts/ directory.","zh":"脚本管理器是一个现代的 AI 辅助工具，用于掌握 Linux Kernel Driver 开发 trên NXP i.MX6ULL。","ja":"スクリプトマネージャーは、NXP i.MX6ULL 向けの Linux Kernel Driver 開発をマスターするためのモダンな AI アシストです。","ko":"스크립트 매니저는 Linux Kernel Driver 개발을 위한 현대적인 AI 지원 도구로 NXP i.MX6ULL에서 사용됩니다.","es":"script-manager es una herramienta de desarrollo de controladores de kernel de Linux para NXP i.MX6ULL. Ayuda a gestionar scripts de forma eficiente.","fr":"script-manager est un outil de développement de pilotes de kernel Linux pour NXP i.MX6ULL. Il aide à gérer les scripts de manière efficace.","de":"script-manager ist ein Entwicklungstool für Linux-Kernel-Treiber für NXP i.MX6ULL. Es hilft bei der effizienten Verwaltung von Skripten.","pt":"O Script Manager é uma ferramenta de desenvolvimento de drivers de kernel Linux que ajuda a gerenciar scripts de forma eficiente","ru":"ИИ Агент Script Manager - это инструмент для разработки драйверов ядра Linux, который помогает эффективно управлять скриптами","ar":"مدير النصوص هو أداة لتطوير برامج تشغيل النواة لينكس تساعد على إدارة النصوص بفعالية"},"seo":{"title":{"en":"script-manager: Linux Kernel Driver Development Setup Gui...","zh":"脚本管理器 Setup Guide - AIエージェント for Linux Kernel Driver","ja":"スクリプトマネージャー Best Practices - AIエージェント for NXP i.MX6ULL","ko":"스크립트 매니저 Setup Guide - AI 에이전트 for Linux Kernel Driver 개발","es":"Guía de Configuración de script-manager para Desarrollo d...","fr":"Guide d''Installation de script-manager pour le Développem...","de":"Einrichtungsleitfaden für script-manager zur Entwicklung ...","pt":"Guia de Configuração do Script Manager para Desenvolvimen...","ru":"ИИ Агент Script Manager: Руководство по Настройке для Раз...","ar":"دليل إعداد مدير النصوص للمطورين: تطوير برامج تشغيل النواة..."},"description":{"en":"Unlock efficient Linux Kernel Driver development on NXP i.MX6ULL with script-manager. Learn how to trigger and utilize this AI-assisted playbook for masterin...","zh":"了解脚本管理器的触发条件和核心工作流程，提高 Linux Kernel Driver 开发效率","ja":"スクリプトマネージャーの機能と設定方法をマスターし、NXP i.MX6ULL 開発を最適化する","ko":"스크립트 매니저의 트리거 조건과 코어 워크플로우를 파악하여 Linux Kernel Driver 개발을 개선하세요","es":"Aprende a configurar script-manager para dominar el desarrollo de controladores de kernel de Linux en NXP i.MX6ULL con esta guía paso a paso","fr":"Découvrez comment installer et utiliser script-manager pour maîtriser le développement de pilotes de kernel Linux sur NXP i.MX6ULL","de":"Erfahren Sie, wie Sie script-manager einrichten, um die Entwicklung von Linux-Kernel-Treibern auf NXP i.MX6ULL zu meistern","pt":"Aprenda a configurar o Script Manager para desenvolver drivers de kernel Linux com eficiência, incluindo trigger conditions e fluxo de trabalho core","ru":"Узнайте, как настроить ИИ Агент Script Manager для разработки драйверов ядра Linux, включая условия триггера и основной рабочий процесс","ar":"اكتشف كيفية إعداد مدير النصوص لتطوير برامج تشغيل النواة لينكس بفعالية، بما في ذلك شروط التنشيط وfluxo de trabalho core"},"definition":{"en":"script-manager is a modern AI-assisted playbook for managing and mastering Linux Kernel Driver development scripts on NXP i.MX6ULL platforms.","zh":"脚本管理器是一个 AI 辅助工具，用于管理和优化 Linux Kernel Driver 开发脚本","ja":"スクリプトマネージャーは、Linux Kernel Driver 開発用のスクリプトを管理・最適化する AI アシストです","ko":"스크립트 매니저는 Linux Kernel Driver 개발 스크립트를 관리 및 최적화하는 AI 에이전트입니다","es":"script-manager es una herramienta de desarrollo asistida por IA para controladores de kernel de Linux","fr":"script-manager est un outil de développement de pilotes de kernel Linux assisté par l''IA","de":"script-manager ist ein Entwicklungstool für Linux-Kernel-Treiber mit KI-Unterstützung","pt":"O Script Manager é uma ferramenta de desenvolvimento que gerencia scripts de kernel Linux","ru":"ИИ Агент Script Manager - это инструмент для разработки, который управляет скриптами ядра Linux","ar":"مدير النصوص هو أداة تطوير تدير النصوص لبرامج تشغيل النواة لينكس"},"features":{"en":["Triggers on script saves, creations, or moves into .gemini/scripts/ directory","Supports explicit indexing and registration of scripts","Ignores temporary or one-off debugging scripts unless explicitly requested","Confirms script location in .gemini/scripts/ directory","Activates on permanent or high-value script identification"],"zh":["触发条件：脚本保存、创建或移动到 `.gemini/scripts/`","核心工作流程：识别、索引和注册脚本","支持 NXP i.MX6ULL 平台","优化 Linux Kernel Driver 开发效率","AI 辅助脚本管理"],"ja":["トリガー条件：スクリプトの保存、作成、または `.gemini/scripts/` への移動","コアワークフロー：スクリプトの識別、索引、登録","NXP i.MX6ULL プラットフォームのサポート","Linux Kernel Driver 開発の効率化","AI アシストによるスクリプト管理"],"ko":["트리거 조건：스크립트 저장, 생성 또는 `.gemini/scripts/`로 이동","코어 워크플로우：스크립트 식별, 색인 및 등록","NXP i.MX6ULL 플랫폼 지원","Linux Kernel Driver 개발 효율화","AI 에이전트를 통한 스크립트 관리"],"es":["Identificación de scripts permanentes o de alto valor","Indexación de scripts en `.gemini/scripts/`","Registro explícito de scripts","Soporte para desarrollo de controladores de kernel de Linux en NXP i.MX6ULL","Gestión eficiente de scripts"],"fr":["Identification de scripts permanents ou de haute valeur","Indexation de scripts dans `.gemini/scripts/`","Enregistrement explicite de scripts","Prise en charge du développement de pilotes de kernel Linux sur NXP i.MX6ULL","Gestion efficace de scripts"],"de":["Identifizierung von permanenten oder hochwertigen Skripten","Indexierung von Skripten in `.gemini/scripts/`","Explizite Registrierung von Skripten","Unterstützung für die Entwicklung von Linux-Kernel-Treibern auf NXP i.MX6ULL","Effiziente Skriptverwaltung"],"pt":["Trigger conditions para scripts permanentes ou de alto valor","Fluxo de trabalho core para identificar e gerenciar scripts","Compatibilidade com desenvolvimento de drivers de kernel Linux","Suporte a scripts em `.gemini/scripts/`","Capacidade de registrar scripts explicitamente"],"ru":["Условия триггера для постоянных или высокоценных скриптов","Основной рабочий процесс для идентификации и управления скриптами","Совместимость с разработкой драйверов ядра Linux","Поддержка скриптов в `.gemini/scripts/`","Возможность explicitного регистрации скриптов"],"ar":["شروط التنشيط للنصوص الدائمة أو القيمة العالية","fluxo de trabalho core لتحديد وإدارة النصوص","التوافق مع تطوير برامج تشغيل النواة لينكس","دعم النصوص في `.gemini/scripts/`","القدرة على تسجيل النصوص بشكل صريح"]},"keywords":{"en":["how to use script-manager","script-manager for Linux Kernel Driver development","NXP i.MX6ULL script management","script-manager setup guide","script-manager alternative","script-manager vs manual scripting","script-manager install","what is script-manager","script-manager tutorial"],"zh":["Linux Kernel Driver 开发","NXP i.MX6ULL","AI 辅助工具","脚本管理器","脚本优化","开发效率","AI エージェント"],"ja":["Linux Kernel Driver 開発","NXP i.MX6ULL","AI アシスト","スクリプトマネージャー","スクリプト最適化","開発効率","AI エージェント"],"ko":["Linux Kernel Driver 개발","NXP i.MX6ULL","AI 에이전트","스크립트 매니저","스크립트 최적화","개발 효율","AI 도구"],"es":["desarrollo de controladores de kernel de Linux","NXP i.MX6ULL","herramientas de desarrollo de controladores","gestión de scripts","IA para desarrollo de controladores","script-manager","desarrollo de software embebido","controladores de kernel de Linux","desarrollo de sistemas operativos"],"fr":["développement de pilotes de kernel Linux","NXP i.MX6ULL","outils de développement de pilotes","gestion de scripts","IA pour le développement de pilotes","script-manager","développement de logiciels embarqués","pilotes de kernel Linux","développement de systèmes d''exploitation"],"de":["Entwicklung von Linux-Kernel-Treibern","NXP i.MX6ULL","Entwicklungstools für Treiber","Skriptverwaltung","KI für die Entwicklung von Treibern","script-manager","Entwicklung von Embedded-Software","Linux-Kernel-Treiber","Entwicklung von Betriebssystemen"],"pt":["desenvolvimento de drivers de kernel linux","script manager","ferramenta de desenvolvimento","gerenciamento de scripts","trigger conditions","fluxo de trabalho core","desenvolvimento de software","linux kernel","nxa i.mx6ull"],"ru":["разработка драйверов ядра linux","ии агент script manager","инструмент для разработки","управление скриптами","условия триггера","основной рабочий процесс","разработка программного обеспечения","ядра linux","nxa i.mx6ull"],"ar":["تطوير برامج تشغيل النواة لينكس","مدير النصوص","أداة تطوير","إدارة النصوص","شروط التنشيط","fluxo de trabalho core","تطوير البرمجيات","نواة لينكس","nxa i.mx6ull"]}},"owner":"yceachan","repo":"Neo-Embedded-Linux","repoPath":"yceachan/Neo-Embedded-Linux","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.597Z","topics":[],"category":"community","skillMd":{"name":"script-manager","description":"Automates the registration and indexing of high-value Python scripts in the projects script library.","bodyPreview":"# Script Manager Skill\r\n\r\n## 1. Trigger Conditions (When to use)\r\n\r\n*   **Active**: When the Agent saves, creates, or moves a \"permanent\" or \"high-value\" script into `.gemini/scripts/`.\r\n*   **Passive**: When the user explicitly asks to \"index scripts\" or \"register this script\".\r\n*   **Negative**: Do *not* trigger for temporary, throwaway, or one-off debugging scripts unless explicitly requested.\r\n\r\n## 2. Core Workflow\r\n1.  **Identify**: Confirm the script is located in (or being written to) `.g","body":"# Script Manager Skill\r\n\r\n## 1. Trigger Conditions (When to use)\r\n\r\n*   **Active**: When the Agent saves, creates, or moves a \"permanent\" or \"high-value\" script into `.gemini/scripts/`.\r\n*   **Passive**: When the user explicitly asks to \"index scripts\" or \"register this script\".\r\n*   **Negative**: Do *not* trigger for temporary, throwaway, or one-off debugging scripts unless explicitly requested.\r\n\r\n## 2. Core Workflow\r\n1.  **Identify**: Confirm the script is located in (or being written to) `.gemini/scripts/`.\r\n2.  **Validate**: Ensure the script has a docstring describing its purpose.\r\n3.  **Register**: Update `.gemini/scripts/GEMINI.md`.\r\n    *   If the file doesn''t exist, create it.\r\n    *   Add a row to the \"Registered Scripts\" table.\r\n\r\n## 3. Index Format (`.gemini/scripts/GEMINI.md`)\r\n\r\nThe index file must contain a table with the following columns:\r\n\r\n| Script Name | Function | Usage Example | Tags |\r\n| :--- | :--- | :--- | :--- |\r\n| `example_script.py` | Brief description of what it does. | `python .gemini/scripts/example.py --arg` | `pdf`, `extraction` |\r\n\r\n## 4. Instructions for Agent\r\n*   **Consistency**: Always check existing tags and try to reuse them (e.g., `pdf`, `parsing`, `validation`).\r\n*   **Brevity**: Keep descriptions under 15 words.\r\n*   **Verification**: After updating the index, verify the entry is correct.\r\n"},"lastSynced":"2026-03-08T02:12:07.056Z","agentAnalysis":{"suitability":{"en":"Ideal for Linux Kernel Driver development agents requiring automated script management on NXP i.MX6ULL","zh":"适用于需要在NXP i.MX6ULL上进行自动化脚本管理的Linux内核驱动开发代理","ja":"NXP i.MX6ULLで自動化スクリプト管理を必要とするLinuxカーネルドライバ開発エージェントに適しています","ko":"NXP i.MX6ULL에서 자동화된 스크립트 관리가 필요한 리눅스 커널 드라이버 개발 에이전트에 적합합니다","es":"Ideal para agentes de desarrollo de controladores de kernel de Linux que requieren una gestión de scripts automatizada en NXP i.MX6ULL","fr":"Idéal pour les agents de développement de pilotes de noyau Linux nécessitant une gestion de scripts automatisée sur NXP i.MX6ULL","de":"Ideal für Linux-Kernel-Treiber-Entwicklungsagenten, die eine automatisierte Skriptverwaltung auf NXP i.MX6ULL benötigen","pt":"Ideal para agentes de desenvolvimento de driver do kernel Linux que exigem gerenciamento de scripts automatizado no NXP i.MX6ULL","ru":"Идеально подходит для агентов разработки драйверов ядра Linux, требующих автоматизированного управления скриптами на NXP i.MX6ULL","ar":"مثالي للوكلاء الذين يطورون برنامج تشغيل نواة لينكس والذين يحتاجون إلى إدارة سكريبتات أوتوماتيكية على NXP i.MX6ULL"},"recommendation":{"en":"Empowers agents to efficiently manage scripts in the .gemini/scripts/ directory, providing AI-assisted playbooks for saving, creating, or moving high-value scripts, and indexing or registering scripts on demand, utilizing trigger conditions for active, passive, and negative script handling","zh":"赋予代理高效管理.gemini/scripts/目录中的脚本的能力，提供AI辅助的playbook以保存、创建或移动高价值脚本，并在需要时索引或注册脚本，利用触发条件进行主动、被动和负面脚本处理","ja":"エージェントが.gemini/scripts/ディレクトリ内のスクリプトを効率的に管理できるようにし、高価値スクリプトの保存、作成、または移動のためのAIアシストプレイブックを提供し、需要に応じてスクリプトの索引付けまたは登録を行い、アクティブ、パッシブ、ネガティブスクリプトハンドリングのためのトリガ条件を利用する","ko":"에이전트가 .gemini/scripts/ 디렉토리 내의 스크립트를 효율적으로 관리할 수 있도록 하며, 고가치 스크립트를 저장, 생성 또는 이동하기 위한 AI 지원 플레이북을 제공하며, 필요에 따라 스크립트의 색인 또는 등록을 수행하며, 활성, 수동 및 부정적인 스크립트 처리를 위한 트리거 조건을 활용한다","es":"Habilita a los agentes a gestionar eficientemente los scripts en el directorio .gemini/scripts/, proporcionando libros de juego asistidos por IA para guardar, crear o mover scripts de alto valor, e indexar o registrar scripts a demanda, utilizando condiciones de activación para el manejo de scripts activos, pasivos y negativos","fr":"Permet aux agents de gérer efficacement les scripts dans le répertoire .gemini/scripts/, en fournissant des livres de jeu assistés par l''IA pour enregistrer, créer ou déplacer des scripts à haute valeur, et indexer ou enregistrer des scripts à la demande, en utilisant des conditions de déclenchement pour la gestion de scripts actifs, passifs et négatifs","de":"Ermächtigt Agenten, Skripte im .gemini/scripts/-Verzeichnis effizient zu verwalten, indem es AI-unterstützte Playbooks für das Speichern, Erstellen oder Verschieben von Skripten mit hohem Wert bereitstellt und Skripte auf Abruf indiziert oder registriert, unter Verwendung von Triggerbedingungen für die Verarbeitung von aktiven, passiven und negativen Skripten","pt":"Habilita os agentes a gerenciar eficientemente os scripts no diretório .gemini/scripts/, fornecendo playbooks assistidos por IA para salvar, criar ou mover scripts de alto valor e indexar ou registrar scripts sob demanda, utilizando condições de gatilho para manipulação de scripts ativos, passivos e negativos","ru":"Наделяет агентов возможностью эффективно управлять скриптами в директории .gemini/scripts/, предоставляя плейбуки, помогающие ИИ сохранять, создавать или перемещать скрипты высокого значения и индексировать или регистрировать скрипты по требованию, используя условия триггера для активной, пассивной и негативной обработки скриптов","ar":"تمكّن الوكلاء من إدارة السكريبتات بفعالية في الدليل .gemini/scripts/، وتقديم كتب ألعاب مدعومة بالذكاء الاصطناعي لحفظ أو إنشاء أو نقل سكريبتات قيمة عالية وتسجيلها أو فهرستها عند الطلب، باستخدام شروط تريكر لمعالجة السكريبتات الفعالة والسلبية والايجابية"},"useCases":{"en":["Automating script registration for permanent scripts","Indexing high-value scripts in .gemini/scripts/","Managing script workflows for Linux Kernel Driver development on NXP i.MX6ULL"],"zh":["自动化永久脚本的注册","在.gemini/scripts/中索引高价值脚本","在NXP i.MX6ULL上管理Linux内核驱动开发的脚本工作流"],"ja":["恒久的なスクリプトの登録を自動化する",".gemini/scripts/内で高価値スクリプトを索引する","NXP i.MX6ULL上のLinuxカーネルドライバ開発のスクリプトワークフローを管理する"],"ko":["영구적인 스크립트의 등록을 자동화하는 것",".gemini/scripts/ 내에서 고가치 스크립트를 색인하는 것","NXP i.MX6ULL上的 리눅스 커널 드라이버 개발의 스크립트 워크플로우를 관리하는 것"],"es":["Automatización del registro de scripts para scripts permanentes","Indexación de scripts de alto valor en .gemini/scripts/","Gestión de flujos de trabajo de scripts para el desarrollo de controladores de kernel de Linux en NXP i.MX6ULL"],"fr":["Automatisation de l''enregistrement de scripts pour les scripts permanents","Indexation de scripts à haute valeur dans .gemini/scripts/","Gestion des flux de travail de scripts pour le développement de pilotes de noyau Linux sur NXP i.MX6ULL"],"de":["Automatisierung der Registrierung von Skripten für permanente Skripte","Indexierung von Skripten mit hohem Wert in .gemini/scripts/","Verwaltung von Skript-Workflows für die Entwicklung von Linux-Kernel-Treibern auf NXP i.MX6ULL"],"pt":["Automatizar o registro de scripts para scripts permanentes","Indexar scripts de alto valor em .gemini/scripts/","Gerenciar fluxos de trabalho de scripts para desenvolvimento de driver do kernel Linux no NXP i.MX6ULL"],"ru":["Автоматизировать регистрацию скриптов для постоянных скриптов","Индексировать скрипты высокого значения в .gemini/scripts/","Управлять рабочими процессами скриптов для разработки драйверов ядра Linux на NXP i.MX6ULL"],"ar":["تأتمتة تسجيل السكريبتات للسكريبتات الدائمة","فهرسة سكريبتات قيمة عالية في .gemini/scripts/","إدارة تدفقات العمل للسكريبتات لتطوير برنامج تشغيل نواة لينكس على NXP i.MX6ULL"]},"limitations":{"en":["Requires access to .gemini/scripts/ directory","Limited to Linux Kernel Driver development on NXP i.MX6ULL","Excludes temporary or throwaway scripts unless explicitly requested"],"zh":[".gemini/scripts/目录的访问是必需的","仅限于NXP i.MX6ULL上的Linux内核驱动开发","除非明确请求，否则排除临时或一次性脚本"],"ja":[".gemini/scripts/ディレクトリへのアクセスが必要","NXP i.MX6ULL上のLinuxカーネルドライバ開発のみ","明示的に要求しない限り、一時的または使い捨てのスクリプトは除外する"],"ko":[".gemini/scripts/ 디렉토리에 대한 액세스가 필요하다","NXP i.MX6ULL上的 리눅스 커널 드라이버 개발만 해당한다","명시적으로 요청하지 않는 한 임시 또는 일회용 스크립트는 제외한다"],"es":["Requiere acceso al directorio .gemini/scripts/","Limitado al desarrollo de controladores de kernel de Linux en NXP i.MX6ULL","Excluye scripts temporales o descartables a menos que se solicite explícitamente"],"fr":["Nécessite un accès au répertoire .gemini/scripts/","Limité au développement de pilotes de noyau Linux sur NXP i.MX6ULL","Exclut les scripts temporaires ou jetables à moins qu''ils ne soient explicitement demandés"],"de":["Erfordert Zugriff auf das .gemini/scripts/-Verzeichnis","Begrenzt auf die Entwicklung von Linux-Kernel-Treibern auf NXP i.MX6ULL","Schließt temporäre oder wegwerfbare Skripte aus, es sei denn, sie werden explizit angefordert"],"pt":["Exige acesso ao diretório .gemini/scripts/","Limitado ao desenvolvimento de driver do kernel Linux no NXP i.MX6ULL","Exclui scripts temporários ou descartáveis, a menos que explicitamente solicitados"],"ru":["Требует доступа к директории .gemini/scripts/","Ограничен разработкой драйверов ядра Linux на NXP i.MX6ULL","Исключает временные или одноразовые скрипты, если не явно запрошено"],"ar":["يتطلب الوصول إلى الدليل .gemini/scripts/","محدود بتطوير برنامج تشغيل نواة لينكس على NXP i.MX6ULL","استبعاد السكريبتات المؤقتة أو القابلة للرمي، trừ إذا تم الطلب صراحة"]},"version":4},"contentHash":"95f5121193f4a9dace05f5ab22ab0a652f02e994e26ff303483db75f70960ff4","qualityScore":29}');
