INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('yceachan/Neo-Embedded-Linux/script-manager', 'script-manager', 'yceachan', 'Neo-Embedded-Linux', 'community', 'script-manager yceachan Neo-Embedded-Linux community The script-manager skill is designed for developers working with Linux Kernel Driver development on NXP i.MX6ULL, providing an AI-assisted playbook for managing scripts in the .gemini/scripts/ directory. 脚本管理器是一个现代的 AI 辅助工具，用于掌握 Linux Kernel Driver 开发 trên NXP i.MX6ULL。 スクリプトマネージャーは、NXP i.MX6ULL 向けの Linux Kernel Driver 開発をマスターするためのモダンな AI アシストです。 스크립트 매니저는 Linux Kernel Driver 개발을 위한 현대적인 AI 지원 도구로 NXP i.MX6ULL에서 사용됩니다. script-manager es una herramienta de desarrollo de controladores de kernel de Linux para NXP i.MX6ULL. Ayuda a gestionar scripts de forma eficiente. script-manager est un outil de développement de pilotes de kernel Linux pour NXP i.MX6ULL. Il aide à gérer les scripts de manière efficace. script-manager ist ein Entwicklungstool für Linux-Kernel-Treiber für NXP i.MX6ULL. Es hilft bei der effizienten Verwaltung von Skripten. O Script Manager é uma ferramenta de desenvolvimento de drivers de kernel Linux que ajuda a gerenciar scripts de forma eficiente ИИ Агент Script Manager - это инструмент для разработки драйверов ядра Linux, который помогает эффективно управлять скриптами مدير النصوص هو أداة لتطوير برامج تشغيل النواة لينكس تساعد على إدارة النصوص بفعالية how to use script-manager script-manager for Linux Kernel Driver development NXP i.MX6ULL script management script-manager setup guide script-manager alternative script-manager vs manual scripting script-manager install what is script-manager script-manager tutorial Linux Kernel Driver 开发 NXP i.MX6ULL AI 辅助工具 脚本管理器 脚本优化 开发效率 AI エージェント Triggers on script saves, creations, or moves into .gemini/scripts/ directory Supports explicit indexing and registration of scripts Ignores temporary or one-off debugging scripts unless explicitly requested Confirms script location in .gemini/scripts/ directory Activates on permanent or high-value script identification script-manager is a modern AI-assisted playbook for managing and mastering Linux Kernel Driver development scripts on NXP i.MX6ULL platforms.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('johncegom/position-size-calculator/consultancy-mode', 'community', 'johncegom', 'position-size-calculator', 'johncegom/position-size-calculator', 'consultancy-mode', 0, 0, 29, '2026-03-08T01:57:15.602Z', '2026-03-08T02:13:06.045Z', '82397976d9c55f00f08fe0b15d5ca792ad50a5941a206ac031c5bf78ae40ab22', '{"id":"johncegom/position-size-calculator/consultancy-mode","name":"consultancy-mode","description":{"en":"Consultancy-mode is an AI agent skill that calculates position size for trade orders, recommended for future orders and volume management. It transforms the agent into a code consultant, providing observation-only functionality.","zh":"Consultancy Mode 是一种将 Agent 转变为代码顾问的技能，通过特定的激活关键词和核心指令，帮助开发者优化代码开发流程","ja":"Consultancy Mode はエージェントをコードコンサルタントに変えるスキルで、特定のキーワードとコア指令を使用してコード開発プロセスを最適化します","ko":"Consultancy Mode는 에이전트를 코드 컨설턴트로 변환하는 스킬로, 특정 키워드와 코어 지침을 사용하여 코드 개발 프로세스를 최적화합니다","es":"El modo consultoría es una herramienta para calcular el tamaño de posición para órdenes de comercio y gestionar volúmenes. Se recomienda su uso para órdenes futuras.","fr":"Le mode consultatif est un outil pour calculer la taille de position pour les ordres de trading et gérer les volumes. Il est recommandé pour les ordres futurs.","de":"Der Code-Beratungsmodus ist ein Tool zum Berechnen der Positiongröße für Handelsaufträge und zur Verwaltung von Volumina. Er wird für zukünftige Aufträge empfohlen.","pt":"O modo de consultoria é uma habilidade que transforma o agente em um consultor de código, fornecendo orientação para calcular o tamanho da posição para pedidos de negociação.","ru":"Консультационный режим - это навык, который превращает агента в кодового консультанта, предоставляя рекомендации для расчета размера позиции для торговых ордеров.","ar":"نمط الاستشارة هو مهارة تحول العامل إلى مستشار код، تقدم إرشادات لحساب حجم المركز لطلبات التداول."},"seo":{"title":{"en":"Consultancy-Mode: Code Consultation Setup Guide | AI Agen...","zh":"AI工具 Consultancy Mode 设置指南","ja":"AIエージェント Consultancy Mode のベストプラクティス","ko":"AI 에이전트 Consultancy Mode 구축 가이드","es":"Configuración de Consultoría de Código: Guía de Implement...","fr":"Mode Consultatif: Guide de Mise en Place pour les Dévelop...","de":"Code-Beratungsmodus: Einrichtungsanleitung für Entwickler","pt":"Guia de Configuração do Modo de Consultoria para Ferramen...","ru":"Настройка консультационного режима для ИИ Агентов: лучшие...","ar":"إعداد نمط الاستشارة لأدوات الذكاء الاصطناعي: دليل المستخدم"},"description":{"en":"Unlock expert code consultation with consultancy-mode. Learn how to activate and use this AI agent skill for observation-only mode, transforming your agent i...","zh":"了解 Consultancy Mode 的激活关键词和核心指令，优化您的代码开发流程","ja":"Consultancy Mode の活用方法を学び、コードの開発効率を上げる","ko":"Consultancy Mode의 기능과 활용 방법을 익히고 개발 생산성을 높이세요","es":"Aprende a configurar el modo consultoría para calcular el tamaño de posición para órdenes de comercio y gestionar volúmenes de forma efectiva con nuestra guí...","fr":"Découvrez comment configurer le mode consultatif pour calculer la taille de position pour les ordres de trading et gérer les volumes de manière efficace avec...","de":"Erfahren Sie, wie Sie den Code-Beratungsmodus konfigurieren, um die Positiongröße für Handelsaufträge zu berechnen und Volumina effektiv zu verwalten, mit un...","pt":"Aprenda a configurar o modo de consultoria para calcular o tamanho da posição para pedidos de negociação e gerenciar volumes com ferramentas de inteligência ...","ru":"Узнайте, как настроить консультационный режим для расчета размера позиции для торговых ордеров и управления объемами с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد نمط الاستشارة لحساب حجم المركز لطلبات التداول وإدارة الحجوم باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"Consultancy-mode is an AI agent skill that enables observation-only mode, where the agent acts as a code consultant, providing code examples without implementation.","zh":"Consultancy Mode 是一种 AI 工具技能，通过特定的激活关键词和核心指令，提供代码开发咨询","ja":"Consultancy Mode は、特定のキーワードとコア指令を使用してコード開発コンサルティングを提供する AI エージェントのスキル","ko":"Consultancy Mode는 특정 키워드와 코어 지침을 사용하여 코드 개발 컨설팅을 제공하는 AI 에이전트의 스킬","es":"El modo consultoría es un modo de operación que transforma al agente en un consultor de código en lugar de un implementador automatizado","fr":"Le mode consultatif est un mode de fonctionnement qui transforme l''agent en un consultant de code plutôt qu''en un implementateur automatique","de":"Der Code-Beratungsmodus ist ein Betriebsmodus, der den Agenten in einen Code-Berater statt in einen automatischen Implementierer umwandelt","pt":"O modo de consultoria é uma habilidade que fornece orientação para calcular o tamanho da posição para pedidos de negociação sem implementar código.","ru":"Консультационный режим - это навык, который предоставляет рекомендации для расчета размера позиции для торговых ордеров без реализации кода.","ar":"نمط الاستشارة هو مهارة تقدم إرشادات لحساب حجم المركز لطلبات التداول دون تنفيذ الكود."},"features":{"en":["Activates observation-only mode using keywords like ''DO NOT IMPLEMENT'' and ''JUST PUT CODE HERE''","Enforces strict file locking, preventing use of ''write_to_file'', ''replace_file_content'', and ''multi_replace_file_content'' commands","Supports code consultation for trade order management","Provides example code for position size calculation","Transforms the agent into a ''Code Consultant'' rather than an ''Automated Implementer''","Prevents state modification while active"],"zh":["激活关键词：DO NOT IMPLEMENT、JUST PUT CODE HERE、CODE ONLY、EXAMPLE ONLY、HOW WOULD I…","核心指令：严格文件锁定，禁止使用 write_to_file、replace_file_content 或 multi_replace_file_content","代码开发咨询","开发流程优化","代码效率提升"],"ja":["Activation Keywords: DO NOT IMPLEMENT、JUST PUT CODE HERE、CODE ONLY、EXAMPLE ONLY、HOW WOULD I…","コア指令：厳格なファイルロック、write_to_file、replace_file_content、multi_replace_file_content を禁止","コード開発コンサルティング","開発プロセスの最適化","コード効率の向上"],"ko":["활성화 키워드: DO NOT IMPLEMENT、JUST PUT CODE HERE、CODE ONLY、EXAMPLE ONLY、HOW WOULD I…","코어 지침: 엄격한 파일 잠금, write_to_file、replace_file_content 또는 multi_replace_file_content 사용 금지","코드 개발 컨설팅","개발 프로세스 최적화","코드 효율성 향상"],"es":["Cálculo de tamaño de posición para órdenes de comercio","Gestión de volúmenes de forma efectiva","Uso de palabras clave de activación como ''DO NOT IMPLEMENT'' y ''CODE ONLY''","Bloqueo estricto de archivos para evitar modificaciones","Compatibilidad con órdenes futuras"],"fr":["Calcul de la taille de position pour les ordres de trading","Gestion des volumes de manière efficace","Utilisation de mots-clés d''activation tels que ''DO NOT IMPLEMENT'' et ''CODE ONLY''","Verrouillage strict des fichiers pour éviter les modifications","Compatibilité avec les ordres futurs"],"de":["Berechnung der Positiongröße für Handelsaufträge","Effektive Verwaltung von Volumina","Verwendung von Aktivierungsschlüsselwörtern wie ''DO NOT IMPLEMENT'' und ''CODE ONLY''","Strenges Dateisperren, um Änderungen zu vermeiden","Kompatibilität mit zukünftigen Aufträgen"],"pt":["Transformação do agente em um consultor de código","Cálculo do tamanho da posição para pedidos de negociação","Gerenciamento de volumes","Uso de palavras-chave de ativação como ''DO NOT IMPLEMENT'' e ''JUST PUT CODE HERE''","Restrição de modificação de arquivos com ''Strict File Locking''","Compatibilidade com tecnologias como CLI"],"ru":["Преобразование агента в кодового консультанта","Расчет размера позиции для торговых ордеров","Управление объемами","Использование ключевых слов активации, таких как ''DO NOT IMPLEMENT'' и ''JUST PUT CODE HERE''","Ограничение модификации файлов с помощью ''Strict File Locking''","Совместимость с технологиями, такими как CLI"],"ar":["تحويل العامل إلى مستشار код","حساب حجم المركز لطلبات التداول","إدارة الحجوم","استخدام كلمات مفتاح التنشيط مثل ''DO NOT IMPLEMENT'' و ''JUST PUT CODE HERE''","تحديد تعديل الملفات باستخدام ''Strict File Locking''","التوافق مع التكنولوجيا مثل CLI"]},"keywords":{"en":["how to use consultancy-mode","what is consultancy-mode","consultancy-mode alternative","consultancy-mode vs automated implementer","consultancy-mode install","consultancy-mode setup guide","code consultation for trade orders","observation-only mode for AI agents","strict file locking in consultancy-mode"],"zh":["AI 工具 Consultancy Mode","代码开发咨询","开发流程优化","代码效率提升","激活关键词","核心指令","严格文件锁定"],"ja":["AI エージェント Consultancy Mode","コード開発コンサルティング","開発プロセスの最適化","コード効率の向上","Activation Keywords","コア指令","厳格なファイルロック"],"ko":["AI 에이전트 Consultancy Mode","코드 개발 컨설팅","개발 프로세스 최적화","코드 효율성 향상","활성화 키워드","코어 지침","엄격한 파일 잠금"],"es":["modo consultoría","cálculo de tamaño de posición","gestión de volúmenes","herramientas de comercio","desarrollo de software","agente de código","consultor de código","programación de trading","automatización de comercio"],"fr":["mode consultatif","calcul de la taille de position","gestion des volumes","outils de trading","développement de logiciels","agent de code","consultant de code","programmation de trading","automatisation de trading"],"de":["Code-Beratungsmodus","Berechnung der Positiongröße","Verwaltung von Volumina","Handelstools","Softwareentwicklung","Code-Agent","Code-Berater","Trading-Programmierung","Handelsautomatisierung"],"pt":["ferramentas de inteligência artificial","modo de consultoria","cálculo do tamanho da posição","gerenciamento de volumes","CLI","consultor de código","palavras-chave de ativação","restrição de modificação de arquivos"," Strict File Locking"],"ru":["ИИ Агенты","консультационный режим","расчет размера позиции","управление объемами","CLI","кодовый консультант","ключевые слова активации","ограничение модификации файлов","Strict File Locking"],"ar":["أدوات الذكاء الاصطناعي","نمط الاستشارة","حساب حجم المركز","إدارة الحجوم","CLI","مستشار کد","كلمات مفتاح التنشيط","تحديد تعديل الملفات","Strict File Locking"]}},"owner":"johncegom","repo":"position-size-calculator","repoPath":"johncegom/position-size-calculator","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.602Z","topics":[],"category":"community","skillMd":{"name":"consultancy-mode","description":"This skill triggers when the user explicitly requests code examples, logic analysis, or architectural advice without wanting the files to be modified. Use this when phrases like DO NOT IMPLEMENT or JUST CODE are present.","bodyPreview":"# 🧠 Consultancy Mode (Observation Only)\n\nWhen this skill is active, the Agent transforms into a \"Code Consultant\" rather than an \"Automated Implementer.\"\n\n## 🚦 Activation Keywords\n\n- \"DO NOT IMPLEMENT\"\n- \"JUST PUT CODE HERE\"\n- \"CODE ONLY\"\n- \"EXAMPLE ONLY\"\n- \"HOW WOULD I...\"\n\n## 📜 Core Instructions\n\n1. **Strict File Locking**:\n   - **NEVER** use `write_to_file`, `replace_file_content`, or `multi_replace_file_content` while this mode is active.\n   - **NEVER** run commands that modify the state","body":"# 🧠 Consultancy Mode (Observation Only)\n\nWhen this skill is active, the Agent transforms into a \"Code Consultant\" rather than an \"Automated Implementer.\"\n\n## 🚦 Activation Keywords\n\n- \"DO NOT IMPLEMENT\"\n- \"JUST PUT CODE HERE\"\n- \"CODE ONLY\"\n- \"EXAMPLE ONLY\"\n- \"HOW WOULD I...\"\n\n## 📜 Core Instructions\n\n1. **Strict File Locking**:\n   - **NEVER** use `write_to_file`, `replace_file_content`, or `multi_replace_file_content` while this mode is active.\n   - **NEVER** run commands that modify the state (e.g., `git commit`, `npm install`).\n\n2. **Analysis Workflow**:\n   - Use `grep_search`, `view_file`, and `list_dir` to gather context from the current repository.\n   - Identify the best integration points (files and line numbers) but do **NOT** modify them.\n\n3. **Output Format**:\n   - Provide complete, copy-pasteable code blocks in the chat.\n   - Use clear markdown headers to separate different components or logic parts.\n   - Include comments explaining _where_ and _why_ specific changes should be made.\n\n4. **Integration Guide**:\n   - Always provide a brief \"Manual Integration Guide\" at the end of the response, explaining the steps the USER needs to take to implement the code themselves.\n\n5. **Exiting Mode**:\n   - This mode is session-based or request-based. Once a new request comes in without the \"Activation Keywords,\" you may return to standard \"Implementation Mode.\"\n"},"lastSynced":"2026-03-08T02:13:06.045Z","agentAnalysis":{"suitability":{"en":"Ideal for Autonomous Agents requiring strategic trade order management and observation-only consultancy capabilities.","zh":"适合需要战略性交易订单管理和仅观察咨询功能的自主代理。","ja":"戦略的な取引注文管理と観察のみのコンサルタント機能を必要とする自律エージェントに適しています。","ko":"전략적인 거래 주문 관리와 관찰 전용 상담 기능을 필요로 하는 자율 에이전트에 적합합니다.","es":"Ideal para Agentes Autónomos que requieren gestión estratégica de órdenes de comercio y capacidades de consultoría de solo observación.","fr":"Idéal pour les Agents Autonomes nécessitant une gestion stratégique des ordres de commerce et des capacités de consultation en lecture seule.","de":"Ideal für autonome Agenten, die eine strategische Handelsauftragsverwaltung und Beobachtungs-Only-Beratungsfunktionen erfordern.","pt":"Ideal para Agentes Autônomos que exigem gestão estratégica de ordens de negociação e capacidades de consultoria somente de observação.","ru":"Идеально подходит для автономных агентов, требующих стратегического управления торговыми ордерами и возможностей консультационных услуг только для наблюдения.","ar":"مثالي للوكلاء المستقلين الذين يتطلبون إدارة استراتيجية لأوامر التداول وقدرات استشارة ملاحظة فقط."},"recommendation":{"en":"Empowers agents to calculate position sizes for trade orders, providing recommended volumes for future orders while ensuring strict file locking and observation-only functionality, utilizing activation keywords like ''DO NOT IMPLEMENT'' and ''CODE ONLY'' to transform into a ''Code Consultant'' role.","zh":"赋予代理计算交易注单的位置大小，并为未来注单提供推荐的交易量，同时确保严格的文件锁定和仅观察功能，利用激活关键词如 ''DO NOT IMPLEMENT'' 和 ''CODE ONLY'' 转变为 ''Code Consultant'' 角色。","ja":"エージェントに取引注文のポジションサイズを計算する機能を与え、将来の注文に推奨されるボリュームを提供し、厳格なファイルロックと観察のみの機能を保証することで、''DO NOT IMPLEMENT'' や ''CODE ONLY'' などのアクティベーションキーワードを使用して ''Code Consultant'' ロールに変換する。","ko":"에이전트로 하여금 거래 주문의 위치 크기를 계산하도록 하며, 향후 주문을 위한 추천 볼륨을 제공하고, 엄격한 파일 잠금 및 관찰 전용 기능을 보장하며, ''DO NOT IMPLEMENT'' 및 ''CODE ONLY''와 같은 활성화 키워드를 사용하여 ''Code Consultant'' 역할로 변환합니다.","es":"Habilita a los agentes a calcular tamaños de posición para órdenes de comercio, proporcionando volúmenes recomendados para órdenes futuras mientras garantiza una estricta bloqueo de archivos y funcionalidad de solo observación, utilizando palabras clave de activación como ''NO IMPLEMENTAR'' y ''CÓDIGO SOLO'' para transformarse en un papel de ''Consultor de Código''.","fr":"Permet aux agents de calculer les tailles de position pour les ordres de commerce, en fournissant des volumes recommandés pour les ordres futurs tout en assurant une fonctionnalité de blocage de fichiers strict et en lecture seule, en utilisant des mots clés d''activation comme ''NE PAS METTRE EN ŒUVRE'' et ''CODE SEULEMENT'' pour se transformer en un rôle de ''Consultant de Code''.","de":"Ermächtigt Agenten, Positionsgroessen für Handelsaufträge zu berechnen und empfohlene Volumina für zukünftige Aufträge bereitzustellen, während sie eine strikte Dateisperre und Beobachtungs-Only-Funktionalität gewährleisten, wobei Aktivierungsschlüsselwörter wie ''NICHT IMPLEMENTIEREN'' und ''NUR CODE'' verwendet werden, um in eine ''Code-Berater''-Rolle umzuwandeln.","pt":"Permite que os agentes calculem tamanhos de posição para ordens de negociação, fornecendo volumes recomendados para ordens futuras, garantindo uma funcionalidade de bloqueio de arquivo estrito e somente de observação, utilizando palavras-chave de ativação como ''NÃO IMPLEMENTAR'' e ''CÓDIGO APENAS'' para se transformar em um papel de ''Consultor de Código''.","ru":"Наделяет агентов возможностью рассчитывать размеры позиций для торговых ордеров, предоставляя рекомендуемые объемы для будущих ордеров, обеспечивая строгое блокирование файлов и функциональность только для наблюдения, используя ключевые слова активации, такие как ''НЕ РЕАЛИЗОВЫВАТЬ'' и ''ТОЛЬКО КОД'', для преобразования в роль ''Консультант кода''.","ar":"يمكن للوكلاء حساب أحجام المراكز لطلبات التداول، وتوفير الحجوم الموصى بها لطلبات المستقبل، مع ضمان وظيفة قفل الملفات الصارمة وظيفة الملاحظة فقط، باستخدام كلمات مفتاح التنشيط مثل ''لا تنفذ'' و ''الكود فقط'' للتحول إلى دور ''استشاري الكود''."},"useCases":{"en":["Calculating optimal position sizes for trade orders","Providing observation-only functionality for code consultancy","Managing volume for future orders with strict file locking"],"zh":["计算交易注单的最佳位置大小","提供仅观察功能的代码咨询","使用严格的文件锁定管理未来订单的交易量"],"ja":["取引注文の最適なポジションサイズを計算する","コードコンサルタント機能の観察のみ機能を提供する","厳格なファイルロックを使用して将来の注文のボリュームを管理する"],"ko":["거래 주문에 대한 최적의 위치 크기 계산","코드 상담 기능을 위한 관찰 전용 기능 제공","엄격한 파일 잠금을 사용하여 미래의 주문에 대한 볼륨 관리"],"es":["Calcular tamaños de posición óptimos para órdenes de comercio","Proporcionar funcionalidad de solo observación para consultoría de código","Gestionar volumen para órdenes futuras con bloqueo de archivos estricto"],"fr":["Calculer les tailles de position optimales pour les ordres de commerce","Fournir une fonctionnalité en lecture seule pour la consultation de code","Gérer le volume pour les ordres futurs avec un verrouillage de fichiers strict"],"de":["Optimale Positionsgroessen für Handelsaufträge berechnen","Beobachtungs-Only-Funktionalität für Code-Beratung bereitstellen","Volumen für zukünftige Aufträge mit strikter Dateisperre verwalten"],"pt":["Calculando tamanhos de posição ótimos para ordens de negociação","Fornecendo funcionalidade somente de observação para consultoria de código","Gerenciando volume para ordens futuras com bloqueio de arquivo estrito"],"ru":["Рассчитывание оптимальных размеров позиций для торговых ордеров","Предоставление функциональности только для наблюдения для консультационных услуг кода","Управление объемом для будущих ордеров со строгим блокированием файлов"],"ar":["حساب أحجام المراكز المثالية لطلبات التداول","توفير وظيفة الملاحظة فقط لاستشارة الكود","إدارة الحجم لطلبات المستقبل مع قفل الملفات الصارم"]},"limitations":{"en":["Requires strict adherence to observation-only functionality","Never uses write_to_file, replace_file_content, or multi_replace_file_content","Does not modify state or run commands that alter it"],"zh":["需要严格遵守仅观察功能","永远不会使用 write_to_file、replace_file_content 或 multi_replace_file_content","不会修改状态或运行修改它的命令"],"ja":["観察のみの機能に厳格に従う必要がある","write_to_file、replace_file_content、または multi_replace_file_content を使用しない","状態を変更したり、それを変更するコマンドを実行しない"],"ko":["관찰 전용 기능을 엄격히遵守해야 함","write_to_file, replace_file_content 또는 multi_replace_file_content를 사용하지 않음","상태를 수정하거나 그것을 수정하는 명령을 실행하지 않음"],"es":["Requiere una estricta adherencia a la funcionalidad de solo observación","Nunca utiliza write_to_file, replace_file_content o multi_replace_file_content","No modifica el estado ni ejecuta comandos que lo alteren"],"fr":["Nécessite une adhésion stricte à la fonctionnalité en lecture seule","N''utilise jamais write_to_file, replace_file_content ou multi_replace_file_content","Ne modifie pas l''état ni exécute des commandes qui le modifient"],"de":["Erfordert eine strikte Einhaltung der Beobachtungs-Only-Funktionalität","Verwendet niemals write_to_file, replace_file_content oder multi_replace_file_content","Ändert den Zustand nicht und führt keine Befehle aus, die ihn ändern"],"pt":["Exige adesão estrita à funcionalidade somente de observação","Nunca usa write_to_file, replace_file_content ou multi_replace_file_content","Não modifica o estado ou executa comandos que o alterem"],"ru":["Требует строгого соблюдения функциональности только для наблюдения","Никогда не использует write_to_file, replace_file_content или multi_replace_file_content","Не изменяет состояние или выполняет команды, которые его изменяют"],"ar":["يتطلب اتباع صارم لوظيفة الملاحظة فقط","لا يستخدم jamais write_to_file، replace_file_content أو multi_replace_file_content","لا يغير الحالة أو ينفذ أوامر التي تغيرها"]},"version":4},"contentHash":"82397976d9c55f00f08fe0b15d5ca792ad50a5941a206ac031c5bf78ae40ab22","qualityScore":29}');
