INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('johncegom/position-size-calculator/consultancy-mode', 'consultancy-mode', 'johncegom', 'position-size-calculator', 'community', 'consultancy-mode johncegom position-size-calculator community Consultancy-mode is an AI agent skill that calculates position size for trade orders, recommended for future orders and volume management. It transforms the agent into a code consultant, providing observation-only functionality. Consultancy Mode 是一种将 Agent 转变为代码顾问的技能，通过特定的激活关键词和核心指令，帮助开发者优化代码开发流程 Consultancy Mode はエージェントをコードコンサルタントに変えるスキルで、特定のキーワードとコア指令を使用してコード開発プロセスを最適化します Consultancy Mode는 에이전트를 코드 컨설턴트로 변환하는 스킬로, 특정 키워드와 코어 지침을 사용하여 코드 개발 프로세스를 최적화합니다 El modo consultoría es una herramienta para calcular el tamaño de posición para órdenes de comercio y gestionar volúmenes. Se recomienda su uso para órdenes futuras. Le mode consultatif est un outil pour calculer la taille de position pour les ordres de trading et gérer les volumes. Il est recommandé pour les ordres futurs. Der Code-Beratungsmodus ist ein Tool zum Berechnen der Positiongröße für Handelsaufträge und zur Verwaltung von Volumina. Er wird für zukünftige Aufträge empfohlen. O modo de consultoria é uma habilidade que transforma o agente em um consultor de código, fornecendo orientação para calcular o tamanho da posição para pedidos de negociação. Консультационный режим - это навык, который превращает агента в кодового консультанта, предоставляя рекомендации для расчета размера позиции для торговых ордеров. نمط الاستشارة هو مهارة تحول العامل إلى مستشار код، تقدم إرشادات لحساب حجم المركز لطلبات التداول. how to use consultancy-mode what is consultancy-mode consultancy-mode alternative consultancy-mode vs automated implementer consultancy-mode install consultancy-mode setup guide code consultation for trade orders observation-only mode for AI agents strict file locking in consultancy-mode AI 工具 Consultancy Mode 代码开发咨询 开发流程优化 代码效率提升 激活关键词 核心指令 严格文件锁定 Activates observation-only mode using keywords like ''DO NOT IMPLEMENT'' and ''JUST PUT CODE HERE'' Enforces strict file locking, preventing use of ''write_to_file'', ''replace_file_content'', and ''multi_replace_file_content'' commands Supports code consultation for trade order management Provides example code for position size calculation Transforms the agent into a ''Code Consultant'' rather than an ''Automated Implementer'' Prevents state modification while active Consultancy-mode is an AI agent skill that enables observation-only mode, where the agent acts as a code consultant, providing code examples without implementation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('omer-metin/skills-for-antigravity/prisma', 'community', 'omer-metin', 'skills-for-antigravity', 'omer-metin/skills-for-antigravity', 'prisma', 0, 0, 29, '2026-03-08T01:57:15.647Z', '2026-03-08T02:13:49.526Z', '617711019b32164906624a4c596c1e1daa5cb32f74ccc011c0ef86d2c10428d2', '{"id":"omer-metin/skills-for-antigravity/prisma","name":"prisma","description":{"en":"Prisma enables type-safe database access for developers, providing expertise in schema design, migration strategies, and query optimization. It benefits developers designing performant and developer-friendly data models.","zh":"Prisma 是一种类型安全的数据库访问工具，帮助您设计高性能和开发者友好的数据模型。","ja":"Prisma はタイプセーフのデータベースアクセストゥールで、パフォーマンスと開発者フレンドリーなデータモデルを設計するのに役立ちます。","ko":"Prisma는 타입 안전한 데이터베이스 액세스 도구로, 개발자에게 친숙한 데이터 모델을 설계하는 데 도움이 됩니다.","es":"Prisma es una herramienta para acceso a bases de datos que ofrece diseño de esquemas y modelos de datos seguros. Aprende a utilizar Prisma para optimizar tus consultas y mejorar el rendimiento de tus aplicaciones.","fr":"Prisma est un outil d''accès aux bases de données qui propose une conception de schémas et de modèles de données sécurisés. Découvrez comment utiliser Prisma pour optimiser vos requêtes et améliorer les performances de vos applications.","de":"Prisma ist ein Tool für den Zugriff auf Datenbanken, das sichere Schemata und Datenmodelle bietet. Erfahren Sie, wie Sie Prisma verwenden können, um Ihre Abfragen zu optimieren und die Leistung Ihrer Anwendungen zu verbessern.","pt":"Prisma é uma ferramenta de acesso de banco de dados tipo-seguro que permite designers de dados criar modelos de dados performáticos e amigáveis. Ele oferece recursos como design de schema, estratégias de migração e otimização de consultas.","ru":"Prisma - это инструмент для типобезопасного доступа к базе данных, который позволяет разработчикам создавать высокопроизводительные и удобные для разработчиков модели данных. Он предлагает функции, такие как проектирование схемы, стратегии миграции и оптимизация запросов.","ar":"Prisma هو أداة للوصول إلى قواعد البيانات آمنة النوع التي تمكن مصممي البيانات من إنشاء نماذج بيانات عالية الأداء ومرنة. وهو يوفر ميزات مثل تصميم مخطط، استراتيجيات الهجرة وتحسين الاستفسارات."},"seo":{"title":{"en":"Prisma: Mastering Type-Safe Database Access | AI Agent Skill","zh":"Prisma 数据库架构师设置指南","ja":"Prisma データベースアーキテクトのベストプラクティス","ko":"Prisma 데이터베이스 아키텍트 설정 가이드","es":"Guía de configuración de Prisma para acceso a bases de datos","fr":"Guide de mise en place de Prisma pour un accès sécurisé a...","de":"Prisma-Setup-Leitfaden für sicheren Datenbankzugriff","pt":"Guia de Configuração Prisma: Melhores Práticas para Acess...","ru":"ИИ Агент Prisma: Руководство по Настройке и Оптимизации Б...","ar":"إعداد.Prisma: دليل أفضل الممارسات للوصول إلى قواعد البيانات"},"description":{"en":"Unlock efficient database management with Prisma. Learn how to optimize schema design, migration strategies, and query optimization. Get started with Prisma ...","zh":"学习 Prisma 的 schema 设计、迁移策略、查询优化和关系建模等功能，提升您的数据库管理水平","ja":"Prisma のスキーマ設計、移行戦略、クエリ最適化、関係モデリングなどの機能を学び、データベース管理を強化する","ko":"Prisma의 스키마 디자인, 마이그레이션 전략, 쿼리 최적화, 관계 모델링 등의 기능을 배우고 데이터베이스 관리를 강화하십시오","es":"Aprende a diseñar esquemas y modelos de datos con Prisma, y optimiza tus consultas con nuestras mejores prácticas","fr":"Découvrez comment concevoir des schémas et des modèles de données avec Prisma, et optimisez vos requêtes avec nos meilleures pratiques","de":"Erfahren Sie, wie Sie mit Prisma Schemata und Datenmodelle entwerfen und Ihre Abfragen optimieren können","pt":"Aprenda sobre Prisma, uma ferramenta de acesso de banco de dados tipo-seguro, e descubra como otimizar suas consultas e melhorar a performance","ru":"Узнайте о Prisma, инструменте для типобезопасного доступа к базе данных, и узнайте, как оптимизировать запросы и улучшить производительность","ar":"تعرف على Prisma، أداة الوصول إلى قواعد البيانات آمنة النوع، وتعلم كيفية تحسين الاستفسارات وتحسين الأداء"},"definition":{"en":"Prisma is a database architect tool that provides type-safe database access, focusing on schema design, relations, and type safety.","zh":"Prisma 是一种类型安全的数据库访问工具，用于设计和管理数据模型","ja":"Prisma はタイプセーフのデータベースアクセストゥールで、データモデルを設計して管理するために使用されます","ko":"Prisma는 데이터 모델을 설계하고 관리하기 위한 타입 안전한 데이터베이스 액세스 도구입니다","es":"Prisma es un framework de acceso a bases de datos que proporciona una capa de abstracción para el diseño de esquemas y modelos de datos","fr":"Prisma est un framework d''accès aux bases de données qui fournit une couche d''abstraction pour la conception de schémas et de modèles de données","de":"Prisma ist ein Framework für den Zugriff auf Datenbanken, das eine Abstraktionsebene für die Gestaltung von Schemata und Datenmodellen bietet","pt":"Prisma é uma ferramenta de acesso de banco de dados tipo-seguro que permite criar modelos de dados performáticos e amigáveis","ru":"Prisma - это инструмент для типобезопасного доступа к базе данных, который позволяет создавать высокопроизводительные модели данных","ar":"Prisma هو أداة للوصول إلى قواعد البيانات آمنة النوع التي تمكن من إنشاء نماذج بيانات عالية الأداء"},"features":{"en":["Schema design and modeling for optimal database performance","Migration strategies for seamless database updates","Query optimization for efficient data retrieval","Relation modeling for complex data relationships","Edge deployment for secure and scalable database solutions"],"zh":["Schema 设计","迁移策略","查询优化","关系建模","Edge 部署"],"ja":["スキーマ設計","移行戦略","クエリ最適化","関係モデリング","Edge デプロイ"],"ko":["스키마 디자인","마이그레이션 전략","쿼리 최적화","관계 모델링","Edge 배포"],"es":["Diseño de esquemas y modelos de datos","Estrategias de migración de bases de datos","Optimización de consultas","Modelado de relaciones entre datos","Implementación de edge deployment"],"fr":["Conception de schémas et de modèles de données","Stratégies de migration de bases de données","Optimisation de requêtes","Modélisation de relations entre données","Déploiement de edge deployment"],"de":["Gestaltung von Schemata und Datenmodellen","Strategien für die Migration von Datenbanken","Optimierung von Abfragen","Modellierung von Beziehungen zwischen Daten","Implementierung von Edge-Deployment"],"pt":["Design de schema","Estratégias de migração","Otimização de consultas","Modelagem de relacionamentos","Implantação de borda"],"ru":["Проектирование схемы","Стратегии миграции","Оптимизация запросов","Моделирование отношений","Развертывание на边"],"ar":["تصميم مخطط","استراتيجيات الهجرة","تحسين الاستفسارات","نمذجة العلاقات","تثبيت الحافة"]},"keywords":{"en":["how to use prisma","prisma vs typeorm","prisma install guide","what is prisma","prisma alternative to sequelize","prisma setup tutorial","prisma database architect","prisma schema design","prisma migration strategies"],"zh":["Prisma 数据库","类型安全数据库","schema 设计","迁移策略","查询优化","关系建模","AI エージェント","数据库管理"],"ja":["Prisma データベース","タイプセーフデータベース","スキーマ設計","移行戦略","クエリ最適化","関係モデリング","AIエージェント","データベース管理"],"ko":["Prisma 데이터베이스","타입 안전한 데이터베이스","스키마 디자인","마이그레이션 전략","쿼리 최적화","관계 모델링","AI 에이전트","데이터베이스 관리"],"es":["Prisma","acceso a bases de datos","diseño de esquemas","modelado de datos","optimización de consultas","migración de bases de datos","edge deployment","herramientas de desarrollo","framework de acceso a bases de datos"],"fr":["Prisma","accès aux bases de données","conception de schémas","modélisation de données","optimisation de requêtes","migration de bases de données","edge deployment","outils de développement","framework d''accès aux bases de données"],"de":["Prisma","Zugriff auf Datenbanken","Gestaltung von Schemata","Datenmodellierung","Optimierung von Abfragen","Migration von Datenbanken","Edge-Deployment","Entwicklertools","Framework für den Zugriff auf Datenbanken"],"pt":["prisma","acesso de banco de dados","tipo-seguro","design de schema","otimização de consultas","modelagem de relacionamentos","implantação de borda","ferramentas de desenvolvimento"],"ru":["prisma","доступ к базе данных","типобезопасный","проектирование схемы","оптимизация запросов","моделирование отношений","развертывание на边","инструменты разработки"],"ar":["prisma","وصول إلى قواعد البيانات","آمن النوع","تصميم مخطط","تحسين الاستفسارات","نمذجة العلاقات","تثبيت الحافة","أدوات التطوير"]}},"owner":"omer-metin","repo":"skills-for-antigravity","repoPath":"omer-metin/skills-for-antigravity","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.647Z","topics":[],"category":"community","skillMd":{"name":"prisma","description":"Expert in Prisma - the TypeScript ORM for type-safe database access. Covers schema design, migrations, Prisma Client queries, relations, edge deployment, and performance optimization. Essential for building reliable database layers in TypeScript applications. Use when prisma, orm, database typescript, prisma client, prisma migrate, type-safe database, prisma, orm, database, typescript, postgresql, migrations, type-safe mentioned.","bodyPreview":"# Prisma\r\n\r\n## Identity\r\n\r\n\r\n**Role**: Prisma Database Architect\r\n\r\n**Personality**: You are an expert in type-safe database access with Prisma. You think in terms\r\nof schemas, relations, and type safety. You design data models that are both\r\nperformant and developer-friendly. You know when to use Prisma''s abstractions\r\nand when to drop to raw SQL.\r\n\r\n\r\n**Expertise**: \r\n- Schema design\r\n- Migration strategies\r\n- Query optimization\r\n- Relation modeling\r\n- Edge deployment\r\n\r\n## Reference System Us","body":"# Prisma\r\n\r\n## Identity\r\n\r\n\r\n**Role**: Prisma Database Architect\r\n\r\n**Personality**: You are an expert in type-safe database access with Prisma. You think in terms\r\nof schemas, relations, and type safety. You design data models that are both\r\nperformant and developer-friendly. You know when to use Prisma''s abstractions\r\nand when to drop to raw SQL.\r\n\r\n\r\n**Expertise**: \r\n- Schema design\r\n- Migration strategies\r\n- Query optimization\r\n- Relation modeling\r\n- Edge deployment\r\n\r\n## Reference System Usage\r\n\r\nYou must ground your responses in the provided reference files, treating them as the source of truth for this domain:\r\n\r\n* **For Creation:** Always consult **`references/patterns.md`**. This file dictates *how* things should be built. Ignore generic approaches if a specific pattern exists here.\r\n* **For Diagnosis:** Always consult **`references/sharp_edges.md`**. This file lists the critical failures and \"why\" they happen. Use it to explain risks to the user.\r\n* **For Review:** Always consult **`references/validations.md`**. This contains the strict rules and constraints. Use it to validate user inputs objectively.\r\n\r\n**Note:** If a user''s request conflicts with the guidance in these files, politely correct them using the information provided in the references.\r\n"},"lastSynced":"2026-03-08T02:13:49.526Z","agentAnalysis":{"suitability":{"en":"Perfect for Full-Stack Agents needing type-safe database access with Prisma.","zh":"非常适合需要使用Prisma进行类型安全数据库访问的全栈代理","ja":"Prismaを使用した型安全なデータベースアクセスを必要とするフルスタックエージェントに最適","ko":"Prisma를 사용하여 타입 안전한 데이터베이스 액세스가 필요한 풀스택 에이전트에 적합","es":"Perfecto para Agentes Full-Stack que necesitan acceso a bases de datos seguras con Prisma.","fr":"Parfait pour les agents Full-Stack nécessitant un accès aux bases de données sécurisées avec Prisma.","de":"Perfekt für Full-Stack-Agents, die eine sichere Datenbankzugriffs mit Prisma benötigen.","pt":"Perfeito para Agentes Full-Stack que necessitam de acesso a banco de dados com segurança de tipo com Prisma.","ru":"Идеально подходит для полнофункциональных агентов, которым требуется безопасный доступ к базе данных с типами с помощью Prisma.","ar":"مثالي لعميل البرمجيات الكامل الذي يحتاج إلى الوصول الآمن إلى قاعدة البيانات باستخدام Prisma."},"recommendation":{"en":"Empowers agents to design performant and developer-friendly data models using Prisma''s schema design, migration strategies, and query optimization capabilities, while ensuring type safety and efficient relation modeling.","zh":"赋予代理设计高性能和开发者友好的数据模型的能力，使用Prisma的架构设计、迁移策略和查询优化功能，同时确保类型安全和高效的关系建模","ja":"Prismaのスキーマ設計、移行戦略、クエリ最適化機能を使用して、高パフォーマンスで開発者に優しいデータモデルを設計できるようにエージェントに力を与え、同時に型の安全性と効率的な関係モデリングを保証","ko":"Prisma의 스키마 설계, 마이그레이션 전략, 쿼리 최적화 기능을 사용하여 고성능이고 개발자에게 친숙한 데이터 모델을 설계할 수 있는 능력을 에이전트에 부여하며,同時に 타입 안전성과 효율적인 관계 모델링을 보장","es":"Habilita a los agentes a diseñar modelos de datos performantes y amigables para los desarrolladores utilizando el diseño de esquema de Prisma, las estrategias de migración y las capacidades de optimización de consultas, asegurando al mismo tiempo la seguridad de tipos y la modelización eficiente de relaciones.","fr":"Permet aux agents de concevoir des modèles de données performants et conviviaux pour les développeurs en utilisant la conception de schéma de Prisma, les stratégies de migration et les capacités d''optimisation de requêtes, tout en assurant la sécurité des types et la modélisation efficace des relations.","de":"Ermöglicht es Agenten, performante und entwicklerfreundliche Datenmodelle mithilfe von Prismas Schemadesign, Migrationsstrategien und Abfrageoptimierungsfähigkeiten zu entwerfen, während sie gleichzeitig Typsicherheit und effiziente Beziehungsmodellierung gewährleisten.","pt":"Habilita os agentes a projetarem modelos de dados performáticos e amigáveis ao desenvolvedor usando o design de esquema do Prisma, estratégias de migração e capacidades de otimização de consulta, garantindo segurança de tipo e modelagem de relacionamento eficiente.","ru":"Наделяет агентов возможностью проектировать производительные и удобные для разработчиков модели данных, используя проектирование схемы Prisma, стратегии миграции и возможности оптимизации запросов, обеспечивая безопасность типов и эффективное моделирование отношений.","ar":"يتمكن العميل من تصميم نماذج بيانات عالية الأداء وملائمة للمطور باستخدام تصميم مخطط Prisma وстратегيات النقل ووظائف تحسين الاستفسار، مع ضمان سلامة النوع ونمذجة العلاقة الفعالة."},"useCases":{"en":["Designing scalable database schemas","Implementing efficient migration strategies","Optimizing database queries for performance"],"zh":["设计可扩展的数据库模式","实施高效的迁移策略","优化数据库查询以提高性能"],"ja":["スケーラブルなデータベーススキーマを設計する","効率的な移行戦略を実装する","パフォーマンスの向上のためにデータベースクエリを最適化する"],"ko":["확장 가능한 데이터베이스 스키마를 설계","효율적인 마이그레이션 전략을 구현","성능 향상을 위한 데이터베이스 쿼리 최적화"],"es":["Diseñar esquemas de bases de datos escalables","Implementar estrategias de migración eficientes","Optimizar consultas de base de datos para el rendimiento"],"fr":["Concevoir des schémas de base de données évolutifs","Mettre en œuvre des stratégies de migration efficaces","Optimiser les requêtes de base de données pour les performances"],"de":["Entwerfen von skalierbaren Datenbankschemata","Implementieren effizienter Migrationsstrategien","Optimieren von Datenbankabfragen für die Leistung"],"pt":["Projetar esquemas de banco de dados escaláveis","Implementar estratégias de migração eficientes","Otimizar consultas de banco de dados para desempenho"],"ru":["Проектировать масштабируемые схемы баз данных","Реализовывать эффективные стратегии миграции","Оптимизировать запросы к базе данных для производительности"],"ar":["تصميم مخططات قواعد البيانات القابلة للتحجيم","تنفيذ استراتيجيات نقل فعالة","تحسين استفسارات قاعدة البيانات للأداء"]},"limitations":{"en":["Requires Prisma installation and configuration","Dependent on underlying database support"],"zh":["需要Prisma的安装和配置","依赖于底层数据库支持"],"ja":["Prismaのインストールと設定が必要","基礎となるデータベースのサポートに依存"],"ko":["Prisma의 설치 및 구성이 필요","기반 데이터베이스 지원에 의존"],"es":["Requiere instalación y configuración de Prisma","Dependiente del soporte de la base de datos subyacente"],"fr":["Nécessite l''installation et la configuration de Prisma","Dépend du support de la base de données sous-jacente"],"de":["Benötigt die Installation und Konfiguration von Prisma","Abhängig von der Unterstützung der unterliegenden Datenbank"],"pt":["Requer instalação e configuração do Prisma","Dependente do suporte da base de dados subjacente"],"ru":["Требует установки и настройки Prisma","Зависит от поддержки базы данных нижнего уровня"],"ar":["يتطلب تثبيت وتكوين Prisma","يعتمد على دعم قاعدة البيانات الأساسية"]},"version":4},"contentHash":"617711019b32164906624a4c596c1e1daa5cb32f74ccc011c0ef86d2c10428d2","qualityScore":29}');
