INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('foxzool/open-lark/openlark-code-standards', 'openlark-code-standards', 'foxzool', 'open-lark', 'community', 'openlark-code-standards foxzool open-lark community feishu feishu-bot feishu-sdk lark lark-bot lark-sdk rust The openlark-code-standards skill provides a Rust SDK for Feishu, supporting custom bots, cloud documents, and more, benefiting developers and teams working with OpenLark. OpenLark 代码规范检查 Skill 是一个用于检查 Rust SDK 代码规范的工具，支持自定义机器人、长连接机器人等 API 调用 OpenLark コード規約チェック AIエージェントは、Rust SDK コードの規約をチェックするツールで、カスタムボット、ロングポーリングボットなど API 呼び出しをサポートします OpenLark 코드 표준 검사 Skill은 Rust SDK 코드의 규약을 확인하는 도구로, 커스텀 봇, 롱 폴링 봇 등 API 호출을 지원합니다 OpenLark Code Standards es un conjunto de reglas para garantizar la calidad del código en proyectos que utilizan el SDK de Rust de Feishu OpenLark Code Standards est un ensemble de règles pour assurer la qualité du code dans les projets utilisant le SDK Rust de Feishu OpenLark Code Standards ist eine Sammlung von Regeln, um die Code-Qualität in Projekten zu gewährleisten, die das Rust-SDK von Feishu verwenden O OpenLark Code Standards é uma ferramenta que ajuda a garantir a consistência do código Rust, verificando a conformidade com as regras de codificação OpenLark Code Standards - это инструмент, который помогает обеспечить согласованность кода на Rust, проверяя соответствие правилам кодирования معايير كود مفتوح لارك هي أداة تساعد على ضمان الاتساق في الكود الرست، من خلال التحقق من مطابقة القواعد البرمجية how to use openlark-code-standards openlark-code-standards setup guide openlark-code-standards vs feishu sdk feishu bot development with rust openlark code standards install rust sdk for feishu open platform OpenLark 代码规范检查 Rust SDK 代码检查 飞书开放平台 自定义机器人 长连接机器人 云文档 飞书卡片 消息 群组 API 调用 Supports API calls for custom bots, long connection bots, and cloud documents Checks code standards for OpenLark core, client, docs, and communication crates Provides a minimum check list for new API implementations Outputs detailed check results with risk levels (P0/P1/P2) and evidence Allows for customizable check ranges, including specific crates or directories openlark-code-standards is an unofficial Rust SDK for the Feishu open platform, enabling standardized API calls and code checks.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('lanasdev/lanasdev/content-modeling-best-practices', 'community', 'lanasdev', 'lanasdev', 'lanasdev/lanasdev', 'content-modeling-best-practices', 1, 0, 28, '2026-02-26T11:18:19Z', '2026-03-06T07:15:59.487Z', '71acacfd0acbc2c0bd22f77bac3fc082d5a8efa26923f22f5c905dce8b4affa1', '{"id":"lanasdev/lanasdev/content-modeling-best-practices","name":"content-modeling-best-practices","description":{"en":"Content-modeling-best-practices helps developers design structured content for headless CMS, including NextJS and Sanity. It benefits web developers and portfolio creators.","zh":"内容建模最佳实践提供了设计结构化内容的原则，适用于Next.js和Sanity，帮助您创建灵活、可重用和可维护的内容","ja":"コンテンツモデル링ベストプラクティスは、構造化コンテンツを設計するための原則を提供し、Next.jsとSanityに対応して、柔軟で再利用可能でメンテナンスが容易なコンテンツを作成するのに役立ちます","ko":"콘텐츠 모델링 최선의 관행은 구조화된 콘텐츠를 설계하는 원칙을 제공하며 Next.js 및 Sanity에 해당하여 유연하고 재사용 가능하며 유지 관리가 쉬운 콘텐츠를 생성하는 데 도움이 됩니다","es":"Mejores prácticas para modelar contenido flexible y reusable en proyectos web con NextJS","fr":"Principes de modélisation de contenu pour des contenus flexibles et réutilisables dans les projets web avec NextJS","de":"Prinzipien für die Modellierung von flexiblen und wiederverwendbaren Inhalten in Webprojekten mit NextJS","pt":"Descubra as melhores práticas para modelagem de conteúdo estruturado e flexível para projetos web com NextJS e Sanity.","ru":"Узнайте о лучших практиках для моделирования структурированного контента для веб-проектов с NextJS и Sanity ИИ Агентов.","ar":"تعرف على أفضل الممارسات لتصميم المحتوى المنظم المرن لأدوات NextJS و Sanity الذكاء الاصطناعي في مشاريع الويب."},"seo":{"title":{"en":"Content-Modeling-Best-Practices: Structured Content Setup...","zh":"内容建模最佳实践设置指南 - AIエージェント","ja":"コンテンツモデル링ベストプラクティス設定ガイド - AIエージェント","ko":"콘텐츠 모델링 최선의 관행 설정 가이드 - AI 에이전트","es":"Guía de mejores prácticas para modelado de contenido con ...","fr":"Meilleures pratiques de modélisation de contenu pour les ...","de":"Leitfaden für Content-Modellierung-Best-Practices mit NextJS","pt":"Melhores Práticas de Modelagem de Conteúdo: Guia de Confi...","ru":"Лучшие практики моделирования контента: Руководство по на...","ar":"أفضل الممارسات لتصميم المحتوى: دليل الإعداد لأدوات الذكاء..."},"description":{"en":"Discover how to design flexible, reusable, and maintainable content models with Sanity-specific implementation notes. Learn best practices now!","zh":"学习内容建模最佳实践，设计灵活、可重用和可维护的结构化内容，适用于Next.js和Sanity","ja":"コンテンツモデル링ベストプラクティスを学び、柔軟で再利用可能でメンテナンスが容易な構造化コンテンツを設計する、Next.jsとSanity対応","ko":"콘텐츠 모델링 최선의 관행을 학습하고 유연하고 재사용 가능하며 유지 관리가 쉬운 구조화 된 콘텐츠를 설계하는 방법, Next.js 및 Sanity対応","es":"Aprende a diseñar contenido estructurado y flexible con nuestras mejores prácticas de modelado de contenido para desarrolladores web","fr":"Découvrez les meilleures pratiques de modélisation de contenu pour créer un contenu structuré et flexible pour les développeurs web","de":"Erfahren Sie, wie Sie strukturierten und flexiblen Inhalt mit unseren Best-Practices für Content-Modellierung für Web-Entwickler erstellen","pt":"Aprenda a projetar conteúdo estruturado flexível e reutilizável com as melhores práticas de modelagem de conteúdo para NextJS e Sanity","ru":"Изучите, как проектировать структурированный контент с помощью лучших практик моделирования контента для NextJS и Sanity ИИ Агентов","ar":"تعرف على كيفية تصميم المحتوى المنظم المرن و قابل لإعادة الاستخدام مع أفضل الممارسات لتصميم المحتوى لأدوات NextJS و Sanity الذكاء الاصطناعي"},"definition":{"en":"content-modeling-best-practices is a set of principles for designing structured content that''s flexible, reusable, and maintainable for headless CMS and web development","zh":"内容建模最佳实践是设计结构化内容的原则，帮助开发者创建灵活、可重用和可维护的内容","ja":"コンテンツモデル링ベストプラクティスは、構造化コンテンツを設計するための原則であり、開発者が柔軟で再利用可能でメンテナンスが容易なコンテンツを作成するのに役立ちます","ko":"콘텐츠 모델링 최선의 관행은 구조화된 콘텐츠를 설계하는 원칙으로開発자가 유연하고 재사용 가능하며 유지 관리가 쉬운 콘텐츠를 생성하는 데 도움이 됩니다","es":"El modelado de contenido es el proceso de diseñar estructuras de contenido flexibles y reutilizables","fr":"La modélisation de contenu est le processus de conception de structures de contenu flexibles et réutilisables","de":"Die Content-Modellierung ist der Prozess der Erstellung flexibler und wiederverwendbarer Inhaltsstrukturen","pt":"Modelagem de conteúdo é a prática de projetar conteúdo estruturado para ser flexível e reutilizável em diferentes canais.","ru":"Моделирование контента - это практика проектирования структурированного контента для того, чтобы он был гибким и повторно используемым в разных каналах ИИ Агентов.","ar":"تصميم المحتوى هو ممارسة تصميم المحتوى المنظم ليكون مرنًا وقابلًا لإعادة الاستخدام في قنوات مختلفة لأدوات الذكاء الاصطناعي."},"features":{"en":["Provides guidelines for starting new projects with structured content","Offers implementation notes specific to Sanity headless CMS","Helps decide between references and embedded content for multi-channel delivery","Supports planning for refactoring existing content models","Applies to various web development frameworks, including NextJS"],"zh":["设计灵活、可重用和可维护的结构化内容","适用于Next.js和Sanity","提供内容模型设计的原则","帮助开发者创建多渠道内容","支持内容重构"],"ja":["柔軟で再利用可能でメンテナンスが容易な構造化コンテンツを設計","Next.jsとSanityに対応","コンテンツモデル設計の原則を提供","開発者がマルチチャネルコンテンツを作成するのを支援","コンテンツリファクタリングをサポート"],"ko":["유연하고 재사용 가능하며 유지 관리가 쉬운 구조화된 콘텐츠를 설계","Next.js 및 Sanity에 해당","콘텐츠 모델 설계의 원칙을 제공","개발자가 멀티 채널 콘텐츠를 생성하는 것을 지원","콘텐츠 리팩토링을 지원"],"es":["Diseño de contenido estructurado con NextJS","Creación de contenido flexible y reusable","Implementación de referencias y contenido incrustado","Planificación de entrega de contenido multi-canal","Refactorización de contenido existente"],"fr":["Conception de contenu structuré avec NextJS","Création de contenu flexible et réutilisable","Mise en œuvre de références et de contenu intégré","Planification de la diffusion de contenu multi-canal","Refactorisation de contenu existant"],"de":["Erstellung strukturierter Inhalte mit NextJS","Erstellung flexibler und wiederverwendbarer Inhalte","Implementierung von Referenzen und eingebettetem Inhalt","Planung der Auslieferung von Inhalten über mehrere Kanäle","Refaktorisierung bestehender Inhalte"],"pt":["Desenvolvimento de conteúdo estruturado com NextJS","Utilização de Sanity para modelagem de conteúdo","Criação de conteúdo flexível e reutilizável","Otimização para entrega de conteúdo em múltiplos canais","Refatoração de conteúdo existente para melhorar a manutenção"],"ru":["Разработка структурированного контента с помощью NextJS","Использование Sanity для моделирования контента ИИ Агентов","Создание гибкого и повторно используемого контента","Оптимизация для доставки контента в нескольких каналах","Рефакторинг существующего контента для улучшения обслуживания"],"ar":["تصميم المحتوى المنظم مع NextJS","استخدام Sanity لتصميم المحتوى لأدوات الذكاء الاصطناعي","إنشاء المحتوى المرن قابل لإعادة الاستخدام","تحسين التسليم المحتوى في قنوات متعددة","إعادة هيكلة المحتوى الحالي لتحسين الصيانة"]},"keywords":{"en":["how to use content-modeling-best-practices","what is content-modeling-best-practices","content-modeling-best-practices alternative","content-modeling-best-practices vs Sanity","content-modeling-best-practices setup guide","content-modeling-best-practices for NextJS"],"zh":["内容建模最佳实践","Next.js","Sanity","结构化内容","内容模型设计","多渠道内容","内容重构","AIエージェント","内容建模"],"ja":["コンテンツモデル링ベストプラクティス","Next.js","Sanity","構造化コンテンツ","コンテンツモデル設計","マルチチャネルコンテンツ","コンテンツリファクタリング","AIエージェント","コンテンツモデル"],"ko":["콘텐츠 모델링 최선의 관행","Next.js","Sanity","구조화된 콘텐츠","콘텐츠 모델 설계","멀티 채널 콘텐츠","콘텐츠 리팩토링","AI 에이전트","콘텐츠 모델"],"es":["modelado de contenido","mejores prácticas de modelado de contenido","NextJS","contenido estructurado","contenido flexible","desarrollo web","contenido reusable","entrega de contenido multi-canal"],"fr":["modélisation de contenu","meilleures pratiques de modélisation de contenu","NextJS","contenu structuré","contenu flexible","développement web","contenu réutilisable","diffusion de contenu multi-canal"],"de":["Content-Modellierung","Best-Practices für Content-Modellierung","NextJS","strukturierter Inhalt","flexibler Inhalt","Web-Entwicklung","wiederverwendbarer Inhalt","Auslieferung von Inhalten über mehrere Kanäle"],"pt":["modelagem de conteúdo","NextJS","Sanity","desenvolvimento web","conteúdo estruturado","flexível e reutilizável","entrega de conteúdo em múltiplos canais","refatoração de conteúdo","melhores práticas de modelagem de conteúdo"],"ru":["моделирование контента","NextJS","Sanity","веб-разработка","структурированный контент","гибкий и повторно используемый","доставка контента в нескольких каналах","рефакторинг контента","лучшие практики моделирования контента ИИ Агентов"],"ar":["تصميم المحتوى","NextJS","Sanity","تطوير الويب","المحتوى المنظم","مرن وقابل لإعادة الاستخدام","التسليم المحتوى في قنوات متعددة","إعادة هيكلة المحتوى","أفضل الممارسات لتصميم المحتوى لأدوات الذكاء الاصطناعي"]}},"owner":"lanasdev","repo":"lanasdev","repoPath":"lanasdev/lanasdev","stars":1,"forks":0,"updatedAt":"2026-02-26T11:18:19Z","topics":["nextjs","portfolio","web"],"category":"community","skillMd":{"name":"content-modeling-best-practices","description":"General principles for structured content modeling that apply across CMSs, with Sanity-specific guidance. Use when designing content schemas, planning content architecture, or evaluating content reuse strategies.","version":"1.0.0","bodyPreview":"# Content Modeling Best Practices\n\nPrinciples for designing structured content that''s flexible, reusable, and maintainable. These concepts apply to any headless CMS but include Sanity-specific implementation notes.\n\n## When to Apply\n\nReference these guidelines when:\n- Starting a new project and designing the content model\n- Evaluating whether content should be structured or free-form\n- Deciding between references and embedded content\n- Planning for multi-channel content delivery\n- Refactoring ex","body":"# Content Modeling Best Practices\n\nPrinciples for designing structured content that''s flexible, reusable, and maintainable. These concepts apply to any headless CMS but include Sanity-specific implementation notes.\n\n## When to Apply\n\nReference these guidelines when:\n- Starting a new project and designing the content model\n- Evaluating whether content should be structured or free-form\n- Deciding between references and embedded content\n- Planning for multi-channel content delivery\n- Refactoring existing content structures\n\n## Core Principles\n\n1. **Content is data, not pages** — Structure content for meaning, not presentation\n2. **Single source of truth** — Avoid content duplication\n3. **Future-proof** — Design for channels that don''t exist yet\n4. **Editor-centric** — Optimize for the people creating content\n\n## Resources\n\nSee `resources/` for detailed guidance on specific topics:\n- Separation of content and presentation\n- Reference vs embedding strategies\n- Content reuse patterns\n- Taxonomy and classification\n"},"lastSynced":"2026-03-06T07:15:59.487Z","agentAnalysis":{"suitability":{"en":"Perfect for Web Development Agents needing structured content design for headless CMS like NextJS and Sanity","zh":"非常适合需要结构化内容设计的Web开发代理，例如针对NextJS和Sanity的无头CMS","ja":"NextJSやSanityのようなヘッドレスCMS向けの構造化コンテンツ設計を必要とするWeb開発エージェントに最適","ko":"NextJS 및 Sanity와 같은 헤드리스 CMS를 위한 구조화된 콘텐츠 디자인을 필요로 하는 웹 개발 에이전트에 적합","es":"Perfecto para Agentes de Desarrollo Web que necesitan un diseño de contenido estructurado para CMS headless como NextJS y Sanity","fr":"Parfait pour les agents de développement Web nécessitant une conception de contenu structuré pour les CMS headless comme NextJS et Sanity","de":"Perfekt für Webentwicklungsagenten, die ein strukturiertes Content-Design für headless CMS wie NextJS und Sanity benötigen","pt":"Perfeito para Agentes de Desenvolvimento Web que necessitam de design de conteúdo estruturado para headless CMS como NextJS e Sanity","ru":"Идеально подходит для агентов веб-разработки, которым требуется структурированный дизайн контента для безголовых CMS, таких как NextJS и Sanity","ar":"مثالي لعميل التطوير الويب الذين يحتاجون إلى تصميم محتوى منظم ل CMS بدون رأس مثل NextJS و Sanity"},"recommendation":{"en":"Empowers agents to design flexible, reusable, and maintainable content models using principles applicable to any headless CMS, with Sanity-specific implementation notes, and supporting multi-channel content delivery","zh":"赋予代理设计灵活、可重用和可维护的内容模型的能力，使用适用于任何头less CMS的原则，并附有Sanity特定的实现说明，支持多渠道内容分发","ja":"ヘッドレスCMSに適用可能な原則を使用して、柔軟で再利用可能、およびメンテナンス可能なコンテンツモデルを設計するエージェントの能力を付与し、Sanity固有の実装ノートを提供し、マルチチャネルコンテンツ配信をサポート","ko":"어떤 헤드리스 CMS에도 적용 가능한 원칙을 사용하여 유연하고 재사용 가능하며 유지 보수 가능한 콘텐츠 모델을 설계할 수 있는 에이전트의 능력을 부여하며, Sanity 특정 구현 노트를 제공하고, 멀티 채널 콘텐츠 전달을 지원","es":"Habilita a los agentes a diseñar modelos de contenido flexibles, reutilizables y mantenibles utilizando principios aplicables a cualquier CMS headless, con notas de implementación específicas de Sanity y soporte para la entrega de contenido multi-canal","fr":"Permet aux agents de concevoir des modèles de contenu flexibles, réutilisables et maintenables en utilisant des principes applicables à tout CMS headless, avec des notes d''implémentation spécifiques à Sanity et un support pour la diffusion de contenu multi-canal","de":"Ermächtigt Agenten, flexible, wiederverwendbare und wartbare Content-Modelle zu entwerfen, indem sie Grundsätze anwenden, die auf jedes headless CMS anwendbar sind, mit Sanity-spezifischen Implementierungshinweisen und Unterstützung für die multi-kanalige Content-Lieferung","pt":"Habilita os agentes a projetarem modelos de conteúdo flexíveis, reutilizáveis e mantidos usando princípios aplicáveis a qualquer headless CMS, com notas de implementação específicas do Sanity e suporte à entrega de conteúdo em vários canais","ru":"Наделяет агентов возможностью проектировать гибкие, повторно используемые и поддерживаемые модели контента, используя принципы, применимые к любой безголовой CMS, с заметками о реализации, специфичными для Sanity, и поддержкой доставки контента в несколько каналов","ar":"يتمكّن الوكلاء من تصميم نماذج المحتوى المرنة والقابلة لإعادة الاستخدام والصيانة باستخدام المبادئ القابلة للتطبيق على أي نظام إدارة المحتوى بدون رأس، مع ملاحظات حول التنفيذ المحدد لبرنامج Sanity ودعم توصيل المحتوى عبر قنوات متعددة"},"useCases":{"en":["Designing structured content for new projects","Evaluating content structure for optimal delivery","Refactoring existing content models for better maintainability"],"zh":["为新项目设计结构化内容","评估内容结构以实现最佳交付","重构现有内容模型以提高可维护性"],"ja":["新規プロジェクトの構造化コンテンツ設計","最適な配信のためのコンテンツ構造評価","既存のコンテンツモデルのリファクタリングによるメンテナンス性の向上"],"ko":["새 프로젝트를 위한 구조화된 콘텐츠 설계","최적의 전달을 위한 콘텐츠 구조 평가","既存 콘텐츠 모델의 리팩토링을 통한 유지 보수성 향상"],"es":["Diseñar contenido estructurado para nuevos proyectos","Evaluar la estructura de contenido para una entrega óptima","Reestructurar modelos de contenido existentes para una mejor mantenibilidad"],"fr":["Concevoir du contenu structuré pour de nouveaux projets","Évaluer la structure de contenu pour une diffusion optimale","Réorganiser les modèles de contenu existants pour une meilleure maintenabilité"],"de":["Strukturierten Inhalt für neue Projekte entwerfen","Inhaltsstruktur für eine optimale Lieferung bewerten","Vorhandene Content-Modelle für eine bessere Wartbarkeit neu strukturieren"],"pt":["Projeto de conteúdo estruturado para novos projetos","Avaliação da estrutura de conteúdo para entrega otimizada","Reprojeto de modelos de conteúdo existentes para melhor manutenção"],"ru":["Проектирование структурированного контента для новых проектов","Оценка структуры контента для оптимальной доставки","Перепроектирование существующих моделей контента для лучшей поддержки"],"ar":["تصميم المحتوى المنظم للمشاريع الجديدة","تقييم هيكل المحتوى للتسليم الأمثل","إعادة تصميم نماذج المحتوى الحالية من أجل الصيانة الأفضل"]},"limitations":{"en":["Requires understanding of headless CMS architecture","Sanity-specific implementation may require additional setup"],"zh":["需要理解无头CMS架构","Sanity特定的实现可能需要额外的设置"],"ja":["ヘッドレスCMSアーキテクチャの理解が必要","Sanity固有の実装には追加の設定が必要"],"ko":["헤드리스 CMS 아키텍처에 대한 이해가 필요","Sanity 특정 구현에는 추가 설정이 필요할 수 있음"],"es":["Requiere comprensión de la arquitectura de CMS headless","La implementación específica de Sanity puede requerir una configuración adicional"],"fr":["Nécessite une compréhension de l''architecture de CMS headless","La mise en œuvre spécifique de Sanity peut nécessiter une configuration supplémentaire"],"de":["Benötigt Verständnis für die Architektur von headless CMS","Die Sanity-spezifische Implementierung kann eine zusätzliche Einrichtung erfordern"],"pt":["Requer compreensão da arquitetura do headless CMS","A implementação específica do Sanity pode exigir configuração adicional"],"ru":["Требует понимания архитектуры безголовой CMS","Реализация, специфичная для Sanity, может потребовать дополнительной настройки"],"ar":["يتطلب فهمًا لعمارة نظام إدارة المحتوى بدون رأس","يمكن أن تتطلب التنفيذ المحدد لبرنامج Sanity إعدادات إضافية"]},"version":4},"contentHash":"71acacfd0acbc2c0bd22f77bac3fc082d5a8efa26923f22f5c905dce8b4affa1","qualityScore":28}');
