INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jhs88/my-shadcn-app-monorepo/tanstack-query', 'tanstack-query', 'jhs88', 'my-shadcn-app-monorepo', 'community', 'tanstack-query jhs88 my-shadcn-app-monorepo community tanstack-query是一个示例Turbo Repo，集成了shadcn和Next.js，用于演示AI工具的功能 tanstack-queryは、Turbo Repoの例であり、shadcnとNext.jsを統合してAIエージェントの機能を示しています tanstack-query는 터보 리포의 예시로, shadcn과 넥스트.js를 통합하여 AI 에이전트의 기능을 보여줍니다 tanstack-query es un ejemplo de Turbo Repo con shadcn y next.js para desarrolladores tanstack-query est un exemple de Turbo Repo avec shadcn et next.js pour les développeurs tanstack-query ist ein Beispiel für ein Turbo Repo mit shadcn und next.js für Entwickler O TanStack Query é uma ferramenta de IA para otimizar a performance da sua aplicação com Next.js ИИ Агенты TanStack Query - это инструмент для оптимизации производительности вашего приложения с Next.js أدوات الذكاء الاصطناعي TanStack Query هي أداة لتحسين أداء تطبيقك مع Next.js Example Turbo Repo with shadcn & next.js tanstack-query AI工具 Turbo Repo Next.js shadcn 如何使用tanstack-query tanstack-query安装 tanstack-query设置指南 Example Turbo Repo with shadcn & next.js');
